                    var(--kp-cp-dash) calc(10 * var(--kp-cp-px)) calc(40 * var(--kp-cp-px)),
                    transparent calc(40 * var(--kp-cp-px)) calc(48 * var(--kp-cp-px)),
                    var(--kp-cp-dash) calc(48 * var(--kp-cp-px)) calc(60 * var(--kp-cp-px)),
                    transparent calc(60 * var(--kp-cp-px)) calc(68 * var(--kp-cp-px)),
                    var(--kp-cp-dash) calc(68 * var(--kp-cp-px)) calc(112 * var(--kp-cp-px)),
