                    transparent calc(32 * var(--kp-cp-px)) calc(176 * var(--kp-cp-px)),
                    var(--accent) calc(176 * var(--kp-cp-px)) calc(188 * var(--kp-cp-px)),
                    transparent calc(188 * var(--kp-cp-px))
