    [data-theme='cyberpunk'] .kp-datatable:has(> .kp-datatable__busy-overlay) .kp-datatable__status > .kp-spinner {
        display: none;
    }

    [data-theme='cyberpunk'] .kp-datatable:has(> .kp-datatable__busy-overlay) .kp-skeleton::before {
        content: none;
        animation: none;
    }

    [data-theme='cyberpunk'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)::before,
    [data-theme='cyberpunk'] .kp-skeleton--block::before,
    [data-theme='cyberpunk'] .kp-progressbar[data-kp-indeterminate]::before,
    [data-theme='cyberpunk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        /* The word comes from js/strings.js (`loadingWord`, through
           setStrings()); the English is the fallback. */
        content: var(--kp-loading-word-7, 'LOADING');
        position: absolute;
        inset: 0;
        z-index: 4;
        display: grid;
        place-items: center;
        overflow: visible;
        background: none;
        clip-path: none;
        color: var(--foreground);
