    /* The waiting part stands dim under its word. */
    [data-theme='cyberpunk'] .kp-progressbar[data-kp-indeterminate] > .kp-progressbar__track {
        opacity: 0.2;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)::before,
        [data-theme='cyberpunk'] .kp-skeleton--block::before,
