        }

        [data-theme='cyberpunk'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block):nth-child(3)::before {
            animation-delay: 720ms;
        }
    }

    [data-theme='cyberpunk'] .kp-switch {
        --kp-switch-radius: 0;
        --kp-switch-thumb-radius: 0;
    }

    [data-theme='cyberpunk'] .kp-switch__input {
        border: 1px solid var(--primary);
