            transition: transform 180ms steps(3, jump-end);
        }
    }

    [data-theme='cyberpunk'] .kp-field__check {
        --kp-sig-dur: 180ms;
    }

    [data-theme='cyberpunk'] .kp-field__check[type='checkbox']:checked {
        background: var(--primary);
    }

    [data-theme='cyberpunk'] .kp-field__check[type='checkbox']:checked::before {
        inline-size: 0.6rem;
        block-size: 0.3rem;
        border-inline-start: 2px solid var(--primary-foreground);
