    [data-theme='cyberpunk'] :is(.kp-icon-button, .kp-tab, .kp-switch__input, .kp-combobox__input, .kp-skip-link, .kp-chart__source):focus-visible {
        outline: none;
        box-shadow:
            inset 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            inset 0 0 0 calc(var(--kp-focus-ring-inner-width, 2px) + 2px) var(--focus-ring-contrast);
    }

    /* ── D. Prose is Rajdhani, the machine's names are mono [G15, lesson 18] ────────────────
       The register had put the mono face on whole parts; the words inside them are prose. */
    [data-theme='cyberpunk']
        :is(
            .kp-alarm__detail,
            .kp-field__help,
            .kp-field__error,
            .kp-empty__body,
            .kp-toast__body,
            .kp-palette,
            .kp-palette__option,
            .kp-palette__description,
            .kp-theme-menu__status,
            .kp-cell-truncate,
            .kp-truncate,
            .kp-accordion__summary,
            .kp-shortcuts__row dd,
            .kp-error,
            .kp-media-figure > figcaption
        ) {
        font-family: var(--theme-font-body);
        letter-spacing: 0.02em;
    }

    [data-theme='cyberpunk'] .kp-media-figure > figcaption {
        text-transform: none;
        font-size: 0.8125rem;
    }

    [data-theme='cyberpunk'] .kp-palette__keys {
        font-family: var(--kp-mono);
    }

    [data-theme='cyberpunk'] .kp-field__error::before {
        font-family: var(--kp-mono);
    }

    /* The machine's prefixes [G15]: `//` before a badge, tag, table head, timestamp and a group
       label, `!!` before a failure's badge; tracked as the labels are. */
    [data-theme='cyberpunk']
        :is(
            .kp-badge,
            .kp-tag,
            .kp-table th:not(:has(input)),
            .kp-timestamp,
            .kp-theme-group__label,
            .kp-shortcuts__group-label,
            .kp-alert__label
        )::before {
        content: '// ';
        content: '// ' / '';
        opacity: 0.7;
    }

    [data-theme='cyberpunk'] :is(.kp-badge--destructive, .kp-badge--warning, .kp-badge[data-status='rejected'])::before {
        content: '!! ';
        content: '!! ' / '';
    }

    [data-theme='cyberpunk'] :is(.kp-theme-group__label, .kp-shortcuts__group-label, .kp-alert__label, .kp-progress__label) {
        font-family: var(--kp-mono);
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }

    [data-theme='cyberpunk'] .kp-timestamp {
        letter-spacing: 0.12em;
    }

    /* ── Leftovers of the notch round [Kenny, 2026-10-12] ───────────────────────────────────
       The check, the calendar and date picker days, the date picker's title and the table's search
       field were still rectangles. A control is cut 8 px; a part too small for that (the check, 18 px)
       by a share of its height (`--kp-cp-clip-mini`). The radio and the graph stay round (G6). The
       focus brackets and the split edge are drawn inside the box, so the cut does not take them:
       the corner brackets sit half a cut clear of the diagonal (`--kp-cp-nbr`). A bare accordion
       item has no chrome, so no plate and no cut. */
    [data-theme='cyberpunk'] :is(.kp-calendar__day, .kp-datepicker__day, .kp-datepicker__title, .kp-datatable__search) {
        --kp-cp-clip: var(--kp-cp-clip-ctl);
        --kp-cp-wide: var(--kp-cp-wide-ctl);
        --kp-cp-nbr: calc(var(--kp-cp-notch-sm) + 2px);
        border-radius: 0;
        clip-path: var(--kp-cp-clip);
    }

    [data-theme='cyberpunk'] .kp-nav__search-trigger {
        --kp-cp-nbr: calc(var(--kp-cp-notch-sm) + 2px);
    }

    [data-theme='cyberpunk'] :is(.kp-nav__search-trigger, .kp-combobox__clear) {
        --kp-cp-clip: var(--kp-cp-clip-ctl);
        --kp-cp-wide: var(--kp-cp-wide-ctl);
        border-radius: 0;
        clip-path: var(--kp-cp-clip);
    }

    /* A colour sample and a legend swatch are small parts: the cut is a share of their height. */
    [data-theme='cyberpunk'] :is(.kp-colorpicker__swatch, .kp-calendar__swatch, .kp-spec__swatch, .kp-datatable__edit, .kp-datatable__pill-edit) {
        --kp-cp-clip: var(--kp-cp-clip-mini);
        --kp-cp-wide: var(--kp-cp-wide-mini);
        border-radius: 0;
        clip-path: var(--kp-cp-clip);
    }

    [data-theme='cyberpunk'] .kp-accordion__item--bare {
        clip-path: none;
    }

    /* The item is a plate now: its words keep clear of the rim and the notch. */
    [data-theme='cyberpunk'] .kp-accordion__item:not(.kp-accordion__item--bare) > :is(.kp-accordion__summary, .kp-accordion__body) {
        padding-inline: 1rem;
    }

    [data-theme='cyberpunk'] .kp-field__check:not([type='radio']) {
        --kp-cp-clip: var(--kp-cp-clip-mini);
        --kp-cp-wide: var(--kp-cp-wide-mini);
        border-radius: 0;
        clip-path: var(--kp-cp-clip);
        background-image: linear-gradient(135deg, transparent calc(50% - 1px), var(--primary) calc(50% - 1px));
        background-position: right bottom;
        background-size: 7px 7px;
        background-repeat: no-repeat;
    }

    /* A check on its own is framed inside itself now (the cut would take a frame drawn outside): the
       brackets are 6 px long and close from 4 px, the split edge is a third of the pair's. */
    [data-theme='cyberpunk'] input.kp-field__check:not([type='radio']):not(.kp-field__option *, .kp-field--check *, .kp-menu__item *) {
        --kp-cp-i: calc(var(--kp-cp-ft) * 1px);
        --kp-cp-fa: calc(var(--kp-cp-fp) * 5px);
        --kp-cp-fai: calc(var(--kp-cp-fp) * 3px);
        --kp-cp-nbr: 10px;
        --kp-cp-d: calc(var(--kp-cp-p) * (1px + var(--kp-cp-t) * 0.5px));
    }

    [data-theme='cyberpunk'] input.kp-field__check:not([type='radio']):not(.kp-field__option *, .kp-field--check *, .kp-menu__item *)::after {
        inset: 0;
    }

    /* The check inside a label is framed by the label; its own outline would be cut, so it has none. */
    [data-theme='cyberpunk'] .kp-field__check:not([type='radio']):focus-visible {
        outline: none;
    }
    /* <<cfd-end>> */
}

/* ── End of the signature ── */

/* <<cfd-layout-begin>> */
/* The package's own rule for these lives in kp.layout, which a register's layers cannot beat. */
@layer kp.layout {
    [data-theme='cyberpunk'] .kp-code-block {
        border-radius: 0;
    }
}

@layer kp.register {
    /* Bottom tab bar [kpadopt-nav] — cyberpunk: a locked target. The current tab is a yellow notched plate with dark ink, acquired in ticks (never eased), the labels prefixed-mono capitals (G1, G5, G6, G15); a count is a notched yellow-and-black tag. */
    [data-theme='cyberpunk'] .kp-tabbar {
        background: var(--background);
        border-block-start: 1px solid var(--primary);
    }

    [data-theme='cyberpunk'] .kp-tabbar__tab {
        border-radius: 0;
        isolation: isolate;
        font-family: var(--theme-font-mono);
        letter-spacing: 0.1em;
        text-transform: uppercase;
    }

    [data-theme='cyberpunk'] .kp-tabbar__tab::before {
        inset: 0;
        block-size: auto;
        z-index: -1;
        background: var(--primary);
        clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 10px 100%, 0 calc(100% - 10px));
        scale: 1 1;
        opacity: 0;
    }

    [data-theme='cyberpunk'] .kp-tabbar__tab[aria-current]:not([aria-current='false']) {
        color: var(--primary-foreground);
    }

    [data-theme='cyberpunk'] .kp-tabbar__tab[aria-current]:not([aria-current='false'])::before {
        opacity: 1;
    }

    [data-theme='cyberpunk'] .kp-tabbar__tab[aria-current]:not([aria-current='false']) .kp-tabbar__icon {
        color: inherit;
    }

    [data-theme='cyberpunk'] .kp-tabbar__tab:is(:hover, :focus-visible):not([aria-current]:not([aria-current='false'])) {
        color: var(--primary);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-tabbar__tab::before {
            transition: opacity calc(var(--fx-duration) / 3) steps(3, jump-end);
        }
    }

    [data-theme='cyberpunk'] .kp-tabbar__badge {
        border-radius: 0;
        clip-path: polygon(0 0, calc(100% - 4px) 0, 100% 4px, 100% 100%, 4px 100%, 0 calc(100% - 4px));
        font-family: var(--theme-font-mono);
    }
}
/* <<cfd-layout-end>> */

/* ── Segmented control, list toolbar, key line [kpadopt-controls] ── */
@layer kp.signature {
    [data-theme='cyberpunk'] .kp-segmented {
        --kp-seg-radius: 0;
        --kp-seg-font: var(--theme-font-body);
        --kp-seg-tracking: 0.12em;
        --kp-seg-case: uppercase;
        --kp-seg-track: var(--background);
        --kp-seg-thumb: hsl(from var(--primary) h s l / 0.14);
        --kp-seg-thumb-ink: var(--primary);
        --kp-seg-thumb-edge: 0 0 0 1px var(--primary);
        --kp-seg-thumb-lift: 0 0 14px hsl(from var(--primary) h s l / 0.45);
        --kp-chip-radius: 0;
        --kp-chip-on: hsl(from var(--primary) h s l / 0.16);
        --kp-chip-on-ink: var(--primary);
        --kp-chip-on-edge: var(--primary);
    }
    [data-theme='cyberpunk'] .kp-toolbar {
        --kp-toolbar-group-gap: 1.125rem;
    }
    [data-theme='cyberpunk'] .kp-toolbar__label {
        font-family: var(--theme-font-body);
        letter-spacing: 0.2em;
    }
    [data-theme='cyberpunk'] .kp-keys {
        --kp-keys-gap: 1rem;
    }
    [data-theme='cyberpunk'] .kp-kbd {
        --kp-kbd-radius: 0;
        --kp-kbd-edge: var(--accent);
        --kp-kbd-ground: transparent;
        --kp-kbd-ink: var(--accent);
        --kp-kbd-foot: 1px;
        text-transform: uppercase;
    }
    /* The press: the chosen word splits into the two neon channels, three
       stepped frames, only when the plate has moved to it (not on arrival). */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-segmented[data-kp-segmented-glide] > .kp-segmented__item[aria-checked='true'] {
            animation: kp-seg-cp-split 160ms steps(4, jump-end) 1;
        }
    }
    [data-theme='cyberpunk'] .kp-segmented__item[aria-checked='true'],
    [data-theme='cyberpunk'] .kp-segmented__item[aria-pressed='true'] {
        text-shadow: 1px 0 hsl(from var(--accent) h s l / 0.7);
    }
    @keyframes kp-seg-cp-split {
        0%,
        100% {
            text-shadow: 1px 0 hsl(from var(--accent) h s l / 0.7);
        }
        35% {
            text-shadow:
                -3px 0 var(--accent),
                3px 0 var(--destructive);
        }
        70% {
            text-shadow:
                2px 0 var(--accent),
                -2px 0 var(--destructive);
        }
    }
}

/* ── The dashboard parts: action tiles, status rows, the facet list, the heat grid, the matrix, the bar in a cell, the
   week agenda and the run timeline [kpadopt2] ──
   Cyberpunk's own (themes/cyberpunk/CHARACTER.md): every plate is a holo card, the void with a yellow rim glowing
   inward, scan lines at 135 degrees, cut at its dossier corner (G6, G7); pointing lights the 14 px circuit in one tick
   (G8) and a press closes it (G14); a failure is locked as a target, four corner brackets in the red (G13); the machine
   speaks in prefixed mono capitals (G15); waiting is signal loss, the word LOADING deciphered over the dimmed part, once
   per waiting part and never once per cell (the register's osd); a running job is a data stream through its wire (G16).
   Hard ticks everywhere, never an ease. */
@layer kp.signature {
    [data-theme='cyberpunk'] .kp-actions {
        --kp-actions-gap: 0.75rem;
    }
    [data-theme='cyberpunk'] .kp-action {
        --kp-action-radius: 0;
        --kp-action-edge: transparent;
        --kp-action-edge-hover: transparent;
        --kp-action-press: 0 0;
        --kp-action-title-font: var(--kp-mono);
        --kp-action-title-case: uppercase;
        --kp-action-title-tracking: 0.12em;
        --kp-action-title-size: 0.875rem;
        --kp-action-pad: 0.75rem 0.875rem;
        --kp-cp-ground: var(--card);
        --kp-cp-grid-a: 0;
        --kp-cp-lk: 3px;
        --kp-cp-rest: inset 0 0 0 1px var(--primary), inset 0 0 10px hsl(from var(--primary) h s l / 0.35);
        --kp-cp-tile-grid:
            repeating-linear-gradient(to bottom, hsl(from var(--primary) h s l / var(--kp-cp-grid-a)) 0 1px, transparent 1px 14px),
            repeating-linear-gradient(to right, hsl(from var(--primary) h s l / var(--kp-cp-grid-a)) 0 1px, transparent 1px 14px);
        --kp-cp-tile-notch: linear-gradient(45deg, transparent calc(50% - 1.5px), var(--primary) calc(50% - 1.5px) 50%, transparent 50%) 100% 0 /
            var(--kp-cp-notch) var(--kp-cp-notch) no-repeat;
        --kp-cp-tile-scan: repeating-linear-gradient(135deg, hsl(from var(--primary) h s l / 0.06) 0 2px, transparent 2px 6px);
        --kp-cp-tile-lock: linear-gradient(transparent, transparent);
        background: var(--kp-cp-tile-lock), var(--kp-cp-tile-grid), var(--kp-cp-tile-notch), var(--kp-cp-tile-scan), var(--kp-cp-ground);
        box-shadow: var(--kp-cp-rest);
        clip-path: var(--kp-cp-clip-plate);
    }
    [data-theme='cyberpunk'] .kp-action > :not(.kp-action__state) {
        position: relative;
    }
    /* The sentence is the machine's read-out: cyan reads (G5). */
    [data-theme='cyberpunk'] .kp-action__meta {
        color: var(--accent);
        font-family: var(--kp-mono);
        letter-spacing: 0.08em;
    }
    [data-theme='cyberpunk'] .kp-action__meta::before {
        content: '// ';
        opacity: 0.7;
    }
    [data-theme='cyberpunk'] .kp-action:hover:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])) {
        --kp-cp-grid-a: 0.3;
        box-shadow: var(--kp-cp-rest);
    }
    [data-theme='cyberpunk'] .kp-action:active:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])) {
        --kp-cp-grid-a: 0.6;
        --kp-cp-ground: color-mix(in oklab, var(--primary) 12%, var(--card));
        box-shadow: var(--kp-cp-rest);
    }
    /* Focus: DI2's two channels drawn inset, so the notch never cuts them; the circuit lit as under the pointer. */
    [data-theme='cyberpunk'] .kp-action:focus-visible {
        --kp-cp-grid-a: 0.3;
        outline: none;
        box-shadow:
            inset 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            inset 0 0 0 calc(var(--kp-focus-ring-inner-width, 2px) + 2px) var(--focus-ring-contrast);
    }
    [data-theme='cyberpunk'] .kp-action:is(:disabled, [aria-disabled='true']) {
        --kp-cp-rest: inset 0 0 0 1px var(--border);
        --kp-cp-ground: var(--muted);
        --kp-cp-tile-notch: linear-gradient(transparent, transparent);
        box-shadow: var(--kp-cp-rest);
    }
    /* Destructive: locked as a target. Four 2 px corner brackets in the red, the title in the red; no side bar. */
    [data-theme='cyberpunk'] .kp-action--destructive:not(:is(:disabled, [aria-disabled='true'])) {
        --kp-cp-tone: var(--destructive);
        --kp-cp-rest: inset 0 0 0 1px hsl(from var(--destructive) h s l / 0.55), inset 0 0 10px hsl(from var(--destructive) h s l / 0.3);
        --kp-cp-tile-lock:
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) var(--kp-cp-lk) / 9px 2px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) var(--kp-cp-lk) / 2px 9px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) calc(100% - var(--kp-cp-lk)) / 9px 2px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) calc(100% - var(--kp-cp-lk)) / 2px 9px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) calc(100% - var(--kp-cp-lk)) calc(100% - var(--kp-cp-lk)) / 9px 2px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) calc(100% - var(--kp-cp-lk)) calc(100% - var(--kp-cp-lk)) / 2px 9px no-repeat;
        --kp-cp-tile-notch: linear-gradient(45deg, transparent calc(50% - 1.5px), var(--destructive) calc(50% - 1.5px) 50%, transparent 50%) 100% 0 /
            var(--kp-cp-notch) var(--kp-cp-notch) no-repeat;
    }
    [data-theme='cyberpunk'] .kp-action--destructive::after {
        display: none;
    }
    [data-theme='cyberpunk'] .kp-action--destructive > .kp-action__title {
        color: var(--destructive);
    }
    [data-theme='cyberpunk'] .kp-action--destructive:is(:disabled, [aria-disabled='true']) > .kp-action__title {
        color: inherit;
    }

    /* Status rows: square read-outs with a hairline; a failed row is locked as a target in the red; the detail is the
       machine's mono. */
    [data-theme='cyberpunk'] .kp-statuslist {
        --kp-statusrow-mark-radius: 0;
    }
    [data-theme='cyberpunk'] .kp-statusrow {
        --kp-statusrow-radius: 0;
        --kp-statusrow-edge: var(--kp-hairline, var(--border));
        --kp-cp-lk: 3px;
        clip-path: var(--kp-cp-clip-ctl);
    }
    [data-theme='cyberpunk'] .kp-statusrow[data-state='failed'] {
        --kp-cp-tone: var(--destructive);
        --kp-statusrow-state-edge: hsl(from var(--destructive) h s l / 0.45);
        background:
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) var(--kp-cp-lk) / 9px 2px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) var(--kp-cp-lk) / 2px 9px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) calc(100% - var(--kp-cp-lk)) var(--kp-cp-lk) / 9px 2px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) calc(100% - var(--kp-cp-lk)) var(--kp-cp-lk) / 2px 9px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) calc(100% - var(--kp-cp-lk)) / 9px 2px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) calc(100% - var(--kp-cp-lk)) / 2px 9px no-repeat,
            var(--card);
    }
    [data-theme='cyberpunk'] .kp-statusrow[data-state='loading'] {
        --kp-statusrow-state-edge: hsl(from var(--accent) h s l / 0.6);
    }
    [data-theme='cyberpunk'] .kp-statusrow__detail {
        font-family: var(--kp-mono);
        letter-spacing: 0.04em;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-statusrow[data-state='failed'] {
            animation: kp-sig-cyberpunk-lock 360ms steps(1, end) 1 both;
        }
    }

    /* Facets: square rows; pointing lights the circuit in the row; the title and the counts are mono read-outs. The
       counts on their way are notched slots whose lock blinks cyan, yellow, cyan in hard ticks. */
    [data-theme='cyberpunk'] .kp-facets {
        --kp-facet-radius: 0;
    }
    [data-theme='cyberpunk'] .kp-facet {
        --kp-facet-hover: hsl(from var(--primary) h s l / 0.08);
    }
    [data-theme='cyberpunk'] .kp-facet:hover {
        background-image:
            repeating-linear-gradient(to bottom, hsl(from var(--primary) h s l / 0.3) 0 1px, transparent 1px 14px),
            repeating-linear-gradient(to right, hsl(from var(--primary) h s l / 0.3) 0 1px, transparent 1px 14px);
    }
    [data-theme='cyberpunk'] :is(.kp-facets__title, .kp-facet__count) {
        font-family: var(--kp-mono);
    }
    [data-theme='cyberpunk'] .kp-facets__title {
        color: var(--accent);
        letter-spacing: 0.14em;
        text-transform: uppercase;
    }
    [data-theme='cyberpunk'] .kp-facets__title::before {
        content: '/// ';
        opacity: 0.7;
    }
    [data-theme='cyberpunk'] .kp-facets[aria-busy='true'] .kp-facet__count {
        border-radius: 0;
        background: var(--sidebar-background);
        box-shadow: inset 0 0 0 1px var(--accent);
        clip-path: var(--kp-cp-clip-ctl);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-facets[aria-busy='true'] .kp-facet__count {
            animation: kp-sig-cyberpunk-blink 1800ms steps(1, end) infinite;
        }
    }

    /* Heat grid and matrix: neon tubes in the void. A cell is a dark tinted ground in its tone's neon edge with a glow
       of the same hue; the pick is a cyan tube; pointing lights the cell's tube (G8). Waiting, the cells dim and one
       word is deciphered over the grid, not one per cell. */
    [data-theme='cyberpunk'] .kp-heat {
        --kp-heat-cell-radius: 0;
        --kp-heat-cell-gap: 2px;
        --kp-heat-gap-y: 6px;
        position: relative;
    }
    [data-theme='cyberpunk'] .kp-matrix {
        --kp-heat-cell-radius: 0;
        --kp-matrix-gap: 4px;
    }
    [data-theme='cyberpunk'] :is(.kp-heat, .kp-matrix) {
        --kp-heat-cell-hover: none;
        --kp-matrix-cell-hover: none;
    }
    [data-theme='cyberpunk']
        .kp-heat__cell:is([data-kp-tone='ok'], [data-kp-tone='warn'], [data-kp-tone='bad'], [data-kp-tone='level']):not([data-kp-share]),
    [data-theme='cyberpunk'] .kp-heat__swatch:is([data-kp-tone='ok'], [data-kp-tone='warn'], [data-kp-tone='bad'], [data-kp-tone='level']) {
        background-color: hsl(from var(--kp-heat-fill) h calc(s * 0.6) 11%);
        background-image: linear-gradient(to top, var(--kp-heat-fill) 0 3px, transparent 3px), var(--kp-heat-pattern);
        border-color: var(--kp-heat-fill);
        box-shadow: 0 0 6px hsl(from var(--kp-heat-fill) h s l / 0.55);
    }
    [data-theme='cyberpunk'] .kp-heat__cell[data-kp-share] {
        background-color: hsl(from var(--muted) h s 8%);
        border-color: hsl(from var(--kp-heat-fill) h s l / 0.7);
    }
    [data-theme='cyberpunk'] .kp-heat__cell:hover:not(.kp-skeleton, [aria-disabled='true']),
    [data-theme='cyberpunk'] .kp-matrix__cell:hover:not([data-kp-inert], [aria-disabled='true'], .kp-skeleton) {
        border-color: var(--primary);
        box-shadow: 0 0 10px hsl(from var(--primary) h s l / 0.6);
    }
    [data-theme='cyberpunk'] .kp-heat__cell[data-kp-picked],
    [data-theme='cyberpunk'] .kp-matrix__cell[aria-pressed='true'] {
        outline: 2px solid var(--accent);
        outline-offset: 1px;
        box-shadow: 0 0 10px var(--accent);
    }
    [data-theme='cyberpunk'] :is(.kp-heat__label, .kp-matrix__name, .kp-heat__col, .kp-matrix__col) {
        font-family: var(--kp-mono);
        text-transform: uppercase;
        letter-spacing: 0.06em;
        font-size: var(--kp-text-xs, 0.75rem);
    }
    [data-theme='cyberpunk'] :is(.kp-heat__label-button, .kp-matrix__name) {
        border-radius: 0;
    }
    [data-theme='cyberpunk'] .kp-heat__label-button[aria-pressed='true'] {
        background: hsl(from var(--primary) h s l / 0.14);
        color: var(--primary);
        box-shadow: inset 0 0 0 1px var(--primary);
    }
    /* Waiting: the cells and the names stand dim and wordless; one LOADING is deciphered over the cells' columns. */
    [data-theme='cyberpunk']
        :is(.kp-heat__cell, .kp-matrix__cell, .kp-heat__label-skeleton, .kp-matrix__col--skeleton, .kp-matrix__row--skeleton).kp-skeleton {
        opacity: 0.45;
    }
    [data-theme='cyberpunk']
        :is(.kp-heat__cell, .kp-matrix__cell, .kp-heat__label-skeleton, .kp-matrix__col--skeleton, .kp-matrix__row--skeleton).kp-skeleton::before {
        content: none;
        animation: none;
    }
    [data-theme='cyberpunk'] .kp-heat:has(.kp-heat__cell.kp-skeleton)::after,
    [data-theme='cyberpunk'] .kp-matrix:has(.kp-matrix__cell.kp-skeleton)::after,
    [data-theme='cyberpunk'] .kp-gantt[data-kp-state='loading'] .kp-gantt__plot::after {
        content: var(--kp-loading-word-7, 'LOADING');
        position: absolute;
        inset: 0 0 0 calc(clamp(4.5rem, 26%, var(--kp-heat-label, 8rem)) + var(--kp-heat-gap-x, 0.75rem));
        z-index: 2;
        inline-size: fit-content;
        block-size: fit-content;
        margin: auto;
        padding: 0.25rem 0.625rem;
        background: var(--card);
        box-shadow: inset 0 0 0 1px var(--accent);
        color: var(--foreground);
        font-family: var(--kp-mono);
        font-size: 0.75rem;
        font-weight: 700;
        letter-spacing: 0.24em;
        line-height: 1.2;
        text-shadow:
            2px -1px 0 var(--accent),
            2px 1px 0 var(--destructive);
        pointer-events: none;
    }
    [data-theme='cyberpunk'] :is(.kp-matrix, .kp-gantt[data-kp-state='loading'] .kp-gantt__plot)::after {
        inset: 0;
    }
    /* Under the busy card (js/busy-card.js: the data table's loading card, centred over the data) the card is the one
       loading picture: the deciphered LOADING gives way to it, never stands beside or on it. */
    [data-theme='cyberpunk'] :is(.kp-heat, .kp-matrix):has(> .kp-datatable__busy-card.kp-datatable__busy-overlay)::after,
    [data-theme='cyberpunk'] .kp-gantt[data-kp-state='loading']:has(.kp-datatable__busy-card) .kp-gantt__plot::after {
        content: none;
        animation: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-heat:has(.kp-heat__cell.kp-skeleton)::after,
        [data-theme='cyberpunk'] .kp-matrix:has(.kp-matrix__cell.kp-skeleton)::after,
        [data-theme='cyberpunk'] .kp-gantt[data-kp-state='loading'] .kp-gantt__plot::after {
            animation:
                kp-sig-cyberpunk-word 1800ms steps(1, end) infinite,
                kp-sig-cyberpunk-word-tear 1800ms steps(1, end) infinite;
        }
    }
    [data-theme='cyberpunk'] .kp-bar-cell {
        --kp-bar-cell-gap: var(--kp-space-sm, 0.5rem);
        font-family: var(--kp-mono);
        font-variant-numeric: tabular-nums;
    }

    /* Week agenda and run timeline: HUD read-outs. One notched corner (cut outwards past the box so the focus ring
       stays whole), a hard 3 px bar on the leading edge in the series' ink, the time in mono; the line for now is the
       primary. A running run is a data stream: the void in a yellow rim with cyan dashes moving through it. */
    [data-theme='cyberpunk'] .kp-week {
        --kp-week-pill-radius: 0;
        --kp-week-now: var(--primary);
    }
    [data-theme='cyberpunk'] .kp-gantt {
        --kp-gantt-state-ground: var(--card);
        --kp-gantt-bar-radius: 0;
        --kp-gantt-now: var(--primary);
    }
    [data-theme='cyberpunk'] :is(.kp-week__pill, .kp-gantt__run) {
        --kp-cp-pill-notch: var(--fx-notch-sm, 8px);
        clip-path: polygon(
            -8px -8px,
            calc(100% + 8px) -8px,
            calc(100% + 8px) calc(100% - var(--kp-cp-pill-notch) - 8px),
            calc(100% - var(--kp-cp-pill-notch) - 8px) calc(100% + 8px),
            -8px calc(100% + 8px)
        );
    }
    /* A bar can be a few pixels wide: its cut is the small one, so a short run stays a bar and not a wedge. */
    [data-theme='cyberpunk'] .kp-gantt__run {
        --kp-cp-pill-notch: 4px;
    }
    [data-theme='cyberpunk'] .kp-week__pill {
        border-color: var(--kp-hairline, var(--border));
        border-inline-start: 3px solid var(--kp-week-ink);
    }
    [data-theme='cyberpunk'] .kp-week__pill:is(button):hover {
        box-shadow:
            0 0 0 1px var(--primary),
            0 0 8px hsl(from var(--primary) h s l / 0.5);
    }
    [data-theme='cyberpunk'] :is(.kp-week__time, .kp-week__head, .kp-gantt__tick, .kp-week__axis > span) {
        font-family: var(--kp-mono);
    }
    [data-theme='cyberpunk'] .kp-week__now::before {
        border-radius: 0;
    }
    [data-theme='cyberpunk'] .kp-gantt__run:is(button):hover {
        box-shadow:
            0 0 0 1px var(--primary),
            0 0 8px hsl(from var(--primary) h s l / 0.5);
    }
    [data-theme='cyberpunk'] .kp-gantt__run[data-kp-state='running'] {
        position: absolute;
        border-color: var(--primary);
        background: var(--card);
        color: var(--foreground);
        box-shadow: inset -3px 0 0 var(--primary);
    }
    [data-theme='cyberpunk'] .kp-gantt__run[data-kp-state='running']::after {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline: -144px 0;
        background:
            repeating-linear-gradient(90deg, var(--accent) 0 18px, transparent 18px 36px) 0 30% / 100% 2px no-repeat,
            repeating-linear-gradient(90deg, transparent 0 9px, var(--accent) 9px 15px, transparent 15px 36px) 0 70% / 100% 2px no-repeat;
        opacity: 0.8;
        pointer-events: none;
    }
    [data-theme='cyberpunk'] .kp-gantt__swatch[data-kp-state='running'] {
        border-color: var(--primary);
        background:
            repeating-linear-gradient(90deg, var(--accent) 0 3px, transparent 3px 6px) 0 50% / 100% 2px no-repeat,
            var(--card);
    }
    /* The loading sentence is the machine's voice on a plate of the void, never over a ghost bar's edge. */
    [data-theme='cyberpunk'] .kp-gantt[data-kp-state='loading'] .kp-gantt__state {
        display: none;
    }
    [data-theme='cyberpunk'] .kp-gantt__ghost .kp-skeleton {
        opacity: 0.45;
    }
    [data-theme='cyberpunk'] .kp-gantt__ghost .kp-skeleton::before {
        content: none;
        animation: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-gantt__run[data-kp-state='running'] {
            animation: none;
        }
        [data-theme='cyberpunk'] .kp-gantt__run[data-kp-state='running']::after {
            animation: kp-sig-cyberpunk-feed 1800ms linear infinite;
        }
    }

    /* A phone's timeline keeps its toolbar on one row: the range steps close in a little in these wide letters. */
    @container kp-gantt (max-width: 22rem) {
        [data-theme='cyberpunk'] .kp-gantt__ranges {
            --kp-seg-item-pad-inline: 0.5rem;
        }
    }

    /* The waiting count's lock blinks: cyan, yellow, cyan, then the void, in hard ticks. */
    @keyframes kp-sig-cyberpunk-blink {
        0% {
            box-shadow: inset 0 0 0 1px var(--accent);
        }

        20% {
            box-shadow: inset 0 0 0 1px var(--primary);
        }

        40% {
            box-shadow: inset 0 0 0 1px var(--accent);
        }

        60%,
        100% {
            box-shadow: inset 0 0 0 1px var(--border);
        }
    }

    /* The stream through a running bar: the dashes move one period of 144 px along it. */
    @keyframes kp-sig-cyberpunk-feed {
        from {
            transform: translateX(0);
        }

        to {
            transform: translateX(144px);
        }
    }
}

/* ── The dashboard parts: what the package leaves to a register [kpadopt2-repairs] ──
   Formal keeps these parts exactly as Kenny approved them; this theme takes the three repairs the review asks for: a
   loading heat grid or matrix row as tall as its ready row (no skeleton gap between cells), an empty or failed run
   timeline with a lane-sized space for its sentence (never over the legend), the sentence as wide as its words on the
   theme's ground (never through a rule or a ghost bar), and an axis label near the end edge standing before its rule. */
@layer kp.signature {
    [data-theme='cyberpunk'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton {
        margin-block: 0;
    }
    [data-theme='cyberpunk'] .kp-gantt {
        --kp-gantt-tick-flip: 1;
    }
    [data-theme='cyberpunk'] .kp-gantt:is([data-kp-state='empty'], [data-kp-state='error']) .kp-gantt__body:not(:has(.kp-gantt__lane)) {
        min-block-size: 5.25rem;
    }
    [data-theme='cyberpunk'] .kp-gantt__state {
        box-sizing: border-box;
        display: block;
        inline-size: fit-content;
        max-inline-size: calc(100% - 2 * var(--kp-space-md, 0.75rem));
        block-size: fit-content;
        margin: auto;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--kp-gantt-state-ground, transparent);
    }
    /* The matrix's corner key breaks as two balanced lines when it has to, never leaving an arrow alone. */
    [data-theme='cyberpunk'] .kp-matrix__corner {
        text-wrap: balance;
    }
    /* A ghost bar stands where its run would, as in formal: absolute in its track, so a second ghost of one track never
       drops under the first and out of the timeline onto the legend. */
    [data-theme='cyberpunk'] .kp-gantt__ghost .kp-gantt__run.kp-skeleton {
        position: absolute;
    }
}

/* ── The six opt-in options of the dashboard adoption, round 3, in this theme [kpadopt3] ──
   The nav bar's separator, the timeline's day buttons and series runs, the week agenda's upcoming list on a phone and
   the facet swatch's identity pattern (the choice-filter value and the heat grid's End are behaviour only).
   Cyberpunk's own (themes/cyberpunk/CHARACTER.md): the separator is the neon slash, the yellow leaning with
   the bar's own cut and split into its cyan ghost (the RGB split); lying down in the phone's list it is a short data
   dash on the plate, yellow then a cyan packet, never wider than the plate. A day on the axis takes the RGB split under
   the pointer; pressed it is a lock-on: the yellow ground with its notched corner and the hard yellow foot. A series'
   finished run has the hard 3 px bar on its leading edge, as a week pill does; the facet pattern is notched. */
@layer kp.signature {
    [data-theme='cyberpunk'] .kp-nav__sep {
        inline-size: 2px;
        border-inline-start: 0;
        background: var(--primary);
        box-shadow: -2px 0 0 hsl(from var(--accent) h s l / 0.75);
        transform: skewX(-18deg);
    }
    @container kp-nav (max-width: 40rem) {
        [data-theme='cyberpunk'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep {
            inline-size: 3.25rem;
            block-size: 2px;
            margin-inline: var(--kp-space-lg, 1rem) auto;
            border-block-start: 0;
            background: linear-gradient(90deg, var(--primary) 0 68%, transparent 68% 76%, var(--accent) 76% 100%);
            box-shadow: none;
            transform: none;
        }
    }

    [data-theme='cyberpunk'] .kp-gantt__tick:is(button) {
        border-radius: 0;
        text-decoration: none;
    }
    [data-theme='cyberpunk'] .kp-gantt__tick:is(button):hover {
        color: var(--primary);
        text-shadow:
            -1px 0 hsl(from var(--accent) h s l / 0.9),
            1px 0 hsl(from var(--destructive) h s l / 0.9);
    }
    [data-theme='cyberpunk'] .kp-gantt__tick:is(button)[aria-pressed='true'] {
        background: linear-gradient(225deg, transparent 5px, hsl(from var(--primary) h s l / 0.18) 5px);
        color: var(--primary);
        box-shadow: inset 0 -2px 0 var(--primary);
        text-shadow: none;
    }
    [data-theme='cyberpunk'] .kp-gantt__run[data-kp-state='ok'][data-kp-series] {
        box-shadow: inset 3px 0 0 var(--kp-gantt-series);
    }
    [data-theme='cyberpunk'] .kp-gantt__run[data-kp-state='ok'][data-kp-series]:hover {
        box-shadow:
            inset 3px 0 0 var(--kp-gantt-series),
            0 0 0 1px var(--primary),
            0 0 8px hsl(from var(--primary) h s l / 0.5);
    }
    [data-theme='cyberpunk'] .kp-week__next:not(:has(+ .kp-week__next:not([data-kp-day-start]))) {
        border-block-end-color: var(--kp-hairline, var(--border));
    }
    [data-theme='cyberpunk'] .kp-facet__swatch[data-kp-facet-pattern] {
        border-radius: 0;
        clip-path: polygon(0 0, calc(100% - 4px) 0, 100% 4px, 100% 100%, 0 100%);
    }
}

@layer kp.register {
    /* @kp-soft/themes — css/synthwave-register.css
   The synthwave register, 5.0.0 [S48, LIFT_PLAN row 1]: the horizon
   register. Scoped to [data-theme='synthwave'] and inert elsewhere;
   opt-in, imported after themes.css. The approved concept demo ("Outrun
   Horizon", 2026-09-08) is the reference for every value here, and
   docs/archive/RESEARCH_2026-09.md §25 is where each mechanism was measured.

   Cyberpunk is diagonal and day; synthwave is horizontal and night. What
   this file does, in order: the knobs and the texture; the type; the
   hooks of S45 — the chrome headline with its tracking wipe and shine,
   the neon tube that a <mark> switches on, the laser line under a
   heading, the horizon as divider; the hero's sky, sun and floor; the
   navbar; the buttons; the fields; and one answer per component root
   (TH124). The reveals have their rest state here and their motion in
   js/effects.js; without the script every one of them stands at rest.

   Colour discipline (DI9): nothing here names a colour. Every paint is a
   token or a relative colour of one. The neon rule of Synthwave '84 is
   kept throughout: the core of a glowing element is near-white and the
   colour lives in its shadow, so every core passes contrast on its own.

   Nothing here flickers. The references' CRT flicker (133/s) and the sun
   that snaps once a second were measured and refused (DI5); the floor
   drifts one cell per six seconds and never changes luminance. */

    [data-theme='synthwave'] {
        /* The month heatmap's nav goes on two rows below this width: the
           widest month and the three buttons in this type [fix-98]. */
        --kp-calendar-nav-fit: 31.75rem;
        /* The configuration surface [AR43], the demo's values as defaults. */
        --kp-nav-enter: 520ms;
        --kp-nav-enter-delay: 80ms;
        --kp-reveal-threshold: 0.6;
        --kp-reveal-stagger: 420ms;
        --kp-redact-stagger: 160ms;
        --kp-classified-delay: 900ms;
        --kp-wipe: 720ms;
        --kp-rule-draw: 900ms;
        --kp-rule-weight: 2px;
        --kp-tracking: 700ms;
        --kp-shine: 1400ms;
        --kp-tube-on: 1100ms;
        --kp-sun-cut: 360ms;
        --kp-floor-drift: 6s;
        --kp-floor-cell: 7vw 6vw;
        --kp-horizon-height: 56px;
        --kp-sun-size: min(38vmin, 340px);
        --kp-boot: 550ms;
        /* The reveals this theme performs [S45]: js/effects.js reads these
           and leaves a theme that declares none at rest. */
        --kp-reveal-headline: tracking;
        --kp-reveal-emphasis: tube;
        --kp-reveal-rule: laser;
        --kp-arrival: boot;
        /* The OSD face for labels, identifiers and timestamps is the theme's
           mono token (VT323); the data face is Share Tech Mono, under Q1's
           name. */
        --kp-osd: var(--theme-font-mono);
        --kp-mono: 'KP Tech Mono', 'Share Tech Mono', 'JetBrains Mono', ui-monospace, Menlo, monospace;
        /* The pink that reads as text: the hero's second ink, 8.9:1 on the
           void and 6.9:1 on the tape (the reference pink fails at 4.34). */
        --kp-pink-text: var(--surface-hero-fg-2);
        --kp-hairline: hsl(from var(--kp-pink-text) h s l / 0.25);
        /* The neon rest stacks (Synthwave '84): a near-white core, the
           colour in the shadow. */
        --kp-tube-pink:
            0 0 2px var(--sidebar-background), 0 0 6px hsl(from var(--primary) h s l / 0.7), 0 0 14px hsl(from var(--primary) h s l / 0.55),
            0 0 28px hsl(from var(--primary) h s l / 0.3);
        --kp-tube-cyan:
            0 0 2px var(--sidebar-background), 0 0 4px hsl(from var(--accent) h s l / 0.8), 0 0 10px hsl(from var(--accent) h s l / 0.5),
            0 0 22px hsl(from var(--accent) h s l / 0.3);
        --kp-tube-laser: 0 0 2px var(--sidebar-background), 0 0 8px hsl(from var(--warning-foreground) h s l / 0.6);
        --kp-core: hsl(from var(--foreground) h 20% 98%);
        /* The stripe of the '84 active tab: pink to cyan, 4px. */
        --kp-stripe: linear-gradient(to right, var(--kp-stripe-from), var(--kp-stripe-to));
        /* The sky, the sun and the chrome, derived from the tokens. Every
           stop of the sky is dark enough for lavender text (4.5:1 and up),
           because the hero's ground is measured on the rendered page. */
        --kp-sky-1: hsl(from var(--surface-hero-bg) calc(h - 26) 69% 15%);
        --kp-sky-2: hsl(from var(--surface-hero-bg) calc(h + 22) 68% 22%);
        --kp-sky-3: hsl(from var(--primary) h 65% 32%);
        --kp-sun-top: hsl(from var(--warning-foreground) calc(h - 5) s calc(l - 9));
        --kp-sun-bottom: hsl(from var(--primary) calc(h - 34) s l);
        --kp-sun-glow: hsl(from var(--destructive) h 95% 52%);
        --kp-grid: hsl(from var(--kp-pink-text) h s l / 0.55);
        --kp-chrome-1: hsl(from var(--accent) 205 65% 48%);
        --kp-chrome-2: hsl(from var(--foreground) 205 40% 88%);
        --kp-chrome-3: hsl(from var(--primary) 330 43% 24%);
        --kp-chrome-4: hsl(from var(--primary) 330 38% 54%);

        /* The texture [DI9, AR46]: a static VHS screen-door — a 2px row
           raster and a 3px RGB stripe (nightride.fm's overlay) — at DI9's
           ceiling and not a hair over. It never moves. */
        --fx-texture:
            linear-gradient(hsl(from var(--sidebar-background) h s l / 0) 50%, hsl(from var(--sidebar-background) h s l / 0.06) 50%),
            linear-gradient(
                90deg,
                hsl(from var(--destructive) h s l / 0.03),
                hsl(from var(--success-foreground) h s l / 0.01),
                hsl(from var(--chart-4) h s l / 0.03)
            );
        --fx-texture-size: 100% 2px, 3px 100%;
        --fx-texture-opacity: 1;

        /* The decided grammar [Kenny, 2026-10-07, research/synthwave-character
           and research/synthwave-anchor; themes/synthwave/CHARACTER.md §0].
           Durations are beats of 225 ms: contact 1, an opening 2, a live
           change 3, an arrival or a leave 4, the spinner 8. Bodies glide on
           the sunrise curve (the tube leads, the bodies follow a beat behind);
           light switches in hard steps. */
        --kp-sw-beat: 225ms;
        --kp-sw-sun: cubic-bezier(0.65, 0, 0.35, 1);
        /* js/motion.js reads its caps from the root: a close of two beats and
           a size glide of two beats are not cut short (its defaults, 600 and
           480 ms, are other themes'). */
        --kp-close-max: 450ms;
        --kp-size-max: 450ms;
        /* The page horizon [the anchor, 2026-10-07 21:21]: one tube for the
           page on the header's foot, the floor under it; every plate carries
           1 px of its light on its top edge and the sides run down from the
           colours of the stripe they touch. */
        --kp-sw-floor: 1.35rem;
        --kp-sw-floor-page: 8.5rem;
        --kp-sw-side: 3px;
        --kp-sw-rail: 3px;
        /* Focus is two tubes, top and foot, plus a hairline each side [G14,
           DI2]: a near-white tube with a dark channel beside it above and
           below (the light and the dark, never colour alone), the sides a
           hairline of the ring's colour. `-in` lives inside the part (a
           framed control, a row, a cell, which a scroller or a neighbour
           could cut); `-out` stands outside it (a link, a plate, a mark small
           enough that the rails would cover it). */
        --kp-sw-rails-in:
            inset 0 var(--kp-sw-rail) 0 0 var(--kp-core), inset 0 calc(var(--kp-sw-rail) * 2) 0 0 var(--focus-ring-contrast),
            inset 0 calc(var(--kp-sw-rail) * -1) 0 0 var(--kp-core), inset 0 calc(var(--kp-sw-rail) * -2) 0 0 var(--focus-ring-contrast),
            inset 1px 0 0 0 var(--focus-ring), inset -1px 0 0 0 var(--focus-ring);
        --kp-sw-rails-out:
            0 calc(var(--kp-sw-rail) * -1) 0 0 var(--kp-core), 0 calc(var(--kp-sw-rail) * -2) 0 0 var(--focus-ring-contrast),
            0 var(--kp-sw-rail) 0 0 var(--kp-core), 0 calc(var(--kp-sw-rail) * 2) 0 0 var(--focus-ring-contrast), -1px 0 0 0 var(--focus-ring),
            1px 0 0 0 var(--focus-ring);
        --kp-stripe-from: var(--primary);
        --kp-stripe-to: var(--accent);
        --kp-sw-tube: 0 0 2px var(--sidebar-background), 0 0 6px hsl(from var(--primary) h s l / 0.6), 0 0 14px hsl(from var(--primary) h s l / 0.3);
        --kp-sw-tube-up:
            0 0 2px var(--sidebar-background), 0 0 7px hsl(from var(--primary) h s l / 0.95), 0 0 18px hsl(from var(--primary) h s l / 0.65),
            0 0 34px hsl(from var(--primary) h s l / 0.4);
        --kp-sw-laser: 0 0 4px var(--primary), 0 0 10px hsl(from var(--primary) h s l / 0.8), 0 0 22px hsl(from var(--primary) h s l / 0.45);
        /* The sun's ramp as the bar draws it, looping: pink, laser yellow, pink. */
        --kp-sw-ramp-loop: linear-gradient(
            90deg,
            var(--kp-sun-bottom),
            var(--primary) 25%,
            var(--kp-sun-top) 50%,
            var(--primary) 75%,
            var(--kp-sun-bottom)
        );
        /* The sun's slab, its stripes bands in the void's colour. */
        --kp-sw-void: var(--sidebar-background);
        --kp-sw-sun-v: linear-gradient(
            180deg,
            var(--kp-sun-top),
            color-mix(in oklab, var(--kp-sun-top) 45%, var(--kp-sun-bottom)),
            var(--kp-sun-bottom)
        );
        --kp-sw-sun-cuts: linear-gradient(
            to bottom,
            transparent 0 52%,
            var(--kp-sw-void) 52% 58%,
            transparent 58% 68%,
            var(--kp-sw-void) 68% 76%,
            transparent 76% 84%,
            var(--kp-sw-void) 84% 93%,
            transparent 93%
        );
        /* The grid floor under a plate's horizon: lines closing toward the
           horizon and lines converging on its centre (G7). */
        --kp-sw-floor-lines:
            linear-gradient(hsl(from var(--primary) h s l / 0.32) 0 0) 0 16% / 100% 1px no-repeat,
            linear-gradient(hsl(from var(--primary) h s l / 0.34) 0 0) 0 38% / 100% 1px no-repeat,
            linear-gradient(hsl(from var(--primary) h s l / 0.36) 0 0) 0 66% / 100% 1px no-repeat,
            linear-gradient(hsl(from var(--primary) h s l / 0.38) 0 0) 0 100% / 100% 1px no-repeat,
            repeating-conic-gradient(from 180deg at 50% -25%, hsl(from var(--primary) h s l / 0.45) 0 0.7deg, transparent 0.7deg 9deg);
    }

    /* ── Type ──────────────────────────────────────────────────────────── */

    [data-theme='synthwave'] h1,
    [data-theme='synthwave'] h2,
    [data-theme='synthwave'] h3 {
        font-family: var(--theme-font-display);
        text-transform: uppercase;
        letter-spacing: 0.08em;
    }

    /* Microlabels: the OSD face, pink, with the tape prefix. */
    [data-theme='synthwave'] .microlabel {
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
        line-height: 1;
    }

    [data-theme='synthwave'] .microlabel::before {
        content: '▶ ';
        color: var(--accent);
    }

    /* ── The hooks [S45]: the heading accent, the mark, the rule, the divider ── */

    /* The heading accent: a display headline at the display step (S47),
       in chrome — the 50/51 break of the genre's title treatment, a
       stroke of near-white, an extrusion below. */
    [data-theme='synthwave'] [data-kp-surface] h1 {
        font-weight: 900;
        letter-spacing: 0.06em;
        margin-block: 0 0.4em;
        text-wrap: balance;
        position: relative;
        background: linear-gradient(
            180deg,
            var(--kp-chrome-1) 0%,
            var(--kp-chrome-2) 50%,
            var(--kp-chrome-3) 51%,
            var(--kp-chrome-4) 55%,
            var(--kp-chrome-3) 59%,
            var(--kp-chrome-4) 65%,
            var(--kp-chrome-4) 75%,
            var(--kp-core) 100%
        );
        -webkit-background-clip: text;
        background-clip: text;
        -webkit-text-fill-color: transparent;
        -webkit-text-stroke: 1px hsl(from var(--kp-core) h s l / 0.35);
        filter: drop-shadow(0 2px 0 hsl(from var(--kp-chrome-1) h s l / 0.6)) drop-shadow(0 4px 12px hsl(from var(--sidebar-background) h s l / 0.5));
    }

    /* A section heading is a cyan tube: near-white core, cyan glow. */
    [data-theme='synthwave'] [data-kp-surface] h2 {
        font-weight: 700;
        color: var(--kp-core);
        text-shadow: var(--kp-tube-cyan);
    }

    [data-theme='synthwave'] [data-kp-reveal='headline'] {
        position: relative;
    }

    /* The headline reveal: one tracking wipe (a band of the text slides
       sideways with an RGB fringe, six steps, once — a VHS head losing the
       picture for a beat), then one shine across the chrome. The copies
       read `data-kp-text`, which the effects module writes. */
    [data-theme='synthwave'] [data-kp-reveal='headline']::before,
    [data-theme='synthwave'] [data-kp-reveal='headline']::after {
        content: attr(data-kp-text);
        position: absolute;
        inset: 0;
        opacity: 0;
        pointer-events: none;
        white-space: pre-wrap;
    }

    [data-theme='synthwave'] [data-kp-reveal='headline']::before {
        -webkit-text-fill-color: var(--kp-core);
        text-shadow: var(--kp-tube-pink);
    }

    [data-theme='synthwave'] [data-kp-reveal='headline']::after {
        opacity: 1;
        background: linear-gradient(225deg, transparent 47%, hsl(from var(--kp-core) h s l / 0.85) 50%, transparent 53%);
        background-size: 400% 400%;
        background-position: 100% 100%;
        -webkit-background-clip: text;
        background-clip: text;
        -webkit-text-fill-color: transparent;
    }

    /* The laser line under a section heading draws from the centre
       outward when the heading enters the viewport (C3). Without the
       script — no data-kp-effects on the root — it stands drawn. */
    [data-theme='synthwave'] [data-kp-reveal='rule']::after {
        content: '';
        display: block;
        height: var(--kp-rule-weight);
        margin-top: 0.5rem;
        /* The laser is the pink of a signal [G5, colour = roles]: laser yellow
           stays for a warning and inside the sun's ramp. */
        background: linear-gradient(to right, transparent, var(--primary) 20%, var(--primary) 80%, transparent);
        box-shadow: 0 0 8px hsl(from var(--primary) h s l / 0.6);
        transform-origin: center;
    }

    [data-theme='synthwave'][data-kp-effects] [data-kp-reveal='rule']:not(.is-in)::after {
        transform: scaleX(0);
    }

    /* The mark: emphasis is a neon tube. At rest it is on — near-white
       core, pink glow. With the script armed it is dark glass until the
       module switches it on, one after another, with two dips on the way
       with one dip on the way (2.7/s, under DI5's three). */
    [data-theme='synthwave'] mark {
        background: none;
        color: var(--kp-core);
        font-weight: 700;
        white-space: nowrap;
        text-shadow: var(--kp-tube-pink);
    }

    [data-theme='synthwave'][data-kp-effects] mark:not(.is-cleared) {
        color: hsl(from var(--foreground) h s l / 0.4);
        text-shadow: none;
    }

    /* The divider: the horizon [TH121]. A magenta line with its triple
       glow across the top, and a short grid ramp receding under it: rows
       spaced by the square rule, verticals converging on the centre. */
    [data-theme='synthwave'] [data-kp-divider] {
        display: block;
        position: relative;
        block-size: var(--kp-horizon-height);
        background: var(--background);
        overflow: hidden;
        isolation: isolate;
    }

    [data-theme='synthwave'] [data-kp-divider]::before {
        content: '';
        position: absolute;
        inset: 10px 0 auto;
        height: 2px;
        background: var(--kp-pink-text);
        box-shadow:
            0 0 12px var(--primary),
            0 0 32px hsl(from var(--primary) h s l / 0.6),
            0 -6px 40px hsl(from var(--accent) h s l / 0.35);
        z-index: 1;
    }

    [data-theme='synthwave'] [data-kp-divider]::after {
        content: '';
        position: absolute;
        inset: 12px -30% 0;
        background:
            repeating-linear-gradient(to bottom, var(--kp-grid) 0 1px, transparent 1px 9px),
            repeating-linear-gradient(to right, var(--kp-grid) 0 1px, transparent 1px 120px);
        transform-origin: 50% 0;
        transform: perspective(90px) rotateX(58deg);
        opacity: 0.6;
        mask-image: linear-gradient(to bottom, hsl(from var(--sidebar-background) h s l) 0, transparent 100%);
    }

    [data-theme='synthwave'] [data-kp-surface='app'] + [data-kp-divider] {
        background: var(--sidebar-background);
    }

    /* ── The hero: the sky, the sun, the floor ────────────────────────── */

    /* The section's own ground is the sky ramp with every stop dark; the
       sun and the floor are pseudo-elements, so the ground a text is
       measured against stays the ramp. The two-colour inset vignette of
       the reference sits on the section. */
    [data-theme='synthwave'] [data-kp-surface='hero'] {
        position: relative;
        overflow: hidden;
        isolation: isolate;
        padding-block: 3.2rem 5rem;
        background: linear-gradient(
            to bottom,
            var(--background) 0,
            var(--kp-sky-1) 22%,
            var(--kp-sky-2) 45%,
            var(--kp-sky-3) 62%,
            var(--kp-sky-1) 66%,
            var(--surface-hero-bg) 100%
        );
        box-shadow:
            inset 0 0 50px 1px hsl(from var(--accent) h s l / 0.22),
            inset 0 0 120px 1px hsl(from var(--kp-sun-bottom) h s l / 0.35);
    }

    /* The sun: a disc from amber to magenta, cut by a mask whose bands
       follow Argyle's rule (band n = n%, gap = (8 − n)%), static. */
    [data-theme='synthwave'] [data-kp-surface='hero']::before {
        content: '';
        position: absolute;
        left: 60%;
        top: 4%;
        width: var(--kp-sun-size);
        aspect-ratio: 1;
        translate: -50% 0;
        border-radius: 50%;
        background: linear-gradient(var(--kp-sun-top), var(--kp-sun-bottom));
        filter: drop-shadow(0 0 1.5rem var(--kp-sun-glow));
        mask-image: linear-gradient(
            to top,
            var(--sidebar-background) 1%,
            0%,
            transparent 8%,
            0%,
            var(--sidebar-background) 10%,
            0%,
            transparent 16%,
            0%,
            var(--sidebar-background) 19%,
            0%,
            transparent 24%,
            0%,
            var(--sidebar-background) 28%,
            0%,
            transparent 32%,
            0%,
            var(--sidebar-background) 37%,
            0%,
            transparent 40%,
            0%,
            var(--sidebar-background) 46%,
            0%,
            transparent 48%,
            0%,
            var(--sidebar-background) 55%,
            0%,
            transparent 56%,
            0%,
            var(--sidebar-background) 57%
        );
        z-index: -2;
        pointer-events: none;
    }

    /* The floor: a conic-gradient grid under rotateX with the three
       horizon glows; it drifts one cell per six seconds, seamless, and
       fades before it reaches the text. */
    [data-theme='synthwave'] [data-kp-surface='hero']::after {
        content: '';
        position: absolute;
        left: -30%;
        right: -30%;
        top: 70%;
        height: 60%;
        background: conic-gradient(from 90deg at 1px 1px, transparent 90deg, var(--kp-grid) 0) 0 0 / var(--kp-floor-cell);
        transform-origin: 50% 0;
        transform: perspective(60vh) rotateX(74deg);
        border-top: 1px solid var(--kp-pink-text);
        box-shadow:
            0 -40px 60px hsl(from var(--kp-pink-text) h s l / 0.35),
            -70px -60px 80px hsl(from var(--accent) h s l / 0.18),
            70px -60px 80px hsl(from var(--accent) h s l / 0.18);
        mask-image: linear-gradient(to bottom, var(--sidebar-background) 0, var(--sidebar-background) 60%, transparent);
        z-index: -1;
        pointer-events: none;
    }

    [data-theme='synthwave'] [data-kp-surface='hero'] [data-kp-hero-grid] {
        grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
        gap: 3rem;
        align-items: end;
    }

    @container (max-width: 52rem) {
        [data-theme='synthwave'] [data-kp-surface='hero'] [data-kp-hero-grid] {
            grid-template-columns: 1fr;
        }
    }

    /* ── The navbar: a flat bar, the stripe under the active item ─────── */

    [data-theme='synthwave'] .kp-nav-wrap {
        background: var(--background);
    }

    [data-theme='synthwave'] .kp-nav {
        background: var(--background);
        border-bottom: 1px solid hsl(from var(--foreground) h s l / 0.08);
        padding-block: calc(var(--kp-nav-pad-block, 1.1rem) * var(--kp-nav-pad-scale, 1))
            calc(var(--kp-nav-pad-block, 0px) * var(--kp-nav-pad-scale, 1));
        position: relative;
        /* Its own stacking context for the bar's decorations; the layer is the
         * wrapper's, from the base [scope-48]. */
        isolation: isolate;
    }

    /* The brand in small chrome. */
    [data-theme='synthwave'] .kp-nav__brand {
        font-family: var(--theme-font-display);
        font-weight: 900;
        font-size: 1.5rem;
        letter-spacing: 0.08em;
        line-height: 1;
        text-transform: uppercase;
        text-decoration: none;
        padding-bottom: 0.9rem;
        background: linear-gradient(
            180deg,
            var(--kp-core) 0%,
            var(--kp-chrome-2) 50%,
            var(--kp-chrome-3) 51%,
            var(--kp-chrome-4) 60%,
            var(--kp-core) 100%
        );
        -webkit-background-clip: text;
        background-clip: text;
        -webkit-text-fill-color: transparent;
    }

    [data-theme='synthwave'] .kp-nav__links {
        gap: 0;
    }

    [data-theme='synthwave'] .kp-nav__link {
        display: block;
        padding-inline: 1.1rem;
        font-weight: 600;
        letter-spacing: 0.18em;
        text-transform: uppercase;
        color: var(--foreground);
        text-decoration: none;
        position: relative;
        border-radius: 0;
    }

    /* The 4px pink→cyan stripe of Synthwave '84's active tab, with its
       underglow, on the current item and on hover. */
    [data-theme='synthwave'] .kp-nav__link::after {
        content: '';
        position: absolute;
        left: 0.6rem;
        right: 0.6rem;
        bottom: 0;
        height: 4px;
        background: var(--kp-stripe);
        transform: scaleX(0);
        transform-origin: left center;
    }

    [data-theme='synthwave'] .kp-nav__link:hover,
    [data-theme='synthwave'] .kp-nav__link:focus-visible,
    [data-theme='synthwave'] .kp-nav__link[aria-current],
    [data-theme='synthwave'] .kp-nav__links > li:focus-within > .kp-nav__link {
        color: var(--kp-core);
        background: none;
        box-shadow: inset 0 -5px 25px hsl(from var(--primary) h s l / 0.15);
    }

    /* The keyboard keeps its ring [fix-38, DI2]: the glow above replaced
       the ring on a focused link, so the two tubes are restated beside the
       glow [G14]. */
    [data-theme='synthwave'] .kp-nav__links > li > .kp-nav__link:focus-visible {
        outline: none;
        box-shadow:
            var(--kp-sw-rails-in),
            inset 0 -5px 25px hsl(from var(--primary) h s l / 0.15);
    }

    [data-theme='synthwave'] .kp-nav__link:hover::after,
    [data-theme='synthwave'] .kp-nav__link:focus-visible::after,
    [data-theme='synthwave'] .kp-nav__link[aria-current]::after,
    [data-theme='synthwave'] .kp-nav__links > li:focus-within > .kp-nav__link::after {
        transform: scaleX(1);
    }

    [data-theme='synthwave'] .kp-nav__link[aria-haspopup]::before {
        content: '▾ ';
        color: var(--accent);
    }

    [data-theme='synthwave'] .kp-nav__link--lang {
        border-left: 1px solid hsl(from var(--foreground) h s l / 0.18);
        margin-left: 0.4rem;
    }

    /* The call to action is a neon frame. */
    [data-theme='synthwave'] .kp-nav__link--cta {
        margin-left: 0.6rem;
        padding-inline: 1.3rem;
        border: 2px solid var(--primary);
        border-radius: var(--radius);
        color: var(--kp-core);
        text-shadow: var(--kp-tube-pink);
        box-shadow:
            inset 0 0 0.5em 0 hsl(from var(--primary) h s l / 0.35),
            0 0 0.5em 0 hsl(from var(--primary) h s l / 0.35);
        align-self: center;
    }

    [data-theme='synthwave'] .kp-nav__link--cta::after {
        display: none;
    }

    [data-theme='synthwave'] .kp-nav__link--cta:hover {
        box-shadow:
            inset 0 0 0.7em 0 hsl(from var(--primary) h s l / 0.55),
            0 0 1.4em 0 hsl(from var(--primary) h s l / 0.55);
    }

    /* The dropdown: a tape panel with the stripe on top, ▶ before every item. */
    [data-theme='synthwave'] .kp-nav__menu {
        background: var(--card);
        border: 1px solid var(--kp-hairline);
        border-top: 4px solid transparent;
        border-image: var(--kp-stripe) 1;
        border-radius: 0;
        padding: 0.5rem 0;
        min-width: 13rem;
        box-shadow: 0 12px 40px hsl(from var(--sidebar-background) h s l / 0.6);
    }

    /* Collapsed, the dropdown is a list in the flow, not a panel [gap-12]:
       the rule above dresses the floating panel in kp.register, which
       beats the reset in kp.components, so the reset is restated here. */
    @container kp-nav (max-width: 40rem) {
        [data-theme='synthwave'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__menu {
            min-width: 0;
            padding-inline-start: var(--kp-nav-menu-indent, 1rem);
            border: 0;
            background: transparent;
            box-shadow: none;
        }
    }

    [data-theme='synthwave'] .kp-nav__menu a {
        display: block;
        padding-inline: 1rem;
        letter-spacing: 0.14em;
        text-transform: uppercase;
        color: var(--foreground);
        text-decoration: none;
    }

    [data-theme='synthwave'] .kp-nav__menu a::before {
        content: '▶ ';
        color: var(--accent);
        font-family: var(--kp-osd);
    }

    [data-theme='synthwave'] .kp-nav__menu a:hover,
    [data-theme='synthwave'] .kp-nav__menu a:focus-visible {
        color: var(--kp-core);
        background: var(--popover);
        text-shadow: var(--kp-tube-pink);
    }

    /* ── Buttons: square, a 2px neon frame, the sun cut on hover ──────── */

    [data-theme='synthwave'] .kp-button {
        --kp-frame: var(--primary);
        --kp-glow: hsl(from var(--primary) h s l / 0.45);
        position: relative;
        padding-inline: 1.8rem;
        font-weight: 700;
        font-size: 0.95rem;
        letter-spacing: 0.16em;
        text-transform: uppercase;
        color: var(--kp-core);
        background: transparent;
        border: 2px solid var(--kp-frame);
        border-radius: var(--radius);
        isolation: isolate;
        text-shadow: var(--kp-tube-pink);
        box-shadow:
            inset 0 0 0.5em 0 var(--kp-glow),
            0 0 0.5em 0 var(--kp-glow);
    }

    /* Pointing turns the tube up [G8, hover = tube; Kenny, 2026-10-07]: the
       bloom widens in one step and the sun cut crosses once. Nothing lifts. */
    [data-theme='synthwave'] .kp-button:hover {
        background: transparent;
        box-shadow:
            inset 0 0 0.7em 0 var(--kp-glow),
            0 0 1.6em 0 var(--kp-glow);
    }

    /* A press charges the piece [G14, press = charge]: the part's own top
       edge burns near-white with the bloom gathered above it, and its ground
       takes the pressed token; nothing moves. Held for as long as the press
       lasts. The focus ring below wins when the key is what presses. */
    [data-theme='synthwave'] .kp-button:active:not(:disabled) {
        background-color: var(--secondary-active);
        box-shadow:
            inset 0 2px 0 0 var(--kp-core),
            0 -4px 14px 0 hsl(from var(--primary) h s l / 0.8);
    }

    /* The demo's call-to-action row: wide buttons, as in the reference. A
       pager's or a menu's button keeps its own width (DI11 at 320 px). */
    [data-theme='synthwave'] [data-kp-surface='hero'] .kp-row > .kp-button {
        min-width: 13rem;
    }

    /* The focus ring is two tubes, top and foot [G14, focus = rails]: a
       near-white tube with a dark channel beside it above and below, the
       sides a hairline of the ring's colour. Two channels (the light and the
       dark, the rails themselves), never colour alone (DI2). It lives inside
       the frame, so the glow outside never covers a half of it (AR30). */
    [data-theme='synthwave'] .kp-button:focus-visible {
        outline: none;
        box-shadow:
            var(--kp-sw-rails-in),
            0 0 12px 0 hsl(from var(--primary) h s l / 0.6);
    }

    /* The sun cut: two horizontal slits in the ground's colour cross the
       button once on hover — the sun's stripes, borrowed for a beat. */
    [data-theme='synthwave'] .kp-button::before,
    [data-theme='synthwave'] .kp-button::after {
        content: '';
        position: absolute;
        /* The slit runs from the padding box's edges and reaches the 4 px past them
           with a side shadow, not with `left` / `right: -4px`: a box that sticks out is
           scrollable overflow, so every button measured 4 px of `scrollWidth` over
           its `clientWidth` and read as a cut label, while the paint is identical. */
        left: 0;
        right: 0;
        height: 3px;
        background: var(--kp-sw-cut-ink, var(--background));
        box-shadow:
            -4px 0 0 0 var(--kp-sw-cut-ink, var(--background)),
            4px 0 0 0 var(--kp-sw-cut-ink, var(--background));
        opacity: 0;
        pointer-events: none;
    }

    [data-theme='synthwave'] .kp-button::before {
        top: 34%;
    }

    [data-theme='synthwave'] .kp-button::after {
        top: 58%;
    }

    [data-theme='synthwave'] .kp-card .kp-button::before,
    [data-theme='synthwave'] .kp-card .kp-button::after {
        --kp-sw-cut-ink: var(--card);
    }

    [data-theme='synthwave'] .kp-button--primary {
        background: var(--primary);
        color: var(--primary-foreground);
        text-shadow: none;
    }

    [data-theme='synthwave'] .kp-button--primary:hover {
        background: hsl(from var(--primary) h s calc(l + 6));
    }

    [data-theme='synthwave'] .kp-button--destructive {
        --kp-frame: var(--destructive);
        --kp-glow: hsl(from var(--destructive) h s l / 0.4);
        background: transparent;
        color: var(--kp-core);
        text-shadow:
            0 0 2px var(--sidebar-background),
            0 0 8px hsl(from var(--destructive) h s l / 0.6);
    }

    [data-theme='synthwave'] .kp-button--ghost {
        --kp-frame: transparent;
        box-shadow: none;
    }

    [data-theme='synthwave'] .kp-button--ghost:hover {
        --kp-frame: var(--kp-hairline);
    }

    [data-theme='synthwave'] .kp-button:disabled {
        opacity: 0.45;
    }

    [data-theme='synthwave'] .kp-button--sm {
        min-width: 0;
        padding-inline: 1rem;
    }

    /* Pink acts [G5, colour = roles]: an icon button is something a person
       presses, so it takes the pink that reads; cyan is for what is read out. */
    [data-theme='synthwave'] .kp-icon-button {
        border: 2px solid var(--kp-hairline);
        border-radius: var(--radius);
        color: var(--kp-pink-text);
    }

    /* On an alert the close button sits on the alert's own plate, in the
       alert's ink, the way it does on a toast [fix-95]. */
    [data-theme='synthwave'] .kp-alert .kp-icon-button {
        background: transparent;
        border-color: transparent;
        color: inherit;
    }

    [data-theme='synthwave'] .kp-icon-button:hover {
        border-color: var(--primary);
        box-shadow: 0 0 0.6em hsl(from var(--primary) h s l / 0.4);
    }

    [data-theme='synthwave'] .kp-icon-button:focus-visible {
        outline: none;
        box-shadow:
            var(--kp-sw-rails-in),
            0 0 12px 0 hsl(from var(--primary) h s l / 0.6);
    }

    /* ── Fields ───────────────────────────────────────────────────────── */

    [data-theme='synthwave'] .kp-field__label {
        font-family: var(--kp-osd);
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
    }

    [data-theme='synthwave'] .kp-field__label::before {
        content: '▶ ';
        color: var(--accent);
    }

    [data-theme='synthwave'] .kp-field__input {
        font-weight: 500;
        background: var(--sidebar-background);
        border: 2px solid hsl(from var(--kp-pink-text) h s l / 0.35);
        border-radius: var(--radius);
        padding-inline: 0.9rem;
        caret-color: var(--accent);
    }

    /* The same two tubes round the field [G14, DI2]: it is a part like any
       other, so its ring is the button's. */
    [data-theme='synthwave'] .kp-field__input:focus-visible {
        outline: none;
        border-color: var(--focus-ring);
        box-shadow:
            var(--kp-sw-rails-in),
            0 0 14px hsl(from var(--primary) h s l / 0.35);
    }

    [data-theme='synthwave'] select.kp-field__input::picker-icon {
        color: var(--accent);
    }

    [data-theme='synthwave'] .kp-field__help {
        font-family: var(--kp-osd);
        letter-spacing: 0.06em;
    }

    [data-theme='synthwave'] .kp-field--invalid .kp-field__input {
        border-color: var(--warning-foreground);
        box-shadow: 0 0 0 1px var(--warning-foreground);
    }

    [data-theme='synthwave'] .kp-field__error {
        font-family: var(--kp-osd);
        color: var(--warning-foreground);
    }

    [data-theme='synthwave'] .kp-field__error::before {
        content: '!! ';
    }

    [data-theme='synthwave'] .kp-field__check {
        box-shadow: 0 0 6px hsl(from var(--primary) h s l / 0.4);
    }

    [data-theme='synthwave'] .kp-field__check:checked {
        background: var(--sidebar-background);
        border-color: var(--primary);
        box-shadow:
            inset 0 0 0 3px var(--sidebar-background),
            inset 0 0 0 8px var(--accent),
            0 0 8px var(--accent);
    }

    [data-theme='synthwave'] .kp-fieldset {
        border: 1px solid var(--kp-hairline);
        border-radius: var(--radius);
    }

    /* The switch [gap-11], in the checkbox's voice: the theme's radius on a
       primary-edged track over the sidebar's night with a faint glow, and
       a thumb that lights in the accent with its own glow once on. */
    [data-theme='synthwave'] .kp-switch {
        --kp-switch-border: 2px;
    }

    [data-theme='synthwave'] .kp-switch__input {
        box-shadow: 0 0 6px hsl(from var(--primary) h s l / 0.4);
    }

    [data-theme='synthwave'] .kp-form__summary {
        border-left: 4px solid transparent;
        border-image: var(--kp-stripe) 1;
        background: var(--card);
    }

    /* ── The page horizon [the anchor, Kenny, 2026-10-07 21:21] ───────────
       One neon tube for the page on the header's foot, the floor under it,
       every plate carrying 1 px of its light on its top edge (the lit line
       under its stripe), and, under a hand, a brighter piece of the tube
       exactly as wide as the part touched. The header draws all of it: the
       tube on its `::after`, the floor and the far cyan line on its `::before`
       (8.5 rem deep under the tube, at z-index -1 inside the header's own
       stacking context, so it lies BEHIND the plates: the header reserves
       nothing and whatever follows it is positioned, at no specificity, so
       it paints above the floor [Kenny, 2026-10-08 01:00]),
       the piece on the inner grid's `::after`, positioned by the hovered
       action through anchor positioning. Every action lights its piece, the
       popover's trigger included. ───────────────────────────────────────── */

    [data-theme='synthwave'] .kp-page-header {
        position: relative;
        padding-block-end: 0.75rem;
    }

    [data-theme='synthwave'] .kp-page-header::after {
        content: '';
        position: absolute;
        inset: auto 0 0;
        z-index: 1;
        block-size: 3px;
        background: var(--kp-core);
        box-shadow: var(--kp-sw-tube);
        pointer-events: none;
    }

    [data-theme='synthwave'] .kp-page-header::before {
        content: '';
        position: absolute;
        inset: 100% 0 auto;
        z-index: -1;
        block-size: var(--kp-sw-floor-page);
        background:
            linear-gradient(hsl(from var(--accent) h s l / 0.7) 0 0) 0 6px / 100% 1px no-repeat,
            linear-gradient(hsl(from var(--primary) h s l / 0.3) 0 0) 0 1.6% / 100% 1px no-repeat,
            linear-gradient(hsl(from var(--primary) h s l / 0.31) 0 0) 0 6.2% / 100% 1px no-repeat,
            linear-gradient(hsl(from var(--primary) h s l / 0.33) 0 0) 0 14.1% / 100% 1px no-repeat,
            linear-gradient(hsl(from var(--primary) h s l / 0.34) 0 0) 0 25% / 100% 1px no-repeat,
            linear-gradient(hsl(from var(--primary) h s l / 0.35) 0 0) 0 39.1% / 100% 1px no-repeat,
            linear-gradient(hsl(from var(--primary) h s l / 0.37) 0 0) 0 56.2% / 100% 1px no-repeat,
            linear-gradient(hsl(from var(--primary) h s l / 0.38) 0 0) 0 76.6% / 100% 1px no-repeat,
            linear-gradient(hsl(from var(--primary) h s l / 0.4) 0 0) 0 100% / 100% 1px no-repeat,
            repeating-conic-gradient(from 180deg at 50% -25%, hsl(from var(--primary) h s l / 0.45) 0 0.7deg, transparent 0.7deg 9deg);
        mask-image: linear-gradient(to bottom, var(--sidebar-background) 0, var(--sidebar-background) 20%, transparent 95%);
        pointer-events: none;
    }

    /* ── The page waits [G10, loading = the oncoming tube and floor, the bars
       as they were; Kenny, 2026-10-07 23:54]. While the page or the part it
       sits in is busy (`aria-busy='true'` on the header or an ancestor), the
       tube is an unlit track with the sun's ramp (pink, laser yellow, pink)
       flowing through it from its start to its end, 8 beats (1800 ms) a
       period, while the floor drives toward you, 4 beats (900 ms) a period:
       the lines are born at the horizon and spread to the foot, one line a
       step. Nothing flickers: every light glides. The bars under them fill as
       they are (the signature below). Standing still, the tube shows the ramp
       and the floor its lines, which says "busy" and claims no share. ─── */
    [data-theme='synthwave'] :is(.kp-page-header[aria-busy='true'], [aria-busy='true'] .kp-page-header)::after {
        background: var(--kp-sw-ramp-loop) 0 0 / 200% 100% repeat-x;
        box-shadow: none;
        filter: drop-shadow(0 0 4px hsl(from var(--primary) h s l / 0.7));
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] :is(.kp-page-header[aria-busy='true'], [aria-busy='true'] .kp-page-header)::after {
            animation: kp-sw-flow calc(8 * var(--kp-sw-beat)) linear infinite reverse;
        }

        [data-theme='synthwave'] :is(.kp-page-header[aria-busy='true'], [aria-busy='true'] .kp-page-header)::before {
            animation: kp-sw-floor-drive calc(4 * var(--kp-sw-beat)) linear infinite;
        }
    }

    @keyframes kp-sw-flow {
        to {
            background-position: 200% 0;
        }
    }

    @keyframes kp-sw-floor-drive {
        from {
            background-position:
                0 6px,
                0 1.6%,
                0 6.2%,
                0 14.1%,
                0 25%,
                0 39.1%,
                0 56.2%,
                0 76.6%,
                0 100%,
                0 0;
        }

        to {
            background-position:
                0 6px,
                0 6.2%,
                0 14.1%,
                0 25%,
                0 39.1%,
                0 56.2%,
                0 76.6%,
                0 100%,
                0 130%,
                0 0;
        }
    }

    [data-theme='synthwave'] .kp-page-header__inner::after {
        content: '';
        position: absolute;
        display: none;
        z-index: 2;
        inset-block-end: -1px;
        block-size: 5px;
        background: var(--kp-core);
        box-shadow:
            var(--kp-sw-tube-up),
            0 8px 18px hsl(from var(--primary) h s l / 0.5);
        pointer-events: none;
    }

    /* The piece is anchored to a pseudo-element of the action, not to the
       action: a popover's trigger names itself in an inline `anchor-name` (its
       popover is positioned by it), and an inline name beats any sheet's, so
       naming the action would either miss the trigger or steal its popover.
       The action's `::after` is its own box, with no inline style, and is
       named only while a hand is on it. A button's `::after` is the sun cut,
       positioned 4 px outside its padding box (2 px past the frame, the frame
       being 2 px), so the piece takes those 2 px back; an icon button's is a transparent box on its border box. */
    @supports (anchor-name: --a) {
        [data-theme='synthwave'] .kp-page-header__actions > .kp-icon-button::after {
            content: '';
            position: absolute;
            inset: 0;
            pointer-events: none;
        }

        [data-theme='synthwave'] .kp-page-header__actions > :is(.kp-button, .kp-icon-button):is(:hover, :focus-visible, :active)::after {
            anchor-name: --kp-sw-hand;
        }

        [data-theme='synthwave']
            .kp-page-header:has(.kp-page-header__actions > :is(.kp-button, .kp-icon-button):is(:hover, :focus-visible, :active))
            .kp-page-header__inner::after {
            display: block;
            left: anchor(--kp-sw-hand left);
            right: anchor(--kp-sw-hand right);
        }

        [data-theme='synthwave']
            .kp-page-header:has(.kp-page-header__actions > .kp-button:is(:hover, :focus-visible, :active))
            .kp-page-header__inner::after {
            left: calc(anchor(--kp-sw-hand left) + 2px);
            right: calc(anchor(--kp-sw-hand right) + 2px);
        }

        /* A press charges the piece: its bloom doubles and spreads and it
           thickens, for as long as the press is held. */
        [data-theme='synthwave']
            .kp-page-header:has(.kp-page-header__actions > :is(.kp-button, .kp-icon-button):active:not(:disabled))
            .kp-page-header__inner::after {
            box-shadow:
                0 0 3px var(--kp-core),
                0 0 12px var(--primary),
                0 0 30px hsl(from var(--primary) h s l / 0.9),
                0 14px 32px hsl(from var(--primary) h s l / 0.75);
            transform: scaleY(1.5);
        }
    }

    /* ── Cards, surfaces and containers: the tape with the stripe ─────── */

    /* A reporting plate is chrome over the floor [G7, surface = floor; the
       shape family of 2026-10-07 01:32 carried to the horizon]: the tape, the
       pink to cyan stripe along its top with a lit line under it (the 1 px of
       the page tube's light every plate carries), a shaded foot, and in its
       lower part the grid floor, lines closing toward a pink horizon and
       lines converging on its centre, faded before the words. The corners
       fall [Kenny, 2026-10-07 23:00]: the left side runs down in the colour of
       the stripe's left end, the right side in its right end, both fading out;
       the hairline round the plate is set aside, the light is the frame.
       Square, never glowing on its rim (the glow belongs to tubes). */
    /* The corners fall [Kenny, 2026-10-07 23:00]: pink down the left side,
       cyan down the right, fading out; each side starts in the colour of the
       top corner it touches, so a part that changes its stripe's ends (a
       tone) changes its sides with it. */
    [data-theme='synthwave']
        :is(
            .kp-card,
            .kp-kpi,
            .kp-dialog,
            .kp-popover,
            .kp-menu:not(.kp-popover .kp-menu),
            .kp-confirm,
            .kp-datepicker__panel,
            .kp-combobox__list,
            .kp-palette,
            .kp-theme-menu__list
        ) {
        --kp-stripe: linear-gradient(to right, var(--kp-stripe-from), var(--kp-stripe-to));
        --kp-sw-fall-l: linear-gradient(to bottom, var(--kp-stripe-from), hsl(from var(--kp-stripe-from) h s l / 0.55) 50%, transparent 100%);
        --kp-sw-fall-r: linear-gradient(to bottom, var(--kp-stripe-to), hsl(from var(--kp-stripe-to) h s l / 0.55) 50%, transparent 100%);
    }

    [data-theme='synthwave'] :is(.kp-card, .kp-kpi) {
        position: relative;
        isolation: isolate;
        background:
            var(--kp-stripe) 0 0 / 100% var(--kp-sw-side) no-repeat,
            linear-gradient(hsl(from var(--kp-core) h s l / 0.22) 0 0) 0 var(--kp-sw-side) / 100% 1px no-repeat,
            var(--kp-sw-fall-l) 0 0 / var(--kp-sw-side) 100% no-repeat,
            var(--kp-sw-fall-r) 100% 0 / var(--kp-sw-side) 100% no-repeat,
            var(--card);
        background-origin: border-box;
        border: 1px solid transparent;
        border-block-start: calc(var(--kp-sw-side) + 1px) solid transparent;
        border-image: none;
        border-radius: 0;
        box-shadow:
            inset 0 -2px 0 0 hsl(from var(--sidebar-background) h s l / 0.7),
            0 0 40px hsl(from var(--sidebar-background) h s l / 0.6);
        padding-block-end: calc(var(--kp-space-md, 1rem) + var(--kp-sw-floor) + 0.55rem);
    }

    [data-theme='synthwave'] :is(.kp-card, .kp-kpi)::after {
        content: '';
        position: absolute;
        grid-area: auto;
        inset: auto 0 0;
        z-index: -1;
        block-size: var(--kp-sw-floor);
        border-block-start: 1px solid hsl(from var(--kp-pink-text) h s l / 0.6);
        background: var(--kp-sw-floor-lines);
        box-shadow: 0 -2px 12px hsl(from var(--primary) h s l / 0.3);
        clip-path: inset(-14px 0 0 0);
        pointer-events: none;
    }

    /* ── A tile waits [G10, loading = the oncoming tube and floor, the bars as
       they were; Kenny, 2026-10-07 23:54]. The page tube at the scale of a
       tile: while a plate is busy (`aria-busy='true'` on the tile itself, or
       on the `.kp-tiles` or `.kp-kpis` that holds it) its stripe is the tube
       unlit, with the sun's ramp (pink, laser yellow, pink) flowing through it
       from its start to its end, 8 beats (1800 ms) a period, and the lines of
       its floor drive toward you, 4 beats (900 ms) a period: each line is born
       at the horizon and spreads to the foot, one line a period. Nothing
       flickers: every light glides on a line. The sides keep falling from the
       stripe's own colours. Standing still, the stripe shows the ramp and the
       floor its lines, which says "busy" and claims nothing. ─────────────── */
    [data-theme='synthwave'] :is(:is(.kp-card, .kp-kpi)[aria-busy='true'], :is(.kp-tiles, .kp-kpis)[aria-busy='true'] > :is(.kp-card, .kp-kpi)) {
        background:
            var(--kp-sw-ramp-loop) 0 0 / 200% var(--kp-sw-side) repeat-x,
            linear-gradient(hsl(from var(--kp-core) h s l / 0.22) 0 0) 0 var(--kp-sw-side) / 100% 1px no-repeat,
            var(--kp-sw-fall-l) 0 0 / var(--kp-sw-side) 100% no-repeat,
            var(--kp-sw-fall-r) 100% 0 / var(--kp-sw-side) 100% no-repeat,
            var(--card);
        background-origin: border-box;
        /* The tube is the sign that it waits, at full light: the package's
           0.7 busy dim (`kp.layout`, knob `--kp-busy-opacity`) would dull it. */
        --kp-busy-opacity: 1;
        box-shadow:
            inset 0 -2px 0 0 hsl(from var(--sidebar-background) h s l / 0.7),
            0 -2px 10px 0 hsl(from var(--primary) h s l / 0.45),
            0 0 40px hsl(from var(--sidebar-background) h s l / 0.6);
    }

    [data-theme='synthwave'] :is(.kp-tiles, .kp-kpis)[aria-busy='true'] {
        --kp-busy-opacity: 1;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] :is(:is(.kp-card, .kp-kpi)[aria-busy='true'], :is(.kp-tiles, .kp-kpis)[aria-busy='true'] > :is(.kp-card, .kp-kpi)) {
            animation: kp-sw-tile-flow calc(8 * var(--kp-sw-beat)) linear infinite reverse;
        }

        [data-theme='synthwave']
            :is(:is(.kp-card, .kp-kpi)[aria-busy='true'], :is(.kp-tiles, .kp-kpis)[aria-busy='true'] > :is(.kp-card, .kp-kpi))::after {
            background:
                linear-gradient(hsl(from var(--primary) h s l / 0.3) 0 0) 0 4% / 100% 1px no-repeat,
                linear-gradient(hsl(from var(--primary) h s l / 0.32) 0 0) 0 16% / 100% 1px no-repeat,
                linear-gradient(hsl(from var(--primary) h s l / 0.34) 0 0) 0 38% / 100% 1px no-repeat,
                linear-gradient(hsl(from var(--primary) h s l / 0.36) 0 0) 0 66% / 100% 1px no-repeat,
                linear-gradient(hsl(from var(--primary) h s l / 0.38) 0 0) 0 100% / 100% 1px no-repeat,
                repeating-conic-gradient(from 180deg at 50% -25%, hsl(from var(--primary) h s l / 0.45) 0 0.7deg, transparent 0.7deg 9deg);
            animation: kp-sw-tile-floor-drive calc(4 * var(--kp-sw-beat)) linear infinite;
        }
    }

    @keyframes kp-sw-tile-flow {
        from {
            background-position:
                0 0,
                0 var(--kp-sw-side),
                0 0,
                100% 0;
        }

        to {
            background-position:
                200% 0,
                0 var(--kp-sw-side),
                0 0,
                100% 0;
        }
    }

    @keyframes kp-sw-tile-floor-drive {
        from {
            background-position:
                0 4%,
                0 16%,
                0 38%,
                0 66%,
                0 100%,
                0 0;
        }

        to {
            background-position:
                0 16%,
                0 38%,
                0 66%,
                0 100%,
                0 130%,
                0 0;
        }
    }

    [data-theme='synthwave'] .kp-card__title {
        font-family: var(--theme-font-display);
        font-weight: 700;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--kp-core);
        text-shadow: var(--kp-tube-pink);
    }

    /* The key figure's number [G15, type = osd: "the OSD names, the chrome
       counts"; Kenny, 2026-10-07 20:41]: figures are counted in the chrome
       display face (`--theme-font-display`, KP Outrun Display), a near-white
       core with the pink tube, as the card's title is. Its unit and note are
       names, so they go back to the body face. A figure on a warning or
       destructive plate keeps the plate's ink and no glow (the pair the
       package guarantees, G13). */
    [data-theme='synthwave'] .kp-kpi > .kp-kpi__value {
        font-family: var(--theme-font-display);
        font-weight: 700;
        letter-spacing: 0.04em;
    }

    [data-theme='synthwave'] .kp-kpi > .kp-kpi__value :is(small, .kp-kpi__note) {
        font-family: var(--theme-font-body);
        font-weight: 600;
        letter-spacing: normal;
        text-shadow: none;
    }

    [data-theme='synthwave'] .kp-kpi:not([data-kp-tone='warning'], [data-kp-tone='destructive']) > .kp-kpi__value {
        color: var(--kp-core);
        text-shadow: var(--kp-tube-pink);
    }

    /* The dossier: a tape card; the label is the OSD's REC stamp; the
       redactions are tracking noise that clears when the file is opened. */
    [data-theme='synthwave'] .kp-card[data-kp-reveal='emphasis'] {
        position: relative;
    }

    [data-theme='synthwave'] .kp-card[data-kp-label]::before {
        content: '● ' attr(data-kp-label);
        position: absolute;
        top: 0.9rem;
        right: 1.4rem;
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.2em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
    }

    [data-theme='synthwave'] .kp-card[data-kp-reveal='emphasis'] mark {
        position: relative;
    }

    [data-theme='synthwave'] .kp-card[data-kp-reveal='emphasis'] mark::after {
        content: '';
        position: absolute;
        inset: -0.05em -0.15em;
        background: repeating-linear-gradient(90deg, var(--primary) 0 2px, var(--card) 2px 3px, var(--accent) 3px 4px, var(--card) 4px 7px);
        opacity: 0.9;
        transform: scaleX(0);
        transform-origin: right center;
    }

    [data-theme='synthwave'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared)::after {
        transform: scaleX(1);
    }

    [data-theme='synthwave'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared {
        text-shadow: var(--kp-tube-cyan);
    }

    /* A panel that opens is the tape with the stripe, without the floor
       [G7]: the same stripe, the lit line and the sides that fall as a plate's. */
    [data-theme='synthwave'] .kp-dialog,
    [data-theme='synthwave'] .kp-popover,
    [data-theme='synthwave'] .kp-menu:not(.kp-popover .kp-menu),
    [data-theme='synthwave'] .kp-confirm,
    [data-theme='synthwave'] .kp-datepicker__panel,
    [data-theme='synthwave'] .kp-combobox__list,
    [data-theme='synthwave'] .kp-palette,
    [data-theme='synthwave'] .kp-theme-menu__list {
        background:
            var(--kp-stripe) 0 0 / 100% var(--kp-sw-side) no-repeat,
            linear-gradient(hsl(from var(--kp-core) h s l / 0.22) 0 0) 0 var(--kp-sw-side) / 100% 1px no-repeat,
            var(--kp-sw-fall-l) 0 0 / var(--kp-sw-side) 100% no-repeat,
            var(--kp-sw-fall-r) 100% 0 / var(--kp-sw-side) 100% no-repeat,
            var(--popover);
        background-origin: border-box;
        border: 1px solid transparent;
        border-block-start: calc(var(--kp-sw-side) + 1px) solid transparent;
        border-image: none;
        border-radius: 0;
        box-shadow: 0 12px 40px hsl(from var(--sidebar-background) h s l / 0.6);
    }

    /* The toast is a plate in its own tone and the tooltip a line of the OSD:
       the toast's stripe is its own (below), the tooltip has none. */
    [data-theme='synthwave'] .kp-toast,
    [data-theme='synthwave'] .kp-tooltip {
        background: var(--popover);
        border: 1px solid var(--kp-hairline);
        border-radius: 0;
        box-shadow: 0 12px 40px hsl(from var(--sidebar-background) h s l / 0.6);
    }

    /* The wrapper round the theme picker's icon button is not a card: only its
       dropdown list is. */
    [data-theme='synthwave'] .kp-theme-menu {
        background: none;
        border: 0;
        border-image: none;
        box-shadow: none;
    }

    /* Severity toasts [scope-60]. The plain toast above is repainted here in
       a later layer than kp.components, which swallowed every variant's
       plate; each is restated on the alert's token pair, as the severity
       badge wears it. */
    [data-theme='synthwave'] .kp-toast--success {
        background: var(--success);
        color: var(--success-foreground);
        border-color: var(--success);
    }

    [data-theme='synthwave'] .kp-toast--info {
        background: var(--info);
        color: var(--info-foreground);
        border-color: var(--info);
    }

    [data-theme='synthwave'] .kp-toast--warning {
        background: var(--warning);
        color: var(--warning-foreground);
        border-color: var(--warning);
    }

    [data-theme='synthwave'] .kp-toast--destructive,
    [data-theme='synthwave'] .kp-toast--error {
        background: var(--destructive);
        color: var(--destructive-foreground);
        border-color: var(--destructive);
    }

    [data-theme='synthwave']
        :is(.kp-toast--success, .kp-toast--info, .kp-toast--warning, .kp-toast--destructive, .kp-toast--error)
        :is(.kp-button--ghost, .kp-icon-button) {
        color: inherit;
    }

    /* A button hovered on a toast takes a shade of the toast's own plate
       (--kp-toast-button-hover, set in kp.components), not this theme's page hover (Kenny's second nostromo pass,
       2026-09-13). Restated here because this layer repaints the hover. */
    [data-theme='synthwave'] .kp-toast :is(.kp-button--ghost, .kp-icon-button):hover:not(:disabled) {
        background: var(--kp-toast-button-hover);
        color: inherit;
    }

    [data-theme='synthwave'] .kp-toasts {
        gap: 0.6rem;
    }

    [data-theme='synthwave'] .kp-dialog__title {
        color: var(--kp-core);
        text-shadow: var(--kp-tube-cyan);
    }

    /* The keyboard highlight is a wash of the ink, not a new colour (KT8). */
    [data-theme='synthwave'] .kp-menu__item:hover,
    [data-theme='synthwave'] .kp-combobox__option[aria-selected='true'],
    [data-theme='synthwave'] .kp-palette__option[aria-selected='true'] {
        background: hsl(from var(--foreground) h s l / 0.14);
    }

    /* The plain alert only [gap-1, Kenny 2026-09-10]. This rule used to
       repaint the ground of EVERY alert, and `kp.register` is a later layer
       than `kp.components`, so it beat `.kp-alert--destructive`'s own plate
       while that variant's ink — `--destructive-foreground`, which is drawn
       to sit ON the plate — stayed. Measured in firefox on 2026-09-12:
       seventeen of the twenty-two themes carried a destructive alert whose
       text was unreadable, grotesk at 1.00 exactly, white on white.

       Kenny saw it in chassis-rs and said to write it down and touch
       nothing; this is the round he asked for it in. Same shape as fix-12,
       one property over: a register overriding half of a pair the base
       layer defines together. */
    [data-theme='synthwave'] .kp-alert:not([class*='kp-alert--']) {
        background: var(--card);
        border: 1px solid var(--kp-hairline);
        border-left: 4px solid var(--accent);
        border-radius: 0;
    }

    [data-theme='synthwave'] .kp-alert--destructive {
        border-left-color: var(--destructive);
    }

    /* The data table's Try again takes the plate's own ink for its frame
       [Kenny's synthwave note, 2026-09-15]. The frame is the primary pink,
       and on the red plate of the failed state it measured 1.06:1 — "poorly
       visible". The alert's label is `--destructive-foreground` on that
       plate, 5.59:1, so the frame is drawn in it. Until scope-94 every
       framed button on any destructive alert took it; Kenny narrowed it to
       this one ("Alleen Try again"), so the retry control the data table
       draws in its failed slot — js/datatable.js, `[data-kp-datatable-
       retry]` inside `[data-kp-datatable-failed]`, whether the page wrote
       the slot or the script did — is the only button it reaches. */
    [data-theme='synthwave'] [data-kp-datatable-failed] .kp-button[data-kp-datatable-retry] {
        --kp-frame: var(--destructive-foreground);
    }

    [data-theme='synthwave'] .kp-alert--warning {
        border-left-color: var(--warning-foreground);
    }

    [data-theme='synthwave'] .kp-alert--success {
        border-left-color: var(--success-foreground);
    }

    [data-theme='synthwave'] .kp-alert__label {
        font-family: var(--kp-osd);
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }

    [data-theme='synthwave'] .kp-grid__tile,
    [data-theme='synthwave'] .kp-split__pane {
        background: var(--card);
        border: 1px solid var(--kp-hairline);
        border-radius: 0;
    }

    [data-theme='synthwave'] .kp-grid {
        gap: 1rem;
    }

    [data-theme='synthwave'] .kp-split__separator {
        background: var(--kp-stripe);
        width: 3px;
    }

    /* Top and bottom [gap-12]: the thickness above is an inline size, so
       a horizontal split takes the same value as a block size. */
    [data-theme='synthwave'] .kp-split[data-kp-orientation='horizontal'] > .kp-split__separator {
        inline-size: auto;
        block-size: 3px;
    }

    [data-theme='synthwave'] .kp-footer {
        background: var(--sidebar-background);
        color: var(--muted-foreground);
    }

    [data-theme='synthwave'] .kp-footer h4 {
        font-family: var(--kp-osd);
        letter-spacing: 0.16em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
    }

    [data-theme='synthwave'] .kp-footer a {
        font-weight: 500;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        font-size: 0.85rem;
        text-decoration: none;
    }

    [data-theme='synthwave'] .kp-footer a:hover {
        color: var(--kp-core);
        text-shadow: var(--kp-tube-cyan);
    }

    /* ── Badges, tags, status: small tubes ───────────────────────────── */

    [data-theme='synthwave'] .kp-badge,
    [data-theme='synthwave'] .kp-tag {
        border-radius: var(--radius);
        border: 1px solid currentColor;
        font-family: var(--kp-osd);
        letter-spacing: 0.1em;
        text-transform: uppercase;
        box-shadow: 0 0 6px hsl(from var(--primary) h s l / 0.25);
    }

    /* The badge's type size is the package's [scope-87]; the tag keeps this register's. */
    [data-theme='synthwave'] .kp-tag {
        font-size: 0.95rem;
    }

    [data-theme='synthwave'] .kp-health__dot {
        box-shadow: 0 0 8px currentColor;
    }

    [data-theme='synthwave'] .kp-health {
        font-family: var(--kp-osd);
        letter-spacing: 0.08em;
    }

    [data-theme='synthwave'] .kp-skeleton {
        background: linear-gradient(90deg, var(--card), var(--popover), var(--card));
        border-radius: 0;
    }

    [data-theme='synthwave'] .kp-spinner {
        border-color: hsl(from var(--accent) h s l / 0.25);
        border-top-color: var(--accent);
        filter: drop-shadow(0 0 4px var(--accent));
    }

    [data-theme='synthwave'] .kp-empty__title {
        font-family: var(--kp-osd);
        text-transform: uppercase;
    }

    [data-theme='synthwave'] .kp-error {
        font-family: var(--kp-osd);
        color: var(--warning-foreground);
        text-shadow: var(--kp-tube-laser);
    }

    /* ── Text shapes: identifiers in the OSD face ────────────────────── */

    [data-theme='synthwave'] .kp-id,
    [data-theme='synthwave'] .kp-url,
    [data-theme='synthwave'] .kp-numeric,
    [data-theme='synthwave'] .kp-timestamp,
    [data-theme='synthwave'] .kp-masked,
    [data-theme='synthwave'] .kp-copyable,
    [data-theme='synthwave'] .kp-truncate,
    [data-theme='synthwave'] .kp-cell-break,
    [data-theme='synthwave'] .kp-cell-truncate {
        font-family: var(--kp-mono);
        letter-spacing: 0.04em;
    }

    [data-theme='synthwave'] .kp-timestamp,
    [data-theme='synthwave'] .kp-id {
        color: var(--accent);
    }

    [data-theme='synthwave'] .kp-copyable__button {
        border: 1px solid var(--kp-hairline);
        border-radius: var(--radius);
        color: var(--kp-pink-text);
    }

    /* The copy button's two states win over this register's own button
       rules [gap-12]: those paint in kp.register, which beats the states
       in kp.components, so copied lost its success plate and a refused
       copy looked idle. Restated token for token. */
    [data-theme='synthwave'] .kp-copyable .kp-copyable__button[data-kp-copied] {
        border-color: var(--success);
        color: var(--success-foreground);
        background: var(--success);
    }

    [data-theme='synthwave'] .kp-copyable .kp-copyable__button[data-kp-copy-failed] {
        border-color: var(--destructive);
        border-style: dashed;
        color: var(--destructive);
    }

    /* ── Data ─────────────────────────────────────────────────────────── */

    [data-theme='synthwave'] .kp-table {
        border-collapse: separate;
        border-spacing: 0;
    }

    /* One stripe across the whole header, not one per cell [gap-3, Kenny
       2026-09-10]. A `border-image` is painted per element by definition,
       so every `<th>` restarted the ramp and the seam he saw was the
       mechanism working exactly as written. The stripe now belongs to the
       row and runs the table's full width.

       `background-image` on the row rather than a border-image: a row is
       not a box that takes a border in every table layout, but it always
       has a background, and a 2px band pinned to its bottom edge is the
       same two pixels the border was. Measured across the register on
       2026-09-11: `.kp-table th` was the only place this declaration
       repeats side by side — the nav menu, form summary, card, theme menu,
       wizard and spec list carry it too and never sit in a row. */
    [data-theme='synthwave'] .kp-table th {
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
        border-bottom: 2px solid transparent;
    }

    [data-theme='synthwave'] .kp-table thead tr {
        background-image: var(--kp-stripe);
        background-size: 100% 2px;
        background-position: 0 100%;
        background-repeat: no-repeat;
    }

    [data-theme='synthwave'] .kp-table td {
        border-bottom: 1px solid var(--kp-hairline);
    }

    [data-theme='synthwave'] .kp-table tbody tr:hover {
        background: var(--card);
    }

    [data-theme='synthwave'] .kp-datatable__bar {
        border-bottom: 1px solid var(--kp-hairline);
    }

    [data-theme='synthwave'] .kp-datatable__sort[aria-sort] {
        color: var(--accent);
        text-shadow: var(--kp-tube-cyan);
    }

    [data-theme='synthwave'] .kp-datatable__status,
    [data-theme='synthwave'] .kp-datatable__page {
        font-family: var(--kp-osd);
        letter-spacing: 0.08em;
    }

    [data-theme='synthwave'] .kp-diff__line,
    [data-theme='synthwave'] .kp-diff__hunk {
        font-family: var(--kp-mono);
    }

    [data-theme='synthwave'] .kp-diff__sign {
        font-weight: 700;
    }

    [data-theme='synthwave'] .kp-timeline__marker {
        background: var(--primary);
        box-shadow: 0 0 10px var(--primary);
        border-radius: 50%;
    }

    [data-theme='synthwave'] .kp-timeline__when {
        font-family: var(--kp-osd);
        color: var(--accent);
        letter-spacing: 0.08em;
    }

    /* The step list is arcade rows with a neon edge; the running row glows. */
    [data-theme='synthwave'] .kp-steplist {
        --kp-steplist-gap: 0.625rem;
    }

    [data-theme='synthwave'] .kp-steplist__item {
        border-color: hsl(from var(--primary) h s l / 0.4);
    }

    [data-theme='synthwave'] .kp-steplist__item[data-state='running'] {
        box-shadow: 0 0 12px hsl(from var(--primary) h s l / 0.45);
    }

    [data-theme='synthwave'] .kp-steplist__time {
        font-family: var(--kp-mono);
    }

    [data-theme='synthwave'] .kp-timeline {
        border-left: 1px solid var(--kp-hairline);
    }

    [data-theme='synthwave'] .kp-tree {
        font-family: var(--kp-mono);
    }

    /* The accordion [gap-12]: spaced capitals, and the hot core its selected tab burns with. */
    [data-theme='synthwave'] .kp-accordion__summary {
        font-weight: 600;
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }

    [data-theme='synthwave'] .kp-accordion__summary::marker {
        color: var(--primary);
    }

    [data-theme='synthwave'] .kp-accordion__item[open] > .kp-accordion__summary {
        color: var(--kp-core);
    }

    [data-theme='synthwave'] .kp-reorder {
        border: 1px solid var(--kp-hairline);
        border-radius: 0;
    }

    /* ── Navigation and steps ─────────────────────────────────────────── */

    [data-theme='synthwave'] .kp-tab {
        border-radius: 0;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        font-weight: 600;
        position: relative;
    }

    [data-theme='synthwave'] .kp-tab[aria-selected='true'] {
        color: var(--kp-core);
        text-shadow: var(--kp-tube-cyan);
        box-shadow: inset 0 -4px 0 0 var(--primary);
    }

    [data-theme='synthwave'] .kp-tabs__list {
        border-bottom: 1px solid var(--kp-hairline);
    }

    [data-theme='synthwave'] .kp-breadcrumb,
    [data-theme='synthwave'] .kp-pagination {
        font-family: var(--kp-osd);
        letter-spacing: 0.1em;
        text-transform: uppercase;
    }

    [data-theme='synthwave'] .kp-pagination a[aria-current],
    [data-theme='synthwave'] .kp-pagination [aria-current] {
        color: var(--kp-core);
        text-shadow: var(--kp-tube-pink);
        border-bottom: 2px solid var(--primary);
    }

    [data-theme='synthwave'] .kp-wizard__steps {
        font-family: var(--kp-osd);
        letter-spacing: 0.1em;
        text-transform: uppercase;
    }

    [data-theme='synthwave'] .kp-wizard {
        border: 1px solid var(--kp-hairline);
        border-top: 4px solid transparent;
        border-image: var(--kp-stripe) 1;
    }

    /* ── Pickers and palettes ─────────────────────────────────────────── */

    [data-theme='synthwave'] .kp-combobox__input,
    [data-theme='synthwave'] .kp-palette__input,
    [data-theme='synthwave'] .kp-datatable__search {
        background: var(--sidebar-background);
        border: 2px solid hsl(from var(--kp-pink-text) h s l / 0.35);
        border-radius: var(--radius);
        caret-color: var(--accent);
    }

    [data-theme='synthwave'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
        box-shadow: 0 0 10px hsl(from var(--primary) h s l / 0.6);
        border-radius: var(--radius);
    }

    [data-theme='synthwave'] .kp-datepicker__weekday,
    [data-theme='synthwave'] .kp-datepicker__title {
        font-family: var(--kp-osd);
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
    }

    [data-theme='synthwave'] .kp-colorpicker__swatch {
        border: 2px solid var(--kp-hairline);
        border-radius: var(--radius);
        box-shadow: 0 0 10px hsl(from var(--primary) h s l / 0.3);
    }

    [data-theme='synthwave'] .kp-colorpicker__value {
        font-family: var(--kp-mono);
        color: var(--accent);
    }

    [data-theme='synthwave'] .kp-shortcuts__row kbd {
        font-family: var(--kp-osd);
        border: 1px solid var(--kp-hairline);
        border-radius: var(--radius);
        color: var(--accent);
    }

    [data-theme='synthwave'] .kp-shortcuts__group-label,
    [data-theme='synthwave'] .kp-palette__group-label {
        font-family: var(--kp-osd);
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
    }

    [data-theme='synthwave'] .kp-theme-menu__status,
    [data-theme='synthwave'] .kp-palette__status,
    [data-theme='synthwave'] .kp-combobox__status {
        font-family: var(--kp-osd);
        letter-spacing: 0.08em;
    }

    /* ── The roots the rules above reach only by their parts ──────────── */

    /* A field, a form, a fieldset of data: the OSD rhythm between rows. */
    [data-theme='synthwave'] .kp-field,
    [data-theme='synthwave'] .kp-form {
        gap: calc(var(--kp-space-xs) * 1.4);
    }

    [data-theme='synthwave'] .kp-form {
        gap: calc(var(--kp-space-lg) * 1.1);
    }

    /* The data pickers and panels: a hairline frame, square. */
    [data-theme='synthwave'] .kp-combobox,
    [data-theme='synthwave'] .kp-datepicker,
    [data-theme='synthwave'] .kp-colorpicker,
    [data-theme='synthwave'] .kp-shortcuts {
        border-radius: 0;
    }

    [data-theme='synthwave'] .kp-datatable {
        border: 1px solid var(--kp-hairline);
        border-radius: 0;
    }

    [data-theme='synthwave'] .kp-diff {
        background: var(--sidebar-background);
        border: 1px solid var(--kp-hairline);
        border-radius: 0;
    }

    [data-theme='synthwave'] .kp-split {
        gap: 0;
    }

    /* ── The scrollbar joins the theme ────────────────────────────────── */

    [data-theme='synthwave'] {
        scrollbar-color: var(--primary) var(--sidebar-background);
    }

    /* ── The demo's own pieces [S46] ──────────────────────────────────── */

    /* The vertical OSD label in the margin: ● REC · SP 0:00:00. */
    [data-theme='synthwave'] .kp-side-note {
        position: absolute;
        right: 1rem;
        top: 3rem;
        writing-mode: vertical-rl;
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.3em;
        color: var(--kp-pink-text);
        z-index: 2;
    }

    /* Laurels: uppercase, each item between two striped bars — the sun's
       stripes, three bands each. */
    [data-theme='synthwave'] .kp-laurels {
        gap: 1.5rem 2.5rem;
        text-transform: uppercase;
        letter-spacing: 0.1em;
        font-size: 0.8rem;
        color: var(--muted-foreground);
    }

    [data-theme='synthwave'] .kp-laurels li {
        position: relative;
        padding-inline: 0.9rem;
        background:
            repeating-linear-gradient(0deg, var(--primary) 0 3px, transparent 3px 6px) left / 4px 100% no-repeat,
            repeating-linear-gradient(0deg, var(--primary) 0 3px, transparent 3px 6px) right / 4px 100% no-repeat;
    }

    [data-theme='synthwave'] .kp-laurels b {
        font-weight: 700;
        font-size: 0.95rem;
        letter-spacing: 0.06em;
        color: var(--kp-core);
        text-shadow: var(--kp-tube-cyan);
    }

    [data-theme='synthwave'] .kp-lede {
        max-width: 34rem;
        font-size: 1.15rem;
        font-weight: 500;
    }

    /* The platforms line: the OSD face, ▶ before every name. */
    [data-theme='synthwave'] .kp-platforms {
        margin-top: 2.4rem;
        gap: 0.4rem 1.6rem;
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.14em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    [data-theme='synthwave'] .kp-platforms span::before {
        content: '▶ ';
        color: var(--accent);
    }

    /* The spec sheet: a tape card with the stripe on top. */
    [data-theme='synthwave'] .kp-spec {
        background: var(--card);
        color: var(--foreground);
        padding: 1.4rem 1.5rem 1.6rem;
        border: 1px solid var(--kp-hairline);
        border-top: 4px solid transparent;
        border-image: var(--kp-stripe) 1;
        font-family: var(--kp-mono);
        font-size: 0.8rem;
        line-height: 1.7;
        box-shadow: 0 0 40px hsl(from var(--sidebar-background) h s l / 0.6);
    }

    [data-theme='synthwave'] .kp-spec dt {
        color: var(--accent);
        letter-spacing: 0.1em;
    }

    /* The log wears what this register already decided for its other data
 * surface, `.kp-spec` — the same ground, the same edge, the same face
 * [gap-14]. A new component that invents a look of its own is a
 * twenty-third decision nobody made. */
    [data-theme='synthwave'] .kp-log {
        background: var(--card);
        color: var(--foreground);
        border: 1px solid var(--kp-hairline);
        font-family: var(--kp-mono);
        box-shadow: 0 0 40px hsl(from var(--sidebar-background) h s l / 0.6);
    }

    [data-theme='synthwave'] .kp-log__level {
        --kp-log-level-ink: var(--accent);
        letter-spacing: 0.1em;
    }

    [data-theme='synthwave'] .kp-spec__swatch {
        border: 1px solid hsl(from var(--kp-core) h s l / 0.25);
    }

    [data-theme='synthwave'] .kp-spec__font {
        font-family: var(--theme-font-display);
    }

    /* ── The arrival [S45, SW2]: the boot line, then the tube switches on ── */

    /* The overlay js/effects.js builds when the theme answers the arrival
       hook with `boot`: a diegetic line counting up in the OSD face, a
       Skip button, and the CRT switching the overlay off in 550 ms. Once
       per session; never under reduced motion (the module does not build
       it). */
    [data-theme='synthwave'] .kp-boot {
        position: fixed;
        inset: 0;
        z-index: var(--kp-z-boot, 100);
        background: var(--background);
        display: grid;
        place-items: center;
        font-family: var(--kp-osd);
        font-size: clamp(1.1rem, 2.4vw, 1.6rem);
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--accent);
        text-shadow: var(--kp-tube-cyan);
        transform-origin: center;
    }

    [data-theme='synthwave'] .kp-boot__line {
        margin: 0;
        font: inherit;
        white-space: pre-wrap;
        min-width: 20ch;
    }

    [data-theme='synthwave'] .kp-boot__skip {
        position: absolute;
        right: 1.5rem;
        bottom: 1.5rem;
        font: inherit;
        letter-spacing: 0.2em;
        color: var(--kp-pink-text);
        background: none;
        border: 2px solid var(--primary);
        border-radius: var(--radius);
        padding: 0.3rem 0.9rem;
        cursor: pointer;
    }

    [data-theme='synthwave'] .kp-boot.is-off {
        pointer-events: none;
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above are what they get. The
       durations are literal because check-motion.mjs computes DI5's rate
       from them; the matching --kp-* knobs are what js/effects.js reads. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] [data-kp-reveal='headline'].is-tracking::before {
            animation: kp-tracking 700ms steps(1, end) 1;
        }

        [data-theme='synthwave'] [data-kp-reveal='headline'].is-shine::after {
            animation: kp-shine 1400ms var(--fx-ease) 1;
        }

        [data-theme='synthwave'] [data-kp-reveal='rule']::after {
            transition: transform var(--kp-rule-draw) var(--fx-ease);
        }

        [data-theme='synthwave'][data-kp-effects] mark.is-cleared {
            animation: kp-tube-on 1100ms steps(1, end) 1;
        }

        [data-theme='synthwave'] .kp-card[data-kp-reveal='emphasis'] mark::after {
            transition: transform var(--kp-wipe) var(--fx-ease);
        }

        [data-theme='synthwave'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2)::after {
            transition-delay: var(--kp-redact-stagger);
        }

        [data-theme='synthwave'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3)::after {
            transition-delay: calc(2 * var(--kp-redact-stagger));
        }

        [data-theme='synthwave'] .kp-nav__links {
            animation: kp-bar-in 520ms var(--fx-ease) 80ms both;
        }

        [data-theme='synthwave'] .kp-nav__link::after {
            transition: transform var(--fx-duration) var(--fx-ease);
        }

        /* Transform only. No box-shadow transition: the focus ring is a
           shadow layer and must appear at once (AR30). No colour transition
           either: a theme applied after first paint transitions every
           colour, and CI's chromium read a nav link halfway — `oklab(…)`,
           a colour the theme does not own (KT8; flake named, rule 8a,
           run 34175026456). */
        [data-theme='synthwave'] .kp-nav__link,
        [data-theme='synthwave'] .kp-nav__link--cta,
        [data-theme='synthwave'] .kp-button {
            transition: transform var(--fx-duration) var(--fx-ease);
        }

        [data-theme='synthwave'] .kp-button:hover::before {
            animation: kp-sun-cut 360ms steps(3, end) 1;
        }

        [data-theme='synthwave'] .kp-button:hover::after {
            animation: kp-sun-cut 360ms steps(3, end) 1 60ms;
        }

        [data-theme='synthwave'] [data-kp-surface='hero']::after {
            animation: kp-floor-drift 6000ms linear infinite;
        }

        [data-theme='synthwave'] .kp-boot.is-off {
            animation: kp-crt-off 550ms var(--fx-ease) 1 forwards;
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* Every keyframe here has its row in TIMINGS (js/effects.js). */
    /* The headline's reveal, its first part: the tube strikes on [G16, motifs =
       meaning: VHS is a still texture and a voice, never a tracking glitch,
       which is cyberpunk's]. The bands that jumped sideways with an RGB fringe
       are gone; the copy of the text in the near-white core lights, dips once
       and goes out in hard steps, and the chrome shine follows. The name and
       the 700 ms stay: js/effects.js waits that long before the shine. */
    @keyframes kp-tracking {
        0% {
            opacity: 0;
        }

        20% {
            opacity: 1;
        }

        34% {
            opacity: 0.35;
        }

        48%,
        72% {
            opacity: 1;
        }

        100% {
            opacity: 0;
        }
    }

    @keyframes kp-shine {
        from {
            background-position: 100% 100%;
        }

        to {
            background-position: 0% 0%;
        }
    }

    @keyframes kp-tube-on {
        0% {
            color: hsl(from var(--foreground) h s l / 0.4);
            text-shadow: none;
        }

        20% {
            color: var(--kp-core);
            text-shadow: var(--kp-tube-pink);
        }

        34% {
            color: hsl(from var(--foreground) h s l / 0.5);
            text-shadow: none;
        }

        50%,
        100% {
            color: var(--kp-core);
            text-shadow: var(--kp-tube-pink);
        }
    }

    @keyframes kp-sun-cut {
        0% {
            opacity: 1;
            transform: translateX(-10%);
        }

        66% {
            opacity: 1;
            transform: translateX(10%);
        }

        100% {
            opacity: 0;
            transform: none;
        }
    }

    @keyframes kp-bar-in {
        0% {
            transform: translateY(10px);
            opacity: 0;
        }

        100% {
            transform: none;
            opacity: 1;
        }
    }

    @keyframes kp-floor-drift {
        to {
            background-position: 0 6vw;
        }
    }

    @keyframes kp-crt-off {
        0% {
            transform: scaleY(1);
            filter: brightness(1);
            opacity: 1;
        }

        60% {
            transform: scaleY(0.006);
            filter: brightness(8);
        }

        100% {
            transform: scaleY(0.006) scaleX(0);
            filter: brightness(50);
            opacity: 0;
        }
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — a neon rule under the band and a glow around the text. */
    [data-theme='synthwave'] .kp-marquee {
        background: linear-gradient(180deg, color-mix(in srgb, var(--primary) 12%, transparent), transparent);
        border-block-end: 2px solid var(--primary);
        text-shadow: 0 0 6px color-mix(in srgb, var(--primary) 60%, transparent);
        --kp-marquee: 26000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    /* A mega menu's group headings speak in the caption's voice [scope-48]. */
    [data-theme='synthwave'] .kp-nav__menu[data-kp-menu-label]::before,
    [data-theme='synthwave'] .kp-nav__menu--wide .kp-nav__menu-heading {
        color: var(--primary);
        text-shadow: 0 0 6px color-mix(in srgb, var(--primary) 60%, transparent);
        border-block-end: 0;
    }

    /* ── The side navigation [feat-nav-3] ────────────────────────────
       The bar lights its current item from underneath. A column has no
       underneath, so the glow moves to the leading edge and becomes the
       tube running down the side of the active row. */
    [data-theme='synthwave'] .kp-sidenav {
        --kp-sidenav-surface: var(--card);
        border-inline-end: 1px solid var(--border-strong);
    }

    [data-theme='synthwave'] .kp-sidenav__title {
        letter-spacing: 0.2em;
        text-transform: uppercase;
        color: var(--primary);
    }

    [data-theme='synthwave'] .kp-sidenav__link,
    [data-theme='synthwave'] .kp-sidenav__category-toggle {
        padding-inline: 1.1rem;
        font-weight: 600;
        border-radius: 0;
    }

    [data-theme='synthwave'] .kp-sidenav__link[aria-current='page'] {
        color: var(--kp-core);
        background: none;
        box-shadow:
            inset 0.2rem 0 0 var(--primary),
            inset 0 0 25px hsl(from var(--primary) h s l / 0.18);
    }

    /* ── Back to top, and a picture [feat-page-1, feat-media-1] ──────
       Both get the tube: a ring of the primary that glows rather than
       merely bounding. */
    [data-theme='synthwave'] .kp-to-top {
        box-shadow: 0 0 12px hsl(from var(--primary) h s l / 0.5);
    }

    [data-theme='synthwave'] .kp-media {
        border: 1px solid var(--primary);
        box-shadow: 0 0 18px hsl(from var(--primary) h s l / 0.28);
    }

    [data-theme='synthwave'] .kp-media-figure > figcaption {
        letter-spacing: 0.14em;
        text-transform: uppercase;
        font-size: 0.6875rem;
    }

    /* The figure carries the caption's voice, so the decision sits with
       the picture rather than with the words under it. */
    [data-theme='synthwave'] .kp-media-figure {
        color: var(--primary);
        text-align: start;
    }

    /* ── The pressed state the register had been cancelling [fix-12] ───
       A layer beats a state: this register's hover background sits in
       kp.register, later than the kp.components rule that says what the
       button looks like while it is held down, so pressing it changed
       nothing. The base layer's own values, put back token for token. */

    [data-theme='synthwave'] .kp-button--primary:active:not(:disabled) {
        background: var(--primary-active);
        border-color: var(--primary-active);
    }

    /* ── Read-only fields [gap-11] ────────────────────────────────────── */

    /* A read-only field is a value on a record, not a box to type in. This
       register sets the field's border and ground in kp.register, which
       beats the read-only look in kp.components, so read-only painted like
       an editable field. The state is answered here, on top of the rest
       look, which stays as it was. */
    [data-theme='synthwave'] .kp-field__input[readonly] {
        border-style: dashed;
        background-color: var(--muted);
    }

    /* ── The palette's trigger in the bar [scope-48, scope-80] ─────────── */

    /* In the voice of this register's own nav links (Kenny, 2026-09-14,
       search-voice "Per thema"): widely spaced capitals with room under them
       for the gradient stripe that runs out beneath them, and the core ink
       with a low inner glow, when pointed at. The link's typeface, case,
       spacing, shape and pointer answer are restated here, because the
       trigger is a button beside the list rather than a link in it. The
       underline a plain link carries is not: it says "this is a link", and
       the trigger is not one. */
    [data-theme='synthwave'] .kp-nav__search .kp-nav__search-trigger {
        position: relative;
        padding-inline: 1.1rem;
        font-weight: 600;
        letter-spacing: 0.18em;
        text-transform: uppercase;
        border: 0;
        border-radius: 0;
        background: none;
        color: var(--foreground);
    }

    [data-theme='synthwave'] .kp-nav__search .kp-nav__search-trigger:hover,
    [data-theme='synthwave'] .kp-nav__search .kp-nav__search-trigger:focus-visible {
        color: var(--kp-core);
        background: none;
        box-shadow: inset 0 -5px 25px hsl(from var(--primary) h s l / 0.15);
    }

    [data-theme='synthwave'] .kp-nav__search .kp-nav__search-trigger::after {
        content: '';
        position: absolute;
        left: 0.6rem;
        right: 0.6rem;
        bottom: 0;
        height: 4px;
        background: var(--kp-stripe);
        transform: scaleX(0);
        transform-origin: left center;
    }

    [data-theme='synthwave'] .kp-nav__search .kp-nav__search-trigger:hover::after,
    [data-theme='synthwave'] .kp-nav__search .kp-nav__search-trigger:focus-visible::after {
        transform: scaleX(1);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] .kp-nav__search .kp-nav__search-trigger::after {
            transition: transform var(--fx-duration) var(--fx-ease);
        }
    }

    /* ── The alarm [scope-94] ──────────────────────────────────────────────
       A neon sign in the night: a violet plate from its background, the red headline haloed in the pink of its primary, pink stripes and a pink frame. Every colour is one of this theme's tokens. The
       button keeps this register's shape and takes the alarm's paint, on
       selectors long enough to outrank this register's own button states;
       the dialog takes no focus ring, because in the auto mode the whole
       screen is what has focus. */
    [data-theme='synthwave'] .kp-alarm {
        --kp-alarm-ground: hsl(from var(--background) h s 4% / 0.95);
        --kp-alarm-ink: hsl(from var(--destructive) h s max(l, 62));
        --kp-alarm-soft: var(--foreground);
        --kp-alarm-split: var(--primary);
        --kp-alarm-on-ink: hsl(from var(--background) h s 4%);
        --kp-alarm-glow: hsl(from var(--primary) h s l / 0.45);
        --kp-alarm-halo: hsl(from var(--primary) h s l / 0.6);
        --kp-alarm-scan: hsl(from var(--primary) h s l / 0.08);
        --kp-alarm-vignette: hsl(from var(--background) h s 2% / 0.8);
        --kp-alarm-stripe: var(--primary);
        --kp-alarm-frame: 2px solid var(--primary);
    }

    [data-theme='synthwave'] .kp-alarm:focus-visible {
        outline: none;
    }

    [data-theme='synthwave'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack,
    [data-theme='synthwave'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:hover:not(:disabled),
    [data-theme='synthwave'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:active:not(:disabled) {
        border-color: var(--kp-alarm-ink);
        background: var(--kp-alarm-ink);
        color: var(--kp-alarm-on-ink);
        text-shadow: none;
    }

    [data-theme='synthwave'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:is(:hover, :focus-visible):not(:disabled):not(:active) {
        background: var(--kp-alarm-on-ink);
        color: var(--kp-alarm-ink);
    }

    [data-theme='synthwave'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep,
    [data-theme='synthwave'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep:is(:hover, :focus-visible):not(:disabled) {
        border-color: currentColor;
        background: transparent;
        color: inherit;
        text-shadow: none;
    }

    /* A submenu item's mark [Kenny, 2026-09-20]: the neon dot it marks its own rows with. */
    [data-theme='synthwave'] .kp-sidenav__submenu .kp-sidenav__link {
        --kp-sidenav-submenu-mark: '●';
    }

    /* ── The OSD names, the chrome counts [G15, type = osd; Kenny,
       2026-10-07 20:41] ─────────────────────────────────────────────────────
       Identifiers, timestamps and the data faces speak in the OSD (VT323);
       KP Tech Mono, the register's data face until now, is cyberpunk's label
       face and leaves synthwave. VT323 stands small on its em, so every
       surface that takes it from `--kp-mono` is sized by its x-height. */
    [data-theme='synthwave'] {
        --kp-mono: var(--kp-osd);
    }

    [data-theme='synthwave']
        :is(
            .kp-id,
            .kp-url,
            .kp-numeric,
            .kp-timestamp,
            .kp-masked,
            .kp-copyable,
            .kp-truncate,
            .kp-cell-break,
            .kp-cell-truncate,
            .kp-diff__line,
            .kp-diff__hunk,
            .kp-tree,
            .kp-colorpicker__value,
            .kp-spec,
            .kp-log
        ) {
        font-size-adjust: 0.5;
    }

    /* ── The VCR's symbols [G13, tone = osd; Kenny, 2026-10-07 23:00] ───────
       A warning is a pause (two tubes), a failure a stop (a square), drawn in
       the part's own ink before its figure or its label: the second channel
       that is not colour. The part's top edge turns to the tone's ink, the
       stripe and the sides that fall from it with it (the tube turns). The
       plate and its ink stay the status pair the package guarantees. ───── */
    [data-theme='synthwave'] .kp-kpi[data-kp-tone='warning'] {
        --kp-stripe-from: var(--warning-foreground);
        --kp-stripe-to: var(--warning-foreground);
    }

    [data-theme='synthwave'] .kp-kpi[data-kp-tone='destructive'] {
        --kp-stripe-from: var(--destructive);
        --kp-stripe-to: var(--destructive);
    }

    [data-theme='synthwave']
        :is(.kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value, .kp-alert--warning, .kp-alert--destructive)::before {
        content: '';
        flex: none;
        align-self: center;
        filter: drop-shadow(0 0 3px currentColor);
    }

    [data-theme='synthwave'] :is(.kp-kpi[data-kp-tone='warning'] .kp-kpi__value, .kp-alert--warning)::before {
        inline-size: 0.5em;
        block-size: 0.6em;
        background: linear-gradient(90deg, currentColor 0 34%, transparent 34% 66%, currentColor 66%);
    }

    [data-theme='synthwave'] :is(.kp-kpi[data-kp-tone='destructive'] .kp-kpi__value, .kp-alert--destructive)::before {
        inline-size: 0.5em;
        block-size: 0.5em;
        background: currentColor;
    }

    [data-theme='synthwave'] :is(.kp-alert--warning, .kp-alert--destructive)::before {
        font-size: 1.1rem;
    }

    /* The focus of a key figure or a menu entry that is a link or a toggle is
       the same two tubes as a button's; hovering turns its tube up [G17: an
       element inside a composite is the theme's own element]. */
    [data-theme='synthwave'] :is(a.kp-kpi, .kp-kpi--toggle):hover {
        border-color: transparent;
        --kp-stripe-from: var(--kp-pink-text);
        --kp-stripe-to: var(--kp-core);
    }

    [data-theme='synthwave'] :is(a.kp-kpi, .kp-kpi--toggle):hover .kp-kpi__value {
        color: var(--kp-core);
        text-shadow: var(--kp-sw-tube-up);
    }

    /* A press charges the part [G14, press = charge; Kenny, 2026-10-07 23:54],
       as it charges a button: the top edge burns near-white (the stripe and
       the sides that fall from it), the bloom gathers above it and the ground
       takes the pressed token; nothing moves. Held for as long as the press
       lasts (`:active`) and, on a toggle, for as long as it is on
       (`aria-pressed='true'`). A toggle that is on says so a second way that
       is not colour [DI2]: the VCR's play symbol before its label and the
       horizon of its floor lit near-white. The focus rails below win while the
       keyboard is on the part. */
    [data-theme='synthwave'] :is(a.kp-kpi, button.kp-kpi--toggle):active,
    [data-theme='synthwave'] button.kp-kpi--toggle[aria-pressed='true'] {
        --kp-stripe-from: var(--kp-core);
        --kp-stripe-to: var(--kp-core);
        background-color: var(--secondary-active);
        box-shadow:
            inset 0 -2px 0 0 hsl(from var(--sidebar-background) h s l / 0.7),
            0 -4px 14px 0 hsl(from var(--primary) h s l / 0.8),
            0 0 40px hsl(from var(--sidebar-background) h s l / 0.6);
    }

    [data-theme='synthwave'] button.kp-kpi--toggle[aria-pressed='true']::after {
        border-block-start-color: var(--kp-core);
        box-shadow:
            0 -2px 12px hsl(from var(--primary) h s l / 0.8),
            0 -1px 3px hsl(from var(--kp-core) h s l / 0.6);
    }

    /* The play symbol stands in the tile's own padding, out of the flow: a
       tile that is pressed keeps the label's line and every sibling's place. */
    [data-theme='synthwave'] button.kp-kpi--toggle[aria-pressed='true'] > .kp-kpi__label::before {
        content: '';
        position: absolute;
        inset-inline-start: 0.2rem;
        margin-block-start: 0.35em;
        inline-size: 0.55em;
        block-size: 0.8em;
        pointer-events: none;
        background:
            linear-gradient(to top right, var(--kp-core) 50%, transparent 50%) 0 0 / 100% 50% no-repeat,
            linear-gradient(to bottom right, var(--kp-core) 50%, transparent 50%) 0 100% / 100% 50% no-repeat;
        filter: drop-shadow(0 0 3px var(--primary));
    }

    [data-theme='synthwave'] :is(a.kp-kpi, .kp-kpi--toggle):focus-visible {
        outline: none;
        box-shadow:
            var(--kp-sw-rails-in),
            0 0 12px 0 hsl(from var(--primary) h s l / 0.6);
    }

    [data-theme='synthwave'] .kp-menu__item:is(:hover, :focus-visible) {
        color: var(--kp-core);
        text-shadow: var(--kp-sw-tube);
    }

    [data-theme='synthwave'] .kp-menu__item:focus-visible {
        outline: none;
        box-shadow: var(--kp-sw-rails-in);
    }

    /* ── Focus is two tubes on every part that takes it [G14, focus = rails;
       DI2; Kenny, 2026-10-07 23:00] ────────────────────────────────────────
       One rule for the rest of the package's focusable parts, so no part is
       left on the global ring (a contrast outline and an inner ring, which is
       the other themes'). `:focus-visible` only: a click leaves nothing
       behind. A part that sits inside a frame, a cell, a row or a scroller
       takes the rails inside it; a link, a mark or a plate takes them outside.
       Forced colours repaint an outline (below), since a box-shadow is not
       drawn there. ──────────────────────────────────────────────────────── */
    [data-theme='synthwave']
        :is(
            .kp-tab,
            .kp-pagination a,
            .kp-pagination button,
            .kp-breadcrumb a,
            .kp-accordion__summary,
            .kp-tree [role='treeitem'],
            .kp-table :is(th, td, button, a),
            .kp-combobox__input,
            .kp-combobox__list [role='option'],
            .kp-combobox button,
            .kp-calendar__day,
            .kp-datepicker__day,
            .kp-chart__source,
            .kp-chart-zoom__reset,
            .kp-chart__release,
            .kp-chart__show-all,
            .kp-chart__plot,
            .kp-kpi__chart-plot,
            .kp-kpi__link,
            .kp-wizard [data-kp-step],
            .kp-grid__tile,
            .kp-sidenav__link,
            .kp-nav__link,
            .kp-nav__menu a,
            .kp-nav__search-trigger,
            .kp-nav__toggle,
            .kp-tag__remove,
            .kp-colorpicker__swatch,
            .kp-split__separator,
            .kp-form__summary,
            .kp-theme-option,
            .kp-palette__input,
            .kp-palette [role='option'],
            .kp-theme-menu__list :is(button, [role='option']),
            .kp-datepicker button,
            .kp-table-wrap,
            .kp-sidenav__category-toggle,
            .kp-nav__disclosure,
            input[type='range'],
            .kp-field__input,
            textarea,
            select,
            summary
        ):focus-visible {
        outline: none;
        box-shadow: var(--kp-sw-rails-in);
    }

    /* A slider paints no inset shadow (its track is the browser's), so its two tubes run outside it
       (Firefox Tab audit, research/all-themes/_audit/tab-paint.mjs: 0 px changed with the inset ones).
       The attribute twice outranks the list above, whose :is() takes its most specific entry. */
    [data-theme='synthwave'] input[type='range'][type='range']:focus-visible {
        box-shadow: var(--kp-sw-rails-out);
    }

    /* The option a list marks as the one the keyboard is on (`aria-activedescendant`
       keeps the focus in the input) takes the same two tubes, while the input
       has the keyboard. */
    [data-theme='synthwave']
        :is(
            .kp-combobox:has(.kp-combobox__input:focus-visible) .kp-combobox__option.is-active,
            .kp-palette:has(.kp-palette__input:focus-visible) .kp-palette__option.is-active
        ) {
        box-shadow: var(--kp-sw-rails-in);
    }

    /* A row that takes the focus rails across its cells, its two ends closing the
       sides. */
    [data-theme='synthwave'] .kp-table tr:focus-visible > :is(th, td) {
        box-shadow:
            inset 0 var(--kp-sw-rail) 0 0 var(--kp-core),
            inset 0 calc(var(--kp-sw-rail) * 2) 0 0 var(--focus-ring-contrast),
            inset 0 calc(var(--kp-sw-rail) * -1) 0 0 var(--kp-core),
            inset 0 calc(var(--kp-sw-rail) * -2) 0 0 var(--focus-ring-contrast);
    }

    [data-theme='synthwave'] .kp-table tr:focus-visible > :first-child {
        box-shadow:
            var(--kp-sw-rails-in),
            inset 1px 0 0 0 var(--focus-ring);
    }

    [data-theme='synthwave'] .kp-table tr:focus-visible > :last-child {
        box-shadow:
            var(--kp-sw-rails-in),
            inset -1px 0 0 0 var(--focus-ring);
    }

    [data-theme='synthwave'] .kp-table tr:focus-visible {
        outline: none;
    }

    /* A link in running text and the small marks stand on their own: the rails
       sit outside them, close, and their own glow stays. */
    [data-theme='synthwave']
        :is(
            a:not(
                .kp-button,
                .kp-kpi,
                .kp-nav__link,
                .kp-nav__menu a,
                .kp-sidenav__link,
                .kp-breadcrumb a,
                .kp-pagination a,
                .kp-table a,
                .kp-menu__item
            ),
            .kp-field__check,
            .kp-switch__input,
            .kp-radio
        ):focus-visible {
        outline: none;
        box-shadow:
            var(--kp-sw-rails-out),
            0 0 12px 0 hsl(from var(--primary) h s l / 0.6);
    }

    /* Whatever else takes the keyboard (a handle, a theme swatch, a custom
       widget with a role) is a part like any other: the same two tubes inside
       it, at almost no specificity, so every rule above and any consumer's own
       wins. The network graph is left as it is (it is no theme's target). */
    :where([data-theme='synthwave'])
        :where(button, [role='button'], [role='tab'], [role='menuitem'], [role='option'], [role='gridcell'], [tabindex]):not(
            .kp-graph *
        ):focus-visible {
        outline: none;
        box-shadow: var(--kp-sw-rails-in);
    }

    @media (forced-colors: active) {
        [data-theme='synthwave'] :focus-visible {
            outline: 2px solid Highlight;
            outline-offset: 2px;
        }
    }
}

/* ── Signature [scope-140] ─────────────────────────────────────────────── */
/* synthwave's approved signature (Kenny, 2026-10-03, three review rounds): the
   progress bar and the ten elements (spinner, skeleton, switch, check and
   radio, toast, dialog, tooltip, wizard steps, empty state, link hover),
   ported once from research/progress-signature/themes/synthwave.css and research/signature-elements/themes/synthwave.css
   and maintained here from now on. In kp.signature, which css/themes.css
   orders after kp.register, so it draws over the register exactly as the
   approved demos did, whatever the weight of a register selector. */
@layer kp.signature {
    /* The link signature is for links in running text; a link in a navigation,
       a menu, a breadcrumb (a nav) or the footer keeps its own component's look
       (scope-93: no link colour in a navigation). */
    /* A shadow or outline the signature draws on a focusable control yields to
       the theme's focus ring while the control has focus (DI2). */
    [data-theme='synthwave'] .kp-progressbar {
        /* The bars fill as they were [loading = combo, Kenny, 2026-10-07 23:54]:
           four beats on the sunrise curve, the head with the fill, the bar
           following the page tube a beat behind (below). */
        --kp-progressbar-duration: calc(4 * var(--kp-sw-beat));
        --kp-progressbar-ease: var(--kp-sw-sun);
        --kp-progressbar-height: calc(1.125rem * var(--kp-progressbar-scale, 1));
        --kp-sw-road: calc(2.25rem * var(--kp-progressbar-scale, 1));
        --kp-sw-void: var(--sidebar-background);
        --kp-sw-core: var(--kp-core, hsl(from var(--foreground) h 20% 98%));
    }

    [data-theme='synthwave'] .kp-progressbar__track {
        border-radius: calc(var(--radius) * var(--kp-progressbar-scale, 1));
        background: var(--kp-sw-void);
    }

    [data-theme='synthwave'] .kp-progressbar__track::before {
        content: '';
        position: absolute;
        inset: 0;
        background:
            linear-gradient(hsl(from var(--border-strong) h s l / 0.5) 0 0) 0 50% / 100% 1px no-repeat,
            repeating-linear-gradient(
                90deg,
                hsl(from var(--border-strong) h s l / 0.38) 0 1px,
                transparent 1px calc(1.5rem * var(--kp-progressbar-scale, 1))
            );
    }

    [data-theme='synthwave'] .kp-progressbar__track::after {
        content: '';
        position: absolute;
        inset: 0;
        z-index: 2;
        border-radius: inherit;
        box-shadow: inset 0 0 0 1px var(--border-strong);
        pointer-events: none;
    }

    [data-theme='synthwave'] .kp-progressbar__fill {
        background:
            linear-gradient(
                to bottom,
                transparent 0 48%,
                var(--kp-sw-void) 48% 54%,
                transparent 54% 64%,
                var(--kp-sw-void) 64% 73%,
                transparent 73% 81%,
                var(--kp-sw-void) 81% 92%,
                transparent 92%
            ),
            linear-gradient(
                90deg,
                var(--kp-sun-bottom, hsl(from var(--primary) calc(h - 34) s l)),
                var(--primary) 45%,
                var(--kp-sun-top, var(--warning-foreground))
            );
        transition-timing-function: var(--kp-sw-sun);
    }

    [data-theme='synthwave'] .kp-progressbar__head {
        inset-inline-start: -2px;
        inline-size: 2px;
        z-index: 1;
        background: var(--kp-sw-core);
        box-shadow:
            0 0 3px hsl(from var(--primary) h s l / 0.9),
            0 0 8px hsl(from var(--primary) h s l / 0.7),
            0 0 16px hsl(from var(--primary) h s l / 0.45);
        transition-timing-function: var(--kp-sw-sun);
    }

    [data-theme='synthwave'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
        inset-inline-end: 0;
        inline-size: auto;
        overflow: hidden;
        clip-path: none;
        animation: none;
        background: none;
    }

    [data-theme='synthwave'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill::before {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: calc(-1 * var(--kp-sw-road));
        inline-size: calc(100% + 2 * var(--kp-sw-road));
        background: linear-gradient(
                90deg,
                var(--kp-sw-core) 0 calc(1.25rem * var(--kp-progressbar-scale, 1)),
                transparent calc(1.25rem * var(--kp-progressbar-scale, 1))
            )
            0 50% / var(--kp-sw-road) 3px repeat-x;
        filter: drop-shadow(0 0 2px var(--primary)) drop-shadow(0 0 5px hsl(from var(--primary) h s l / 0.8));
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill::before {
            animation: kp-sw-road 600ms linear infinite;
        }

        /* A bar with a share is drawn from nothing to its mark when it arrives:
           the tube leads, the bar follows one beat behind, then it fills, on
           the sunrise curve, in four beats. */
        [data-theme='synthwave'] .kp-progressbar:not([data-kp-indeterminate]) .kp-progressbar__fill {
            animation: kp-sw-bar-fill calc(4 * var(--kp-sw-beat)) var(--kp-sw-sun) var(--kp-sw-beat) backwards;
        }

        [data-theme='synthwave'] .kp-progressbar:not([data-kp-indeterminate]) .kp-progressbar__head {
            animation: kp-sw-bar-head calc(4 * var(--kp-sw-beat)) var(--kp-sw-sun) var(--kp-sw-beat) backwards;
        }
    }

    @keyframes kp-sw-bar-fill {
        from {
            clip-path: inset(0 100% 0 0);
        }
    }

    @keyframes kp-sw-bar-head {
        from {
