        }
    }

    [data-theme='synthwave'] {
        --kp-sig-sw-ease: cubic-bezier(0.22, 1, 0.36, 1);
        --kp-sig-sw-sun: linear-gradient(var(--kp-sun-top), var(--kp-sun-bottom));
        /* The sun's stripe cuts: opaque, then horizontal gaps that widen
           towards the horizon. Used as a mask, so only their alpha counts. */
        --kp-sig-sw-cuts: linear-gradient(
            to bottom,
            var(--foreground) 0 52%,
            transparent 52% 58%,
            var(--foreground) 58% 68%,
            transparent 68% 76%,
            var(--foreground) 76% 84%,
            transparent 84% 93%,
            var(--foreground) 93%
