    }

    [data-theme='synthwave'] .kp-spinner {
        /* The sun sets and rises, on the beat [G11, spinner = sun; G4]: one
           cycle in eight beats, each half on the sunrise curve. */
        --kp-sig-dur: calc(8 * var(--kp-sw-beat));
        position: relative;
        overflow: hidden;
        border: 0;
        border-radius: 2px;
        background: none;
        animation: none;
    }

    [data-theme='synthwave'] .kp-spinner::before {
        content: '';
        position: absolute;
        inset-inline: 8%;
        inset-block-start: 10%;
        aspect-ratio: 1;
        border-radius: 50%;
        background: var(--kp-sig-sw-sun);
        -webkit-mask: var(--kp-sig-sw-cuts);
        mask: var(--kp-sig-sw-cuts);
    }

    [data-theme='synthwave'] .kp-spinner::after {
        content: '';
        position: absolute;
        inset-inline: 0;
        inset-block: 66% 0;
