        background: var(--card);
        color: var(--muted-foreground);
    }

    [data-theme='synthwave'] .kp-wizard__steps li[data-state='done'] {
        color: var(--foreground);
    }

    [data-theme='synthwave'] .kp-wizard__steps li[data-state='done']::before {
        border-color: var(--accent);
        color: var(--accent);
        box-shadow: 0 0 6px hsl(from var(--accent) h s l / 0.5);
    }

    [data-theme='synthwave'] .kp-wizard__steps li[data-state='current'] {
        color: var(--kp-pink-text);
    }

    [data-theme='synthwave'] .kp-wizard__steps li[data-state='current']::before {
        border: 0;
        background:
            linear-gradient(
                to bottom,
                transparent 62%,
                hsl(from var(--sidebar-background) h s l / 0.55) 62% 68%,
                transparent 68% 78%,
                hsl(from var(--sidebar-background) h s l / 0.55) 78% 84%,
                transparent 84%
            ),
            var(--kp-sig-sw-sun);
        box-shadow: 0 0 10px hsl(from var(--primary) h s l / 0.5);
        color: var(--sidebar-background);
        font-weight: 700;
    }

    [data-theme='synthwave'] .kp-empty {
        position: relative;
        padding: 3.75rem 1.5rem 1.25rem;
        border: 0;
        border-radius: 2px;
    }

    [data-theme='synthwave'] .kp-empty::before {
        content: '';
        position: absolute;
        inset-block-start: 0.6rem;
        inset-inline-start: calc(50% - 1.6rem);
        inline-size: 3.2rem;
        block-size: 3.2rem;
        border-radius: 50%;
        background: var(--kp-sig-sw-sun);
