            var(--foreground) 0 50%,
            transparent 50% 56%,
            var(--foreground) 56% 63%,
            transparent 63% 70%,
            var(--foreground) 70% 75%,
            transparent 75%
        );
        mask: linear-gradient(
            to bottom,
            var(--foreground) 0 50%,
            transparent 50% 56%,
            var(--foreground) 56% 63%,
            transparent 63% 70%,
            var(--foreground) 70% 75%,
            transparent 75%
        );
