    [data-theme='synthwave'] .kp-empty::after {
        content: '';
        position: absolute;
        inset-block-start: calc(0.6rem + 2.4rem);
        inset-inline: 15%;
        block-size: 1.5px;
        background: linear-gradient(to right, transparent, var(--accent) 20%, var(--accent) 80%, transparent);
        box-shadow: 0 0 6px hsl(from var(--accent) h s l / 0.5);
    }

    [data-theme='synthwave'] .kp-empty__title {
        color: var(--foreground);
        letter-spacing: 0.04em;
    }

    [data-theme='synthwave'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a) {
        padding-block-end: 2px;
        text-decoration: none;
        background: var(--kp-stripe) left bottom / 100% 2px no-repeat;
        -webkit-box-decoration-break: clone;
        box-decoration-break: clone;
    }

    [data-theme='synthwave']
        a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a):hover {
        background-size: 100% 3px;
        text-shadow: var(--kp-tube-pink);
    }

    @media (forced-colors: active) {
        [data-theme='synthwave'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a) {
            text-decoration: underline;
        }
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] .kp-spinner::before {
            animation: kp-sig-synthwave-sw-set var(--kp-sig-dur) var(--kp-sw-sun) infinite;
        }

        [data-theme='synthwave'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)::after {
            animation: kp-sig-synthwave-sw-sheen var(--kp-sig-dur) var(--kp-sig-sw-ease) infinite;
        }

        [data-theme='synthwave'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block):nth-child(2)::after {
            animation-delay: 220ms;
        }

        [data-theme='synthwave'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block):nth-child(3)::after {
            animation-delay: 440ms;
        }

