            opacity: 1;
        }

        [data-theme='synthwave']
            :is(
                .kp-nav__links > li:is(:hover, :focus-within, [data-kp-nav-menu-open]) > .kp-nav__menu:not(.kp-nav__menu--wide),
                .kp-nav__links > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true'])) > .kp-nav__menu--wide
            ) {
            clip-path: inset(-4rem);
        }

        [data-theme='synthwave']
            :is(
                .kp-nav__links > li:is(:hover, :focus-within, [data-kp-nav-menu-open]) > .kp-nav__menu:not(.kp-nav__menu--wide),
                .kp-nav__links > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true'])) > .kp-nav__menu--wide
            )::after {
            inset-block-start: 0;
            opacity: 0;
            transition:
                inset-block-start calc(2 * var(--kp-sw-beat)) var(--kp-sw-sun),
                opacity calc(2 * var(--kp-sw-beat)) cubic-bezier(0.85, 0, 1, 1);
        }

        @starting-style {
            [data-theme='synthwave']
                :is(
                    .kp-nav__links > li:is(:hover, :focus-within, [data-kp-nav-menu-open]) > .kp-nav__menu:not(.kp-nav__menu--wide),
                    .kp-nav__links > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true'])) > .kp-nav__menu--wide
                ) {
                clip-path: inset(100% -4rem -4rem -4rem);
            }

            [data-theme='synthwave']
                :is(
                    .kp-nav__links > li:is(:hover, :focus-within, [data-kp-nav-menu-open]) > .kp-nav__menu:not(.kp-nav__menu--wide),
                    .kp-nav__links > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true'])) > .kp-nav__menu--wide
                )::after {
                inset-block-start: calc(100% - 2px);
                opacity: 1;
            }
        }

