            [data-theme='synthwave'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links {
                clip-path: inset(-1rem);
            }

            [data-theme='synthwave'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links::after {
                inset-block-start: 0;
                opacity: 0;
                transition:
                    inset-block-start calc(2 * var(--kp-sw-beat)) var(--kp-sw-sun),
                    opacity calc(2 * var(--kp-sw-beat)) cubic-bezier(0.85, 0, 1, 1);
            }

            @starting-style {
                [data-theme='synthwave'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links {
                    clip-path: inset(100% -1rem -1rem -1rem);
                }

                [data-theme='synthwave'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links::after {
                    inset-block-start: calc(100% - 2px);
                    opacity: 1;
