    }

    [data-theme='phantom'] .kp-datatable {
        border: 2px solid var(--border);
        border-radius: 0;
    }

    [data-theme='phantom'] .kp-diff {
        background: var(--card);
        border: 2px solid var(--border);
        border-radius: 0;
    }

    [data-theme='phantom'] .kp-split {
        gap: 0;
    }

    /* ── The scrollbar joins the theme ────────────────────────────────── */

