        color: var(--primary);
    }

    /* The spec sheet: a cut-paper card with the red edge. */
    [data-theme='phantom'] .kp-spec {
        background: var(--card);
        color: var(--card-foreground);
        padding: 1.3rem 1.4rem 1.5rem;
        border-left: 5px solid var(--primary);
        clip-path: var(--kp-paperclip);
        font-family: var(--kp-mono);
        font-size: 0.74rem;
        line-height: 1.75;
    }

    [data-theme='phantom'] .kp-spec dt {
        color: var(--muted-foreground);
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }

    /* The log wears what this register already decided for its other data
 * surface, `.kp-spec` — the same ground, the same edge, the same face
 * [gap-14]. A new component that invents a look of its own is a
 * twenty-third decision nobody made. */
    [data-theme='phantom'] .kp-log {
        background: var(--card);
        color: var(--card-foreground);
        clip-path: var(--kp-paperclip);
        font-family: var(--kp-mono);
    }

    [data-theme='phantom'] .kp-log__level {
        --kp-log-level-ink: var(--muted-foreground);
