/* ── Signature [scope-140] ─────────────────────────────────────────────── */
/* phantom's approved signature (Kenny, 2026-10-03, three review rounds): the
   progress bar and the ten elements (spinner, skeleton, switch, check and
   radio, toast, dialog, tooltip, wizard steps, empty state, link hover),
   ported once from research/progress-signature/themes/phantom.css and research/signature-elements/themes/phantom.css
   and maintained here from now on. In kp.signature, which css/themes.css
   orders after kp.register, so it draws over the register exactly as the
   approved demos did, whatever the weight of a register selector. */
@layer kp.signature {
    /* The link signature is for links in running text; a link in a navigation,
       a menu, a breadcrumb (a nav) or the footer keeps its own component's look
       (scope-93: no link colour in a navigation). */
    /* A shadow or outline the signature draws on a focusable control yields to
       the theme's focus ring while the control has focus (DI2). */
    [data-theme='phantom'] .kp-progressbar {
        --kp-progressbar-height: calc(1rem * var(--kp-progressbar-scale, 1));
        --kp-ps-slant: calc(0.375rem * var(--kp-progressbar-scale, 1));
        --kp-ps-shard: calc(0.3125rem * var(--kp-progressbar-scale, 1));
        --kp-ps-gap: calc(3px * var(--kp-progressbar-scale, 1));
        --kp-ps-dot: calc(5px * var(--kp-progressbar-scale, 1));
        --kp-ps-stripe: calc(6px * var(--kp-progressbar-scale, 1));
        --kp-ps-pitch: calc(13px * var(--kp-progressbar-scale, 1));
        --kp-ps-edge: calc(var(--kp-value) * (100% - var(--kp-ps-slant)));
        /* The cut's slant, full from the first two percent, none at zero, so an
           empty card shows no red at all. */
        --kp-ps-cut: calc(var(--kp-ps-slant) * min(1, var(--kp-value) * 50));
    }

    [data-theme='phantom'] .kp-progressbar__track {
        border-radius: 0;
        background: var(--border-strong);
        clip-path: polygon(var(--kp-ps-slant) 0, 100% 0, calc(100% - var(--kp-ps-slant)) 100%, 0 100%);
    }

    [data-theme='phantom'] .kp-progressbar__track::before {
        content: '';
        position: absolute;
        inset: 2px 2px 2px 2px;
        background:
            radial-gradient(
                    circle at center,
                    color-mix(in srgb, var(--foreground) 28%, transparent) calc(0.9px * var(--kp-progressbar-scale, 1)),
                    transparent calc(1px * var(--kp-progressbar-scale, 1))
                )
                0 0 / var(--kp-ps-dot) var(--kp-ps-dot),
            var(--background);
        clip-path: polygon(calc(var(--kp-ps-slant) - 1px) 0, 100% 0, calc(100% - var(--kp-ps-slant) + 1px) 100%, 0 100%);
    }

    [data-theme='phantom'] .kp-progressbar__track::after {
        content: '';
        position: absolute;
        inset: 0;
        z-index: 1;
        background: var(--kp-red-deep, var(--sidebar-background));
        clip-path: polygon(
            0 0,
            calc(var(--kp-ps-edge) + var(--kp-ps-cut) + var(--kp-ps-gap) * min(1, var(--kp-value) * 50)) 0,
            calc(var(--kp-ps-edge) + var(--kp-ps-gap) * min(1, var(--kp-value) * 50)) 100%,
            0 100%
        );
        transition: clip-path var(--fx-duration) var(--fx-ease);
    }

    [data-theme='phantom'] .kp-progressbar__fill {
        z-index: 2;
        clip-path: polygon(0 0, calc(var(--kp-ps-edge) + var(--kp-ps-cut)) 0, var(--kp-ps-edge) 100%, 0 100%);
        transition: clip-path var(--fx-duration) var(--fx-ease);
    }

    [data-theme='phantom'] .kp-progressbar__head {
        z-index: 3;
        inline-size: calc(var(--kp-ps-slant) + var(--kp-ps-shard));
        background: var(--foreground);
        clip-path: polygon(var(--kp-ps-slant) 0, 100% 0, var(--kp-ps-shard) 100%, 0 100%);
        transform: translateX(calc(var(--kp-value) * (100cqi - var(--kp-ps-slant)) + var(--kp-ps-gap) * 2 + 1px));
        transition: transform var(--fx-duration) var(--fx-ease);
    }

    [data-theme='phantom'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__track::after {
        display: none;
    }

    [data-theme='phantom'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
        inline-size: 34%;
        clip-path: polygon(var(--kp-ps-slant) 0, 100% 0, calc(100% - var(--kp-ps-slant)) 100%, 0 100%);
        box-shadow: none;
        /* The slab shoved across as a screen [G11; Kenny, 2026-10-09 on
           research/phantom-character: "the slab shoved across as a screen"]:
           busy, with no share known, the red slab is a silhouette of dots on a
           4 px cell that never resolves, 1500 ms, and again. */
        mask-image: var(--kp-sig-ph-dots);
        mask-size: 4px 4px;
        animation: kp-progressbar-phantom-shove 1500ms cubic-bezier(0.81, 0, 0, 1) infinite;
    }

    @media (prefers-reduced-motion: reduce) {
        [data-theme='phantom'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
            inset-inline: 0;
            inline-size: auto;
            animation: none;
            transform: none;
            mask-image: none;
            clip-path: none;
            background: repeating-linear-gradient(-69deg, var(--primary) 0 var(--kp-ps-stripe), transparent var(--kp-ps-stripe) var(--kp-ps-pitch));
        }
    }

    [data-theme='phantom'] {
        --kp-sig-ph-plate: var(--sidebar-background, var(--primary));
        --kp-sig-ph-cut: polygon(0 6%, 100% 0, 96% 100%, 3% 92%);
    }

    [data-theme='phantom'] .kp-spinner {
        --kp-sig-dur: 1200ms;
        position: relative;
        border: 0;
        border-radius: 0;
        background: none;
        animation: none;
    }

    [data-theme='phantom'] .kp-spinner::before,
    [data-theme='phantom'] .kp-spinner::after {
        content: '';
        position: absolute;
        inset: 0;
        clip-path: polygon(50% 0, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%);
    }

    [data-theme='phantom'] .kp-spinner::before {
        background: var(--primary);
        translate: 2px 2px;
    }

    [data-theme='phantom'] .kp-spinner::after {
        background: var(--foreground);
    }

    /* ── Loading is the red slash across a halftone block [themes/phantom/
       CHARACTER.md G10; Kenny, 2026-10-09 on research/phantom-character:
       "the red slash (as today)"]. A part that waits is a block of the screen
       with a red slash sweeping over it, 1400 ms a loop, the register's own
       skeleton, drawn on every waiting surface the package has: the skeleton's
       lines, blocks and circles, the loading meter, the table's busy panel,
       the loading entry of a menu, a busy button and card, the tiles' cards,
       the calendar's days and busy panel, the chart's plot. The block fills
       the whole element and is shaped like the result (the line's leaning
       sheet, the plate's cut corner, the circle); the part's words stand
       above it. Nothing is translucent: the layout layer's busy dim is off. ── */
    [data-theme='phantom'] {
        --kp-sig-ph-block: radial-gradient(circle, hsl(from var(--foreground) h s l / 0.32) 1px, transparent 1.4px) 0 0 / 5px 5px, var(--muted);
        --kp-sig-ph-slash: polygon(0.8rem 0, 2.6rem 0, 1.8rem 100%, 0 100%);
    }

    [data-theme='phantom'] .kp-skeleton {
        --kp-sig-dur: 1400ms;
        position: relative;
        overflow: hidden;
        border-radius: 0;
        background: var(--kp-sig-ph-block);
        animation: none;
    }

    [data-theme='phantom'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        block-size: 0.95rem;
        clip-path: var(--kp-sig-ph-cut);
    }

    [data-theme='phantom'] .kp-skeleton--block {
        clip-path: var(--kp-paperclip);
    }

    [data-theme='phantom'] .kp-skeleton--circle {
        border-radius: 50%;
    }

    [data-theme='phantom'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) + .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        margin-block-start: 0.55rem;
    }

    [data-theme='phantom'] .kp-skeleton::after {
        content: '';
        position: absolute;
        inset: 0;
        background: var(--primary);
        clip-path: var(--kp-sig-ph-slash);
        translate: -2.8rem 0;
    }

    /* The other surfaces that wait. */
    [data-theme='phantom']
        :is(
            .kp-card[aria-busy='true'],
            .kp-tiles[aria-busy='true'] > .kp-card,
            .kp-chart__state[data-kp-state='loading'],
            .kp-calendar__day[data-kp-tone='loading'],
            .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading]
        ) {
        --kp-busy-opacity: 1;
        position: relative;
        isolation: isolate;
        overflow: clip;
        animation: none;
    }

    /* The block and the slash are drawn against the panel itself: both
       panels are static in the package (a flex item in the table's layer, a
       grid item of the month), so without a position of their own the two
       layers below were laid against the nearest positioned ancestor, the
       whole window in the review stage (Kenny, review round 2: "staat de
       laadanimatie over het hele scherm ipv enkel in de tabel"; lesson 5:
       the panel is static, so `relative` moves nothing). */
    [data-theme='phantom'] :is(.kp-datatable__busy-panel, .kp-calendar--busy-whole > .kp-calendar__busy) {
        --kp-busy-opacity: 1;
        position: relative;
        isolation: isolate;
        overflow: clip;
    }

    [data-theme='phantom']
        :is(
            .kp-card[aria-busy='true'],
            .kp-tiles[aria-busy='true'] > .kp-card,
            .kp-chart__state[data-kp-state='loading'],
            .kp-calendar__day[data-kp-tone='loading'],
            .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading],
            .kp-datatable__busy-panel,
            .kp-calendar--busy-whole > .kp-calendar__busy
        )::before {
        content: '';
        position: absolute;
        inset: 0;
        z-index: -2;
        background: var(--kp-sig-ph-block);
        transform: none;
        translate: none;
        mask-image: none;
        pointer-events: none;
    }

    [data-theme='phantom']
        :is(
            .kp-card[aria-busy='true'],
            .kp-tiles[aria-busy='true'] > .kp-card,
            .kp-chart__state[data-kp-state='loading'],
            .kp-calendar__day[data-kp-tone='loading'],
            .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading],
            .kp-datatable__busy-panel,
            .kp-calendar--busy-whole > .kp-calendar__busy
        )::after {
        content: '';
        position: absolute;
        inset: 0;
        z-index: -1;
        background: var(--primary);
        clip-path: var(--kp-sig-ph-slash);
        translate: -2.8rem 0;
        pointer-events: none;
    }

    /* A busy button is the key cap with its plate a block of the screen and the
       slash across it; its label and spinner stand above. */
    [data-theme='phantom'] .kp-button[aria-busy='true'] {
        --kp-plate-fill: var(--kp-sig-ph-block);
        --kp-plate-ink: var(--foreground);
        --kp-busy-opacity: 1;
        overflow: clip;
    }

    [data-theme='phantom'] .kp-button[aria-busy='true']::after {
        width: calc(100% - 4px);
        background: var(--primary);
        clip-path: var(--kp-sig-ph-slash);
        translate: -2.8rem 0;
        transition: none;
        mask-image: none;
    }

    /* The loading meter: its groove is the block and the slash crosses it. */
    [data-theme='phantom'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::before {
        display: block;
        content: '';
        position: absolute;
        inset: 0;
        inline-size: auto;
        z-index: 1;
        border-radius: 0;
        background: var(--primary);
        clip-path: var(--kp-sig-ph-slash);
        translate: -2.8rem 0;
        transition: none;
        pointer-events: none;
    }

    [data-theme='phantom'] .kp-switch {
        --kp-switch-radius: 0;
        --kp-switch-thumb-radius: 0;
    }

    [data-theme='phantom'] .kp-switch__input {
        border: 2px solid var(--foreground);
        background: var(--background);
    }

    [data-theme='phantom'] .kp-switch__input::before {
        inset-block: 1px;
        inline-size: calc(var(--kp-switch-height, 1.5rem) - 2px);
        background: var(--muted-foreground);
        clip-path: polygon(22% 0, 100% 0, 78% 100%, 0 100%);
    }

    [data-theme='phantom'] .kp-switch__input:checked {
        border-color: var(--foreground);
        background: var(--primary);
    }

    [data-theme='phantom'] .kp-switch__input:checked::before {
        inset-inline-start: var(--kp-switch-inset, 0.125rem);
        background: var(--foreground);
        transform: translateX(calc(var(--kp-switch-width, 2.5rem) - var(--kp-switch-height, 1.5rem) - 2px));
    }

    [data-theme='phantom'] .kp-field__check {
        --kp-sig-dur: 300ms;
        appearance: none;
        position: relative;
        display: inline-grid;
        place-content: center;
        inline-size: 1.15rem;
        block-size: 1.15rem;
        /* Room for the slant: skewed, the box reaches about 1.3px past each side. */
        margin: 0 2px;
        border: 2px solid var(--foreground);
        border-radius: 0;
        background: var(--background);
        transform: skewX(var(--kp-skew, -8deg));
    }

    [data-theme='phantom'] .kp-field__check:not(:focus-visible) {
        box-shadow: 3px 3px 0 var(--kp-sig-ph-plate);
    }

    [data-theme='phantom'] .kp-field__check:checked {
        border-color: var(--foreground);
        background: var(--foreground);
    }

    [data-theme='phantom'] .kp-field__check:checked:not(:focus-visible) {
        box-shadow: 3px 3px 0 var(--kp-sig-ph-plate);
    }

    [data-theme='phantom'] .kp-field__check[type='checkbox']:checked::before {
        content: '';
        position: absolute;
        inset-block-start: -0.42rem;
        inset-inline-start: 0.02rem;
        inline-size: 1.25rem;
        block-size: 1.05rem;
        background: var(--primary);
        clip-path: polygon(0 52%, 22% 38%, 40% 66%, 82% 0, 100% 14%, 42% 100%);
        filter: drop-shadow(1px 1px 0 var(--primary-foreground));
        transform: skewX(calc(var(--kp-skew, -8deg) * -1));
    }

    [data-theme='phantom'] .kp-field__check[type='radio'] {
        border-radius: 50%;
        transform: none;
    }

    [data-theme='phantom'] .kp-field__check[type='radio']:checked::before {
        content: '';
        inline-size: 0.85rem;
        block-size: 0.85rem;
        background: var(--primary);
        clip-path: polygon(50% 0, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%);
    }

    [data-theme='phantom'] .kp-toast {
        --kp-sig-dur: 700ms;
        border: 2px solid var(--foreground);
        border-radius: 0;
        background: var(--background);
        color: var(--foreground);
        --kp-sig-ph-corner: var(--kp-sig-ph-plate);
        box-shadow: 6px 6px 0 var(--kp-sig-ph-corner);
        rotate: var(--kp-land);
    }

    [data-theme='phantom'] .kp-toast--success {
        border-color: var(--success-foreground);
        background: var(--success);
        color: var(--success-foreground);
        --kp-sig-ph-corner: hsl(from var(--success) h s calc(l + 16));
        box-shadow: 6px 6px 0 var(--kp-sig-ph-corner);
    }

    [data-theme='phantom'] .kp-toast--info {
        border-color: var(--info-foreground);
        background: var(--info);
        color: var(--info-foreground);
        --kp-sig-ph-corner: hsl(from var(--info) h s calc(l + 16));
        box-shadow: 6px 6px 0 var(--kp-sig-ph-corner);
    }

    [data-theme='phantom'] .kp-toast--warning {
        border-color: var(--warning-foreground);
        background: var(--warning);
        color: var(--warning-foreground);
        --kp-sig-ph-corner: hsl(from var(--warning) h s calc(l + 16));
        box-shadow: 6px 6px 0 var(--kp-sig-ph-corner);
    }

    [data-theme='phantom'] :is(.kp-toast--destructive, .kp-toast--error) {
        border-color: var(--foreground);
        background: var(--destructive);
        color: var(--destructive-foreground);
        box-shadow: 6px 6px 0 var(--kp-sig-ph-corner);
    }

    [data-theme='phantom'] .kp-toast__body {
        font-family: var(--theme-font-display);
        font-size: 1.05rem;
        font-style: italic;
        font-weight: 800;
        letter-spacing: 0.02em;
        text-transform: uppercase;
    }

    [data-theme='phantom'] .kp-dialog::backdrop {
        background:
            radial-gradient(circle, hsl(from var(--primary) h s l / 0.45) 1.4px, transparent 1.9px) 0 0 / 8px 8px,
            var(--background);
    }

    /* The unopened dialog is the one js/motion.js measures for the theme's
       time (a probe it adds and takes off), and it reads close = two thirds
       of that: so it runs one and a half throws, and the dialog that is open
       runs one, which is also its close and its opening [see the motion block
       below]. */
    [data-theme='phantom'] .kp-dialog[open] {
        --kp-sig-dur: 700ms;
    }

    [data-theme='phantom'] .kp-dialog {
        --kp-sig-dur: 1050ms;
        --kp-sig-ph-edge: 2.2rem;
        border: 3px solid var(--foreground);
        border-radius: 0;
        background: var(--background);
        box-shadow: 10px 10px 0 var(--kp-sig-ph-plate);
        rotate: var(--kp-land);
        /* Its turn, for a part inside it placed by measuring (kp-sig-phantom-fly-placed). */
        --kp-sig-ph-host-turn: var(--kp-land);
        /* The red edge stands outside the content: the title, the words and
           the buttons are inset from it by its own width and 12 px, so no word
           sits on the red [Kenny, 2026-10-09: "in a dialog with a title, the
           red on the side makes some of the content hard to read"]. */
        padding-inline-end: calc(var(--kp-sig-ph-edge) + 12px);
    }

    /* On a phone the edge is thinner, so the actions keep their words. */
    @media (max-width: 30rem) {
        [data-theme='phantom'] .kp-dialog {
            --kp-sig-ph-edge: 1.25rem;
            padding-inline-end: calc(var(--kp-sig-ph-edge) + 8px);
        }
    }

    [data-theme='phantom'] .kp-dialog.kp-drawer {
        padding-inline-end: 0;
        rotate: none;
        --kp-sig-ph-host-turn: 0deg;
    }

    /* The slash the hero carries, here as the dialog's end edge: a red plate
       cut at 40 %, behind nothing. */
    [data-theme='phantom'] .kp-dialog:not(.kp-drawer)::after {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-end: 0;
        inline-size: var(--kp-sig-ph-edge);
        background: var(--primary);
        clip-path: polygon(40% 0, 100% 0, 100% 100%, 0 100%);
        opacity: 0.9;
        pointer-events: none;
    }

    [data-theme='phantom'] .kp-dialog:not(.kp-drawer):dir(rtl)::after {
        clip-path: polygon(0 0, 60% 0, 100% 100%, 0 100%);
    }

    /* ── The second plate, drawn [G7; Kenny, 2026-10-15 02:12, research/leftover-looks,
       option 1 "one hard plate"] ────────────────────────────────────────
       The paperclip is a clip-path, and a clip-path clips the part's own box-shadow,
       so the deep red plate the register declared for a card, a menu, a toast and a
       dialog was never seen. The clip is widened to take in the room of the plate
       (--kp-sig-ph-d, the plate's offset: 4 px for a card and a menu, 6 px for a
       toast, 10 px for a dialog) and the part's own box-shadow shows through it.
       The bottom-end cut is the part's own corner: a box-shadow cannot reach it, so
       one pseudo-element fills it, red where the plate shows through (the dialog's
       ::after is its slash, so a dialog takes ::before). --kp-sig-ph-bw is the
       border the pseudo-element is placed past. A part clipped by a theme's other
       rules (a menu or a theme menu inside a surface) has no plate. */
    [data-theme='phantom'] :is(.kp-card, .kp-menu, .kp-toast, .kp-dialog:not(.kp-drawer)) {
        clip-path: polygon(
            0 var(--kp-cut-size),
            var(--kp-cut-size) 0,
            100% 0,
            100% var(--kp-sig-ph-d),
            calc(100% + var(--kp-sig-ph-d)) var(--kp-sig-ph-d),
            calc(100% + var(--kp-sig-ph-d)) calc(100% - var(--kp-cut-size) + var(--kp-sig-ph-d)),
            calc(100% - var(--kp-cut-size) + var(--kp-sig-ph-d)) calc(100% + var(--kp-sig-ph-d)),
            var(--kp-sig-ph-d) calc(100% + var(--kp-sig-ph-d)),
            var(--kp-sig-ph-d) 100%,
            0 100%
        );
