        background:
            radial-gradient(circle, var(--primary-foreground) 1px, transparent 1.4px) 0 0 / 5px 5px,
            var(--primary);
        box-shadow: inset -3px 0 0 var(--primary-foreground);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='phantom'] .kp-gantt__run[data-kp-state='running'] {
            animation: kp-sig-phantom-screen 1500ms linear infinite;
        }
    }

    /* The screen over a running slab runs start to end, one dot pitch a loop. */
    @keyframes kp-sig-phantom-screen {
        from {
            background-position:
                0 0,
                0 0;
        }

        to {
            background-position:
                5px 0,
                0 0;
        }
    }
}

/* ── The dashboard parts: what the package leaves to a register [kpadopt2-repairs] ──
   Formal keeps these parts exactly as Kenny approved them; this theme takes the three repairs the review asks for: a
   loading heat grid or matrix row as tall as its ready row (no skeleton gap between cells), an empty or failed run
   timeline with a lane-sized space for its sentence (never over the legend), the sentence as wide as its words on the
   theme's ground (never through a rule or a ghost bar), and an axis label near the end edge standing before its rule. */
@layer kp.signature {
    [data-theme='phantom'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton {
        margin-block: 0;
    }
    [data-theme='phantom'] .kp-gantt {
        --kp-gantt-tick-flip: 1;
    }
    [data-theme='phantom'] .kp-gantt:is([data-kp-state='empty'], [data-kp-state='error']) .kp-gantt__body:not(:has(.kp-gantt__lane)) {
        min-block-size: 5.25rem;
    }
    [data-theme='phantom'] .kp-gantt__state {
        box-sizing: border-box;
        display: block;
        inline-size: fit-content;
        max-inline-size: calc(100% - 2 * var(--kp-space-md, 0.75rem));
        block-size: fit-content;
        margin: auto;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--kp-gantt-state-ground, transparent);
    }
    /* The matrix's corner key breaks as two balanced lines when it has to, never leaving an arrow alone. */
    [data-theme='phantom'] .kp-matrix__corner {
        text-wrap: balance;
    }
    /* A ghost bar stands where its run would, as in formal: absolute in its track, so a second ghost of one track never
       drops under the first and out of the timeline onto the legend. */
    [data-theme='phantom'] .kp-gantt__ghost .kp-gantt__run.kp-skeleton {
        position: absolute;
    }
}

/* ── The six opt-in options of the dashboard adoption, round 3, in this theme [kpadopt3] ──
   The nav bar's separator, the timeline's day buttons and series runs, the week agenda's upcoming list on a phone and
   the facet swatch's identity pattern (the choice-filter value and the heat grid's End are behaviour only).
   Phantom's own (themes/phantom/CHARACTER.md): the separator is the red slash, leaning with the theme's
   skew; lying down across the phone's list it is a short red strip cut on the slant. A day on the axis gets the red
   slash under it when pointed at; pressed the red plate is thrown in under it, cut on the slant, the date in the black
   ink. A series' finished run carries a hard leading edge in its ink; the facet pattern is cut as a calling card. */
@layer kp.signature {
    [data-theme='phantom'] .kp-nav__sep {
        inline-size: 3px;
        border-inline-start: 0;
        background: var(--primary);
        transform: skewX(-14deg);
    }
    @container kp-nav (max-width: 40rem) {
        [data-theme='phantom'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep {
            inline-size: 6rem;
            block-size: 3px;
            margin-inline-end: auto;
            border-block-start: 0;
            clip-path: polygon(0 0, 100% 0, calc(100% - 6px) 100%, 0 100%);
            transform: none;
        }
    }

    [data-theme='phantom'] .kp-gantt__tick:is(button) {
        border-radius: 0;
        text-decoration: none;
    }
    [data-theme='phantom'] .kp-gantt__tick:is(button):hover {
        color: var(--foreground);
        box-shadow: inset 0 -3px 0 var(--primary);
    }
    [data-theme='phantom'] .kp-gantt__tick:is(button)[aria-pressed='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
        box-shadow: none;
    }
    [data-theme='phantom'] .kp-gantt__tick:is(button)[aria-pressed='true']:not(:focus-visible) {
        clip-path: polygon(4px 0, 100% 0, calc(100% - 4px) 100%, 0 100%);
    }
    [data-theme='phantom'] .kp-gantt__run[data-kp-state='ok'][data-kp-series] {
        box-shadow: inset 3px 0 0 var(--kp-gantt-series);
    }
    [data-theme='phantom'] .kp-week__next:not(:has(+ .kp-week__next:not([data-kp-day-start]))) {
        border-block-end-color: hsl(from var(--primary) h s l / 0.5);
    }
    [data-theme='phantom'] .kp-facet__swatch[data-kp-facet-pattern] {
        border-radius: 0;
        clip-path: polygon(14% 0, 100% 0, 86% 100%, 0 100%);
    }
}

/* Two numbers the writing runs on, registered so a keyframe can step them:
   the share of a loading row that is lit (0 to 1, one cell a step through
   round()) and the size of its head cursor (1 lit, 0 dark). Both rest at 1:
   the finished picture, the cursor standing lit. At the top level because
   Firefox does not register an @property inside a layer. */
@property --kp-sig-tm-k {
    syntax: '<number>';
    inherits: false;
    initial-value: 1;
}

@property --kp-sig-tm-head {
    syntax: '<number>';
    inherits: false;
    initial-value: 1;
}

/* The header's mega menu is held on screen while a transition on its panel runs
   (js/components.js settleClosing): this number is that transition, 1 open and 0
   shut, run over the menu's print (all-themes audit, 2026-10-13). */
@property --kp-sig-tm-hold {
    syntax: '<number>';
    inherits: false;
    initial-value: 0;
}

@layer kp.register {
    /* @kp-soft/themes — css/terminal-register.css
   The terminal register, 5.0.0 [S48, LIFT_PLAN row 4]: the phosphor CRT.
   Scoped to [data-theme='terminal'] and inert elsewhere; opt-in, imported
   after themes.css. The approved concept demo ("Green Phosphor",
   2026-09-08) is the reference for every value here, and
   docs/archive/RESEARCH_2026-09.md §6 is where each mechanism was measured: the
   block cursor of one character cell (Measham, dottxt.ai), the sweep band
   resting eight of ten seconds (ekeijl, a transform), the bezel by
   border-image (ekeijl, a gradient instead of the reference's image), the
   bitmap display without anti-aliasing (dottxt.ai), the static raster.

   What this file does, in order: the knobs; the glass — the bezel and the
   sweep on the root's own pseudo-elements; the type; the hooks of S45 —
   the headline that types itself with a block caret riding the last
   glyph, the mark as inverse video, the dashed rule that types itself
   out, the dashes with a plus at each end as divider; the shell line as
   navbar; the buttons as brackets and plates; the wells with the block
   cursor inside the box (R6-Q7); and one answer per component root
   (TH124). The reveals have their rest state here and their motion in
   js/effects.js; without the script every one of them stands at rest.

   Colour discipline (DI9): nothing here names a colour. One hue at 120°,
   the sanctioned red for danger, the yellow-green accent — the whole set
   (the anatomy). A phosphor brightens under pressure rather than stepping
   toward the ground: that is this theme's DI3 opt-out, written down.

   The only loops are the sweep (a transform, one pass per ten seconds,
   resting eight of them) and the caret (one opposing change per second
   over one character cell, wherever the cursor waits) — both rated in
   TIMINGS. The reference's flicker at .15s infinite was measured and
   refused (DI5); the raster never moves.

   The grammar (themes/terminal/CHARACTER.md G1-G18, Kenny's sixteen picks of
   2026-10-07 on research/terminal-character): the cursor writes the screen.
   What arrives is typed a cell a step, what opens is printed a line a step,
   what waits is an htop row with the cursor its head, a change blinks three
   times, pointing brings the cursor ring, focus is a dashed box, a press is
   entered in reverse video, a plate is a line of htop between brackets and a
   window a box line, a tone is printed in reverse and says its level, and
   the labels are written as a shell writes them. */

    [data-theme='terminal'] {
        /* The month heatmap's nav goes on two rows below this width: the
           widest month and the three buttons in this type [fix-98]. */
        --kp-calendar-nav-fit: 24.5rem;
        /* The configuration surface [AR43], the demo's values as defaults. */
        --kp-reveal-threshold: 0.5;
        --kp-reveal-stagger: 320ms;
        --kp-redact-stagger: 200ms;
        --kp-classified-delay: 260ms;
        --kp-decipher-cps: 29.41;
        /* Two clocks (themes/terminal/CHARACTER.md G4): the line, one cell
           34 ms (the headline's rate) and a printed line four cells; and the
           blink, 1000 ms for what waits, 900 ms (three rapid blinks) for what
           changed. The leave stays Kenny's 480 ms. */
        --kp-sig-tm-cell: 34ms;
        --kp-sig-tm-line: 136ms;
        --kp-sig-tm-slow: 1000ms;
        --kp-sig-tm-change: 900ms;
        /* One ring: the bright phosphor, 1 px on the line and 1 px round it. */
        --kp-sig-tm-ring: inset 0 0 0 1px var(--ring), 0 0 0 1px var(--ring);
        /* A busy part is not see-through: the row and its cursor say busy. */
        --kp-busy-opacity: 1;
        /* A printed dialog is six lines of 136 ms; js/motion.js closes in two
           thirds of the entrance it measures, capped at this. */
        --kp-close-max: 816ms;
        --kp-decipher-lead: 0;
        --kp-lift: 640ms;
        --kp-rule: 900ms;
        --kp-sweep: 10000ms;
        --kp-tube-off: 420ms;
        --kp-bezel: clamp(6px, 1.6vw, 18px);
        --kp-caret-inset: 0.625rem;
        /* The reveals this theme performs [S45]: js/effects.js reads these
           and leaves a theme that declares none at rest. */
        --kp-reveal-headline: type;
        --kp-reveal-emphasis: inverse;
        --kp-reveal-rule: dashes;
        --kp-arrival: boot;
        /* The block cursor in the box [TM2, R6-Q7]: the module writes the
           column, this file paints the cell. */
        --kp-caret: block;
        /* The bloom on the titles, and the brighter phosphor under pressure. */
        --kp-bloom: 0 0 0.4em hsl(from var(--primary) h s l / 0.28);
        --kp-bloom-accent: 0 0 0.4em hsl(from var(--accent) h s l / 0.25);
        /* One hot phosphor for text and plate alike, and one for the
           alarm — the flat pair the approved demo measured [S49, A9],
           carried by the token contract so DI9 keeps its rule. */
        --kp-hot: var(--fx-hot);
        --kp-hot-plate: var(--fx-hot);
        --kp-hot-alarm: var(--fx-hot-alarm);
        /* The dashes of a rule and the character cells of a redaction. */
        --kp-dash: repeating-linear-gradient(90deg, var(--border-strong) 0 8px, transparent 8px 14px);
        --kp-cells: repeating-linear-gradient(90deg, var(--foreground) 0 calc(1ch - 1px), transparent calc(1ch - 1px) 1ch);
    }

    /* ── The glass: the bezel and the sweep, on the root's own pseudo-elements ── */

    /* ekeijl's bezel, drawn with a gradient (no image assets): fixed, so
       it costs no layout, above everything and under the pointer's reach
       of nothing. Both assume the theme on the document root, which is how
       the package applies it. */
    /* The skip link is positioned against the page rather than flowed, so
       the padding above does not move it — and it is the first thing a
       keyboard user reaches, which makes it the worst one to hide. It
       clears the bezel on both axes instead. */
    :root[data-theme='terminal'] .kp-skip-link {
        inset-inline-start: calc(0.5rem + var(--kp-bezel));
    }

    :root[data-theme='terminal'] .kp-skip-link:focus {
        inset-block-start: calc(0.5rem + var(--kp-bezel));
    }

    /* The bezel takes its own space rather than sitting on the content
       [Kenny, 2026-09-12: "links moeten compleet en klikbaar zijn"]. It is
       `position: fixed` against the viewport, so anything the page puts
       within `--kp-bezel` of the edge disappears behind it. Measured on a
       1600px viewport, where the clamp resolves to 17.8px: the
       documentation site's first navigation link starts at 8px and lost
       9.8 of them, and the approved demo itself hid the skip link and two
       picker buttons by ten pixels each. Clicks still landed — the bezel
       takes no pointer events — but a link you cannot fully read is not a
       link you can fully use.

       Padding on the root pushes everything inside the frame; the bezel
       stays where the demo drew it, over empty space. A page's own body
       padding still applies, inside this. */
    :root[data-theme='terminal'] {
        box-sizing: border-box;
        padding: var(--kp-bezel);
    }

    /* Scoped to the ROOT, not to whatever carries the attribute [Kenny,
       2026-09-12, at the release gate]. These two are `position: fixed`,
       and a fixed element escapes its container: a page that previews
       terminal inside a box — the documentation site puts one story card
       per theme, each with its own `data-theme` — got this bezel and this
       sweep across the WHOLE viewport, over its own navigation, while the
       page itself was wearing formal. Kenny found it by opening the page,
       which is what that rule is for: no assertion anyone had written
       could see it, because every one of them measured a page whose root
       carried the theme.

       `:root` costs nothing where the theme IS on the root, which is the
       case the approved demo shows. It only stops a preview from taking
       over the page around it. terminal is the only register with rules
       of this shape; phantom's equivalent asks for a `body` underneath
       and a card has none. */
    :root[data-theme='terminal']::before {
        content: '';
        position: fixed;
        inset: 0;
        z-index: var(--kp-z-bezel, 55);
        pointer-events: none;
        border: var(--kp-bezel) solid transparent;
        border-image-source: linear-gradient(
            160deg,
            hsl(from var(--foreground) h 10% 17%) 0%,
            hsl(from var(--foreground) h 10% 7%) 28%,
            hsl(from var(--foreground) h 10% 3%) 55%,
            hsl(from var(--foreground) h 10% 11%) 78%,
            hsl(from var(--foreground) h 10% 21%) 100%
        );
        border-image-slice: 1;
        box-shadow:
            inset 0 0 2px 1px hsl(from var(--background) h s 0% / 0.9),
            inset 0 0 60px 8px hsl(from var(--background) h s 0% / 0.55);
    }

    /* The sweep band: one pass every ten seconds, resting eight of them,
       transform-only; at rest it sits above the viewport. */
    :root[data-theme='terminal']::after {
        content: '';
        position: fixed;
        left: 0;
        right: 0;
        top: -140px;
        height: 140px;
        z-index: var(--kp-z-sweep, 51);
        pointer-events: none;
        background: linear-gradient(
            180deg,
            transparent 0%,
            hsl(from var(--foreground) h s l / 0.09) 55%,
            hsl(from var(--foreground) h s l / 0.03) 82%,
            transparent 100%
        );
    }

    /* ── Type: one face, no smoothing on the display ──────────────────── */

    [data-theme='terminal'] h1,
    [data-theme='terminal'] h2,
    [data-theme='terminal'] h3 {
        font-family: var(--theme-font-display);
        font-weight: 400;
        letter-spacing: 0.02em;
        color: var(--primary);
        text-shadow: var(--kp-bloom);
        -webkit-font-smoothing: none;
    }

    [data-theme='terminal'] [data-kp-surface] h1 {
        letter-spacing: 0.01em;
        margin-block: 0 0.35em;
        min-block-size: 2.2em;
        overflow-wrap: anywhere;
    }

    /* The typing caret the module appends: one character cell, riding
       the last glyph, gone when the line lands. */
    [data-theme='terminal'] [data-kp-reveal='headline'] [data-caret] {
        display: inline-block;
        inline-size: 1ch;
        block-size: 0.92em;
        vertical-align: -0.06em;
        background: var(--primary);
        box-shadow: var(--kp-bloom);
    }

    /* Microlabels: a shell prompt. */
    [data-theme='terminal'] .microlabel {
        font-family: var(--theme-font-mono);
        font-size: 0.9rem;
        letter-spacing: 0;
        color: var(--muted-foreground);
        line-height: 1.3;
        overflow-wrap: anywhere;
    }

    [data-theme='terminal'] .microlabel::before {
        content: '$ ';
        color: var(--primary);
    }

    /* ── The hooks [S45]: the mark, the rule, the divider ─────────────── */

    /* The mark: emphasis is inverse video, the only highlight a terminal
       has. At rest the words are inverted; with the script armed they
       stand in phosphor inside a dim frame until the line lands, then
       switch over in one step — no colour in between (KT8). */
    [data-theme='terminal'] mark {
        background: var(--foreground);
        color: var(--background);
        padding: 0 0.15em;
        white-space: nowrap;
    }

    [data-theme='terminal'][data-kp-effects] mark:not(.is-cleared) {
        background: transparent;
        color: var(--foreground);
        box-shadow: inset 0 0 0 1px var(--border-strong);
    }

    /* The rule: a dashed line that types itself out, left to right, in
       twelve steps when the heading enters the viewport. */
    [data-theme='terminal'] [data-kp-reveal='rule']::after {
        content: '';
        display: block;
        block-size: 1px;
        margin-block-start: 0.6rem;
        background: var(--kp-dash);
        transform: scaleX(1);
        transform-origin: left center;
    }

    [data-theme='terminal'][data-kp-effects] [data-kp-reveal='rule']:not(.is-in)::after {
        transform: scaleX(0);
    }

    /* The divider: a rule of dashes with a plus at each end; the second
       one doubles the line. */
    [data-theme='terminal'] [data-kp-divider] {
        display: flex;
        align-items: center;
        justify-content: space-between;
        block-size: 2.4rem;
        padding-inline: 0.2rem;
        color: var(--border-strong);
        font-family: var(--theme-font-mono);
        font-size: 0.9rem;
        line-height: 1;
        background: var(--kp-dash) center / 100% 1px no-repeat;
    }

    [data-theme='terminal'] [data-kp-divider]::before,
    [data-theme='terminal'] [data-kp-divider]::after {
        content: '+';
        background: var(--background);
        padding-inline: 0.2rem;
    }

    [data-theme='terminal'] [data-kp-divider='alt'] {
        block-size: 3rem;
        background:
            var(--kp-dash) center calc(50% - 1px) / 100% 1px no-repeat,
            var(--kp-dash) center calc(50% + 1px) / 100% 1px no-repeat;
    }

    /* ── The hero: the void, nothing added ────────────────────────────── */

    [data-theme='terminal'] [data-kp-surface='hero'] {
        position: relative;
        padding-block: 2.4rem 3.2rem;
    }

    [data-theme='terminal'] [data-kp-surface='hero'] [data-kp-hero-grid] {
        grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
        gap: 2.5rem;
        align-items: end;
    }

    @container (max-width: 60rem) {
        [data-theme='terminal'] [data-kp-surface='hero'] [data-kp-hero-grid] {
            grid-template-columns: 1fr;
        }
    }

    /* ── The navbar: a shell line, not a bar ──────────────────────────── */

    [data-theme='terminal'] .kp-nav-wrap {
        background: var(--background);
    }

    [data-theme='terminal'] .kp-nav {
        background: var(--background);
        border-bottom: 1px solid var(--border);
        padding-block: calc(var(--kp-nav-pad-block, 1rem) * var(--kp-nav-pad-scale, 1))
            calc(var(--kp-nav-pad-block, 0.6rem) * var(--kp-nav-pad-scale, 1));
        position: relative;
        /* Its own stacking context for the bar's decorations; the layer is the
         * wrapper's, from the base [scope-48]. */
        isolation: isolate;
    }

    [data-theme='terminal'] .kp-nav__brand {
        font-family: var(--theme-font-display);
        font-weight: 400;
        font-size: 1.25rem;
        letter-spacing: 0.02em;
        color: var(--primary);
        text-shadow: var(--kp-bloom);
        -webkit-font-smoothing: none;
        text-decoration: none;
        white-space: nowrap;
    }

    [data-theme='terminal'] .kp-nav__links {
        gap: 0;
        align-items: stretch;
    }

    [data-theme='terminal'] .kp-nav__link {
        display: block;
        padding-inline: 0.7rem;
        letter-spacing: 0;
        color: var(--foreground);
        border-radius: 0;
        background: none;
        text-decoration: none;
        white-space: nowrap;
    }

    /* The current one is inverse video (emphasis, G16); pointing brings the
       cursor ring (G8). */
    [data-theme='terminal'] .kp-nav__link[aria-current] {
        background: var(--primary);
        color: var(--primary-foreground);
        text-shadow: none;
    }

    [data-theme='terminal'] .kp-nav__link:hover,
    [data-theme='terminal'] .kp-nav__links > li:focus-within > .kp-nav__link {
        box-shadow: inset 0 0 0 1px var(--ring);
    }

    [data-theme='terminal'] .kp-nav__link:active {
        background: var(--primary);
        color: var(--primary-foreground);
        text-shadow: none;
    }

    [data-theme='terminal'] .kp-nav__link[aria-haspopup]::after {
        content: ' ▾';
        color: var(--muted-foreground);
    }

    [data-theme='terminal'] .kp-nav__link[aria-current][aria-haspopup]::after,
    [data-theme='terminal'] .kp-nav__link:active[aria-haspopup]::after {
        color: var(--primary-foreground);
    }

    [data-theme='terminal'] .kp-nav__link--lang {
        margin-inline-start: 0.3rem;
        border-inline-start: 1px solid var(--border);
        padding-inline-start: 0.7rem;
        text-transform: uppercase;
    }

    /* The call to action is a bracketed command in the accent. */
    [data-theme='terminal'] .kp-nav__link--cta {
        color: var(--accent);
        text-shadow: var(--kp-bloom-accent);
    }

    [data-theme='terminal'] .kp-nav__link--cta::before {
        content: '[ ';
    }

    [data-theme='terminal'] .kp-nav__link--cta::after {
        content: ' ]';
    }

    [data-theme='terminal'] .kp-nav__link--cta:active {
        background: var(--accent);
        color: var(--accent-foreground);
        text-shadow: none;
    }

    /* The dropdown: a TUI panel, one boundary in a dimmer phosphor (DI1),
       the pointer a prompt. */
    [data-theme='terminal'] .kp-nav__menu {
        background: var(--secondary);
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: none;
        padding: 0.3rem 0;
        min-width: 12rem;
    }

    /* Collapsed, the dropdown is a list in the flow, not a panel [gap-12]:
       the rule above dresses the floating panel in kp.register, which
       beats the reset in kp.components, so the reset is restated here. */
    @container kp-nav (max-width: 40rem) {
        [data-theme='terminal'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__menu {
            min-width: 0;
            padding-inline-start: var(--kp-nav-menu-indent, 1rem);
            border: 0;
            background: transparent;
            box-shadow: none;
        }
    }

    [data-theme='terminal'] .kp-nav__menu a {
        display: block;
        padding-inline: 0.8rem;
        color: var(--foreground);
        text-decoration: none;
        border-radius: 0;
    }

    [data-theme='terminal'] .kp-nav__menu a::before {
        content: '  ';
        white-space: pre;
    }

    [data-theme='terminal'] .kp-nav__menu a:hover {
        box-shadow: inset 0 0 0 1px var(--ring);
    }

    [data-theme='terminal'] .kp-nav__menu a:active {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    [data-theme='terminal'] .kp-nav__menu a:hover::before,
    [data-theme='terminal'] .kp-nav__menu a:focus-visible::before {
        content: '> ';
    }

    /* ── Focus is the dashed box [G14, DI2] ────────────────────────────────
       2 px dashed in the bright phosphor, standing 2 px out on the ground:
       the second channel is the near-black it stands on (12.7:1), where the
       package's ring paints a second line. One rule for every focusable part. */
    [data-theme='terminal'] :focus-visible {
        outline: 2px dashed var(--primary);
        outline-offset: 2px;
        box-shadow: none;
    }

    /* ── Buttons: brackets and plates; no radius, a cell has no corner ── */

    [data-theme='terminal'] .kp-button {
        font-family: var(--theme-font-mono);
        font-weight: 400;
        letter-spacing: 0;
        color: var(--foreground);
        background: transparent;
        border: 1px solid var(--border-strong);
        border-radius: 0;
        position: relative;
    }

    /* The size the demo drew, and the two the package owes beside it
       [S49, A4 + TH111's amendment]: one height for all three, and the
       type and the padding are what tell them apart. */
    [data-theme='terminal'] .kp-button:not(.kp-button--sm):not(.kp-button--lg) {
        font-size: 0.9rem;
        padding-inline: 1.4rem;
    }

    [data-theme='terminal'] .kp-button--sm {
        font-size: 0.78rem;
        padding-inline: 0.9rem;
    }

    [data-theme='terminal'] .kp-button--lg {
        font-size: 1.05rem;
        padding-inline: 1.9rem;
    }

    /* Pointing brings the cursor [G8]: the line turns the bright phosphor
       with a 1 px ring round it, and the block cursor blinks after the label
       (gap-4, below). Nothing moves. A phosphor brightens under pressure; it
       does not step toward the ground (DI3 opt-out, anatomy.md). Focus is
       the dashed box (below), not this ring. */
    [data-theme='terminal'] .kp-button:hover:not(:disabled) {
        background: transparent;
        border-color: var(--ring);
        box-shadow: var(--kp-sig-tm-ring);
    }

    /* A press enters the part in reverse video [G14]: the plate turns the
       bright phosphor and the ink the ground, and it never moves. */
    [data-theme='terminal'] .kp-button:active:not(:disabled) {
        background: var(--primary);
        border-color: var(--primary);
        color: var(--primary-foreground);
        --kp-button-caret-colour: var(--primary-foreground);
    }

    [data-theme='terminal'] [data-kp-surface='hero'] .kp-row > .kp-button {
        min-width: min(11rem, 100%);
    }

    [data-theme='terminal'] .kp-button--primary,
    [data-theme='terminal'] .kp-button--primary:hover,
    [data-theme='terminal'] .kp-button--primary:focus-visible {
        background: var(--primary);
        border-color: var(--primary);
        color: var(--primary-foreground);
    }

    [data-theme='terminal'] .kp-button--primary:hover:not(:disabled) {
        background: var(--primary);
        border-color: var(--primary);
        box-shadow:
            0 0 0 1px var(--background),
            0 0 0 2px var(--ring);
    }

    [data-theme='terminal'] .kp-button--destructive,
    [data-theme='terminal'] .kp-button--destructive:hover,
    [data-theme='terminal'] .kp-button--destructive:focus-visible {
        background: transparent;
        border-color: var(--destructive);
        color: var(--destructive);
    }

    [data-theme='terminal'] .kp-button--destructive:hover:not(:disabled) {
        border-color: var(--destructive);
        box-shadow:
            inset 0 0 0 1px var(--destructive),
            0 0 0 1px var(--destructive);
    }

    /* Ghost: a command whose brackets appear under the pointer. */
    [data-theme='terminal'] .kp-button--ghost {
        border-color: transparent;
        color: var(--muted-foreground);
    }

    [data-theme='terminal'] .kp-button--ghost::before,
    [data-theme='terminal'] .kp-button--ghost::after {
        position: absolute;
        opacity: 0;
    }

    [data-theme='terminal'] .kp-button--ghost::before {
        content: '[';
        inset-inline-start: 0.45rem;
    }

    [data-theme='terminal'] .kp-button--ghost::after {
        content: ']';
        inset-inline-end: 0.45rem;
    }

    [data-theme='terminal'] .kp-button--ghost:hover:not(:disabled) {
        border-color: transparent;
        box-shadow: none;
        color: var(--foreground);
    }

    /* The ghost's brackets are its line: they turn the bright phosphor. */
    [data-theme='terminal'] .kp-button--ghost:hover:not(:disabled)::before {
        color: var(--primary);
    }

    [data-theme='terminal'] .kp-button--ghost:hover::before,
    [data-theme='terminal'] .kp-button--ghost:hover::after,
    [data-theme='terminal'] .kp-button--ghost:focus-visible::before,
    [data-theme='terminal'] .kp-button--ghost:focus-visible::after {
        opacity: 1;
    }

    [data-theme='terminal'] .kp-button:disabled {
        color: var(--muted-foreground);
        border-color: var(--border);
        background: transparent;
    }

    [data-theme='terminal'] .kp-icon-button {
        border: 1px solid var(--border-strong);
        border-radius: 0;
        background: transparent;
        color: var(--foreground);
    }

    /* On a toast the close button sits on the toast's own plate, in the
       toast's ink: a plate of its own under the error toast's dark ink read
       1.01:1 (nostromo-notes, 2026-10-04). */
    [data-theme='terminal'] .kp-toast .kp-icon-button {
        background: transparent;
        border-color: transparent;
        color: inherit;
    }

    /* On an alert the close button sits on the alert's own plate, in the
       alert's ink, the way it does on a toast [fix-95]. */
    [data-theme='terminal'] .kp-alert .kp-icon-button {
        background: transparent;
        border-color: transparent;
        color: inherit;
    }

    [data-theme='terminal'] .kp-icon-button:hover:not(:disabled) {
        border-color: var(--ring);
        box-shadow: var(--kp-sig-tm-ring);
    }

    [data-theme='terminal'] .kp-icon-button:active:not(:disabled) {
        border-color: var(--primary);
        background: var(--primary);
        color: var(--primary-foreground);
        box-shadow: none;
    }

    /* ── Fields: wells, and the block cursor inside the box [R6-Q7] ───── */

    [data-theme='terminal'] .kp-field__label {
        letter-spacing: 0;
        color: var(--muted-foreground);
    }

    [data-theme='terminal'] .kp-field__label::after {
        content: ':';
    }

    [data-theme='terminal'] .kp-field__input,
    [data-theme='terminal'] .kp-datatable__search,
    [data-theme='terminal'] .kp-combobox__input,
    [data-theme='terminal'] .kp-palette__input {
        background: var(--secondary);
        color: var(--foreground);
        border: 1px solid var(--border-strong);
        border-radius: 0;
        caret-color: var(--primary);
        padding-inline: var(--kp-caret-inset);
    }

    [data-theme='terminal'] .kp-field__input:focus-visible,
    [data-theme='terminal'] .kp-datatable__search:focus-visible,
    [data-theme='terminal'] .kp-combobox__input:focus-visible,
    [data-theme='terminal'] .kp-palette__input:focus-visible {
        border-color: var(--primary);
    }

    /* The cursor in the box: a block of one character cell painted as a
       background layer of the field itself, at the column the module
       writes (`--kp-col`, in the field's own ch), so it lives in the box
       at the caret and never after the label — Kenny's reading of
       2026-09-08, R6-Q7. The native caret steps aside while the block is
       there; a textarea keeps the browser's own. */
    [data-theme='terminal'] input.kp-field__input:focus {
        caret-color: transparent;
        background-image: linear-gradient(var(--primary), var(--primary));
        background-repeat: no-repeat;
        background-size: 1ch 1.15em;
        background-position: calc(var(--kp-caret-inset) + var(--kp-col, 0) * 1ch) center;
    }

    [data-theme='terminal'] .kp-field__help {
        color: var(--muted-foreground);
    }

    [data-theme='terminal'] .kp-field__help::before {
        content: '# ';
    }

    [data-theme='terminal'] .kp-field--invalid .kp-field__input {
        border-color: var(--destructive);
        box-shadow: inset 0 0 0 1px var(--destructive);
    }

    [data-theme='terminal'] .kp-field__error {
        color: var(--destructive);
    }

    [data-theme='terminal'] .kp-field__error::before {
        content: '!! ';
    }

    /* The checkbox is [ ] and [x]. */
    [data-theme='terminal'] .kp-field__check {
        position: relative;
    }

    [data-theme='terminal'] .kp-field__check::before {
        content: '[ ]';
        position: absolute;
        inset: 0;
        white-space: pre;
        font-family: var(--theme-font-mono);
        font-size: 1rem;
        line-height: 1.45;
        color: var(--muted-foreground);
    }

    [data-theme='terminal'] .kp-field__check:checked {
        background: transparent;
        border: 0;
    }

    [data-theme='terminal'] .kp-field__check:checked::before {
        content: '[x]';
        color: var(--primary);
        text-shadow: var(--kp-bloom);
    }

    [data-theme='terminal'] select.kp-field__input::picker-icon {
        color: var(--primary);
    }

    [data-theme='terminal'] .kp-fieldset {
        border: 1px solid var(--border-strong);
        border-radius: 0;
    }

    [data-theme='terminal'] .kp-switch__input:checked {
        border-color: var(--primary);
    }

    [data-theme='terminal'] .kp-switch__state {
        font-family: var(--theme-font-mono);
    }

    /* ── Cards and the dossier: a file with redactions that repaint ──── */

    /* A plate is a line of htop [G7; the shape family, Kenny 2026-10-07]:
       no fill and no closed frame, a square bracket at each end (a 1 px
       upright with 3 px ticks) in the dim phosphor and the head in the
       phosphor. What floats over the screen keeps its one box line below.
       The border stays as a transparent line so no plate changes size. */
    [data-theme='terminal']
        :is(
            .kp-card,
            .kp-kpi,
            .kp-grid__tile,
            .kp-split__pane,
            .kp-alert:not([class*='kp-alert--']),
            .kp-datatable,
            .kp-datatable__busy-panel,
            .kp-wizard,
            .kp-spec,
            .kp-log,
            .kp-diff,
            .kp-form__summary
        ) {
        --kp-sig-tm-bracket: var(--border-strong);
        border: 1px solid transparent;
        border-radius: 0;
        box-shadow: none;
        background-color: transparent;
        background-image:
            linear-gradient(var(--kp-sig-tm-bracket), var(--kp-sig-tm-bracket)), linear-gradient(var(--kp-sig-tm-bracket), var(--kp-sig-tm-bracket)),
            linear-gradient(var(--kp-sig-tm-bracket), var(--kp-sig-tm-bracket)), linear-gradient(var(--kp-sig-tm-bracket), var(--kp-sig-tm-bracket)),
            linear-gradient(var(--kp-sig-tm-bracket), var(--kp-sig-tm-bracket)), linear-gradient(var(--kp-sig-tm-bracket), var(--kp-sig-tm-bracket));
        background-size:
            1px 100%,
            0.4rem 1px,
            0.4rem 1px,
            1px 100%,
            0.4rem 1px,
            0.4rem 1px;
        background-position:
            0 0,
            0 0,
            0 100%,
            100% 0,
            100% 0,
            100% 100%;
        background-repeat: no-repeat;
        background-origin: border-box;
    }

    /* The busy panel lies over the rows it waits for, so it keeps the
       ground behind its brackets. */
    [data-theme='terminal'] .kp-datatable__busy-overlay .kp-datatable__busy-panel {
        background-color: var(--background);
    }

    /* Pointing at a plate that is a link or a toggle brings the cursor
       ring: its brackets turn the bright phosphor, a 1 px ring round it. */
    [data-theme='terminal'] :is(a.kp-kpi, .kp-kpi--toggle, a.kp-card, .kp-grid__tile):hover {
        --kp-sig-tm-bracket: var(--ring);
        box-shadow: var(--kp-sig-tm-ring);
    }

    [data-theme='terminal'] .kp-kpi--toggle[aria-pressed='true'] {
        --kp-sig-tm-bracket: var(--primary);
    }

    /* A press enters the plate in reverse video [G14]. */
    [data-theme='terminal'] :is(a.kp-kpi, .kp-kpi--toggle):active {
        background-color: var(--primary);
        background-image: none;
        color: var(--primary-foreground);
        box-shadow: none;
    }

    [data-theme='terminal'] :is(a.kp-kpi, .kp-kpi--toggle):active :is(.kp-kpi__label, .kp-kpi__trend, .kp-kpi__hint, .kp-kpi__note, small) {
        color: inherit;
    }

    [data-theme='terminal'] .kp-card__title {
        letter-spacing: 0;
    }

    /* A key figure's label is written as a shell writes one: lower case,
       untracked, ending in its colon [G15]. */
    [data-theme='terminal'] .kp-kpi__label {
        letter-spacing: 0;
        text-transform: none;
        font-weight: 400;
    }

    [data-theme='terminal'] .kp-kpi__label::after {
        content: ':';
    }

    /* A tone is printed in reverse in its colour, and says its level [G13]:
       the figure stands on the tone's square plate (the package's pair) and
       the level is written before it as a log line writes it, bracketed, in
       the tone's ink on the ground. The change is underlined, 2 px in the
       tone; never a frame all round, an edge bar or a flash. */
    [data-theme='terminal'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value {
        --kp-sig-tm-level: calc(6ch * 0.55);
        border-radius: 0;
        background: linear-gradient(var(--kp-sig-tm-plate), var(--kp-sig-tm-plate)) 100% 0 /
            calc(100% - var(--kp-sig-tm-level) - var(--kp-space-sm, 0.5rem)) 100% no-repeat;
        color: var(--kp-sig-tm-ink);
    }

    [data-theme='terminal'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value::before {
        color: var(--kp-sig-tm-level-ink);
        font-size: 0.55em;
        align-self: center;
    }

    [data-theme='terminal'] .kp-kpi[data-kp-tone='warning'] {
        --kp-sig-tm-plate: var(--warning);
        --kp-sig-tm-ink: var(--warning-foreground);
        --kp-sig-tm-level-ink: var(--warning-foreground);
    }

    [data-theme='terminal'] .kp-kpi[data-kp-tone='destructive'] {
        --kp-sig-tm-plate: var(--destructive);
        --kp-sig-tm-ink: var(--destructive-foreground);
        --kp-sig-tm-level-ink: var(--destructive);
    }

    [data-theme='terminal'] .kp-kpi[data-kp-tone='warning'] .kp-kpi__value::before {
        content: '[warn]';
    }

    [data-theme='terminal'] .kp-kpi[data-kp-tone='destructive'] .kp-kpi__value::before {
        content: '[fail]';
    }

    [data-theme='terminal'] .kp-kpi__delta {
        text-decoration: underline 1px var(--border-strong);
        text-underline-offset: 0.25em;
    }

    [data-theme='terminal'] .kp-kpi__delta[data-kp-tone] {
        padding-inline: 0;
        border-radius: 0;
        background: none;
        text-decoration-thickness: 2px;
    }

    [data-theme='terminal'] .kp-kpi__delta[data-kp-tone='good'] {
        color: var(--success-foreground);
        text-decoration-color: var(--success-foreground);
    }

    [data-theme='terminal'] .kp-kpi__delta[data-kp-tone='bad'] {
        color: var(--destructive);
        text-decoration-color: var(--destructive);
    }

    [data-theme='terminal'] .kp-card[data-kp-reveal='emphasis'] {
        position: relative;
    }

    /* The stamp: a bracketed label in the accent. */
    [data-theme='terminal'] .kp-card[data-kp-label]::before {
        content: '[ ' attr(data-kp-label) ' ]';
        position: absolute;
        inset-block-start: 0.8rem;
        inset-inline-end: 1.1rem;
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0;
        color: var(--accent);
    }

    /* The redactions: a run of character cells over the words, cleared
       left to right in nine steps when the file is opened — the way a
       screen repaints a line, not the way a curtain opens. */
    [data-theme='terminal'] .kp-card[data-kp-reveal='emphasis'] mark {
        position: relative;
        background: none;
        color: var(--card-foreground);
        padding: 0;
        box-shadow: none;
    }

    [data-theme='terminal'] .kp-card[data-kp-reveal='emphasis'] mark::after {
        content: '';
        position: absolute;
        inset: -0.06em -0.1em;
        background: var(--kp-cells);
        transform: scaleX(0);
        transform-origin: left center;
        pointer-events: none;
    }

    [data-theme='terminal'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared) {
        color: transparent;
    }

    [data-theme='terminal'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared)::after {
        transform: scaleX(1);
    }

    /* Panels: one boundary in a dimmer phosphor, nothing floats. */
    [data-theme='terminal'] .kp-dialog,
    [data-theme='terminal'] .kp-popover,
    [data-theme='terminal'] .kp-menu,
    [data-theme='terminal'] .kp-toast,
    [data-theme='terminal'] .kp-tooltip,
    [data-theme='terminal'] .kp-confirm,
    [data-theme='terminal'] .kp-datepicker__panel,
    [data-theme='terminal'] .kp-combobox__list,
    [data-theme='terminal'] .kp-palette,
    [data-theme='terminal'] .kp-theme-menu__list {
        background: var(--secondary);
        color: var(--foreground);
        border: 1px solid var(--border-strong);
        border-radius: 0;
        box-shadow: none;
    }

    /* The wrapper round the theme picker's icon button is not a card: only its
       dropdown list is. */
    [data-theme='terminal'] .kp-theme-menu {
        background: none;
        border: 0;
        box-shadow: none;
    }

    /* Severity toasts [scope-60]. The plain toast above is repainted here in
       a later layer than kp.components, which swallowed every variant's
       plate; each is restated on the alert's token pair, as the severity
       badge wears it. */
    [data-theme='terminal'] .kp-toast--success {
        background: var(--success);
        color: var(--success-foreground);
        border-color: var(--success);
    }

    [data-theme='terminal'] .kp-toast--info {
        background: var(--info);
        color: var(--info-foreground);
        border-color: var(--info);
    }

    [data-theme='terminal'] .kp-toast--warning {
        background: var(--warning);
        color: var(--warning-foreground);
        border-color: var(--warning);
    }

    [data-theme='terminal'] .kp-toast--destructive,
    [data-theme='terminal'] .kp-toast--error {
        background: var(--destructive);
        color: var(--destructive-foreground);
        border-color: var(--destructive);
    }

    [data-theme='terminal']
        :is(.kp-toast--success, .kp-toast--info, .kp-toast--warning, .kp-toast--destructive, .kp-toast--error)
        :is(.kp-button--ghost, .kp-icon-button) {
        color: inherit;
    }

    /* A button hovered on a toast takes a shade of the toast's own plate
       (--kp-toast-button-hover, set in kp.components), not this theme's page hover (Kenny's second nostromo pass,
       2026-09-13). Restated here because this layer repaints the hover. */
    [data-theme='terminal'] .kp-toast :is(.kp-button--ghost, .kp-icon-button):hover:not(:disabled) {
        background: var(--kp-toast-button-hover);
        color: inherit;
    }

    [data-theme='terminal'] .kp-toasts {
        gap: 0.4rem;
    }

    [data-theme='terminal'] .kp-dialog__title {
        letter-spacing: 0;
    }

    /* An entry under the pointer takes the cursor ring, inset to its width
       [G8]; pressed, it is entered in reverse video [G14]. */
    [data-theme='terminal'] .kp-menu__item:hover {
        background: none;
        box-shadow: inset 0 0 0 1px var(--ring);
    }

    [data-theme='terminal'] .kp-menu__item:active {
        background: var(--primary);
        color: var(--primary-foreground);
        box-shadow: none;
    }

    /* Focus on an entry is the dashed box inside its width, never the
       package's highlight plate (proposal-20): reverse video is the press. */
    [data-theme='terminal'] .kp-menu__item:focus-visible {
        outline: 2px dashed var(--primary);
        outline-offset: -4px;
    }

    [data-theme='terminal'] .kp-menu--rich .kp-menu__item:focus:not(:active) {
        background: none;
    }

    /* A chart legend key is a small terminal button [G17, proposal-23]: the
       ring under the pointer, the dashed box on focus (the rule above for
       every part), reverse video while held. A key that is shown stands in
       the dim line at rest, so the ring only ever means "pointed at". */
    [data-theme='terminal'] :is(.kp-chart__source, .kp-chart__show-all) {
        border-radius: 0;
        font-family: var(--theme-font-mono);
    }

    [data-theme='terminal'] .kp-chart__source[aria-pressed='true'] {
        border-color: var(--border-strong);
        background: none;
        box-shadow: none;
    }

    [data-theme='terminal'] :is(.kp-chart__source, .kp-chart__show-all):hover {
        border-color: var(--ring);
        box-shadow: var(--kp-sig-tm-ring);
    }

    [data-theme='terminal'] :is(.kp-chart__source, .kp-chart__show-all):active {
        border-color: var(--primary);
        background: var(--primary);
        color: var(--primary-foreground);
        box-shadow: none;
    }

    [data-theme='terminal'] .kp-chart__source:active > b {
        color: inherit;
    }

    /* A day of the calendar [proposal-24]: pointing brings the cursor ring,
       today is the figure in reverse video (cal(1)), and the pick is told by
       the prompt before its figure and its count in reverse, where the
       package drew a 3 px line. The line is focus's dashed box alone. */
    [data-theme='terminal'] .kp-calendar__day {
        border-radius: 0;
    }

    [data-theme='terminal'] .kp-calendar__day:hover {
        position: relative;
        z-index: 1;
        box-shadow: var(--kp-sig-tm-ring);
    }

    [data-theme='terminal'] .kp-calendar__day[data-kp-today]:not(:hover) {
        box-shadow: none;
    }

    [data-theme='terminal'] .kp-calendar__day[data-kp-today] .kp-calendar__num {
        padding-inline: 2px;
        background: var(--foreground);
        color: var(--background);
    }

    [data-theme='terminal'] td[aria-selected='true'] > .kp-calendar__day:not(:focus-visible) {
        outline: none;
    }

    [data-theme='terminal'] td[aria-selected='true'] > .kp-calendar__day .kp-calendar__num::before {
        content: '>';
        color: currentColor;
    }

    [data-theme='terminal'] td[aria-selected='true'] > .kp-calendar__day .kp-calendar__count {
        padding-inline: 2px;
        background: var(--primary);
        color: var(--primary-foreground);
    }

    /* The plain alert only [gap-1, Kenny 2026-09-10]: the plate rule above names
       it with `:not([class*='kp-alert--'])`. A rule here used to
       repaint the ground of EVERY alert, and `kp.register` is a later layer
       than `kp.components`, so it beat `.kp-alert--destructive`'s own plate
       while that variant's ink — `--destructive-foreground`, which is drawn
       to sit ON the plate — stayed. Measured in firefox on 2026-09-12:
       seventeen of the twenty-two themes carried a destructive alert whose
       text was unreadable, grotesk at 1.00 exactly, white on white.

       Kenny saw it in chassis-rs and said to write it down and touch
       nothing; this is the round he asked for it in. Same shape as fix-12,
       one property over: a register overriding half of a pair the base
       layer defines together. */
    [data-theme='terminal'] .kp-alert {
        border-radius: 0;
    }

    [data-theme='terminal'] .kp-alert__label {
        letter-spacing: 0;
        text-transform: none;
    }

    [data-theme='terminal'] .kp-grid {
        gap: 1ch;
    }

    [data-theme='terminal'] .kp-split {
        gap: 0;
    }

    [data-theme='terminal'] .kp-split__separator {
        background: var(--border-strong);
        inline-size: 1px;
    }

    /* Top and bottom [gap-12]: the thickness above is an inline size, so
       a horizontal split takes the same value as a block size. */
    [data-theme='terminal'] .kp-split[data-kp-orientation='horizontal'] > .kp-split__separator {
        inline-size: auto;
        block-size: 1px;
    }

    /* The footer: one step down from the void. */
    [data-theme='terminal'] .kp-footer {
        background: var(--sidebar-background);
        color: var(--muted-foreground);
    }

    [data-theme='terminal'] .kp-footer h4 {
        font-family: var(--theme-font-display);
        font-weight: 400;
        letter-spacing: 0;
        color: var(--foreground);
        text-shadow: none;
    }

    [data-theme='terminal'] .kp-footer a {
        color: var(--muted-foreground);
        font-size: 0.9rem;
        text-decoration: none;
    }

    [data-theme='terminal'] .kp-footer a:hover {
        color: var(--primary);
        text-shadow: var(--kp-bloom);
        box-shadow: 0 0 0 1px var(--ring);
    }

    [data-theme='terminal'] .kp-footer a:active {
        background: var(--primary);
        color: var(--primary-foreground);
        text-shadow: none;
    }

    /* ── Badges, tags, status: bracketed cells ────────────────────────── */

    [data-theme='terminal'] .kp-badge,
    [data-theme='terminal'] .kp-tag {
        border-radius: 0;
        border: 1px solid var(--border-strong);
        font-family: var(--theme-font-mono);
        letter-spacing: 0;
        text-transform: none;
    }

    [data-theme='terminal'] .kp-health {
        letter-spacing: 0;
        text-transform: none;
    }

    [data-theme='terminal'] .kp-health__dot {
        border-radius: 0;
    }

    [data-theme='terminal'] .kp-skeleton {
        background: repeating-linear-gradient(90deg, var(--border) 0 calc(1ch - 1px), transparent calc(1ch - 1px) 1ch);
        border-radius: 0;
    }

    [data-theme='terminal'] .kp-spinner {
        border-color: var(--border-strong);
        border-top-color: var(--primary);
    }

    [data-theme='terminal'] .kp-empty__title {
        letter-spacing: 0;
    }

    [data-theme='terminal'] .kp-error {
        color: var(--destructive);
    }

    [data-theme='terminal'] .kp-error::before {
        content: '!! ';
    }

    /* ── Text shapes ──────────────────────────────────────────────────── */

    [data-theme='terminal'] .kp-id,
    [data-theme='terminal'] .kp-url,
    [data-theme='terminal'] .kp-numeric,
    [data-theme='terminal'] .kp-timestamp,
    [data-theme='terminal'] .kp-masked,
    [data-theme='terminal'] .kp-copyable,
    [data-theme='terminal'] .kp-truncate,
    [data-theme='terminal'] .kp-cell-break,
    [data-theme='terminal'] .kp-cell-truncate {
        letter-spacing: 0.02em;
    }

    [data-theme='terminal'] .kp-timestamp,
    [data-theme='terminal'] .kp-id {
        color: var(--muted-foreground);
    }

    [data-theme='terminal'] .kp-copyable__button {
        border: 1px solid var(--border-strong);
        border-radius: 0;
        background: transparent;
    }

    /* The copy button's two states win over this register's own button
       rules [gap-12]: those paint in kp.register, which beats the states
       in kp.components, so copied lost its success plate and a refused
       copy looked idle. Restated token for token. */
    [data-theme='terminal'] .kp-copyable .kp-copyable__button[data-kp-copied] {
        border-color: var(--success);
        color: var(--success-foreground);
        background: var(--success);
    }

    [data-theme='terminal'] .kp-copyable .kp-copyable__button[data-kp-copy-failed] {
        border-color: var(--destructive);
        border-style: dashed;
        color: var(--destructive);
    }

    /* ── Data ─────────────────────────────────────────────────────────── */

    [data-theme='terminal'] .kp-table {
        border-collapse: separate;
        border-spacing: 0;
    }

    [data-theme='terminal'] .kp-table th {
        letter-spacing: 0;
        text-transform: none;
        font-weight: 400;
        color: var(--muted-foreground);
        border-bottom: 1px solid var(--border-strong);
    }

    [data-theme='terminal'] .kp-table td {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='terminal'] .kp-table tbody tr:hover {
        background: var(--card);
    }

    [data-theme='terminal'] .kp-datatable__bar {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='terminal'] .kp-datatable__sort[aria-sort] {
        color: var(--primary);
    }

    [data-theme='terminal'] .kp-datatable__status,
    [data-theme='terminal'] .kp-datatable__page {
        letter-spacing: 0;
        color: var(--muted-foreground);
    }

    [data-theme='terminal'] .kp-diff__line,
    [data-theme='terminal'] .kp-diff__hunk {
        letter-spacing: 0.02em;
    }

    /* The hunk header is a printed rule: dashes, as a terminal separates
       sections of output. */
    [data-theme='terminal'] .kp-diff__hunk {
        border-block-end: 1px dashed var(--border-strong);
    }

    [data-theme='terminal'] .kp-diff__hunk:not(:first-child) {
        border-block-start: 1px dashed var(--border-strong);
    }

    /* The step list is program output: no plates, a dashed rule at the left,
       square marks, the mono face, plain glyphs (+ done, x failed, - skipped). */
    [data-theme='terminal'] .kp-steplist {
        --kp-steplist-gap: 0;
        --kp-steplist-mark-radius: 0;
        --kp-glyph-done: '+';
        --kp-glyph-failed: 'x';
        --kp-glyph-skipped: '-';
        font-family: var(--theme-font-mono, var(--font-mono, monospace));
    }

    [data-theme='terminal'] .kp-steplist__item {
        border-width: 0;
        border-inline-start: 1px dashed var(--border-strong);
        border-radius: 0;
        background: transparent;
    }

    [data-theme='terminal'] .kp-steplist__item[data-state='running'] {
        border-inline-start-style: solid;
    }

    [data-theme='terminal'] .kp-timeline {
        border-inline-start: 1px dashed var(--border-strong);
    }

    [data-theme='terminal'] .kp-timeline__marker {
        background: var(--primary);
        border-radius: 0;
        box-shadow: var(--kp-bloom);
    }

    [data-theme='terminal'] .kp-timeline__when {
        color: var(--muted-foreground);
        letter-spacing: 0;
    }

    [data-theme='terminal'] .kp-tree {
        letter-spacing: 0.02em;
    }

    /* The accordion [gap-12]: written as a shell writes, the phosphor for what is open. */
    [data-theme='terminal'] .kp-accordion__summary {
        letter-spacing: 0;
        text-transform: none;
    }

    [data-theme='terminal'] .kp-accordion__summary::marker {
        color: var(--primary);
    }

    [data-theme='terminal'] .kp-accordion__item[open] > .kp-accordion__summary {
        color: var(--primary);
    }

    [data-theme='terminal'] .kp-reorder {
        border: 1px solid var(--border-strong);
        border-radius: 0;
    }

    /* ── Navigation and steps: inverse video marks the current one ────── */

    [data-theme='terminal'] .kp-tab {
        border-radius: 0;
        letter-spacing: 0;
        text-transform: none;
        color: var(--muted-foreground);
    }

    [data-theme='terminal'] .kp-tab[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    [data-theme='terminal'] .kp-tabs__list {
        border-bottom: 1px solid var(--border-strong);
    }

    [data-theme='terminal'] .kp-breadcrumb,
    [data-theme='terminal'] .kp-pagination {
        letter-spacing: 0;
    }

    [data-theme='terminal'] .kp-pagination a[aria-current],
    [data-theme='terminal'] .kp-pagination [aria-current] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: 0;
    }

    [data-theme='terminal'] .kp-wizard__steps {
        letter-spacing: 0;
        text-transform: none;
    }

    /* ── Pickers and palettes ─────────────────────────────────────────── */

    [data-theme='terminal'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: 0;
    }

    [data-theme='terminal'] .kp-datepicker__weekday,
    [data-theme='terminal'] .kp-datepicker__title {
        letter-spacing: 0;
        text-transform: none;
    }

    [data-theme='terminal'] .kp-colorpicker__swatch {
        border: 1px solid var(--border-strong);
        border-radius: 0;
    }

    [data-theme='terminal'] .kp-colorpicker__value {
        letter-spacing: 0.04em;
    }

    [data-theme='terminal'] .kp-shortcuts__row kbd {
        border: 1px solid var(--border-strong);
        border-radius: 0;
        background: transparent;
        display: inline-block;
        padding: 0 0.4em;
    }

    [data-theme='terminal'] .kp-shortcuts__group-label,
    [data-theme='terminal'] .kp-palette__group-label {
        letter-spacing: 0;
        text-transform: none;
        color: var(--muted-foreground);
    }

    [data-theme='terminal'] .kp-theme-menu__status,
    [data-theme='terminal'] .kp-palette__status,
    [data-theme='terminal'] .kp-combobox__status {
        letter-spacing: 0;
        color: var(--muted-foreground);
    }

    /* ── The roots the rules above reach only by their parts ──────────── */

    [data-theme='terminal'] .kp-field {
        gap: calc(var(--kp-space-xs) * 1.2);
    }

    [data-theme='terminal'] .kp-form {
        gap: var(--kp-space-lg);
    }

    [data-theme='terminal'] .kp-combobox,
    [data-theme='terminal'] .kp-datepicker,
    [data-theme='terminal'] .kp-colorpicker,
    [data-theme='terminal'] .kp-shortcuts,
    [data-theme='terminal'] .kp-tabs {
        border-radius: 0;
    }

    /* ── The scrollbar joins the theme ────────────────────────────────── */

    [data-theme='terminal'] {
        scrollbar-color: var(--border-strong) var(--background);
    }

    /* ── The demo's own pieces [S46] ──────────────────────────────────── */

    /* The side note: a status line in the margin, with the REC dot. */
    [data-theme='terminal'] .kp-side-note {
        position: absolute;
        inset-inline-end: 0.4rem;
        inset-block-start: 2.5rem;
        writing-mode: vertical-rl;
        font-family: var(--theme-font-mono);
        font-size: 0.8rem;
        letter-spacing: 0.26em;
        color: var(--muted-foreground);
    }

    [data-theme='terminal'] .kp-side-note::before {
        content: '● ';
        color: var(--destructive);
        filter: drop-shadow(0 0 0.18em hsl(from var(--destructive) h s l / 0.5));
    }

    /* The laurels are a status line: three fields of a screen's bottom
       row, the first in inverse video. */
    [data-theme='terminal'] .kp-laurels {
        gap: 0;
        border: 1px solid var(--border-strong);
        font-size: 0.82rem;
        color: var(--muted-foreground);
        letter-spacing: 0;
    }

    [data-theme='terminal'] .kp-laurels li {
        padding: 0.35rem 0.9rem;
        border-inline-end: 1px solid var(--border-strong);
    }

    [data-theme='terminal'] .kp-laurels li:last-child {
        border-inline-end: 0;
    }

    [data-theme='terminal'] .kp-laurels li:first-child {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    [data-theme='terminal'] .kp-laurels b {
        font-weight: 400;
        color: var(--foreground);
    }

    [data-theme='terminal'] .kp-laurels li:first-child b {
        color: var(--primary-foreground);
    }

    [data-theme='terminal'] .kp-lede {
        max-width: 36rem;
        font-size: 1.02rem;
    }

    [data-theme='terminal'] .kp-platforms {
        margin-block-start: 1.8rem;
        gap: 0.2rem 1.4rem;
        font-size: 0.85rem;
        letter-spacing: 0;
        color: var(--muted-foreground);
    }

    [data-theme='terminal'] .kp-platforms span::before {
        content: '· ';
        color: var(--primary);
    }

    /* The spec sheet is a man page. */
    [data-theme='terminal'] .kp-spec {
        color: var(--card-foreground);
        padding: 1.1rem 1.2rem 1.3rem;
        font-family: var(--theme-font-mono);
        font-size: 0.82rem;
        line-height: 1.7;
    }

    /* A man page's section heads are capitals: the one place a terminal shouts. */
    [data-theme='terminal'] .kp-spec dt {
        color: var(--accent);
        letter-spacing: 0;
        text-transform: uppercase;
    }

    /* The log wears what this register already decided for its other data
 * surface, `.kp-spec` — the same ground, the same edge, the same face
 * [gap-14]. A new component that invents a look of its own is a
 * twenty-third decision nobody made. */
    [data-theme='terminal'] .kp-log {
        color: var(--card-foreground);
        font-family: var(--theme-font-mono);
    }

    [data-theme='terminal'] .kp-log__level {
        --kp-log-level-ink: var(--accent);
        letter-spacing: 0;
        text-transform: none;
    }

    [data-theme='terminal'] .kp-spec__swatch {
        inline-size: 1ch;
        block-size: 1em;
        border: 1px solid var(--border-strong);
        border-radius: 0;
    }

    [data-theme='terminal'] .kp-spec__font {
        font-family: var(--theme-font-display);
        -webkit-font-smoothing: none;
    }

    /* ── The arrival [S45, TM2]: the POST, then the tube collapses ────── */

    [data-theme='terminal'] .kp-boot {
        position: fixed;
        inset: 0;
        z-index: var(--kp-z-boot, 100);
        background: var(--background);
        color: var(--foreground);
        display: grid;
        place-items: center;
        font-family: var(--theme-font-mono);
        font-size: clamp(0.8rem, 2.4vw, 1.05rem);
        line-height: 1.7;
        text-shadow: var(--kp-bloom);
        transform-origin: center;
    }

    [data-theme='terminal'] .kp-boot__line {
        margin: 0;
        font: inherit;
        white-space: pre-wrap;
        min-width: min(34ch, 90vw);
    }

    [data-theme='terminal'] .kp-boot__skip {
        position: absolute;
        inset-inline-end: 1.6rem;
        inset-block-end: 1.6rem;
        font: inherit;
        font-size: 0.85rem;
        letter-spacing: 0.1em;
        color: var(--muted-foreground);
        background: none;
        border: 1px solid var(--border-strong);
        border-radius: 0;
        padding: 0.3rem 0.8rem;
        cursor: pointer;
        text-shadow: none;
    }

    [data-theme='terminal'] .kp-boot__skip:hover,
    [data-theme='terminal'] .kp-boot__skip:focus-visible {
        color: var(--foreground);
        border-color: var(--foreground);
    }

    [data-theme='terminal'] .kp-boot.is-off {
        pointer-events: none;
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above are what they get. The
       durations are literal because check-motion.mjs computes DI5's rate
       from them; the matching --kp-* knobs are what js/effects.js reads. A
       terminal does not ease: every timing function here steps. */
    @media (prefers-reduced-motion: no-preference) {
        :root[data-theme='terminal']::after {
            animation: kp-sweep 10000ms linear infinite;
        }

        [data-theme='terminal'] [data-kp-reveal='rule'].is-in::after {
            animation: kp-rule-in 900ms steps(12, end) 1 both;
        }

        [data-theme='terminal'] .kp-card[data-kp-reveal='emphasis'] mark::after {
            transition: transform 640ms steps(9, end);
        }

        [data-theme='terminal'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2)::after {
            transition-delay: var(--kp-redact-stagger);
        }

        [data-theme='terminal'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3)::after {
            transition-delay: calc(2 * var(--kp-redact-stagger));
        }

        /* The cursor in the box blinks once per second — a tenth of what
           DI5 allows, over one character cell. */
        [data-theme='terminal'] input.kp-field__input:focus {
            animation: kp-caret 1000ms steps(1, end) infinite;
        }

        [data-theme='terminal'] .kp-boot.is-off {
            animation: kp-tube-off 420ms steps(4, end) 1 forwards;
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* Every keyframe here has its row in TIMINGS (js/effects.js); kp-rule-in
       is the base layer's. */
    @keyframes kp-sweep {
        0%,
        80% {
            transform: translateY(0);
        }

        100% {
            transform: translateY(calc(100vh + 140px));
        }
    }

    @keyframes kp-caret {
        0%,
        49% {
            background-size: 1ch 1.15em;
        }

        50%,
        100% {
            background-size: 0 0;
        }
    }

    /* The character under the cursor, in step with kp-caret: the ground's
       ink while the block is lit, the phosphor while it is out. */
    @keyframes kp-caret-reverse {
        0%,
        49% {
            color: var(--primary-foreground);
        }

        50%,
        100% {
            color: var(--foreground);
        }
    }

    /* Transform and opacity only: the reference's brightness spike is left
       out, so nothing on the page ever flashes. */
    @keyframes kp-tube-off {
        0% {
            transform: scaleY(1);
            opacity: 1;
        }

        70% {
            transform: scaleY(0.02);
            opacity: 1;
        }

        100% {
            transform: scaleY(0.02) scaleX(0);
            opacity: 0;
        }
    }

    /* The tty the shell line is attached to [S49, A3]. */
    [data-theme='terminal'] .kp-nav__brand-tag {
        color: var(--muted-foreground);
        letter-spacing: 0;
    }

    /* The demo's own arrow [S49, A12]: two triangles in the bright
       phosphor, with the platform list behind them. KT8's exception for
       this theme is recorded in tests/fixtures.spec.mjs. */
    [data-theme='terminal'] select.kp-field__input {
        appearance: none;
        padding-inline-end: 2rem;
        background-image: linear-gradient(45deg, transparent 50%, var(--primary) 50%), linear-gradient(135deg, var(--primary) 50%, transparent 50%);
        background-repeat: no-repeat;
        background-size:
            7px 7px,
            7px 7px;
        background-position:
            right 19px center,
            right 13px center;
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — phosphor between dashed rules. */
    [data-theme='terminal'] .kp-marquee {
        background: var(--background);
        color: var(--primary);
        border-block: 1px dashed color-mix(in srgb, var(--primary) 50%, transparent);
        font-family: var(--theme-font-mono);
        --kp-marquee: 30000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    /* A mega menu's group headings speak in the caption's voice [scope-48]. */
    [data-theme='terminal'] .kp-nav__menu[data-kp-menu-label]::before,
    [data-theme='terminal'] .kp-nav__menu--wide .kp-nav__menu-heading {
        color: var(--primary);
        font-family: var(--theme-font-mono);
        border-block-end: 1px dashed currentColor;
    }

    /* ── The side navigation [feat-nav-3] ────────────────────────────
       A column of paths with the prompt in front of the one you are in.
       The bar fills its current item; here the fill stays and the caret
       arrives in the gutter, which is where this theme puts every mark of
       where you are. */
    [data-theme='terminal'] .kp-sidenav {
        --kp-sidenav-surface: var(--card);
        --kp-sidenav-gap: 0;
        /* The refused cue's two steps: the register's one-step clock would
           pull the panel and let it go within a single frame. */
        --kp-sidenav-refuse-ease: steps(2, end);
        border-inline-end: 1px dashed var(--border-strong);
    }

    [data-theme='terminal'] .kp-sidenav__title {
        font-family: var(--theme-font-mono);
        letter-spacing: 0;
    }

    [data-theme='terminal'] .kp-sidenav__link,
    [data-theme='terminal'] .kp-sidenav__category-toggle {
        padding-left: 1.4rem;
        padding-right: 0.7rem;
        letter-spacing: 0;
        border-radius: 0;
    }

    /* The row is what the mark below is measured from [fix-73]. Without this
       it fell back to whatever ancestor happened to be positioned, which is
       not the row — the same fault Kenny found in nostromo, and the search
       in gates/check-anchors.mjs found here. */
    [data-theme='terminal'] .kp-sidenav__link {
        position: relative;
    }

    [data-theme='terminal'] .kp-sidenav__link::before {
        content: '>';
        position: absolute;
        inset-inline-start: 0.55rem;
        color: var(--primary);
        opacity: 0;
    }

    [data-theme='terminal'] .kp-sidenav__link:hover {
        box-shadow: inset 0 0 0 1px var(--ring);
    }

    [data-theme='terminal'] .kp-sidenav__link:hover::before {
        opacity: 1;
    }

    [data-theme='terminal'] .kp-sidenav__link[aria-current='page'] {
        background: var(--primary);
        color: var(--primary-foreground);
        text-shadow: none;
    }

    [data-theme='terminal'] .kp-sidenav__link[aria-current='page']::before {
        color: var(--primary-foreground);
        opacity: 1;
    }

    /* ── Back to top, and a picture [feat-page-1, feat-media-1] ──────
       A picture in a terminal is an attachment, so it is framed the way
       this theme frames everything it did not draw itself: a dashed rule
       and a filename underneath. */
    [data-theme='terminal'] .kp-to-top {
        border-radius: 0;
        font-family: var(--theme-font-mono);
    }

    [data-theme='terminal'] .kp-media {
        border: 1px dashed var(--border-strong);
        border-radius: 0;
    }

    [data-theme='terminal'] .kp-media-figure > figcaption {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
    }

    [data-theme='terminal'] .kp-media-figure > figcaption::before {
        content: '# ';
        color: var(--primary);
    }

    /* The figure carries the caption's voice, so the decision sits with
       the picture rather than with the words under it. */
    [data-theme='terminal'] .kp-media-figure {
        color: var(--muted-foreground);
    }

    /* ── The pressed state the register had been cancelling [fix-12] ───
       A layer beats a state: this register's hover background sits in
       kp.register, later than the kp.components rule that says what the
       button looks like while it is held down, so pressing it changed
       nothing. Pressing is reverse video [G14]: the plate and the ink swap,
       the primary onto the ground in the bright phosphor, the destructive
       onto red. */

    [data-theme='terminal'] .kp-button--primary:active:not(:disabled) {
        background: var(--background);
        border-color: var(--primary);
        color: var(--primary);
        box-shadow: none;
        --kp-button-caret-colour: var(--primary);
    }

    [data-theme='terminal'] .kp-button--destructive:active:not(:disabled) {
        background: var(--destructive);
        border-color: var(--destructive);
        color: var(--destructive-foreground);
        box-shadow: none;
        --kp-button-caret-colour: var(--destructive-foreground);
    }

    /* ── The cursor arrives [gap-4, approved 2026-09-12] ───────────────
       A terminal puts a blinking block where it expects your input.
       Touching a control puts that block after the label — the same block
       this theme already draws inside its fields, on the same keyframe and
       at the same rate, so there is one cursor in this theme and not two.

       The only one of the six that moves in time, and therefore the only
       one the motion rules have anything to say about. One blink a second
       is far under the three-per-second threshold, and `kp-caret` is
       already in the table at that rate. */
    /* One text line tall and centred on the button, as the label is
       [scope-80]. The box used to run from 0.55rem below the top to 0.55rem
       above the bottom, and the blink paints 1.15em from the box's top: on
       catalogue/button.html the cursor started 8.8px down while the text
       started 14.7px down (15.2px small, 13.2px large), so it rode above the
       label in every size. Now the box is the blink's own 1.15em, centred,
       and the destructive button blinks in its alarm colour
       (`--kp-button-caret-colour`). */
    [data-theme='terminal'] .kp-button::after {
        content: '';
        position: absolute;
        inset-block-start: calc(50% - 0.575em);
        block-size: 1.15em;
        inset-inline-end: var(--kp-button-caret-gap, 0.5rem);
        inline-size: 1ch;
        background-image: linear-gradient(var(--kp-button-caret-colour, var(--primary)), var(--kp-button-caret-colour, var(--primary)));
        background-repeat: no-repeat;
        background-size: 0 0;
        pointer-events: none;
    }

    [data-theme='terminal'] .kp-button--destructive {
        --kp-button-caret-colour: var(--destructive);
    }

    /* The primary is a green plate, so a green block on it read as nothing
       (Kenny, 2026-09-14, terminal-primary-cursor "Tekstkleur van de knop"
       [scope-83]): its cursor takes the button's own ink, the colour its
       label is set in. */
    [data-theme='terminal'] .kp-button--primary {
        --kp-button-caret-colour: var(--primary-foreground);
    }

    [data-theme='terminal'] .kp-button:hover:not(:disabled)::after,
    [data-theme='terminal'] .kp-button:focus-visible::after {
        background-size: 1ch 100%;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='terminal'] .kp-button:hover:not(:disabled)::after,
        [data-theme='terminal'] .kp-button:focus-visible::after {
            animation: kp-caret 1s steps(1) infinite;
        }
    }

    /* The ghost keeps its closing bracket under the cursor. Its `]` and the
       cursor both live on ::after, and the rule above, later and of the same
       weight, emptied the content: under the pointer the ghost showed `[`,
       the label and a cursor, never the `]` its picture is named for
       (2026-10-07, terminal outlier-16). There is no room for a cell after
       the bracket (a small ghost's end padding holds the bracket alone), so
       the cursor stands on the bracket, as a terminal's cursor stands on the
       last character: the `]` in reverse while the block is lit, in the
       phosphor while it is out. Both brackets share the cursor's line box,
       so they sit level. */
    [data-theme='terminal'] .kp-button--ghost::before,
    [data-theme='terminal'] .kp-button--ghost::after {
        inset-block-start: calc(50% - 0.575em);
        block-size: 1.15em;
        inline-size: 1ch;
        line-height: 1.15em;
        text-align: center;
    }

    [data-theme='terminal'] .kp-button--ghost::after {
        content: ']';
        inset-inline-end: 0.45rem;
    }

    [data-theme='terminal'] .kp-button--ghost:hover:not(:disabled)::after,
    [data-theme='terminal'] .kp-button--ghost:focus-visible::after {
        color: var(--primary-foreground);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='terminal'] .kp-button--ghost:hover:not(:disabled)::after,
        [data-theme='terminal'] .kp-button--ghost:focus-visible::after {
            animation:
                kp-caret 1s steps(1) infinite,
                kp-caret-reverse 1s steps(1) infinite;
        }
    }

    /* ── Read-only fields [gap-11] ────────────────────────────────────── */

    /* A read-only field is a value on a record, not a box to type in. This
       register sets the field's border and ground in kp.register, which
       beats the read-only look in kp.components, so read-only painted like
       an editable field. The state is answered here, on top of the rest
       look, which stays as it was. */
    [data-theme='terminal'] .kp-field__input[readonly] {
        border-style: dashed;
        background-color: var(--muted);
    }

    /* ── The palette's trigger in the bar [scope-48, scope-80] ─────────── */

    /* In the voice of this register's own nav links (Kenny, 2026-09-14,
       search-voice "Per thema"): lightly spaced phosphor words that invert
       onto the primary block when pointed at, the glow switched off on the
       block. The link's typeface, case, spacing, shape and pointer answer
       are restated here, because the trigger is a button beside the list
       rather than a link in it. The underline a plain link carries is not:
       it says "this is a link", and the trigger is not one. */
    [data-theme='terminal'] .kp-nav__search .kp-nav__search-trigger {
        padding-inline: 0.7rem;
        letter-spacing: 0;
        white-space: nowrap;
        border: 0;
        border-radius: 0;
        background: none;
        color: var(--foreground);
    }

    [data-theme='terminal'] .kp-nav__search .kp-nav__search-trigger:hover {
        box-shadow: inset 0 0 0 1px var(--ring);
    }

    [data-theme='terminal'] .kp-nav__search .kp-nav__search-trigger:active {
        background: var(--primary);
        color: var(--primary-foreground);
        text-shadow: none;
    }

    /* ── The alarm [scope-94] ──────────────────────────────────────────────
       The phosphor reversed: green on black becomes red on black, the headline in the mono face, a dashed frame, the green of its primary only in the split, and a prompt before the code line. Every colour is one of this theme's tokens. The
       button keeps this register's shape and takes the alarm's paint, on
       selectors long enough to outrank this register's own button states;
       the dialog takes no focus ring, because in the auto mode the whole
       screen is what has focus. */
    [data-theme='terminal'] .kp-alarm {
        --kp-alarm-ground: hsl(from var(--background) h s 2% / 0.97);
        --kp-alarm-ink: hsl(from var(--destructive) h s max(l, 62));
        --kp-alarm-soft: hsl(from var(--destructive) h s 80);
        --kp-alarm-split: var(--primary);
        --kp-alarm-on-ink: hsl(from var(--background) h s 2%);
        --kp-alarm-glow: hsl(from var(--destructive) h s 50 / 0.4);
        --kp-alarm-halo: hsl(from var(--destructive) h s 50 / 0.7);
        --kp-alarm-scan: hsl(from var(--destructive) h s 50 / 0.12);
        --kp-alarm-vignette: hsl(from var(--background) h s 1% / 0.85);
        --kp-alarm-frame: 2px dashed;
        --kp-alarm-title-font: var(--theme-font-mono, monospace);
        --kp-alarm-title-tracking: 0;
    }

    [data-theme='terminal'] .kp-alarm:focus-visible {
        outline: none;
    }

    [data-theme='terminal'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack,
    [data-theme='terminal'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:hover:not(:disabled),
    [data-theme='terminal'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:active:not(:disabled) {
        border-color: var(--kp-alarm-ink);
        background: var(--kp-alarm-ink);
        color: var(--kp-alarm-on-ink);
        text-shadow: none;
    }

    [data-theme='terminal'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:is(:hover, :focus-visible):not(:disabled):not(:active) {
        background: var(--kp-alarm-on-ink);
        color: var(--kp-alarm-ink);
    }

    [data-theme='terminal'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep,
    [data-theme='terminal'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep:is(:hover, :focus-visible):not(:disabled) {
        border-color: currentColor;
        background: transparent;
        color: inherit;
        text-shadow: none;
    }

    [data-theme='terminal'] .kp-alarm__code::before {
        content: '> ';
    }

    [data-theme='terminal'] .kp-alarm .kp-alarm__ack {
        --kp-button-caret-colour: currentColor;
    }

    /* A submenu item's mark [Kenny, 2026-09-20]: a prompt, one level in. */
    [data-theme='terminal'] .kp-sidenav__submenu .kp-sidenav__link {
        --kp-sidenav-submenu-mark: '>';
    }
}

/* ── Signature [scope-140] ─────────────────────────────────────────────── */
/* terminal's approved signature (Kenny, 2026-10-03, three review rounds): the
   progress bar and the ten elements (spinner, skeleton, switch, check and
   radio, toast, dialog, tooltip, wizard steps, empty state, link hover),
   ported once from research/progress-signature/themes/terminal.css and research/signature-elements/themes/terminal.css
   and maintained here from now on. In kp.signature, which css/themes.css
   orders after kp.register, so it draws over the register exactly as the
   approved demos did, whatever the weight of a register selector. */
@layer kp.signature {
    /* A box grows and shrinks one line at a time, as a terminal prints and
       clears them [scope-142; Kenny, 2026-10-04: "the shrinking should look
       like the inverse of the growing, where every line gets removed at a
       time"]. js/motion.js reads it. */
    [data-theme='terminal'] {
        --kp-size-steps: line;
        /* One step per 136 ms line: a resize, a fold and an unfold keep the theme's clock
           (js/motion.js steppedDuration). */
        --kp-size-step: var(--kp-sig-tm-line);
    }

    /* The link signature is for links in running text; a link in a navigation,
       a menu, a breadcrumb (a nav) or the footer keeps its own component's look
       (scope-93: no link colour in a navigation). */
    [data-theme='terminal'] .kp-progressbar {
        --kp-progressbar-height: calc(1.25rem * var(--kp-progressbar-scale, 1));
        /* The run between the brackets, a whole number of cells, so the last
           cell is never cut and 100% is exactly every cell. */
        --kp-tp-run: round(down, 100% - 2ch, 1ch);
        font-family: var(--theme-font-mono);
        font-size: calc(1rem * var(--kp-progressbar-scale, 1));
        line-height: var(--kp-progressbar-height);
        white-space: nowrap;
        color: var(--foreground);
        text-shadow: var(--kp-bloom, 0 0 0.4em hsl(from var(--primary) h s l / 0.28));
    }

    [data-theme='terminal'] .kp-progressbar::before,
    [data-theme='terminal'] .kp-progressbar::after {
        position: absolute;
        inset-block: 0;
        inline-size: 1ch;
        color: var(--foreground);
    }

    [data-theme='terminal'] .kp-progressbar::before {
        content: '[';
        inset-inline-start: 0;
    }

    [data-theme='terminal'] .kp-progressbar::after {
        content: ']';
        inset-inline-start: calc(1ch + var(--kp-tp-run));
    }

    [data-theme='terminal'] .kp-progressbar__track {
        inset-inline: 1ch auto;
        inline-size: var(--kp-tp-run);
        border-radius: 0;
        background: transparent;
    }

    [data-theme='terminal'] .kp-progressbar__track::after {
        content: '------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------';
        position: absolute;
        inset: 0;
        overflow: hidden;
        color: var(--border-strong);
        text-shadow: none;
        clip-path: inset(0 0 0 round(down, var(--kp-value) * 100% + 0.5px, 1ch));
    }

    [data-theme='terminal'] .kp-progressbar__fill {
        overflow: hidden;
        background: none;
        color: var(--primary);
        clip-path: inset(0 calc(100% - round(down, var(--kp-value) * 100% + 0.5px, 1ch)) 0 0);
        transition: none;
    }

    [data-theme='terminal'] .kp-progressbar__fill::before {
        content: '################################################################################################################################################################################################';
    }

    [data-theme='terminal'] .kp-progressbar__head {
        inset-block: calc(0.1875rem * var(--kp-progressbar-scale, 1));
        inline-size: 1ch;
        background: var(--foreground);
        box-shadow: var(--kp-bloom, 0 0 0.4em hsl(from var(--primary) h s l / 0.28));
        transform: translateX(round(down, var(--kp-value) * 100cqi + 0.5px, 1ch));
        transition: none;
    }

    [data-theme='terminal'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__track::after {
        content: none;
    }

    [data-theme='terminal'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
        inline-size: 3ch;
        color: var(--foreground);
        clip-path: none;
        animation: none;
        transform: translateX(calc(50cqi - 1.5ch));
    }

    [data-theme='terminal'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill::before {
        content: '<=>';
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='terminal'] .kp-progressbar__head {
            animation: kp-tp-caret 1000ms steps(1, end) infinite;
        }

        [data-theme='terminal'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
            animation: kp-tp-walk 2400ms steps(24, jump-none) infinite alternate;
        }
    }

    [data-theme='terminal'] {
        --kp-sig-tm-bloom: var(--kp-bloom, 0 0 0.4em hsl(from var(--primary) h s l / 0.28));
    }

    [data-theme='terminal'] .kp-spinner {
        --kp-sig-dur: 800ms;
        position: relative;
        inline-size: calc(var(--kp-spinner-size, 1.25rem) * 0.55);
        block-size: var(--kp-spinner-size, 1.25rem);
        border: 0;
        border-radius: 0;
        /* The unlit dots: phosphor that is off still shows faintly. */
        background: hsl(from var(--primary) h s l / 0.24);
        vertical-align: middle;
        -webkit-mask: radial-gradient(circle closest-side, var(--foreground) 64%, transparent 72%) 0 0 / 50% 25%;
        mask: radial-gradient(circle closest-side, var(--foreground) 64%, transparent 72%) 0 0 / 50% 25%;
        animation: none;
    }

    [data-theme='terminal'] .kp-spinner::before,
    [data-theme='terminal'] .kp-spinner::after {
        content: '';
        position: absolute;
        inset-block-start: 0;
        inset-inline-start: 0;
        inline-size: 50%;
        block-size: 25%;
        background: var(--primary);
    }

    [data-theme='terminal'] .kp-spinner::after {
        opacity: 0.5;
        transform: translate(0, 100%);
    }

    /* A waiting line is an htop row, drawn below with every other waiting
       part (Loading is an htop row). */
    [data-theme='terminal'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        block-size: 1em;
        border-radius: 0;
        background: none;
        font-family: var(--theme-font-mono);
        animation: none;
    }

    [data-theme='terminal']
        .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)
        + .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        margin-block-start: 0.35em;
    }

    [data-theme='terminal'] .kp-switch {
        --kp-switch-border: 0px;
        --kp-switch-inset: 4px;
        --kp-switch-radius: 0;
        --kp-switch-thumb-radius: 0;
    }

    [data-theme='terminal'] .kp-switch__input,
    [data-theme='terminal'] .kp-switch__input:checked {
        border: 0;
        background:
            linear-gradient(var(--primary), var(--primary)) left / 2px 100% no-repeat,
            linear-gradient(var(--primary), var(--primary)) right / 2px 100% no-repeat,
            linear-gradient(var(--primary), var(--primary)) left top / 7px 2px no-repeat,
            linear-gradient(var(--primary), var(--primary)) left bottom / 7px 2px no-repeat,
            linear-gradient(var(--primary), var(--primary)) right top / 7px 2px no-repeat,
            linear-gradient(var(--primary), var(--primary)) right bottom / 7px 2px no-repeat;
    }

    [data-theme='terminal'] .kp-switch__input::before {
        inline-size: 0.6rem;
        background: hsl(from var(--primary) h s l / 0.3);
    }

    [data-theme='terminal'] .kp-switch__input:checked::before {
        inset-inline-start: 4px;
        background: var(--primary);
        box-shadow: var(--kp-sig-tm-bloom);
        transform: translateX(calc(var(--kp-switch-width, 2.5rem) - 8px - 0.6rem));
    }

    [data-theme='terminal'] .kp-field__check {
        appearance: none;
        display: inline-block;
        inline-size: 3ch;
        block-size: 1.25em;
        margin: 0;
        border: 0;
        border-radius: 0;
        background: none;
        color: var(--primary);
        font: 1rem / 1.25 var(--theme-font-mono);
        white-space: pre;
    }

    [data-theme='terminal'] .kp-field__check::before {
        display: inline;
        inline-size: auto;
        block-size: auto;
        border: 0;
        background: none;
        transform: none;
    }

    [data-theme='terminal'] .kp-field__check[type='checkbox']::before {
        content: '[ ]';
    }

    [data-theme='terminal'] .kp-field__check[type='checkbox']:checked::before {
        content: '[x]';
        text-shadow: var(--kp-sig-tm-bloom);
    }

    [data-theme='terminal'] .kp-field__check[type='radio']::before {
        content: '( )';
    }

    [data-theme='terminal'] .kp-field__check[type='radio']:checked::before {
        content: '(*)';
        text-shadow: var(--kp-sig-tm-bloom);
    }

    /* A toast is one line, typed: twenty cells at 34 ms. */
    [data-theme='terminal'] .kp-toast {
        --kp-sig-dur: calc(20 * var(--kp-sig-tm-cell));
        border-radius: 0;
        font-family: var(--theme-font-mono);
    }

    [data-theme='terminal'] .kp-toast__body::before {
        content: '> ';
        color: var(--primary);
    }

    /* A dialog is printed, a line a step: six lines at 136 ms. The unopened
       dialog is the one js/motion.js measures for the theme's time (a probe it
       adds and takes off) and it reads close = two thirds of that, so it runs
       one and a half prints and the dialog that is open runs one, which is
       also its close and its opening. */
    [data-theme='terminal'] .kp-dialog {
        --kp-sig-dur: calc(6 * var(--kp-sig-tm-line) * 1.5);
        border: 3px double var(--primary);
        border-radius: 0;
    }

    [data-theme='terminal'] .kp-dialog[open] {
        --kp-sig-dur: calc(6 * var(--kp-sig-tm-line));
    }

    /* The cursor stands at the start of the line being printed. */
    [data-theme='terminal'] :is(.kp-dialog, .kp-palette, .kp-shortcuts)::after {
        content: '';
        position: absolute;
        inset-block-start: 1.25rem;
        inset-inline-start: 1.25rem;
        inline-size: 1ch;
        block-size: 1.2em;
        background: var(--primary);
        box-shadow: var(--kp-sig-tm-bloom);
        visibility: hidden;
        pointer-events: none;
    }

    [data-theme='terminal'] .kp-dialog__title {
        color: var(--primary);
        text-shadow: var(--kp-sig-tm-bloom);
    }

    /* The cursor at the line a menu or popover is printing; at rest it is not
       drawn (nothing sits on a part that is not waiting, G16). */
    [data-theme='terminal']
        :is(.kp-popover[popover], .kp-menu-button > .kp-menu, .kp-combobox__list, .kp-datepicker__panel, .kp-tour):not(.kp-tooltip)::before,
    [data-theme='terminal'] .kp-nav__links > li > .kp-nav__menu::after {
        content: '';
        position: absolute;
        inset-block-start: 0.6rem;
        inset-inline-start: 0.6rem;
        inline-size: 1ch;
        block-size: 1.2em;
        background: var(--primary);
        box-shadow: var(--kp-sig-tm-bloom);
        visibility: hidden;
        pointer-events: none;
    }

    /* A tooltip is one line, typed: twelve cells at 34 ms. */
    [data-theme='terminal'] .kp-tooltip {
        --kp-sig-dur: calc(12 * var(--kp-sig-tm-cell));
        margin-inline-start: 0;
        padding: 0.1rem 0.6ch;
        border: 0;
        border-radius: 0;
        background: var(--primary);
        color: var(--primary-foreground);
        box-shadow: var(--kp-sig-tm-bloom);
        font-family: var(--theme-font-mono);
        font-size: 0.875rem;
    }

    [data-theme='terminal'] .kp-wizard__steps {
        gap: 0.4rem 0;
        font-family: var(--theme-font-mono);
    }

    [data-theme='terminal'] .kp-wizard__steps li {
        gap: 0.6ch;
        padding-inline: 0.5ch;
    }

    [data-theme='terminal'] .kp-wizard__steps li::before {
        content: '[' counter(kp-step) ']';
        inline-size: auto;
        block-size: auto;
        border: 0;
        border-radius: 0;
        background: none;
        color: inherit;
        font-size: inherit;
    }

    [data-theme='terminal'] .kp-wizard__steps li:not(:last-child)::after {
        content: '>';
        margin-inline-start: 1ch;
        color: var(--muted-foreground);
        font-weight: 400;
    }

    [data-theme='terminal'] .kp-wizard__steps li[data-state='done'] {
        color: var(--primary);
    }

    [data-theme='terminal'] .kp-wizard__steps li[data-state='done']::before {
        content: '[x]';
        border: 0;
        color: inherit;
    }

    [data-theme='terminal'] .kp-wizard__steps li[data-state='current'] {
        background: var(--primary);
        color: var(--primary-foreground);
        box-shadow: var(--kp-sig-tm-bloom);
    }

    [data-theme='terminal'] .kp-wizard__steps li[data-state='current']::before {
        border: 0;
        background: none;
        color: inherit;
    }

    [data-theme='terminal'] .kp-wizard__steps li[data-state='current']::after {
        color: var(--primary-foreground);
    }

    [data-theme='terminal'] .kp-empty {
        padding: 0.75rem 0;
        border: 0;
        border-radius: 0;
        font-family: var(--theme-font-mono);
        text-align: start;
    }

    [data-theme='terminal'] .kp-empty__title {
        margin: 0 0 0.25rem;
        color: var(--foreground);
    }

    [data-theme='terminal'] .kp-empty__title::before {
        content: '> ';
        color: var(--primary);
    }

    [data-theme='terminal'] .kp-empty__title::after {
        content: '';
        display: inline-block;
        inline-size: 0.6em;
        block-size: 1.1em;
        margin-inline-start: 0.3ch;
        vertical-align: text-bottom;
        background: var(--primary);
        box-shadow: var(--kp-sig-tm-bloom);
    }

    [data-theme='terminal'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a) {
        text-decoration-style: dashed;
        text-decoration-thickness: 1px;
        text-underline-offset: 0.2em;
        -webkit-box-decoration-break: clone;
        box-decoration-break: clone;
    }

    [data-theme='terminal'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a):hover {
        box-shadow: 0 0 0 1px var(--ring);
        text-decoration-style: solid;
    }

    [data-theme='terminal']
        a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a):active {
        background: var(--primary);
        color: var(--primary-foreground);
        text-decoration-style: solid;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='terminal'] .kp-spinner::before {
            animation: kp-sig-terminal-tm-dot var(--kp-sig-dur) step-end infinite;
        }

        [data-theme='terminal'] .kp-spinner::after {
            animation:
                kp-sig-terminal-tm-trail var(--kp-sig-dur) step-end infinite,
                kp-sig-terminal-tm-decay calc(var(--kp-sig-dur) / 8) linear infinite;
        }

        /* The thumb steps across four cells. Going on it holds the first cell
           and lands on the last (jump-end); going off it is that played
           backwards, so it leaves the last cell at once and lands on the
           first (jump-start). A transition runs on the curve of the state
           it arrives at, so each state names its own. */
        [data-theme='terminal'] .kp-switch__input::before {
            transition: transform 200ms steps(4, jump-start);
        }

        [data-theme='terminal'] .kp-switch__input:checked::before {
            transition: transform 200ms steps(4, jump-end);
        }

        [data-theme='terminal'] .kp-toast {
            animation: kp-sig-terminal-tm-type var(--kp-sig-dur) steps(20, jump-end) backwards;
        }

        [data-theme='terminal'] .kp-dialog {
            animation: kp-sig-terminal-tm-rows var(--kp-sig-dur) steps(6, jump-end) backwards;
        }

        [data-theme='terminal'] .kp-dialog::after {
            animation: kp-sig-terminal-tm-feed var(--kp-sig-dur) steps(6, jump-end) backwards;
        }

        [data-theme='terminal'] .kp-dialog::backdrop {
            animation: kp-sig-terminal-tm-wash var(--kp-sig-dur) steps(6, jump-end) backwards;
        }

        [data-theme='terminal'] .kp-tooltip {
            animation: kp-sig-terminal-tm-type var(--kp-sig-dur) steps(12, jump-end) backwards;
        }

        /* A menu or a popover is printed from the top, a line a step, four
           lines at 136 ms, the block cursor at the line being printed [G3].
           The close is the same keyframes played backwards
           (js/motion.js playEntranceBackwards), frame for frame. */
        [data-theme='terminal']
            :is(
                .kp-popover[popover]:popover-open,
                .kp-menu-button > .kp-menu:not([hidden]),
                .kp-combobox__list:popover-open,
                .kp-datepicker__panel:is([data-kp-date-open], [data-kp-closing], [data-kp-reversing]):popover-open
            ):not(.kp-tooltip) {
            animation: kp-sig-terminal-tm-menu calc(4 * var(--kp-sig-tm-line)) steps(4, jump-end) backwards;
        }

        [data-theme='terminal']
            :is(
                .kp-popover[popover]:popover-open,
                .kp-menu-button > .kp-menu:not([hidden]),
                .kp-combobox__list:popover-open,
                .kp-datepicker__panel:is([data-kp-date-open], [data-kp-closing], [data-kp-reversing]):popover-open
            ):not(.kp-tooltip)::before {
            animation: kp-sig-terminal-tm-menu-feed calc(4 * var(--kp-sig-tm-line)) steps(4, jump-end) backwards;
        }

        /* The combobox's list and the date picker's panel are printed as a menu is
           (they had no motion); the list prints as its own entrance, not as the
           leave turned around. */
        [data-theme='terminal'] .kp-combobox__list {
            --kp-open: own;
        }

        /* The command palette and the shortcuts sheet are dialogs: printed as the
           dialog is, six lines, the cursor at the line being printed, the dim in
           the same steps (they faded in the package's way). js/motion.js plays
           the print backwards to close them. */
        [data-theme='terminal'] :is(.kp-palette, .kp-shortcuts) {
            --kp-sig-dur: calc(6 * var(--kp-sig-tm-line) * 1.5);
            animation: kp-sig-terminal-tm-rows var(--kp-sig-dur) steps(6, jump-end) backwards;
        }

        [data-theme='terminal'] :is(.kp-palette, .kp-shortcuts)[open] {
            --kp-sig-dur: calc(6 * var(--kp-sig-tm-line));
        }

        [data-theme='terminal'] :is(.kp-palette, .kp-shortcuts)::after {
            animation: kp-sig-terminal-tm-feed var(--kp-sig-dur) steps(6, jump-end) backwards;
        }

        [data-theme='terminal'] :is(.kp-palette, .kp-shortcuts)::backdrop {
            animation: kp-sig-terminal-tm-wash var(--kp-sig-dur) steps(6, jump-end) backwards;
        }

        [data-theme='terminal'] .kp-empty__title::after {
            animation: kp-sig-terminal-tm-blink 1000ms step-end 5;
        }
    }

    @keyframes kp-sig-terminal-tm-dot {
