            visibility: visible;
        }
    }

    /* The dim behind a dialog comes up in the dialog's own six steps, never
       as a fade (js/motion.js plays its fallback fade when the register gives
       the backdrop no motion of its own). */
    @keyframes kp-sig-terminal-tm-wash {
        from {
            opacity: 0;
        }

        to {
            opacity: 1;
        }
    }

    @keyframes kp-sig-terminal-tm-blink {
        50% {
            opacity: 0;
        }
    }

    @keyframes kp-tp-caret {
        50% {
            opacity: 0;
        }
    }

    @keyframes kp-tp-walk {
        from {
            transform: translateX(0);
        }
        to {
            transform: translateX(calc(100cqi - 3ch));
        }
