            transition:
                translate calc(6 * var(--kp-sig-tm-line)) steps(6, jump-start),
                visibility 0s linear calc(6 * var(--kp-sig-tm-line)),
                transform 0s linear calc(6 * var(--kp-sig-tm-line));
            animation: kp-sig-terminal-tm-nav-rows-back calc(6 * var(--kp-sig-tm-line)) steps(6, jump-end) reverse both;
        }

        [data-theme='terminal'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='true'] {
            transform: none;
            visibility: visible;
            transition:
                translate calc(6 * var(--kp-sig-tm-line)) steps(6, jump-end),
                visibility 0s linear,
                transform 0s;
            animation: kp-sig-terminal-tm-nav-rows calc(6 * var(--kp-sig-tm-line)) steps(6, jump-end) backwards;
        }

        /* The cursor, the dialog's: one cell of the bright phosphor at the start of the line being
           printed; at rest it is not drawn. */
        [data-theme='terminal'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])::after {
            content: '';
            position: absolute;
            inset-block-start: 0.75rem;
            inset-inline-start: 0.75rem;
            z-index: 3;
            inline-size: 1ch;
            block-size: 1.2em;
            background: var(--primary);
            box-shadow: var(--kp-sig-tm-bloom);
            visibility: hidden;
            pointer-events: none;
            animation: kp-sig-terminal-tm-nav-feed-back calc(6 * var(--kp-sig-tm-line)) steps(6, jump-end) reverse backwards;
        }

        [data-theme='terminal'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='true']::after {
            animation: kp-sig-terminal-tm-nav-feed calc(6 * var(--kp-sig-tm-line)) steps(6, jump-end) backwards;
        }

        /* Its backdrop (where a page keeps one) comes up in the same six steps, as the dialog's. */
        [data-theme='terminal'] .kp-sidenav__backdrop {
            animation-duration: calc(6 * var(--kp-sig-tm-line));
            animation-timing-function: steps(6, jump-end);
        }

        /* The alarm is a dialog the size of the screen: printed as the dialog, six lines from the top,
           the cursor at the line being printed (the scan layer's ::after, a band this theme never
           opted into); js/motion.js keeps this entrance and plays it backwards to close it. The
           package's fade, rise and scale are not this theme's (G1: no fade, no scale). */
        [data-theme='terminal'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) {
            animation: kp-sig-terminal-tm-rows calc(6 * var(--kp-sig-tm-line)) steps(6, jump-end) backwards;
        }

        [data-theme='terminal'] .kp-alarm:not([data-kp-alarm-motion='still']) :is(.kp-alarm__panel, .kp-alarm__title, .kp-alarm__detail) {
            animation: none;
        }

        [data-theme='terminal'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) .kp-alarm__scan::after {
            content: '';
            inset-block-start: 1.25rem;
            inset-inline: 1.25rem auto;
            z-index: 3;
            inline-size: 1ch;
            block-size: 1.2em;
            background: var(--kp-alarm-ink);
            box-shadow: 0 0 0.4em var(--kp-alarm-halo);
            visibility: hidden;
            animation: kp-sig-terminal-tm-feed calc(6 * var(--kp-sig-tm-line)) steps(6, jump-end) backwards;
        }
    }

    /* The side navigation's print: its first line (the header, 3 rem) stands at once, the rest is
       printed under it; the cursor stands at the start of each line, from the header to the foot. */
    @keyframes kp-sig-terminal-tm-nav-rows {
        from {
            clip-path: inset(0 0 calc(100% - 3rem) 0);
        }

        to {
            clip-path: inset(0);
        }
    }

    @keyframes kp-sig-terminal-tm-nav-rows-back {
        from {
            clip-path: inset(0 0 calc(100% - 3rem) 0);
        }

        to {
            clip-path: inset(0);
        }
    }

    @keyframes kp-sig-terminal-tm-nav-feed {
        from {
            inset-block-start: 0.75rem;
            visibility: visible;
        }

        to {
            inset-block-start: calc(100% - 0.75rem - 1.2em);
            visibility: visible;
        }
    }

    @keyframes kp-sig-terminal-tm-nav-feed-back {
        from {
            inset-block-start: 0.75rem;
            visibility: visible;
        }

        to {
            inset-block-start: calc(100% - 0.75rem - 1.2em);
            visibility: visible;
        }
    }
}

@layer kp.register {
    /* Bottom tab bar [kpadopt-nav] — terminal: a shell. The current tab is printed in reverse video, in one step (no easing, the line clock); pointing underlines the label like a cursor line; a press enters it in reverse (G8, G14); everything in the one mono, in cells. */
    [data-theme='terminal'] .kp-tabbar {
        background: var(--background);
        border-block-start-color: var(--border);
    }

    [data-theme='terminal'] .kp-tabbar__tab {
        border-radius: 0;
    }

    [data-theme='terminal'] .kp-tabbar__tab::before {
        content: none;
    }

    [data-theme='terminal'] .kp-tabbar__tab[aria-current]:not([aria-current='false']),
    [data-theme='terminal'] .kp-tabbar__tab:active {
        background: var(--foreground);
        color: var(--background);
    }

    [data-theme='terminal'] .kp-tabbar__tab[aria-current]:not([aria-current='false']) .kp-tabbar__icon,
    [data-theme='terminal'] .kp-tabbar__tab:active .kp-tabbar__icon {
        color: inherit;
    }

    [data-theme='terminal'] .kp-tabbar__tab:is(:hover, :focus-visible):not([aria-current]:not([aria-current='false'])) .kp-tabbar__label {
        text-decoration: underline;
        text-underline-offset: 0.25em;
    }

    [data-theme='terminal'] .kp-tabbar__badge {
        border-radius: 0;
    }

    [data-theme='terminal'] .kp-tabbar__tab[aria-current]:not([aria-current='false']) .kp-tabbar__badge {
        box-shadow: 0 0 0 1px var(--background);
    }
}
/* ── End of the signature ── */

/* ── Segmented control, list toolbar, key line [kpadopt-controls] ── */
@layer kp.signature {
    [data-theme='terminal'] .kp-segmented {
        --kp-seg-radius: 0;
        --kp-seg-pad: 2px;
        --kp-seg-gap: 0;
        --kp-seg-font: var(--theme-font-mono);
        --kp-seg-track: var(--background);
        --kp-seg-thumb: var(--primary);
        --kp-seg-thumb-ink: var(--background);
        --kp-seg-thumb-edge: 0 0 0 0 transparent;
        --kp-seg-thumb-lift: 0 0 0 0 transparent;
        --kp-chip-radius: 0;
        --kp-chip-edge: var(--border-strong);
        --kp-chip-on: var(--primary);
        --kp-chip-on-ink: var(--background);
        --kp-chip-on-edge: var(--primary);
    }
    [data-theme='terminal'] .kp-toolbar {
        --kp-toolbar-group-gap: 1.125rem;
    }
    [data-theme='terminal'] .kp-toolbar__label {
        font-family: var(--theme-font-mono);
        letter-spacing: 0;
        text-transform: lowercase;
    }
    [data-theme='terminal'] .kp-keys {
        font-family: var(--theme-font-mono);
    }
    [data-theme='terminal'] .kp-kbd {
        --kp-kbd-radius: 0;
        --kp-kbd-edge: transparent;
        --kp-kbd-ground: transparent;
        --kp-kbd-foot: 0;
        --kp-kbd-pad: 0;
        min-inline-size: 0;
        font-family: var(--theme-font-mono);
    }
    /* A key is written the way a man page writes it: [ / ]. */
    [data-theme='terminal'] .kp-kbd::before {
        content: '[';
    }
    [data-theme='terminal'] .kp-kbd::after {
        content: ']';
    }
    [data-theme='terminal'] .kp-toolbar__key.kp-kbd {
        color: var(--muted-foreground);
    }
}

/* ── The dashboard parts: action tiles, status rows, the facet list, the heat grid, the matrix, the bar in a cell, the
   week agenda and the run timeline [kpadopt2] ──
   Terminal's own (themes/terminal/CHARACTER.md): a plate is a line of htop held between square brackets, no fill and no
   closed frame (G7); pointing brings the cursor, the brackets turn the bright phosphor with a 1 px ring and the block
   cursor blinks after the title (G8); a press enters the part in reverse video (G14); focus is the dashed box; a tone is
   printed in reverse in its colour and says its level (G13); waiting is an htop row with the cursor its head, ONE row
   per waiting surface (G10): a heat grid's row of cells is one row, the matrix and the timeline one row each, never a
   cursor in every cell; what runs is written by the cursor at its head (G2); one mono, as a shell writes (G15). */
@layer kp.signature {
    [data-theme='terminal'] .kp-actions {
        --kp-actions-gap: 0.75rem;
    }
    /* The brackets: a 1 px upright at each end with 3 px ticks, in the dim phosphor (the bright one under the hand). */
    [data-theme='terminal'] .kp-action {
        --kp-action-radius: 0;
        --kp-action-edge: transparent;
        --kp-action-edge-hover: transparent;
        --kp-action-ground: transparent;
        --kp-action-ground-active: var(--primary);
        --kp-action-press: 0 0;
        --kp-action-pad: 0.625rem 0.875rem;
        --kp-tm-bk: var(--border-strong);
        font-family: var(--theme-font-mono);
        background:
            linear-gradient(var(--kp-tm-bk), var(--kp-tm-bk)) 0 0 / 1px 100% no-repeat,
            linear-gradient(var(--kp-tm-bk), var(--kp-tm-bk)) 0 0 / 5px 1px no-repeat,
            linear-gradient(var(--kp-tm-bk), var(--kp-tm-bk)) 0 100% / 5px 1px no-repeat,
            linear-gradient(var(--kp-tm-bk), var(--kp-tm-bk)) 100% 0 / 1px 100% no-repeat,
            linear-gradient(var(--kp-tm-bk), var(--kp-tm-bk)) 100% 0 / 5px 1px no-repeat,
            linear-gradient(var(--kp-tm-bk), var(--kp-tm-bk)) 100% 100% / 5px 1px no-repeat,
            var(--kp-action-ground);
    }
    [data-theme='terminal'] .kp-action__title {
        font-weight: 700;
    }
    [data-theme='terminal'] .kp-action__title::after {
        content: '';
        display: inline-block;
        inline-size: 1ch;
        block-size: 1.1em;
        margin-inline-start: 0.5ch;
        vertical-align: -0.2em;
        background: var(--primary);
        visibility: hidden;
    }
    [data-theme='terminal'] .kp-action:hover:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])) {
        --kp-tm-bk: var(--primary);
        box-shadow: 0 0 0 1px var(--ring);
    }
    [data-theme='terminal']
        .kp-action:is(:hover, :focus-visible):not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'], :active))
        .kp-action__title::after {
        visibility: visible;
    }
    /* A press: reverse video, the plate the bright phosphor and the ink the ground; nothing moves. */
    [data-theme='terminal'] .kp-action:active:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])) {
        --kp-action-ground: var(--primary);
        --kp-tm-bk: var(--primary);
        color: var(--primary-foreground);
    }
    [data-theme='terminal']
        .kp-action:active:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true']))
        :is(.kp-action__text, .kp-action__meta, .kp-action__mark, .kp-action__title) {
        color: var(--primary-foreground);
    }
    /* Focus: the dashed box, 2 px in the bright phosphor, 2 px out. */
    [data-theme='terminal'] .kp-action:focus-visible {
        outline: 2px dashed var(--primary);
        outline-offset: 2px;
        box-shadow: none;
    }
    [data-theme='terminal'] .kp-action:is(:disabled, [aria-disabled='true']) {
        --kp-action-ground: transparent;
        --kp-tm-bk: hsl(from var(--border-strong) h s l / 0.5);
    }
    /* Destructive: the title printed in reverse in the red, after the error's sigil; the brackets in the red. */
    [data-theme='terminal'] .kp-action--destructive:not(:is(:disabled, [aria-disabled='true'])) {
        --kp-tm-bk: var(--destructive);
    }
    [data-theme='terminal'] .kp-action--destructive::after {
        display: none;
    }
    [data-theme='terminal'] .kp-action--destructive:not(:is(:disabled, [aria-disabled='true'])) > .kp-action__title {
        justify-self: start;
        padding-inline: 1ch;
        background: var(--destructive);
        color: var(--destructive-foreground);
    }
    [data-theme='terminal'] .kp-action--destructive:not(:is(:disabled, [aria-disabled='true'])) > .kp-action__title::before {
        content: '!! ';
    }
    [data-theme='terminal'] .kp-action--destructive > .kp-action__title::after {
        background: var(--destructive-foreground);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='terminal'] .kp-action:is(:hover, :focus-visible) .kp-action__title::after {
            animation: kp-caret var(--kp-sig-tm-slow) steps(1) infinite;
        }
    }

    /* Status rows: log lines, all mono, a dashed rule at the start in the dim phosphor: + ok, x failed, - empty. A
       failed row says its level, [fail], in the red before its name; a loading row's reading has the cursor at its
       head, waiting. */
    [data-theme='terminal'] .kp-statuslist {
        --kp-statuslist-gap: 0;
        --kp-statusrow-mark-radius: 0;
        --kp-glyph-done: '+';
        --kp-glyph-failed: 'x';
        --kp-glyph-empty: '-';
        font-family: var(--theme-font-mono);
    }
    [data-theme='terminal'] .kp-statusrow {
        --kp-statusrow-ground: transparent;
        --kp-statusrow-radius: 0;
        border-width: 0;
        border-inline-start: 1px dashed var(--border-strong);
    }
    [data-theme='terminal'] .kp-statusrow[data-state='loading'] {
        border-inline-start-style: solid;
        border-inline-start-color: var(--primary);
    }
    [data-theme='terminal'] .kp-statusrow[data-state='failed'] {
        border-inline-start: 1px solid var(--destructive);
    }
    [data-theme='terminal'] .kp-statusrow[data-state='failed'] .kp-statusrow__label::before {
        content: '[fail] ';
        color: var(--destructive);
    }
    [data-theme='terminal'] .kp-statusrow[data-state='loading'] .kp-statusrow__detail::after {
        content: '';
        display: inline-block;
        inline-size: 1ch;
        block-size: 1em;
        margin-inline-start: 0.5ch;
        vertical-align: -0.15em;
        background: var(--primary);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='terminal'] .kp-statusrow[data-state='loading'] .kp-statusrow__detail::after {
            animation: kp-caret var(--kp-sig-tm-slow) steps(1) infinite;
        }
    }

    /* Facets: plain text rows, all mono; pointing brings the cursor ring; the title is a shell label. The counts on
       their way: the cursor waits where each count will be written. */
    [data-theme='terminal'] .kp-facets {
        --kp-facet-radius: 0;
        font-family: var(--theme-font-mono);
    }
    [data-theme='terminal'] .kp-facet {
        --kp-facet-hover: transparent;
    }
    [data-theme='terminal'] .kp-facet:hover {
        box-shadow: var(--kp-sig-tm-ring);
    }
    [data-theme='terminal'] .kp-facets__title {
        text-transform: none;
        letter-spacing: 0;
    }
    [data-theme='terminal'] .kp-facets__title::before {
        content: '$ ';
        color: var(--muted-foreground);
    }
    [data-theme='terminal'] .kp-facets[aria-busy='true'] .kp-facet__count {
        border-radius: 0;
        background: linear-gradient(var(--primary), var(--primary)) 100% 50% / 1ch 1em no-repeat;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='terminal'] .kp-facets[aria-busy='true'] .kp-facet__count {
            animation: kp-caret var(--kp-sig-tm-slow) steps(1) infinite;
        }
    }

    /* Heat grid and matrix: character cells, square, no shadow; a cell under the pointer takes the cursor ring; the pin
       is the dashed box; a pressed name is reverse video. */
    [data-theme='terminal'] :is(.kp-heat, .kp-matrix) {
        --kp-heat-cell-radius: 0;
        --kp-heat-cell-gap: 2px;
        --kp-heat-cell-hover: none;
        --kp-matrix-cell-hover: none;
    }
    [data-theme='terminal'] .kp-heat {
        --kp-heat-gap-y: 6px;
    }
    [data-theme='terminal'] .kp-matrix {
        --kp-matrix-gap: 4px;
    }
    [data-theme='terminal'] .kp-heat__cell:hover:not(.kp-skeleton, [aria-disabled='true']),
    [data-theme='terminal'] .kp-matrix__cell:hover:not([data-kp-inert], [aria-disabled='true'], .kp-skeleton) {
        box-shadow: var(--kp-sig-tm-ring);
        z-index: 1;
    }
    [data-theme='terminal'] .kp-heat__cell[data-kp-picked],
    [data-theme='terminal'] .kp-matrix__cell[aria-pressed='true'] {
        outline: 2px dashed var(--primary);
        outline-offset: 1px;
    }
    [data-theme='terminal'] .kp-heat__col[data-kp-picked] {
        background: var(--primary);
        color: var(--primary-foreground);
    }
    [data-theme='terminal'] .kp-heat__label-button[aria-pressed='true'],
    [data-theme='terminal'] :is(.kp-matrix__col, .kp-matrix__row)[aria-pressed='true'] {
        background: var(--foreground);
        color: var(--background);
    }
    [data-theme='terminal'] :is(.kp-heat__label-button, .kp-matrix__name) {
        border-radius: 0;
    }
    /* Waiting: one htop row per row of cells, the cells giving it their place; in the matrix and the timeline one row
       over the whole, on the screen's ground. The rows' own cursors in every cell are put away. */
    [data-theme='terminal'] :is(.kp-heat__cell, .kp-matrix__cell, .kp-gantt__ghost .kp-skeleton).kp-skeleton::before {
        content: none;
        animation: none;
    }
    /* A name still to come is its row of dim cells between brackets, unlit: the grid's one cursor is in its rows. */
    [data-theme='terminal'] .kp-heat__label-skeleton.kp-skeleton::before {
        --kp-sig-tm-k: 0;
        --kp-sig-tm-head: 0;
        animation: none;
    }
    [data-theme='terminal'] .kp-heat__cell.kp-skeleton {
        background: transparent;
    }
    [data-theme='terminal'] .kp-matrix__cell.kp-skeleton {
        background: hsl(from var(--muted) h s l / 0.6);
    }
    [data-theme='terminal'] .kp-heat__cells:has(> .kp-heat__cell.kp-skeleton) {
        position: relative;
        container-type: inline-size;
    }
    [data-theme='terminal'] .kp-heat__cells:has(> .kp-heat__cell.kp-skeleton)::before,
    [data-theme='terminal'] .kp-matrix:has(.kp-matrix__cell.kp-skeleton)::after,
    [data-theme='terminal'] .kp-gantt__state[data-kp-state='loading']::after {
        content: '';
        box-sizing: border-box;
        inline-size: calc(var(--kp-sig-tm-w) * 1ch + 8px);
        max-inline-size: 100%;
        block-size: var(--kp-sig-tm-row);
        pointer-events: none;
        background:
            linear-gradient(var(--primary), var(--primary))
                calc(4px + max(0px, round(down, var(--kp-sig-tm-k) * var(--kp-sig-tm-w) * 1ch, 1ch) - 1ch)) 3px /
                calc(var(--kp-sig-tm-head) * (1ch - 2px)) calc(100% - 6px) no-repeat,
            repeating-linear-gradient(90deg, var(--foreground) 0 calc(1ch - 2px), transparent calc(1ch - 2px) 1ch) 4px 3px /
                round(down, var(--kp-sig-tm-k) * var(--kp-sig-tm-w) * 1ch, 1ch) calc(100% - 6px) no-repeat,
            repeating-linear-gradient(90deg, var(--border-strong) 0 calc(1ch - 2px), transparent calc(1ch - 2px) 1ch) 4px 3px /
                calc(var(--kp-sig-tm-w) * 1ch) calc(100% - 6px) no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 0 0 / 1px 100% no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 0 0 / 3px 1px no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 0 100% / 3px 1px no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 100% 0 / 1px 100% no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 100% 0 / 3px 1px no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 100% 100% / 3px 1px no-repeat;
    }
    /* Under the busy card (js/busy-card.js: the data table's loading card, centred over the data) the card is the
       matrix's one loading picture: the htop row across the matrix gives way to it. */
    [data-theme='terminal'] .kp-matrix:has(> .kp-datatable__busy-card.kp-datatable__busy-overlay)::after {
        content: none;
    }
    [data-theme='terminal'] .kp-heat__cells:has(> .kp-heat__cell.kp-skeleton)::before {
        --kp-sig-tm-w: 12;
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        margin-block: auto;
        font-family: var(--theme-font-mono);
    }
    @container (min-width: 16rem) {
        [data-theme='terminal'] .kp-heat__cells:has(> .kp-heat__cell.kp-skeleton)::before {
            --kp-sig-tm-w: 24;
        }
    }
    @container (min-width: 30rem) {
        [data-theme='terminal'] .kp-heat__cells:has(> .kp-heat__cell.kp-skeleton)::before {
            --kp-sig-tm-w: 44;
        }
    }
    @container (min-width: 45rem) {
        [data-theme='terminal'] .kp-heat__cells:has(> .kp-heat__cell.kp-skeleton)::before {
            --kp-sig-tm-w: 70;
        }
    }
    [data-theme='terminal'] .kp-heat__row:nth-child(n + 3) .kp-heat__cells::before {
        animation-delay: var(--kp-sig-tm-line), 0ms;
    }
    [data-theme='terminal'] .kp-matrix:has(.kp-matrix__cell.kp-skeleton)::after {
        --kp-sig-tm-w: 24;
        position: absolute;
        inset: 0;
        z-index: 2;
        margin: auto;
        padding: 0;
        outline: 0.5rem solid var(--background);
        background-color: var(--background);
        font-family: var(--theme-font-mono);
    }
    /* The timeline: its sentence on the screen's ground, with the row after it where the reading will be written;
       the ghost bars stand, dim. */
    [data-theme='terminal'] .kp-gantt__state[data-kp-state='loading'] {
        inset: var(--kp-gantt-axis, 1.75rem) 0 0;
        display: flex;
        gap: 1ch;
        align-items: center;
        justify-content: center;
        inline-size: fit-content;
        block-size: fit-content;
        margin: auto;
        padding: 0.25rem 1ch;
        background: var(--background);
        color: var(--foreground);
        font-family: var(--theme-font-mono);
    }
    [data-theme='terminal'] .kp-gantt__state[data-kp-state='loading']::before {
        content: '> ';
        color: var(--muted-foreground);
    }
    [data-theme='terminal'] .kp-gantt__state[data-kp-state='loading']::after {
        --kp-sig-tm-w: 12;
        flex: none;
    }
    [data-theme='terminal'] .kp-gantt__ghost .kp-skeleton {
        background: hsl(from var(--muted) h s l / 0.6);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='terminal'] .kp-heat__cells:has(> .kp-heat__cell.kp-skeleton)::before,
        [data-theme='terminal'] .kp-matrix:has(.kp-matrix__cell.kp-skeleton)::after,
        [data-theme='terminal'] .kp-gantt__state[data-kp-state='loading']::after {
            animation:
                kp-sig-terminal-tm-fill var(--kp-sig-tm-slow) linear infinite alternate backwards,
                kp-sig-terminal-tm-head var(--kp-sig-tm-slow) steps(1, jump-end) infinite;
        }
    }
    /* A phone's timeline keeps its toolbar on one row: the range steps close in a little in the mono's wide cells. */
    @container kp-gantt (max-width: 22rem) {
        [data-theme='terminal'] .kp-gantt__ranges {
            --kp-seg-item-pad-inline: 0.5rem;
        }
    }
    [data-theme='terminal'] .kp-bar-cell {
        --kp-bar-cell-gap: 1ch;
        font-family: var(--theme-font-mono);
        font-variant-numeric: tabular-nums;
    }

    /* Week agenda and run timeline: program output. No plates: the time in [brackets], blocks of the phosphor, dashed
       rules; pointing brings the cursor ring; the line for now is the bright phosphor with its bloom. A running run is
       written as it grows: the block cursor stands at its head, blinking on the slow clock, no marching stripes. */
    [data-theme='terminal'] .kp-week {
        --kp-week-pill-radius: 0;
        --kp-week-now: var(--primary);
        font-family: var(--theme-font-mono, var(--font-mono, monospace));
    }
    [data-theme='terminal'] .kp-gantt {
        --kp-gantt-state-ground: var(--background);
        --kp-gantt-bar-radius: 0;
        font-family: var(--theme-font-mono, var(--font-mono, monospace));
    }
    [data-theme='terminal'] .kp-week__pill {
        background: transparent;
    }
    [data-theme='terminal'] :is(.kp-week__pill, .kp-gantt__run):is(button):hover {
        box-shadow: var(--kp-sig-tm-ring);
    }
    [data-theme='terminal'] .kp-week__pill[data-kp-state='next'] {
        background: var(--primary);
        color: var(--primary-foreground);
        box-shadow: none;
    }
    [data-theme='terminal'] .kp-week__time::before {
        content: '[';
    }
    [data-theme='terminal'] .kp-week__time::after {
        content: ']';
    }
    [data-theme='terminal'] .kp-week__head {
        text-transform: none;
        letter-spacing: 0;
    }
    [data-theme='terminal'] .kp-week__col,
    [data-theme='terminal'] .kp-gantt__rule {
        border-inline-start-style: dashed;
    }
    [data-theme='terminal'] .kp-week__now,
    [data-theme='terminal'] .kp-gantt__now {
        border-color: var(--primary);
        box-shadow: var(--kp-bloom);
    }
    [data-theme='terminal'] .kp-week__now::before {
        border-radius: 0;
    }
    [data-theme='terminal'] :is(.kp-gantt__run, .kp-gantt__swatch)[data-kp-state='running'] {
        --kp-gantt-fill: var(--primary);
        --kp-gantt-ink: var(--primary-foreground);
        background-image: none;
        box-shadow: none;
    }
    [data-theme='terminal'] .kp-gantt__run[data-kp-state='running']::after {
        content: '';
        position: absolute;
        inset-block: 1px;
        inset-inline-end: 1px;
        inline-size: min(1ch, 40%);
        background: var(--kp-hot, var(--foreground));
        box-shadow: var(--kp-bloom);
        pointer-events: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='terminal'] .kp-gantt__run[data-kp-state='running'] {
            animation: none;
        }
        [data-theme='terminal'] .kp-gantt__run[data-kp-state='running']::after {
            animation: kp-caret var(--kp-sig-tm-slow) steps(1) infinite;
        }
    }
}

/* ── The dashboard parts: what the package leaves to a register [kpadopt2-repairs] ──
   Formal keeps these parts exactly as Kenny approved them; this theme takes the three repairs the review asks for: a
   loading heat grid or matrix row as tall as its ready row (no skeleton gap between cells), an empty or failed run
   timeline with a lane-sized space for its sentence (never over the legend), the sentence as wide as its words on the
   theme's ground (never through a rule or a ghost bar), and an axis label near the end edge standing before its rule. */
@layer kp.signature {
    [data-theme='terminal'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton {
        margin-block: 0;
    }
    [data-theme='terminal'] .kp-gantt {
        --kp-gantt-tick-flip: 1;
    }
    [data-theme='terminal'] .kp-gantt:is([data-kp-state='empty'], [data-kp-state='error']) .kp-gantt__body:not(:has(.kp-gantt__lane)) {
        min-block-size: 5.25rem;
    }
    [data-theme='terminal'] .kp-gantt__state {
        box-sizing: border-box;
        display: block;
        inline-size: fit-content;
        max-inline-size: calc(100% - 2 * var(--kp-space-md, 0.75rem));
        block-size: fit-content;
        margin: auto;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--kp-gantt-state-ground, transparent);
    }
    /* The matrix's corner key breaks as two balanced lines when it has to, never leaving an arrow alone. */
    [data-theme='terminal'] .kp-matrix__corner {
        text-wrap: balance;
    }
    /* A ghost bar stands where its run would, as in formal: absolute in its track, so a second ghost of one track never
       drops under the first and out of the timeline onto the legend. */
    [data-theme='terminal'] .kp-gantt__ghost .kp-gantt__run.kp-skeleton {
        position: absolute;
    }
}

/* ── The six opt-in options of the dashboard adoption, round 3, in this theme [kpadopt3] ──
   The nav bar's separator, the timeline's day buttons and series runs, the week agenda's upcoming list on a phone and
   the facet swatch's identity pattern (the choice-filter value and the heat grid's End are behaviour only).
   Terminal's own (themes/terminal/CHARACTER.md): the separator is written, not drawn: the box-drawing
   character │ in the dim phosphor between two groups, and a line of ─ across the phone's list. A day on the axis takes
   the cursor ring under the pointer; pressed it is reverse video, the phosphor block with the date in the ground's ink
   (the menu's Reverse). The upcoming list's day rule is dashed, as the week's rules are; a facet pattern blooms in its
   hue on a square cell. Nothing eases: the screen redraws. */
@layer kp.signature {
    [data-theme='terminal'] .kp-nav__sep {
        display: grid;
        place-items: center;
        inline-size: 1ch;
        border-inline-start: 0;
        color: var(--muted-foreground);
        font-size: 1.25em;
        line-height: 1;
    }
    [data-theme='terminal'] .kp-nav__sep::before {
        content: '│';
    }
    @container kp-nav (max-width: 40rem) {
        [data-theme='terminal'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep {
            display: block;
            contain: inline-size;
            inline-size: auto;
            block-size: 1em;
            overflow: hidden;
            border-block-start: 0;
            font-size: 1em;
            white-space: nowrap;
        }
        [data-theme='terminal'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep::before {
            content: '────────────────────────────────────────────────────────────';
        }
    }

    [data-theme='terminal'] .kp-gantt__tick:is(button) {
        border-radius: 0;
        text-decoration: none;
    }
    [data-theme='terminal'] .kp-gantt__tick:is(button):hover {
        color: var(--primary);
        box-shadow: var(--kp-sig-tm-ring);
    }
    [data-theme='terminal'] .kp-gantt__tick:is(button)[aria-pressed='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
        box-shadow: none;
    }
    [data-theme='terminal'] .kp-week__next:not(:has(+ .kp-week__next:not([data-kp-day-start]))) {
        border-block-end-style: dashed;
    }
    [data-theme='terminal'] .kp-facet__swatch[data-kp-facet-pattern] {
        border-radius: 0;
        box-shadow: 0 0 4px hsl(from var(--kp-facet-swatch-colour, var(--primary)) h s l / 0.6);
    }
}

/* A share, 0 to 1 (a progress bar's, a meter's), is walked to its value on
   two registered copies, one on each mirror of the motion, so that a rise is
   the picture's fall and a fall is that fall turned around; registered so
   the transitions interpolate them. At the top level because Firefox does
   not register an @property inside a layer. */
@property --kp-sig-br-lag {
    syntax: '<number>';
    inherits: true;
    initial-value: 0;
}

@property --kp-sig-br-lead {
    syntax: '<number>';
    inherits: true;
    initial-value: 0;
}

/* A clock with nothing drawn on it: the bar's mega menu is held on screen
   until a transition on its panel has played (js/components.js); this is
   that transition, the length of the panel's lift. */
@property --kp-sig-br-hold {
    syntax: '<number>';
    inherits: false;
    initial-value: 0;
}

/* How far the side navigation still stands above its footprint while it is
   dropped onto it (review round 2): the panel is held up-left by this much and
   each slab's hard shadow stays on the ground, its offset grown by it. */
@property --kp-sig-br-lift {
    syntax: '<length>';
    inherits: true;
    initial-value: 0px;
}

@layer kp.register {
    /* @kp-soft/themes — css/brutalism-register.css
   The brutalism register, 5.0.0 [S48, LIFT_PLAN row 5]: printed matter.
   Scoped to [data-theme='brutalism'] and inert elsewhere; opt-in, imported
   after themes.css. The approved concept demo ("Hard Copy", 2026-09-08)
   is the reference for every value here, and docs/archive/RESEARCH_2026-09.md
   §12 is where each mechanism was measured: Gumroad's lift/drop shadow
   pair and its per-plate ink token, BEIGE FORCE's pixel outline from four
   box-shadows and its relative-colour hover, Future Pharmaceutical's
   seamless -50% marquee and its ink-on-paper selection.

   What this file does, in order: the knobs; the type; the hooks of S45 —
   the headline whose words slam onto their yellow offset, the plate wiped
   in behind a <mark>, the six-pixel bar that rules a heading off, the
   marquee band as divider; the strip as navbar; the plates as buttons
   with the lift and the drop; the wells; the dossier with its stamp and
   its bars; and one answer per component root (TH124). The reveals have
   their rest state here and their motion in js/effects.js; without the
   script every one of them stands at rest.

   The grammar of themes/brutalism/CHARACTER.md (G1-G18, decided by Kenny
   on research/brutalism-character, 2026-10-07 23:44) is applied in two
   places: the plates, hover, focus and press here, in kp.register; the
   motion, the waiting and the tokens of the grammar (--kp-sig-br-*) in
   kp.signature below. A box stands on its hard shadow; pointing inverts
   it, focus lifts it under the two-channel ring, a press drives it onto
   its footprint; what arrives falls onto the footprint from up-left and
   what leaves is lifted off it.

   Colour discipline (DI9): nothing here names a colour; ink builds, yellow
   is the hand, lavender the second sheet, a status is paint under black
   ink and never a line, a shadow or a glow. One ink in two line weights,
   a hard shadow on the ground, no blur, no gradient that is not a flat
   fill or the hazard tape, no transparency. */

    [data-theme='brutalism'] {
        /* The month heatmap's nav goes on two rows below this width: the
           widest month and the three buttons in this type [fix-98]. */
        --kp-calendar-nav-fit: 28.25rem;
        /* The configuration surface [AR43], the demo's values as defaults. */
        --kp-reveal-threshold: 0.6;
        /* Every duration counts the register's 100 ms [G4]. */
        --kp-reveal-stagger: 300ms;
        --kp-redact-stagger: 100ms;
        --kp-classified-delay: 700ms;
        --kp-word-stagger: 100ms;
        --kp-plate-in: 400ms;
        --kp-bar: 600ms;
        --kp-marquee: 42000ms;
        --kp-line: 3px;
        --kp-drop: 6px;
        /* The reveals this theme performs [S45]: js/effects.js reads these
           and leaves a theme that declares none at rest. */
        --kp-reveal-headline: slam;
        --kp-reveal-emphasis: plate;
        --kp-reveal-rule: bar;
        /* The one shadow, and the one lifted a step; the pixel outline. */
        --kp-shadow: var(--kp-drop) var(--kp-drop) 0 0 var(--border-strong);
        --kp-shadow-up: calc(var(--kp-drop) + 2px) calc(var(--kp-drop) + 2px) 0 0 var(--border-strong);
        --kp-pixel:
            calc(-1 * var(--kp-line)) 0 0 0 var(--border-strong), var(--kp-line) 0 0 0 var(--border-strong),
            0 calc(-1 * var(--kp-line)) 0 0 var(--border-strong), 0 var(--kp-line) 0 0 var(--border-strong);
        /* The marquee's hatch: a strip of the plate colour on the ink. One
           tile is --kp-hatch-tile wide and holds exactly one stripe period
           along x: at -45deg a stripe period of tile / sqrt(2) across the
           stripe (28.2843px for 40px) moves the stripe one whole tile along
           the band, so a tile's right edge meets the next tile's left edge
           with no seam. */
        --kp-hatch-tile: 40px;
        --kp-hatch: repeating-linear-gradient(-45deg, var(--secondary) 0 6px, transparent 6px 28.2843px);
        --kp-hatch-alt: repeating-linear-gradient(-45deg, var(--foreground) 0 6px, transparent 6px 28.2843px);
        /* The voice [G15]: prose speaks at 500; every label, figure, date and
           tag is 700 or heavier and never under 12 px. */
        font-weight: 500;
        /* Nothing is translucent [G7, proposal-29]: a busy part says so with
           the lintel (G10), not with a dimmed ink. */
        --kp-busy-opacity: 1;
        --kp-datatable-busy-opacity: 1;
    }

    /* ── The ring, in the demo's order [S49, A5 of 2026-09-08] ────────────
       The base layer puts the contrast colour outside and the ring colour
       against the element; this theme's approved demo does it the other
       way round, and DI2's promise holds either way — two channels, one
       of which always clears 3:1 on the surface behind it. The broad rule
       sits here, before the register's own component rules, so a control
       that composes its own shadow stack still wins. */
    [data-theme='brutalism'] :focus-visible {
        outline-color: var(--focus-ring);
        box-shadow: 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring-contrast);
    }

    /* Future Pharmaceutical's selection: ink on paper. */
    [data-theme='brutalism'] ::selection {
        background: var(--foreground);
        color: var(--background);
    }

    /* ── Type ──────────────────────────────────────────────────────────── */

    [data-theme='brutalism'] h1,
    [data-theme='brutalism'] h2,
    [data-theme='brutalism'] h3 {
        font-family: var(--theme-font-display);
        font-weight: 400;
        text-transform: uppercase;
        letter-spacing: -0.02em;
    }

    [data-theme='brutalism'] [data-kp-surface] h1 {
        letter-spacing: -0.025em;
        margin-block: 0 0.4em;
        text-wrap: balance;
        overflow-wrap: anywhere;
    }

    /* The headline reveal: every word drops onto its yellow offset, once,
       one after another. The module wraps the words; the register moves
       them. At rest every word carries the offset. */
    [data-theme='brutalism'] [data-kp-reveal='headline'] [data-word] {
        display: inline-block;
        text-shadow: 4px 4px 0 var(--secondary);
    }

    /* Microlabels: BEIGE FORCE's pixel outline — four box-shadows, no
       border at all — on the yellow plate. */
    [data-theme='brutalism'] .microlabel {
        display: inline-block;
        padding: 0.3rem 0.7rem;
        background: var(--secondary);
        color: var(--secondary-foreground);
        font-weight: 700;
        font-size: 0.78rem;
        letter-spacing: 0.18em;
        text-transform: uppercase;
        line-height: 1.2;
        box-shadow: var(--kp-pixel);
    }

    /* ── The hooks [S45]: the mark, the rule, the divider ─────────────── */

    /* The mark: emphasis is a plate wiped in behind the word, closed by
       the one line weight. At rest the plate is there; armed, the word
       stands on the paper until the plate arrives — a size, not a colour
       (KT8). */
    [data-theme='brutalism'] mark {
        background: linear-gradient(var(--secondary), var(--secondary)) left / 100% 100% no-repeat;
        color: var(--secondary-foreground);
        font-weight: 700;
        padding-inline: 0.14em;
        border-bottom: var(--kp-line) solid var(--border-strong);
        white-space: nowrap;
    }

    [data-theme='brutalism'][data-kp-effects] mark:not(.is-cleared) {
        background-size: 0 100%;
        color: var(--foreground);
        border-bottom-color: transparent;
    }

    /* The rule: a six-pixel bar that rules the heading off, left to right,
       once, when the heading enters the viewport. */
    [data-theme='brutalism'] [data-kp-reveal='rule']::after {
        content: '';
        display: block;
        block-size: 6px;
        margin-block-start: 0.7rem;
        background: var(--border-strong);
        transform: scaleX(1);
        transform-origin: left center;
    }

    [data-theme='brutalism'][data-kp-effects] [data-kp-reveal='rule']:not(.is-in)::after {
        transform: scaleX(0);
    }

    /* The divider: Future Pharmaceutical's marquee — a strip twice the
       band's width translated -50%, seamless, one cycle in 42 seconds,
       frozen under reduced motion. A hatch of the plate on the ink, the
       second one the ink on the plate, running the other way. The tile is
       one stripe period, never the band's own width (which is no multiple
       of the period, and left a seam where one tile ended), and the strip's
       half is rounded up to whole tiles so the -50% loop lands on one. */
    [data-theme='brutalism'] [data-kp-divider] {
        display: block;
        position: relative;
        block-size: 46px;
        border-block: var(--kp-line) solid var(--border-strong);
        background: var(--foreground);
        overflow: hidden;
    }

    [data-theme='brutalism'] [data-kp-divider]::before {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        inline-size: calc(2 * round(up, 100%, var(--kp-hatch-tile)));
        background: var(--kp-hatch) 0 0 / var(--kp-hatch-tile) 100% repeat-x;
    }

    [data-theme='brutalism'] [data-kp-divider='alt'] {
        background: var(--secondary);
    }

    [data-theme='brutalism'] [data-kp-divider='alt']::before {
        background: var(--kp-hatch-alt) 0 0 / var(--kp-hatch-tile) 100% repeat-x;
    }

    /* ── The hero: paper, and the dot grid the base layer draws ───────── */

    [data-theme='brutalism'] [data-kp-surface='hero'] {
        position: relative;
        padding-block: 2.2rem 3.4rem;
    }

    [data-theme='brutalism'] [data-kp-surface='hero'] [data-kp-hero-grid] {
        grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
        gap: 2.5rem;
        align-items: end;
    }

    @container (max-width: 56rem) {
        [data-theme='brutalism'] [data-kp-surface='hero'] [data-kp-hero-grid] {
            grid-template-columns: 1fr;
        }
    }

    /* ── The navbar: a strip on paper, ruled off with the one line weight ── */

    [data-theme='brutalism'] .kp-nav-wrap {
        background: var(--background);
        border-bottom: var(--kp-line) solid var(--border-strong);
    }

    [data-theme='brutalism'] .kp-nav {
        background: var(--background);
        padding-block: calc(var(--kp-nav-pad-block, 1.1rem) * var(--kp-nav-pad-scale, 1));
        position: relative;
        /* Its own stacking context for the bar's decorations; the layer is the
         * wrapper's, from the base [scope-48]. */
        isolation: isolate;
    }

    [data-theme='brutalism'] .kp-nav__brand {
        font-family: var(--theme-font-display);
        font-weight: 400;
        font-size: 1.45rem;
        letter-spacing: -0.02em;
        text-transform: uppercase;
        line-height: 1;
        color: var(--foreground);
        text-decoration: none;
    }

    [data-theme='brutalism'] .kp-nav__links {
        gap: 0.35rem;
        align-items: center;
    }

    [data-theme='brutalism'] .kp-nav__link {
        display: block;
        padding-inline: 0.75rem;
        font-weight: 700;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--foreground);
        border: var(--kp-line) solid transparent;
        border-radius: 0;
        background: none;
        text-decoration: none;
    }

    /* Pointing at it inverts it [G8, Kenny 2026-10-07 23:44]; the current
       one and the one with focus are the yellow hand. */
    [data-theme='brutalism'] .kp-nav__link:focus-visible,
    [data-theme='brutalism'] .kp-nav__link[aria-current],
    [data-theme='brutalism'] .kp-nav__links > li:focus-within > .kp-nav__link {
        background: var(--secondary);
        color: var(--secondary-foreground);
        border-color: var(--border-strong);
    }

    [data-theme='brutalism'] .kp-nav__link:hover {
        background: var(--foreground);
        color: var(--secondary);
        border-color: var(--border-strong);
    }

    [data-theme='brutalism'] .kp-nav__link[aria-haspopup]::after {
        content: ' ▾';
    }

    [data-theme='brutalism'] .kp-nav__link--lang {
        margin-inline-start: 0.5rem;
        padding-inline-start: 0.7rem;
        border-inline-start: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
    }

    [data-theme='brutalism'] .kp-nav__link--lang:hover,
    [data-theme='brutalism'] .kp-nav__link--lang:focus-visible {
        border-inline-start-color: var(--border-strong);
    }

    /* The call to action: the ink plate with the yellow ink and the shadow;
       pointed at it inverts (yellow plate, ink words), focus lifts it under
       the ring, a press drives it onto its footprint [G8, G14]. */
    [data-theme='brutalism'] .kp-nav__link--cta {
        background: var(--primary);
        color: var(--primary-foreground);
        border-color: var(--border-strong);
        box-shadow: var(--kp-shadow);
    }

    [data-theme='brutalism'] .kp-nav__link--cta:hover {
        background: var(--primary-foreground);
        color: var(--primary);
    }

    [data-theme='brutalism'] .kp-nav__link--cta:focus-visible {
        translate: -2px -2px;
        box-shadow: var(--kp-shadow-up);
    }

    [data-theme='brutalism'] .kp-nav__link--cta:focus-visible {
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring-contrast),
            var(--kp-shadow-up);
    }

    [data-theme='brutalism'] .kp-nav__link--cta:active {
        background: var(--primary-active);
        color: var(--primary-foreground);
        translate: var(--kp-drop) var(--kp-drop);
        box-shadow: none;
    }

    /* The dropdown snaps: white, the line, the shadow — no fade, no blur. */
    [data-theme='brutalism'] .kp-nav__menu {
        background: var(--popover);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
        padding: 0.3rem 0;
        min-width: 12rem;
    }

    /* Collapsed, the dropdown is a list in the flow, not a panel [gap-12]:
       the rule above dresses the floating panel in kp.register, which
       beats the reset in kp.components, so the reset is restated here. */
    @container kp-nav (max-width: 40rem) {
        [data-theme='brutalism'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__menu {
            min-width: 0;
            padding-inline-start: var(--kp-nav-menu-indent, 1rem);
            border: 0;
            background: transparent;
            box-shadow: none;
        }
    }

    [data-theme='brutalism'] .kp-nav__menu a {
        display: block;
        padding-inline: 0.9rem;
        font-weight: 700;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        color: var(--popover-foreground);
        text-decoration: none;
        border-radius: 0;
    }

    [data-theme='brutalism'] .kp-nav__menu a:focus-visible {
        background: var(--secondary);
        color: var(--secondary-foreground);
    }

    [data-theme='brutalism'] .kp-nav__menu a:hover {
        background: var(--foreground);
        color: var(--secondary);
    }

    /* ── Buttons: a plate, the line, the shadow; inverted, lifted, driven in ──
       Pointing at a plate inverts it: the ink takes the plate and the plate
       becomes the ink, nothing moves and the shadow stays on the ground
       [G8, Kenny 2026-10-07 23:44, "hover = invert"]. Focus lifts the box
       off its footprint under the two-channel ring [G14]. A press drives it
       onto its footprint, the shadow's own 6 px, in 1 unit on the fall
       [G14]. A plate steps with --kp-plate and --kp-plate-ink, so every
       variant inverts its own pair. */
    [data-theme='brutalism'] .kp-button {
        --kp-plate: var(--secondary);
        --kp-plate-ink: var(--secondary-foreground);
        font-weight: 700;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--kp-plate-ink);
        background: var(--kp-plate);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
    }

    /* The size the demo drew, and the two the package owes beside it
       [S49, A4 + TH111's amendment]: one height for all three, and the
       type and the padding are what tell them apart. */
    [data-theme='brutalism'] .kp-button:not(.kp-button--sm):not(.kp-button--lg) {
        font-size: 0.9rem;
        padding-inline: 1.5rem;
    }

    [data-theme='brutalism'] .kp-button--sm {
        font-size: 0.78rem;
        padding-inline: 1rem;
    }

    [data-theme='brutalism'] .kp-button--lg {
        font-size: 1.05rem;
        padding-inline: 2rem;
    }

    /* Pointed at: inverted. */
    [data-theme='brutalism'] .kp-button:not(:active, :disabled):hover {
        color: var(--kp-plate);
        background: var(--kp-plate-ink);
        border-color: var(--border-strong);
        translate: none;
        box-shadow: var(--kp-shadow);
    }

    /* Focused: lifted off its footprint, the two channels the base layer
       composes (the outline in the paper, the inner ring in the ink) kept in
       front of the shadow (DI2, AR30). */
    [data-theme='brutalism'] .kp-button:not(:active, :disabled):focus-visible {
        border-color: var(--border-strong);
        translate: -2px -2px;
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring-contrast),
            var(--kp-shadow-up);
    }

    [data-theme='brutalism'] [data-kp-surface='hero'] .kp-row > .kp-button {
        min-width: min(11rem, 100%);
    }

    [data-theme='brutalism'] .kp-button--primary {
        --kp-plate: var(--primary);
        --kp-plate-ink: var(--primary-foreground);
    }

    [data-theme='brutalism'] .kp-button--destructive {
        --kp-plate: var(--destructive);
        --kp-plate-ink: var(--destructive-foreground);
    }

    /* Ghost: no plate, no line, no shadow, until the pointer is on it; then
       it is the inverted slab. */
    [data-theme='brutalism'] .kp-button--ghost {
        --kp-plate: transparent;
        --kp-plate-ink: var(--foreground);
        border-color: transparent;
        box-shadow: none;
    }

    [data-theme='brutalism'] .kp-button--ghost:not(:active, :disabled):hover {
        color: var(--secondary);
        background: var(--foreground);
    }

    [data-theme='brutalism'] .kp-button--ghost:not(:active, :disabled):focus-visible {
        background: transparent;
    }

    [data-theme='brutalism'] .kp-button:disabled {
        background: var(--muted);
        color: var(--muted-foreground);
        translate: none;
        box-shadow: var(--kp-shadow);
    }

    /* Small parts are small slabs [G7]: a 2 px line on a 3 px shadow, and
       they take the same three gestures at their own size. */
    [data-theme='brutalism'] .kp-icon-button {
        border: 2px solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
        color: var(--foreground);
        box-shadow: 3px 3px 0 0 var(--border-strong);
    }

    /* On a toast the close button sits on the toast's own plate, in the
       toast's ink: a plate of its own under the error toast's dark ink read
       1.01:1 (nostromo-notes, 2026-10-04). */
    [data-theme='brutalism'] .kp-toast .kp-icon-button {
        background: transparent;
        border-color: transparent;
        box-shadow: none;
        color: inherit;
    }

    /* On an alert the close button sits on the alert's own plate, in the
       alert's ink, the way it does on a toast [fix-95]. */
    [data-theme='brutalism'] .kp-alert .kp-icon-button {
        background: transparent;
        border-color: transparent;
        box-shadow: none;
        color: inherit;
        /* The cross is a label: 700, and big enough to read at a glance. */
        font-size: 1.5rem;
        font-weight: 700;
        line-height: 1;
    }

    /* A button inside a toast or an alert is brutalism's own [G17]: pointed
       at it is the inverted slab, whatever plate it stands on. */
    [data-theme='brutalism'] .kp-icon-button:not(:active, :disabled):hover,
    [data-theme='brutalism'] :is(.kp-toast, .kp-alert) :is(.kp-icon-button, .kp-button--ghost):not(:active, :disabled):hover {
        background: var(--foreground);
        border-color: var(--border-strong);
        color: var(--secondary);
        box-shadow: 3px 3px 0 0 var(--border-strong);
    }

    [data-theme='brutalism'] .kp-icon-button:not(:active, :disabled):focus-visible {
        translate: -2px -2px;
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring-contrast),
            5px 5px 0 0 var(--border-strong);
    }

    [data-theme='brutalism'] .kp-icon-button:active:not(:disabled) {
        background: var(--secondary-active);
        color: var(--secondary-foreground);
        translate: 3px 3px;
        box-shadow: none;
    }

    /* ── Fields: white wells with the line and the shadow ─────────────── */

    [data-theme='brutalism'] .kp-field__label {
        font-weight: 700;
        letter-spacing: 0.14em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-field__input,
    [data-theme='brutalism'] .kp-datatable__search,
    [data-theme='brutalism'] .kp-combobox__input,
    [data-theme='brutalism'] .kp-palette__input {
        background: var(--card);
        color: var(--card-foreground);
        border: var(--kp-line) solid var(--input);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
        padding-inline: 0.8rem;
    }

    /* The field and the combobox take their height from the package
       [scope-80]; the search box and the palette keep their own. */
    [data-theme='brutalism'] .kp-datatable__search,
    [data-theme='brutalism'] .kp-palette__input {
        padding-block: calc(var(--kp-space-sm) * 1.3);
    }

    /* Focus fills the well with the plate: the ring stays outside it. */
    [data-theme='brutalism'] .kp-field__input:focus-visible,
    [data-theme='brutalism'] .kp-datatable__search:focus-visible,
    [data-theme='brutalism'] .kp-combobox__input:focus-visible,
    [data-theme='brutalism'] .kp-palette__input:focus-visible {
        background: var(--secondary);
        color: var(--secondary-foreground);
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring-contrast),
            var(--kp-shadow);
    }

    [data-theme='brutalism'] select.kp-field__input::picker-icon {
        color: var(--foreground);
    }

    [data-theme='brutalism'] .kp-field__help {
        color: var(--muted-foreground);
    }

    /* A failed part is taped off [G13]: the line and the shadow stay the
       ink, and the error is printed on the failure's plate beneath it. */
    [data-theme='brutalism'] .kp-field--invalid .kp-field__input {
        border-color: var(--border-strong);
        box-shadow: var(--kp-shadow);
    }

    [data-theme='brutalism'] .kp-field__error {
        display: block;
        align-self: start;
        inline-size: fit-content;
        padding-inline: 0.5rem;
        border: 2px solid var(--border-strong);
        background: var(--destructive);
        color: var(--destructive-foreground);
        font-weight: 700;
    }

    [data-theme='brutalism'] .kp-field__error::before {
        content: '!! ';
    }

    /* The checkbox: a small box with its own shadow; checked is the ink
       with a yellow square. */
    [data-theme='brutalism'] .kp-field__check {
        place-items: center;
    }

    [data-theme='brutalism'] .kp-field__check:checked {
        border-color: var(--border-strong);
    }

    [data-theme='brutalism'] .kp-field__check:checked::before {
        content: '';
        inline-size: 0.5rem;
        block-size: 0.5rem;
        background: var(--primary-foreground);
    }

    [data-theme='brutalism'] .kp-fieldset {
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
    }

    [data-theme='brutalism'] .kp-switch__input {
        border: var(--kp-line) solid var(--border-strong);
    }

    [data-theme='brutalism'] .kp-form__summary {
        background: var(--card);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
    }

    /* ── Cards and the dossier ────────────────────────────────────────── */

    [data-theme='brutalism'] .kp-card {
        background: var(--card);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
    }

    [data-theme='brutalism'] .kp-card[data-kp-reveal='emphasis'] {
        position: relative;
    }

    /* The stamp: a signal plate with the pixel outline, tilted. */
    [data-theme='brutalism'] .kp-card[data-kp-label]::before {
        content: attr(data-kp-label);
        position: absolute;
        inset-block-start: 0.9rem;
        inset-inline-end: 1.1rem;
        rotate: -7deg;
        background: var(--fx-signal);
        color: var(--fx-signal-foreground);
        font-family: var(--theme-font-display);
        font-size: 0.8rem;
        letter-spacing: 0.14em;
        text-transform: uppercase;
        padding: 0.3rem 0.55rem;
        box-shadow: var(--kp-pixel);
    }

    /* The stamp changes when the file opens, as the demo's does [S49, A11]. */
    [data-theme='brutalism'] .kp-card[data-kp-open][data-kp-label-open]::before {
        content: attr(data-kp-label-open);
        background: var(--success);
        color: var(--success-foreground);
    }

    /* The redactions: black bars that slide off one after another, the
       way a pen is dragged off a page. */
    [data-theme='brutalism'] .kp-card[data-kp-reveal='emphasis'] mark {
        position: relative;
        background: none;
        color: var(--card-foreground);
        font-weight: 400;
        padding: 0;
        border-bottom: 0;
    }

    [data-theme='brutalism'] .kp-card[data-kp-reveal='emphasis'] mark::after {
        content: '';
        position: absolute;
        inset: -0.12em -0.2em;
        background: var(--foreground);
        transform: scaleX(0);
        transform-origin: right center;
        pointer-events: none;
    }

    [data-theme='brutalism'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared) {
        color: transparent;
    }

    [data-theme='brutalism'][data-kp-effects] .kp-card[data-kp-reveal='emphasis'] mark:not(.is-cleared)::after {
        transform: scaleX(1);
    }

    /* Panels: white, the line, the shadow; nothing floats, nothing fades. */
    [data-theme='brutalism'] .kp-dialog,
    [data-theme='brutalism'] .kp-popover,
    [data-theme='brutalism'] .kp-menu,
    [data-theme='brutalism'] .kp-toast,
    [data-theme='brutalism'] .kp-tooltip,
    [data-theme='brutalism'] .kp-confirm,
    [data-theme='brutalism'] .kp-datepicker__panel,
    [data-theme='brutalism'] .kp-combobox__list,
    [data-theme='brutalism'] .kp-palette,
    [data-theme='brutalism'] .kp-theme-menu__list {
        background: var(--popover);
        color: var(--popover-foreground);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
    }

    /* The wrapper round the theme picker's icon button is not a card: only its
       dropdown list is. */
    [data-theme='brutalism'] .kp-theme-menu {
        background: none;
        border: 0;
        box-shadow: none;
    }

    [data-theme='brutalism'] .kp-toast {
        letter-spacing: 0.1em;
        text-transform: uppercase;
    }

    /* Severity toasts [scope-60]. The plain toast above is repainted here in
       a later layer than kp.components, which swallowed every variant's
       plate; each is restated on the alert's token pair, as the severity
       badge wears it. A status is paint under black ink [G5]: the plate
       changes, the line stays the ink. */
    [data-theme='brutalism'] .kp-toast--info {
        background: var(--info);
        color: var(--info-foreground);
    }

    [data-theme='brutalism'] .kp-toast--warning {
        background: var(--warning);
        color: var(--warning-foreground);
    }

    [data-theme='brutalism'] .kp-toast--destructive,
    [data-theme='brutalism'] .kp-toast--error {
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    [data-theme='brutalism']
        :is(.kp-toast--success, .kp-toast--info, .kp-toast--warning, .kp-toast--destructive, .kp-toast--error)
        :is(.kp-button--ghost, .kp-icon-button) {
        color: inherit;
    }

    [data-theme='brutalism'] .kp-toasts {
        gap: 0.9rem;
    }

    /* The menu keeps a ring's width of paper inside its frame: with the
       line directly against the items, an item's ink ring fell onto the
       ink line and painted nothing new (AR30's dashboard test). */
    [data-theme='brutalism'] .kp-menu {
        padding: calc(2 * var(--kp-focus-ring-inner-width, 2px));
    }

    /* The items are flat on the menu's own plate, as the demo's dropdown
       was: the line, the shadow and the lift belong to the menu, not to
       each row — a row that carried them drowned its ink ring in the ink
       of its own shadow and the frame (AR30's dashboard test). */
    [data-theme='brutalism'] .kp-menu .kp-menu__item {
        --kp-plate: var(--popover);
        --kp-plate-ink: var(--popover-foreground);
        border: 0;
        box-shadow: none;
        translate: none;
        padding: 0.5rem 0.75rem;
    }

    [data-theme='brutalism'] .kp-menu .kp-menu__item--destructive {
        --kp-plate-ink: var(--destructive);
    }

    /* An entry is brutalism's own element [G17]: pointed at it inverts, with
       focus it is the yellow hand under the inner ring, a press drives it
       onto the active plate. */
    [data-theme='brutalism'] .kp-menu .kp-menu__item:not(:active, [aria-disabled='true']):hover {
        background: var(--foreground);
        color: var(--secondary);
        translate: none;
        box-shadow: none;
    }

    [data-theme='brutalism'] .kp-menu .kp-menu__item--destructive:not(:active, [aria-disabled='true']):hover {
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    [data-theme='brutalism'] .kp-menu .kp-menu__item:not(:active):focus-visible {
        background: var(--secondary);
        color: var(--secondary-foreground);
        translate: none;
        box-shadow: 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring-contrast);
    }

    [data-theme='brutalism'] .kp-menu .kp-menu__item:active:not([aria-disabled='true']) {
        background: var(--secondary-active);
        color: var(--secondary-foreground);
        translate: none;
        box-shadow: none;
    }

    /* The plain alert only [gap-1, Kenny 2026-09-10]. This rule used to
       repaint the ground of EVERY alert, and `kp.register` is a later layer
       than `kp.components`, so it beat `.kp-alert--destructive`'s own plate
       while that variant's ink — `--destructive-foreground`, which is drawn
       to sit ON the plate — stayed. Measured in firefox on 2026-09-12:
       seventeen of the twenty-two themes carried a destructive alert whose
       text was unreadable, grotesk at 1.00 exactly, white on white.

       Kenny saw it in chassis-rs and said to write it down and touch
       nothing; this is the round he asked for it in. Same shape as fix-12,
       one property over: a register overriding half of a pair the base
       layer defines together. */
    [data-theme='brutalism'] .kp-alert:not([class*='kp-alert--']) {
        background: var(--card);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
    }

    [data-theme='brutalism'] .kp-alert[class*='kp-alert--'] {
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
    }

    /* A warning or a failure is taped off [G13]: a band of 45 degree hazard
       stripes along its foot, 0.5 rem, in the tone's paint and the ink. The
       tape means danger and nothing else [G16]. */
    [data-theme='brutalism'] .kp-alert--warning,
    [data-theme='brutalism'] .kp-alert--destructive {
        --kp-sig-br-tone: var(--warning);
        padding-block-end: calc(0.75rem + 0.5rem);
        background-image: repeating-linear-gradient(45deg, var(--kp-sig-br-tone) 0 6px, var(--border-strong) 6px 12px);
        background-position: 0 100%;
        background-size: 100% 0.5rem;
        background-repeat: no-repeat;
    }

    [data-theme='brutalism'] .kp-alert--destructive {
        --kp-sig-br-tone: var(--destructive);
    }

    [data-theme='brutalism'] .kp-alert__label {
        font-family: var(--theme-font-display);
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-grid__tile,
    [data-theme='brutalism'] .kp-split__pane {
        background: var(--card);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
    }

    [data-theme='brutalism'] .kp-grid {
        gap: 1.25rem;
    }

    [data-theme='brutalism'] .kp-split {
        gap: 1rem;
    }

    [data-theme='brutalism'] .kp-split__separator {
        background: var(--border-strong);
        inline-size: var(--kp-line);
    }

    /* Top and bottom [gap-12]: the thickness above is an inline size, so
       a horizontal split takes the same value as a block size. */
    [data-theme='brutalism'] .kp-split[data-kp-orientation='horizontal'] > .kp-split__separator {
        inline-size: auto;
        block-size: var(--kp-line);
    }

    /* The footer: the ink, the paper, the yellow. */
    [data-theme='brutalism'] .kp-footer {
        background: var(--sidebar-background);
        color: var(--sidebar-foreground);
    }

    [data-theme='brutalism'] .kp-footer h4 {
        font-family: var(--theme-font-display);
        font-weight: 400;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        color: var(--sidebar-primary);
    }

    [data-theme='brutalism'] .kp-footer a {
        color: var(--sidebar-foreground);
        font-size: 0.85rem;
        font-weight: 700;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        text-decoration: none;
        border-bottom: var(--kp-line) solid transparent;
    }

    [data-theme='brutalism'] .kp-footer a:hover,
    [data-theme='brutalism'] .kp-footer a:focus-visible {
        color: var(--sidebar-primary);
        border-bottom-color: var(--sidebar-primary);
    }

    [data-theme='brutalism'] .kp-footer .microlabel {
        background: none;
        box-shadow: none;
        padding: 0.8rem 0 0;
        border-top: var(--kp-line) solid var(--sidebar-primary);
        color: var(--sidebar-foreground);
        font-family: var(--theme-font-body);
        font-weight: 700;
        letter-spacing: 0.1em;
        display: block;
    }

    /* ── Badges, tags, status: candy plates with black ink ────────────── */

    [data-theme='brutalism'] .kp-badge,
    [data-theme='brutalism'] .kp-tag {
        border-radius: 0;
        border: 2px solid var(--border-strong);
        box-shadow: 3px 3px 0 0 var(--border-strong);
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-health {
        font-weight: 700;
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-health__dot {
        border-radius: 0;
        border: 2px solid var(--border-strong);
    }

    /* A skeleton is a well, the place the reading will stand [G10]: white in
       the 2 px ink line on a 3 px shadow; the lintel is hoisted in it in
       kp.signature. */
    [data-theme='brutalism'] .kp-skeleton {
        background-color: var(--card);
        border: 2px solid var(--border-strong);
        border-radius: 0;
        box-shadow: 3px 3px 0 0 var(--border-strong);
    }

    [data-theme='brutalism'] .kp-error {
        color: var(--destructive);
        font-weight: 700;
    }

    /* ── Text shapes ──────────────────────────────────────────────────── */

    [data-theme='brutalism'] .kp-id,
    [data-theme='brutalism'] .kp-url,
    [data-theme='brutalism'] .kp-numeric,
    [data-theme='brutalism'] .kp-timestamp,
    [data-theme='brutalism'] .kp-masked,
    [data-theme='brutalism'] .kp-copyable,
    [data-theme='brutalism'] .kp-truncate,
    [data-theme='brutalism'] .kp-cell-break,
    [data-theme='brutalism'] .kp-cell-truncate {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.04em;
    }

    /* Dates and identifiers are bold mono in ink, never the muted 400 [G15,
       Kenny 2026-10-07: "some text is too thin, like the date"]. */
    [data-theme='brutalism'] .kp-id,
    [data-theme='brutalism'] .kp-url,
    [data-theme='brutalism'] .kp-numeric,
    [data-theme='brutalism'] .kp-timestamp,
    [data-theme='brutalism'] .kp-masked,
    [data-theme='brutalism'] .kp-copyable {
        font-weight: 700;
    }

    [data-theme='brutalism'] .kp-timestamp,
    [data-theme='brutalism'] .kp-id {
        color: var(--foreground);
        font-size: max(0.75rem, 0.9375em);
    }

    [data-theme='brutalism'] .kp-copyable__button {
        border: 2px solid var(--border-strong);
        border-radius: 0;
        box-shadow: 3px 3px 0 0 var(--border-strong);
    }

    /* The copy button's two states win over this register's own button
       rules [gap-12]: those paint in kp.register, which beats the states
       in kp.components, so copied lost its success plate and a refused
       copy looked idle. Restated token for token. */
    [data-theme='brutalism'] .kp-copyable .kp-copyable__button[data-kp-copied] {
