    /* ── The switch and the check [G7]: small slabs, a 2 px line on a 3 px
       shadow. ── */
    [data-theme='brutalism'] .kp-switch {
        --kp-switch-border: 2px;
        --kp-switch-radius: 0;
        --kp-switch-thumb-radius: 0;
