        border-color: var(--primary-foreground);
        background: var(--primary-foreground);
        transform: translateX(calc(var(--kp-switch-width, 2.5rem) - var(--kp-switch-height, 1.5rem)));
    }

    [data-theme='brutalism'] .kp-field__check {
        --kp-sig-dur: var(--kp-sig-br-time);
        appearance: none;
        display: inline-grid;
        place-content: center;
        inline-size: 1.25rem;
        block-size: 1.25rem;
        margin: 0;
        border: 2px solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
    }

    [data-theme='brutalism'] .kp-field__check:not(:focus-visible) {
        box-shadow: 3px 3px 0 var(--border-strong);
    }

    [data-theme='brutalism'] .kp-field__check:checked {
