    [data-theme='brutalism'] .kp-field__check[type='checkbox']:checked::before {
        content: '';
        inline-size: 0.7rem;
        block-size: 0.36rem;
        border-inline-start: 3px solid var(--border-strong);
        border-block-end: 3px solid var(--border-strong);
        transform: translateY(-2px) rotate(-45deg);
    }

    [data-theme='brutalism'] .kp-field__check[type='radio'] {
        border-radius: 50%;
    }

    [data-theme='brutalism'] .kp-field__check[type='radio']:checked {
