    }

    [data-theme='brutalism'] .kp-field__check[type='radio']:checked::before {
        content: '';
        inline-size: 0.5rem;
        block-size: 0.5rem;
        border-radius: 50%;
        background: var(--border-strong);
    }

    /* ── What opens is dropped onto its footprint [G3]: the toast, the dialog
       and the tooltip. Their hard shadow is on the page from the first frame,
       where the panel will stand; the panel falls onto it from up-left on
       the fall curve and stops dead. A toast and the tooltip fall 3 units, the
       dialog, the big slab, 15 (Kenny, 2026-10-03: "I prefer this at 1/4
       speed"). No clip, no fade, no scale, no tilt. ── */
    [data-theme='brutalism'] .kp-toast {
        --kp-sig-dur: var(--kp-sig-br-time);
        --kp-sig-br-h: var(--kp-sig-br-h-plate);
        --kp-sig-br-sh: var(--kp-sig-br-drop);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        color: var(--secondary-foreground);
        box-shadow: var(--kp-shadow);
        font-weight: 700;
    }

    [data-theme='brutalism'] .kp-toast {
        background: var(--secondary);
    }

    [data-theme='brutalism'] .kp-toast--success {
        background: var(--success);
        color: var(--success-foreground);
    }

    [data-theme='brutalism'] .kp-dialog::backdrop {
        background: var(--accent);
    }

    [data-theme='brutalism'] .kp-dialog {
        /* The drop starts 2.5 rem up-left of the footprint: on a narrow
           screen the dialog leaves that much room on both sides, so no
           frame of the drop is outside the window. */
        max-inline-size: var(--kp-dialog-max-width, min(32rem, calc(100vw - 2 * var(--kp-sig-br-h-slab))));
        /* js/motion.js measures the theme's time on an unopened probe and
           takes a close as two thirds of what it reads: the unopened dialog
           runs one and a half drops, the open one a drop, which is also its
           close and its opening. */
        --kp-sig-dur: calc(var(--kp-sig-br-dialog) * 1.5);
        --kp-sig-br-h: var(--kp-sig-br-h-slab);
        --kp-sig-br-sh: var(--kp-sig-br-drop);
        padding-block-start: 0;
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
        box-shadow: var(--kp-shadow);
    }

    [data-theme='brutalism'] .kp-dialog[open] {
        --kp-sig-dur: var(--kp-sig-br-dialog);
    }

    [data-theme='brutalism'] .kp-dialog__title {
        /* The title at the package's metrics [scope-87]: Kenny chose the fixed size
           over the theme's own on 2026-10-03 (research/dialog-title). */
        margin-inline: calc(-1 * var(--kp-dialog-padding, 1.25rem));
        padding-inline: var(--kp-dialog-padding, 1.25rem);
        border-block-end: var(--kp-line) solid var(--border-strong);
        background: var(--secondary);
        color: var(--secondary-foreground);
        font-family: var(--theme-font-display);
        letter-spacing: -0.01em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-tooltip {
        --kp-sig-dur: var(--kp-sig-br-time);
        --kp-sig-br-h: var(--kp-sig-br-h-part);
        --kp-sig-br-sh: 3px;
        margin-block-start: 0.6rem;
        margin-inline-start: 0.35rem;
        padding: 0.25rem 0.6rem;
        border: 2px solid var(--border-strong);
        border-radius: 0;
        background: var(--info);
        color: var(--border-strong);
        box-shadow: 3px 3px 0 var(--border-strong);
        font-size: 0.8rem;
        font-weight: 700;
        letter-spacing: 0.03em;
        text-transform: uppercase;
    }

    [data-theme='brutalism'] .kp-tooltip::before {
        content: '';
        position: absolute;
        inset-block-end: 100%;
        inset-inline-start: 0.8rem;
        inline-size: 12px;
        block-size: 8px;
        background: var(--border-strong);
        clip-path: polygon(0 100%, 50% 0, 100% 100%);
    }

    [data-theme='brutalism'] .kp-wizard__steps {
        gap: 0.75rem 0;
    }

    [data-theme='brutalism'] .kp-wizard__steps li {
        gap: 0.5rem;
        color: var(--foreground);
        font-weight: 700;
    }

    [data-theme='brutalism'] .kp-wizard__steps li:not(:last-child)::after {
        content: '';
        inline-size: 1.1rem;
        block-size: 3px;
        margin-inline: 0.35rem;
        background: var(--border-strong);
