        anchor-scope: --kp-sig-pa-tip;
    }

    [data-theme='pastel'] .kp-tooltip {
        anchor-name: --kp-sig-pa-tip;
        z-index: 2;
        transform-origin: var(--kp-sig-pa-corner);
    }

    [data-theme='pastel'] .kp-tooltip-anchor:has(> .kp-tooltip:not([hidden]))::after {
        content: '';
        position: absolute;
        z-index: 1;
        position-anchor: --kp-sig-pa-tip;
        inset: auto;
        inline-size: anchor-size(width);
        block-size: anchor-size(height);
        left: calc(anchor(left) + 3px * var(--kp-sig-pa-dir));
        top: calc(anchor(top) + 3px);
        border-radius: var(--kp-sig-pa-r-chip);
        background: var(--kp-sig-pa-pass-c);
        pointer-events: none;
