            }

            [data-theme='pastel']
                .kp-nav__links
                > li:is(:hover, :focus-within, [data-kp-nav-menu-open]):has(> .kp-nav__menu:not(.kp-nav__menu--wide))::after,
            [data-theme='pastel']
                .kp-nav__links
                > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true'])):has(> .kp-nav__menu--wide)::after {
                animation: kp-sig-pastel-pass-in var(--kp-sig-pa-window) var(--kp-sig-pa-land) backwards;
            }

