        :is(
            .kp-toast,
            .kp-alert,
            .kp-tour,
            .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']),
            .kp-datatable__busy-panel,
            .kp-calendar__busy
