           and curve, and back on its reflection. */
        [data-theme='pastel'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='true'] {
            transition: translate 0s linear;
            animation: kp-sig-pastel-sidenav-in var(--kp-sig-pa-window) var(--kp-sig-pa-land) backwards;
        }

        [data-theme='pastel'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='false'] {
            transition: translate 0s linear var(--kp-sig-pa-window);
            animation: kp-sig-pastel-sidenav-out var(--kp-sig-pa-window) var(--kp-sig-pa-land) reverse forwards;
        }

        [data-theme='pastel'] .kp-sidenav__backdrop {
            animation-duration: var(--kp-sig-pa-window);
        }

        [data-theme='pastel'] [data-kp-sidenav-shift='open'] {
            transition-duration: var(--kp-sig-pa-window);
            transition-timing-function: var(--kp-sig-pa-land);
            transition-delay: 0s;
        }

        [data-theme='pastel'] [data-kp-sidenav-shift='closed'] {
            transition-duration: var(--kp-sig-pa-window);
            transition-timing-function: var(--kp-sig-pa-land-back);
            transition-delay: 0s;
        }

        /* On a phone the bar's links are a panel of their own under the bar:
           stuck on, and taken off as that backwards (js/components.js keeps it
           open `--kp-nav-close-time` while `[data-kp-nav-closing]`). */
        @container kp-nav (max-width: 40rem) {
            [data-theme='pastel'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links {
                animation: kp-sig-pastel-stuck-plate-in var(--kp-sig-pa-window) var(--kp-sig-pa-land) backwards;
            }

            [data-theme='pastel'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-closing] > .kp-nav__links {
                animation: kp-sig-pastel-stuck-plate-out var(--kp-sig-pa-window) var(--kp-sig-pa-land) reverse forwards;
            }

            [data-theme='pastel'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) .kp-nav__links > li > .kp-nav__menu {
                animation: none;
                transition: none;
            }
        }
    }

    /* The phone panel's own paper and pass (B), only while it is a panel. */
    @container kp-nav (max-width: 40rem) {
        [data-theme='pastel'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links {
            --kp-sig-pa-plate: var(--card);
            --kp-sig-pa-edge: var(--border-strong);
            position: relative;
            isolation: isolate;
            margin-block: 0.5rem calc(var(--kp-sig-pa-off) + 0.25rem);
            padding: 0.5rem;
            border-radius: var(--kp-sig-pa-r-plate);
            transform-origin: var(--kp-sig-pa-corner);
        }

        [data-theme='pastel'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links::before {
            content: '';
            position: absolute;
            z-index: -1;
            inset: 0;
            border-radius: inherit;
            background: var(--kp-sig-pa-pass-c);
            transform-origin: var(--kp-sig-pa-corner);
            rotate: calc(9deg * var(--kp-sig-pa-turn, var(--kp-sig-pa-dir)) * (1 - var(--kp-sig-pa-ink)));
            transform: translate(
                calc((var(--kp-sig-pa-off) + 18px * (1 - var(--kp-sig-pa-pass))) * var(--kp-sig-pa-dir)),
                calc(var(--kp-sig-pa-off) + 16px * (1 - var(--kp-sig-pa-pass)) + 8px * (1 - var(--kp-sig-pa-ink)))
            );
            opacity: clamp(0, var(--kp-sig-pa-pass), 1);
            pointer-events: none;
        }

        [data-theme='pastel'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links::after {
            content: '';
            position: absolute;
            z-index: -1;
            inset: 0;
            box-sizing: border-box;
            border: 1px solid var(--kp-sig-pa-edge);
            border-radius: inherit;
            background: var(--kp-sig-pa-plate);
            opacity: clamp(0, var(--kp-sig-pa-ink), 1);
            pointer-events: none;
        }
    }

    /* ── 5 · The alarm (scope-94, scope-98; G3 for a free part) ──────────── */

    /* The alarm's plate comes on the pass's clock and its panel is stuck on
       it: the dialog runs the two clocks alone (js/motion.js keeps them and
       plays them backwards to close), its ground, its pearl seams and its
       backdrop follow the pass, the panel follows the ink, and the alarm's
       ::after is the panel's pass, anchored on the panel. */
    [data-theme='pastel'] .kp-alarm {
        anchor-scope: --kp-sig-pa-alarm;
        background: color-mix(in srgb, var(--kp-alarm-ground) calc(clamp(0, var(--kp-sig-pa-pass), 1) * 100%), transparent);
    }

    [data-theme='pastel'] .kp-alarm__bars {
        opacity: clamp(0, var(--kp-sig-pa-pass), 1);
    }

    [data-theme='pastel'] .kp-alarm::backdrop {
        opacity: clamp(0, var(--kp-sig-pa-pass), 1);
    }

    [data-theme='pastel'] .kp-alarm__panel {
        anchor-name: --kp-sig-pa-alarm;
        border-radius: var(--kp-sig-pa-r-plate);
        box-shadow: none;
        transform-origin: var(--kp-sig-pa-corner);
        rotate: calc(-9deg * var(--kp-sig-pa-turn, var(--kp-sig-pa-dir)) * (1 - var(--kp-sig-pa-ink)));
        translate: 0 calc(-8px * (1 - var(--kp-sig-pa-ink)));
        opacity: clamp(0, var(--kp-sig-pa-ink), 1);
    }

    [data-theme='pastel'] .kp-alarm::after {
        content: '';
        position: absolute;
        z-index: 0;
        position-anchor: --kp-sig-pa-alarm;
        inset: auto;
        inline-size: anchor-size(width);
        block-size: anchor-size(height);
        left: calc(anchor(left) + var(--kp-sig-pa-off) * var(--kp-sig-pa-dir));
        top: calc(anchor(top) + var(--kp-sig-pa-off));
        border-radius: var(--kp-sig-pa-r-plate);
        background: var(--kp-sig-pa-pass-c);
        box-shadow: none;
        translate: calc(18px * var(--kp-sig-pa-dir) * (1 - var(--kp-sig-pa-pass))) calc(16px * (1 - var(--kp-sig-pa-pass)));
        opacity: clamp(0, var(--kp-sig-pa-pass), 1);
        pointer-events: none;
    }

    @supports not (anchor-name: --a) {
        [data-theme='pastel'] .kp-alarm::after {
            content: none;
        }

        [data-theme='pastel'] .kp-alarm__panel {
            box-shadow: calc(var(--kp-sig-pa-off) * var(--kp-sig-pa-dir)) var(--kp-sig-pa-off) 0 var(--kp-sig-pa-pass-c);
        }
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) {
            animation: kp-sig-pastel-pass-host-in var(--kp-sig-pa-dialog) var(--kp-sig-pa-land) backwards;
        }

        [data-theme='pastel'] .kp-alarm[open]:not([data-kp-alarm-motion='still'])::backdrop {
            animation: kp-sig-pastel-pass-host-in var(--kp-sig-pa-dialog) var(--kp-sig-pa-land) backwards;
        }
    }

    /* ── 6 · Leaving and arriving (G12: the anchor, then a thumbtack) ──── */

    /* js/motion.js marks what leaves `[data-kp-leaving]`, closes its space
       in the leave's own time (`--kp-leave-fold-*`) and lets what arrives
       play the leave backwards. What leaves peels off at its top-start
       corner and its pass slides off register: the landing backwards. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] [data-kp-leaving] {
            transform-origin: var(--kp-sig-pa-corner);
            animation: kp-sig-pastel-stuck-out var(--kp-sig-pa-window) var(--kp-sig-pa-land) reverse forwards;
        }

        /* A part that draws its own plate and pass leaves with them. */
        [data-theme='pastel'] :is(.kp-toast, .kp-alert, .kp-calendar__busy)[data-kp-leaving] {
            animation: kp-sig-pastel-stuck-plate-out var(--kp-sig-pa-window) var(--kp-sig-pa-land) reverse forwards;
        }

        /* The busy table's layer: its clocks alone; the veil and the panel
           in it follow. The layer keeps its place (lessons 5, 43). */
        [data-theme='pastel'] .kp-datatable__busy-overlay[data-kp-leaving] {
            position: absolute;
            animation: kp-sig-pastel-pass-host-out var(--kp-sig-pa-window) var(--kp-sig-pa-land) reverse forwards;
        }

        /* The table and the rows under the layer dim on the pass's clock
           and come back on it (css/layout.css `--kp-busy-opacity`, the rows'
           `--kp-datatable-busy-opacity`, both switched with `aria-busy` in one
           frame while the layer took 560 ms): one keyframe set forwards as the
           layer arrives, a second name played backwards as it leaves
           (lessons 8, 44). */
        [data-theme='pastel'] .kp-datatable {
            --kp-sig-pa-dim: var(--kp-busy-opacity, 0.7);
        }

        [data-theme='pastel'] .kp-datatable .kp-table tbody {
            --kp-sig-pa-dim: var(--kp-datatable-busy-opacity, 0.55);
        }

        [data-theme='pastel'] :is(.kp-datatable[aria-busy='true'], .kp-datatable[aria-busy='true'] .kp-table tbody) {
            animation: kp-sig-pastel-busy-dim var(--kp-sig-pa-window) var(--kp-sig-pa-land) backwards;
        }

        [data-theme='pastel']
            :is(
                .kp-datatable:not([aria-busy='true']):has(> .kp-datatable__busy-overlay[data-kp-leaving]),
                .kp-datatable:not([aria-busy='true']):has(> .kp-datatable__busy-overlay[data-kp-leaving]) .kp-table tbody
            ) {
            animation: kp-sig-pastel-busy-dim-back var(--kp-sig-pa-window) var(--kp-sig-pa-land) reverse backwards;
        }

        /* On the pass's own stops: nothing in the first frame, there at
           78.57 % (440 of the 560). */
        @keyframes kp-sig-pastel-busy-dim {
            0% {
                opacity: 1;
            }

            78.5714%,
            100% {
                opacity: var(--kp-sig-pa-dim);
            }
        }

        @keyframes kp-sig-pastel-busy-dim-back {
            0% {
                opacity: 1;
            }

            78.5714%,
            100% {
                opacity: var(--kp-sig-pa-dim);
            }
        }

        /* A part fixed to the page (a card, a key figure, a tile): the
           thumbtack comes out first, then the landing backwards; arriving,
           js/motion.js plays it the other way, the tack pushed in last. */
        [data-theme='pastel'] :is(.kp-card, .kp-kpi, .kp-grid__tile)[data-kp-leaving] {
            /* Its space closes with the landing backwards, after the tack is
               out (360 of the 560 ms leave: a share of 0.6429). */
            --kp-leave-fold-start: 0.6429;
            animation: kp-sig-pastel-stuck-out var(--kp-sig-pa-window) var(--kp-sig-pa-land) var(--kp-sig-pa-tack) reverse forwards;
        }

        /* The tack is the ::after, or the ::before on a key figure that acts
           (its ::after is its fold, section 8). */
        [data-theme='pastel'] :is(.kp-card, .kp-kpi:not(a, .kp-kpi--toggle), .kp-grid__tile)[data-kp-leaving]::after,
        [data-theme='pastel'] :is(a.kp-kpi, .kp-kpi--toggle)[data-kp-leaving]::before {
            animation: kp-sig-pastel-tack-out var(--kp-sig-pa-tack) var(--kp-sig-pa-land) reverse forwards;
        }
    }

    /* The busy month's card is held on screen through its leave (lesson 19):
       js/calendar.js marks it `[data-kp-leaving]` while its state goes. */
    [data-theme='pastel'] .kp-calendar__busy {
        --kp-calendar-busy-leave: hold;
        /* ... with its words on it, so the card that peels off is the card
           that was stuck on (js/calendar.js empties them when it is gone). */
        --kp-calendar-busy-words: hold;
        transition: none;
    }

    [data-theme='pastel'] .kp-calendar--busy-whole > .kp-calendar__busy[data-kp-leaving] {
        --kp-spinner-size: var(--kp-calendar-busy-spinner, 2.5rem);
        z-index: 1;
        display: grid;
        place-self: center;
        place-items: center;
        padding: var(--kp-space-md, 1rem);
        line-height: 0;
    }

    /* A loading day is the caterpillar's body itself (section 10): its own
       spinner stands down, so no second picture comes or goes. */
    [data-theme='pastel'] .kp-calendar__day-busy {
        display: none !important;
    }

    /* ── 7 · Paper at rest: the pass, the tape, the tack (G6, G7) ──────── */

    /* A plate is white paper with its flat sky pass 6 px off register. */
    [data-theme='pastel']
        :is(
            .kp-card,
            .kp-kpi,
            .kp-grid__tile,
            .kp-split__pane,
            .kp-datatable,
            .kp-wizard,
            .kp-spec,
            .kp-log,
            .kp-calendar,
            .kp-reorder,
            .kp-diff,
            .kp-nav__menu
        ) {
        border-radius: var(--kp-sig-pa-r-plate);
        box-shadow: calc(var(--kp-sig-pa-off) * var(--kp-sig-pa-dir)) var(--kp-sig-pa-off) 0 var(--kp-sig-pa-pass-c);
    }

    /* The bar's menu draws its pass in its item (section 3), where anchor
       positioning is there. */
    @supports (anchor-name: --a) {
        @container kp-nav (width > 40rem) {
            [data-theme='pastel'] .kp-nav__menu {
                box-shadow: none;
            }
        }
    }

    @container kp-nav (max-width: 40rem) {
        [data-theme='pastel'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__menu {
            box-shadow: none;
            border-radius: 0;
        }
    }

    /* A part fixed to the page carries its thumbtack at its top centre: a
       round plum head with a rim and a glint, its flat shadow in the second
       ink (G12, Kenny 2026-10-14). Every key figure carries it, the ones
       that act too (a link, a toggle): theirs is the ::before, since their
       ::after is the corner that curls on a hover (section 8). */
    [data-theme='pastel'] :is(.kp-card, .kp-kpi, .kp-grid__tile) {
        position: relative;
    }

    [data-theme='pastel'] :is(.kp-card, .kp-kpi, .kp-grid__tile)::after,
    [data-theme='pastel'] :is(a.kp-kpi, .kp-kpi--toggle)::before {
        content: '';
        position: absolute;
        z-index: 3;
        inset-block-start: -0.5rem;
        inset-inline-start: 50%;
        inline-size: 1.2rem;
        block-size: 1.2rem;
        box-sizing: border-box;
        border: 1.5px solid var(--kp-sig-pa-peel);
        border-radius: 50%;
        background:
            radial-gradient(ellipse 0.3rem 0.2rem at 36% 32%, color-mix(in srgb, var(--primary) 22%, var(--card)) 0 92%, transparent 100%),
            radial-gradient(circle at 50% 50%, var(--primary) 0 54%, hsl(from var(--primary) h s calc(l * 0.82)) 58% 100%);
        box-shadow: 2px 2px 0 var(--kp-sig-pa-pass-c);
        translate: -50% 0;
        pointer-events: none;
    }

    [data-theme='pastel'] :is(.kp-card, .kp-kpi, .kp-grid__tile):dir(rtl)::after,
    [data-theme='pastel'] :is(a.kp-kpi, .kp-kpi--toggle):dir(rtl)::before {
        translate: 50% 0;
    }

    /* A panel stuck to the page carries one strip of washi tape across its
       top-start corner. */
    [data-theme='pastel'] :is(.kp-wizard, .kp-spec) {
        position: relative;
    }

    [data-theme='pastel'] :is(.kp-wizard, .kp-spec)::after {
        content: '';
        position: absolute;
        z-index: 2;
        inset-block-start: -0.4rem;
        inset-inline-start: 0.5rem;
        inline-size: 2.75rem;
        block-size: 0.8rem;
        border-radius: 2px;
        background: var(--kp-sig-pa-tape-bg);
        rotate: calc(-14deg * var(--kp-sig-pa-dir));
        opacity: 0.94;
        pointer-events: none;
    }

    /* ── 8 · Pointing, focus, press (G13-G16) ───────────────────────────── */

    /* A control is a sticker with its flat plum peel 3 px under it. Hover
       lifts it 2 px on its peel (5 px) and its top-end corner curls into a
       fold of its back; a press sticks it down flat (3 px, peel 0, the fold
       flat); focus is the dashed plum line alone, 3 px out. All on the
       landing in the contact time; the words never turn. A button in a
       composite (a header, a menu, a tile, an alert, the alarm) is this
       button (G13). */
    [data-theme='pastel'] .kp-button {
        border-radius: var(--kp-sig-pa-r-ctl);
        box-shadow: 0 3px 0 var(--kp-sig-pa-peel);
        translate: 0 0;
        rotate: none;
    }

    [data-theme='pastel'] .kp-button--ghost {
        border: 1px solid var(--border-strong);
    }

    /* The fold: the ground where the corner lifted off, the sticker's back
       below the crease. */
    [data-theme='pastel'] :is(.kp-button, .kp-menu__item, a.kp-kpi, .kp-kpi--toggle)::after {
        content: '';
        position: absolute;
        z-index: 1;
        inset-block-start: -1px;
        inset-inline-end: -1px;
        inline-size: 0.95rem;
        block-size: 0.95rem;
        border-start-end-radius: var(--kp-sig-pa-r-ctl);
        border-end-start-radius: 0.4rem;
        background: linear-gradient(calc(225deg - 90deg * (1 - var(--kp-sig-pa-dir))), var(--kp-sig-pa-ground) 0 50%, var(--muted) 50% 100%);
        box-shadow: calc(-1px * var(--kp-sig-pa-dir)) 1px 0 hsl(from var(--border-strong) h s l / 0.7);
        scale: 0;
        transform-origin: calc(50% + 50% * var(--kp-sig-pa-dir)) 0;
        pointer-events: none;
    }

    /* A key figure that is a link or a toggle folds at its plate's corner. */
    [data-theme='pastel'] :is(a.kp-kpi, .kp-kpi--toggle)::after {
        inline-size: calc(var(--kp-sig-pa-r-plate) + 0.3rem);
        block-size: calc(var(--kp-sig-pa-r-plate) + 0.3rem);
        border-start-end-radius: var(--kp-sig-pa-r-plate);
        border-end-start-radius: 0.55rem;
        border-start-start-radius: 0;
        inset-inline-start: auto;
        translate: none;
        border-width: 0;
        background: linear-gradient(calc(225deg - 90deg * (1 - var(--kp-sig-pa-dir))), var(--kp-sig-pa-ground) 0 50%, var(--muted) 50% 100%);
        box-shadow: calc(-1px * var(--kp-sig-pa-dir)) 1px 0 hsl(from var(--border-strong) h s l / 0.7);
    }

    [data-theme='pastel'] :is(.kp-menu__item, a.kp-kpi, .kp-kpi--toggle) {
        position: relative;
    }

    /* A key figure that acts is a sticker: its peel, not its pass. */
    [data-theme='pastel'] :is(a.kp-kpi, .kp-kpi--toggle) {
        box-shadow: 0 3px 0 var(--kp-sig-pa-peel);
        translate: 0 0;
    }

    [data-theme='pastel'] .kp-menu__item {
        border-radius: calc(var(--kp-sig-pa-r-ctl) * 0.8);
    }

    [data-theme='pastel'] .kp-menu__item::after {
        border-start-end-radius: calc(var(--kp-sig-pa-r-ctl) * 0.8);
        inline-size: 0.8rem;
        block-size: 0.8rem;
    }

    [data-theme='pastel'] :is(.kp-button, a.kp-kpi, .kp-kpi--toggle):hover:not(:disabled, [aria-disabled='true']) {
        translate: 0 -2px;
        box-shadow: 0 5px 0 var(--kp-sig-pa-peel);
    }

    [data-theme='pastel'] :is(.kp-button, .kp-menu__item, a.kp-kpi, .kp-kpi--toggle):hover:not(:disabled, [aria-disabled='true'], :active)::after {
        scale: 1;
    }

    [data-theme='pastel'] .kp-menu__item:hover:not(:disabled, [aria-disabled='true']) {
        background: var(--accent);
        color: var(--accent-foreground);
    }

    [data-theme='pastel'] :is(.kp-button, a.kp-kpi, .kp-kpi--toggle):active:not(:disabled, [aria-disabled='true']) {
        translate: 0 3px;
        box-shadow: 0 0 0 var(--kp-sig-pa-peel);
    }

    [data-theme='pastel'] .kp-menu__item:active:not(:disabled, [aria-disabled='true']) {
        translate: 0 1px;
        background: var(--accent);
        color: var(--accent-foreground);
    }

    /* G15, Kenny's pick: the dashed line alone, in the ring's plum, 3 px out
       (the package's inner ring is 0 wide in pastel). A part keeps its own
       peel or pass under it. */
    [data-theme='pastel'] :focus-visible {
        outline: 2px dashed var(--ring);
        outline-offset: 3px;
    }

    [data-theme='pastel'] :is(.kp-button, a.kp-kpi, .kp-kpi--toggle):focus-visible {
        box-shadow: 0 3px 0 var(--kp-sig-pa-peel);
    }

    [data-theme='pastel'] :is(.kp-button, a.kp-kpi, .kp-kpi--toggle):focus-visible:hover:not(:disabled, [aria-disabled='true']) {
        box-shadow: 0 5px 0 var(--kp-sig-pa-peel);
    }

    /* On a tone's own plate the plum line would sink in (the ring reads
       1.34:1 on the destructive plate and 2.92:1 on the info plate): there
       it takes the plate's ink, the words' colour, still dashed and alone
       (measured, research/pastel-applied/_audit/MISSING.md). */
    [data-theme='pastel']
        :is(
            .kp-toast--destructive,
            .kp-toast--error,
            .kp-toast--info,
            .kp-alert--destructive,
            .kp-alert--info,
            .kp-button--primary,
            .kp-button--destructive
        )
        :focus-visible {
        outline-color: currentColor;
    }

    /* An entry in a list sits in a scrolling box: its line is 1 px out. */
    [data-theme='pastel']
        :is(
            .kp-menu__item,
            .kp-palette__option,
            .kp-combobox__option,
            [role='option'],
            .kp-menu [data-kp-theme],
            .kp-datepicker__day,
            .kp-calendar__day,
            .kp-tree [role='treeitem'],
            .kp-sidenav__link,
            .kp-sidenav__category-toggle,
            .kp-nav__menu a
        ):focus-visible {
        outline-offset: 1px;
        box-shadow: none;
    }

    /* A cell of a grid and a box that scrolls take the line inside. */
    [data-theme='pastel']
        :is(.kp-table[role='grid'] :is(th, td), .kp-table-wrap, .kp-datatable > .kp-table-wrap, .kp-chart__plot, .kp-kpi__chart-plot):focus-visible {
        outline-offset: -3px;
        box-shadow: none;
    }

    /* A field's line goes round its box, the box stays as it is. */
    [data-theme='pastel'] :is(.kp-field__input, .kp-combobox__input):focus-visible {
        box-shadow: none;
    }

    /* The alarm takes no line: in its auto mode the whole screen has focus. */
    [data-theme='pastel'] .kp-alarm:focus-visible {
        outline: none;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] :is(.kp-button, a.kp-kpi, .kp-kpi--toggle, .kp-menu__item) {
            transition:
                translate var(--fx-duration) var(--kp-sig-pa-land),
                box-shadow var(--fx-duration) var(--kp-sig-pa-land),
                background-color var(--fx-duration) ease,
                border-color var(--fx-duration) ease,
                color var(--fx-duration) ease;
        }

        [data-theme='pastel'] :is(.kp-button, .kp-menu__item, a.kp-kpi, .kp-kpi--toggle)::after {
            transition: scale var(--fx-duration) var(--kp-sig-pa-land);
        }
    }

    /* ── One face; weight speaks (G17) ──────────────────────────────────── */

    /* Labels are the body face at 600 in sentence case; the microlabel and
       the stamp keep their spaced capitals (the one exception), the
       alarm's code is an identifier. */
    [data-theme='pastel']
        :is(
            .kp-kpi__label,
            .kp-kpi__label-note,
            .kp-theme-group__label,
            .kp-palette__group-label,
            .kp-shortcuts__group-label,
            .kp-menu__heading,
            .kp-nav__menu-heading,
            .kp-log__level,
            .kp-alarm__countdown,
            .kp-alarm__hint
        ),
    [data-theme='pastel'] .kp-nav__menu[data-kp-menu-label]::before {
        font-family: var(--theme-font-body);
        font-weight: 600;
        letter-spacing: normal;
        text-transform: none;
    }

    /* ── 9 · Tones, the live change (G8, G9) ───────────────────────────── */

    /* A change is a small sticker on the tone's own plate and ink, with its
       own flat peel. */
    [data-theme='pastel'] .kp-kpi__delta[data-kp-tone] {
        padding: 0.05rem 0.5rem;
        border-radius: var(--kp-sig-pa-r-ctl);
        font-weight: 700;
    }

    [data-theme='pastel'] .kp-kpi__delta[data-kp-tone='good'] {
        background: var(--success);
        color: var(--success-foreground);
        box-shadow: 0 2px 0 var(--success-foreground);
    }

    [data-theme='pastel'] .kp-kpi__delta[data-kp-tone='bad'] {
        background: hsl(from var(--destructive) h s 94%);
        color: var(--destructive);
        box-shadow: 0 2px 0 var(--destructive);
    }

    /* A warning or failed figure carries the note in its label, on the
       tone's plate; no edge, no bar (G5). */
    [data-theme='pastel'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) {
        box-shadow: calc(var(--kp-sig-pa-off) * var(--kp-sig-pa-dir)) var(--kp-sig-pa-off) 0 var(--kp-sig-pa-pass-c);
    }

    [data-theme='pastel'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value {
        padding-inline: 0;
        background: none;
        color: inherit;
    }

    [data-theme='pastel'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__label {
        justify-self: start;
        padding: 0.05rem 0.5rem;
        border-radius: var(--kp-sig-pa-r-ctl);
    }

    [data-theme='pastel'] .kp-kpi[data-kp-tone='warning'] .kp-kpi__label {
        background: var(--warning);
        color: var(--warning-foreground);
    }

    [data-theme='pastel'] .kp-kpi[data-kp-tone='destructive'] {
        border-color: var(--destructive);
    }

    [data-theme='pastel'] .kp-kpi[data-kp-tone='destructive'] .kp-kpi__label {
        background: hsl(from var(--destructive) h s 94%);
        color: var(--destructive);
    }

    /* A live change wobbles once round its foot, like jelly; its pass stays
       where it is (js/update.js marks it `[data-kp-updating='wobble']`). */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] [data-kp-updating='wobble'] {
            transform-origin: 50% 100%;
            animation: kp-sig-pastel-update-wobble var(--kp-sig-pa-wobble) ease-out;
        }
    }

    @keyframes kp-sig-pastel-update-wobble {
        25% {
            rotate: 10deg;
        }

        50% {
            rotate: -7deg;
        }

        75% {
            rotate: 3deg;
        }
    }

    /* ── 10 · Loading: everything becomes caterpillar (G10, b-bug-6) ──── */

    /* What waits becomes the pom-pom caterpillar itself. js/loading-pieces.js
