        --kp-action-press: 0 3px;
        --kp-action-title-weight: 700;
    }
    /* The fold: the ground where the corner lifted off, the sticker's back below the crease (the key figure's). */
    [data-theme='pastel'] .kp-action::after,
    [data-theme='pastel'] .kp-action--destructive::after {
        content: '';
        position: absolute;
        z-index: 1;
        inset: -1px -1px auto auto;
        inset-block: -1px auto;
        inset-inline: auto -1px;
        inline-size: 0.85rem;
        block-size: 0.85rem;
        border-radius: 0;
        border-start-end-radius: var(--kp-sig-pa-r-plate);
        border-end-start-radius: 0.4rem;
        background: linear-gradient(calc(225deg - 90deg * (1 - var(--kp-sig-pa-dir))), var(--kp-sig-pa-ground) 0 50%, var(--muted) 50% 100%);
        box-shadow: calc(-1px * var(--kp-sig-pa-dir)) 1px 0 hsl(from var(--border-strong) h s l / 0.7);
        scale: 0;
        transform-origin: calc(50% + 50% * var(--kp-sig-pa-dir)) 0;
        pointer-events: none;
    }
    [data-theme='pastel'] .kp-action:hover:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'], :active))::after {
        scale: 1;
    }
    [data-theme='pastel'] .kp-action:focus-visible {
        outline: 2px dashed var(--ring);
        outline-offset: 3px;
        box-shadow: var(--kp-action-shadow);
    }
    [data-theme='pastel'] .kp-action:is(:disabled, [aria-disabled='true']) {
        box-shadow: 0 3px 0 var(--border);
    }
    /* Destructive: a tone is a sticker. The title stands on the red's own plate with its own flat peel. */
    [data-theme='pastel'] .kp-action--destructive {
        --kp-action-tone-edge: var(--border-strong);
        --kp-action-tone-edge-hover: var(--border-strong);
    }
    [data-theme='pastel'] .kp-action--destructive:not(:is(:disabled, [aria-disabled='true'])) > .kp-action__title {
        justify-self: start;
        padding: 0.05rem 0.5rem;
        border-radius: var(--kp-sig-pa-r-ctl);
        background: var(--destructive);
        color: var(--destructive-foreground);
        box-shadow: 0 2px 0 hsl(from var(--destructive) h s calc(l * 0.6));
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-action {
            transition:
                translate var(--fx-duration) var(--kp-sig-pa-land),
                box-shadow var(--fx-duration) var(--kp-sig-pa-land),
                background-color var(--fx-duration) ease,
                border-color var(--fx-duration) ease;
        }
        [data-theme='pastel'] .kp-action::after {
            transition: scale var(--fx-duration) var(--kp-sig-pa-land);
        }
    }

    /* Status rows: white paper with its sky pass off register beside it, a control's corner. A failed row's reason is
       a sticker on the red's plate; an empty row is a dashed outline with no pass. Marks stand upright. */
    [data-theme='pastel'] .kp-statuslist {
        --kp-statuslist-gap: 0.75rem;
    }
    [data-theme='pastel'] .kp-statusrow {
        --kp-statusrow-radius: var(--kp-sig-pa-r-ctl);
        --kp-statusrow-edge: var(--border-strong);
        box-shadow: calc(4px * var(--kp-sig-pa-dir)) 4px 0 var(--kp-sig-pa-pass-c);
    }
    [data-theme='pastel'] .kp-statusrow[data-state='failed'] {
        --kp-statusrow-state-edge: var(--border-strong);
    }
    [data-theme='pastel'] .kp-statusrow[data-state='failed'] .kp-statusrow__detail {
        justify-self: start;
        margin-block-start: 0.2rem;
        padding: 0 0.45rem;
        border-radius: var(--kp-sig-pa-r-ctl);
        background: var(--destructive);
        color: var(--destructive-foreground);
        box-shadow: 0 2px 0 hsl(from var(--destructive) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-statusrow[data-state='empty'] {
        border-style: dashed;
        box-shadow: none;
    }

    /* Facets: entries of a list, a menu entry's corner and its mint wash. The counts on their way are pom-poms of
       the caterpillar standing in their column, the hump running down the list. */
    [data-theme='pastel'] .kp-facets {
        --kp-facet-radius: calc(var(--kp-sig-pa-r-ctl) * 0.8);
    }
    [data-theme='pastel'] .kp-facet {
        --kp-facet-hover: var(--accent);
    }
    [data-theme='pastel'] .kp-facet:hover {
        color: var(--accent-foreground);
    }
    [data-theme='pastel'] .kp-facets[aria-busy='true'] .kp-facet__count {
        border-radius: 0;
        background:
            radial-gradient(circle closest-side, var(--accent) 0 calc(100% - 0.5px), transparent 100%) 100% 50% / 1.1em 1.1em no-repeat,
            radial-gradient(circle, var(--kp-sig-pa-tape-stripe) 0.6px, transparent 1.1px) 0 0 / 3px 3px;
        -webkit-mask: radial-gradient(circle closest-side, var(--foreground) 0 calc(100% - 0.5px), transparent 100%) 100% 50% / 1.1em 1.1em no-repeat;
        mask: radial-gradient(circle closest-side, var(--foreground) 0 calc(100% - 0.5px), transparent 100%) 100% 50% / 1.1em 1.1em no-repeat;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-facets[aria-busy='true'] .kp-facet__count {
            animation: kp-sig-pastel-bug-rise calc(var(--kp-sig-pa-loop) / 2) ease-in-out infinite;
        }
        [data-theme='pastel'] .kp-facets[aria-busy='true'] li:nth-child(2) .kp-facet__count {
            animation-delay: 140ms;
        }
        [data-theme='pastel'] .kp-facets[aria-busy='true'] li:nth-child(3) .kp-facet__count {
            animation-delay: 280ms;
        }
        [data-theme='pastel'] .kp-facets[aria-busy='true'] li:nth-child(4) .kp-facet__count {
            animation-delay: 420ms;
        }
        [data-theme='pastel'] .kp-facets[aria-busy='true'] li:nth-child(n + 5) .kp-facet__count {
            animation-delay: 560ms;
        }
    }

    /* Heat grid and matrix: small stickers with a flat pass; pointing lifts a cell 2 px, a press sticks it down; the
       pin is the dashed plum line. Waiting: a heat row is one caterpillar (its cells give their place to it), a matrix
       cell is a pom-pom, the hump running along the row to the head at its end. */
    [data-theme='pastel'] :is(.kp-heat, .kp-matrix) {
        --kp-heat-cell-radius: 6px;
        --kp-heat-cell-gap: 4px;
        --kp-heat-cell-lift: calc(1.5px * var(--kp-sig-pa-dir)) 1.5px 0 var(--kp-sig-pa-pass-c);
        --kp-heat-cell-hover: translateY(-2px);
        --kp-matrix-cell-hover: translateY(-2px);
