    [data-theme='pastel'] .kp-heat__cell:active:not(.kp-skeleton, [aria-disabled='true']),
    [data-theme='pastel'] .kp-matrix__cell:active:not([data-kp-inert], [aria-disabled='true'], .kp-skeleton) {
