        box-shadow: 0 2px 0 var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-gantt__run[data-kp-state='queued'] {
        border-style: dashed;
        border-width: 1.5px;
    }
    [data-theme='pastel'] :is(.kp-gantt__run, .kp-gantt__swatch)[data-kp-state='running'] {
        border-color: var(--kp-sig-pa-peel);
        background: var(--kp-sig-pa-tape-bg);
        color: var(--accent-foreground);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-gantt__run[data-kp-state='running'] {
