    [data-theme='forest'] .kp-switch__input:checked::before {
        inset-inline-start: var(--kp-switch-inset, 0.125rem);
        border-color: var(--primary-foreground);
        background: conic-gradient(from 150deg at 50% 28%, var(--primary) 0 60deg, transparent 0), var(--primary-foreground);
        transform: translateX(calc(var(--kp-switch-width, 2.5rem) - var(--kp-switch-height, 1.5rem)));
    }

    [data-theme='forest'] .kp-field__check {
        appearance: none;
        display: inline-grid;
        place-content: center;
