    }
    [data-theme='forest'] .kp-gantt__tick:is(button):hover {
        background: var(--muted);
        color: var(--foreground);
    }
    [data-theme='forest'] .kp-gantt__tick:is(button)[aria-pressed='true'] {
        background: color-mix(in oklab, var(--primary) 16%, var(--card));
        color: var(--primary);
        box-shadow: inset 0 -2px 0 var(--primary);
    }
    [data-theme='forest'] .kp-gantt__run[data-kp-state='ok'][data-kp-series] {
