    @keyframes kp-sig-deco-meter-knock-d {
        0% {
            translate: 0 0;
        }

        30% {
            translate: 0 -3px;
        }

        60% {
            translate: 0 1px;
        }

        100% {
            translate: 0 0;
        }
    }

    @keyframes kp-sig-deco-meter-knock-o {
        0% {
            translate: 0 0;
        }

        30% {
            translate: 0 -3px;
        }

        60% {
            translate: 0 1px;
        }

