    [data-theme='deco'] :is(.kp-gantt__run, .kp-gantt__swatch)[data-kp-state='running'] {
        border-color: var(--primary);
        color: var(--foreground);
        background:
            linear-gradient(var(--primary), var(--primary)) 0 3px / 100% 1px no-repeat,
            linear-gradient(var(--primary), var(--primary)) 0 calc(100% - 3px) / 100% 1px no-repeat,
            linear-gradient(
                    90deg,
                    transparent calc(var(--kp-sig-deco-g, 1) * 140% - 48%),
                    hsl(from var(--primary) h s l / 0.35) calc(var(--kp-sig-deco-g, 1) * 140% - 30%),
                    hsl(from var(--kp-sig-deco-gold-lt) h s l / 0.85) calc(var(--kp-sig-deco-g, 1) * 140% - 8%),
                    hsl(from var(--foreground) h s 97%) calc(var(--kp-sig-deco-g, 1) * 140% - 3%),
                    transparent calc(var(--kp-sig-deco-g, 1) * 140% - 1%)
