        }
        [data-theme='deco'] :is(.kp-heat__cell, .kp-matrix__cell, .kp-week__pill, .kp-gantt__run) {
            transition:
                border-color var(--kp-sig-deco-contact, 160ms) var(--fx-ease),
                box-shadow var(--kp-sig-deco-contact, 160ms) var(--fx-ease);
        }
    }
}

/* ── The dashboard parts: what the package leaves to a register [kpadopt2-repairs] ──
   Formal keeps these parts exactly as Kenny approved them; this theme takes the three repairs the review asks for: a
   loading heat grid or matrix row as tall as its ready row (no skeleton gap between cells), an empty or failed run
   timeline with a lane-sized space for its sentence (never over the legend), the sentence as wide as its words on the
   theme's ground (never through a rule or a ghost bar), and an axis label near the end edge standing before its rule. */
@layer kp.signature {
    [data-theme='deco'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton {
        margin-block: 0;
    }
    [data-theme='deco'] .kp-gantt {
        --kp-gantt-tick-flip: 1;
    }
    [data-theme='deco'] .kp-gantt:is([data-kp-state='empty'], [data-kp-state='error']) .kp-gantt__body:not(:has(.kp-gantt__lane)) {
        min-block-size: 5.25rem;
    }
    [data-theme='deco'] .kp-gantt__state {
        box-sizing: border-box;
        display: block;
        inline-size: fit-content;
        max-inline-size: calc(100% - 2 * var(--kp-space-md, 0.75rem));
        block-size: fit-content;
        margin: auto;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--kp-gantt-state-ground, transparent);
    }
    /* The matrix's corner key breaks as two balanced lines when it has to, never leaving an arrow alone. */
    [data-theme='deco'] .kp-matrix__corner {
        text-wrap: balance;
    }
    /* A ghost bar stands where its run would, as in formal: absolute in its track, so a second ghost of one track never
       drops under the first and out of the timeline onto the legend. */
    [data-theme='deco'] .kp-gantt__ghost .kp-gantt__run.kp-skeleton {
        position: absolute;
    }
}

/* ── The six opt-in options of the dashboard adoption, round 3, in this theme [kpadopt3] ──
   The nav bar's separator, the timeline's day buttons and series runs, the week agenda's upcoming list on a phone and
   the facet swatch's identity pattern (the choice-filter value and the heat grid's End are behaviour only).
   Deco's own (themes/deco/CHARACTER.md): the separator is a gold hairline with the lozenge at its middle, the
   inlay's own mark; lying down across the phone's list the lozenge sits on the gold line. A day on the axis is ruled
   in gold under the pointer; pressed it stands on the lacquer over the inlay's double gold rule, the date in the high
   gold. A series' finished run is a double rule in its ink, as a week pill is; the upcoming list's day rule is a gold
   hairline; the facet pattern is set in a gilt frame. */
@layer kp.signature {
    [data-theme='deco'] .kp-nav__sep {
        position: relative;
        border-inline-start-color: hsl(from var(--primary) h s l / 0.6);
    }
    [data-theme='deco'] .kp-nav__sep::after {
        content: '';
        position: absolute;
        inset-block-start: calc(50% - 2.5px);
        inset-inline-start: -3px;
        inline-size: 5px;
        block-size: 5px;
        background: var(--primary);
        rotate: 45deg;
    }
    @container kp-nav (max-width: 40rem) {
        [data-theme='deco'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep {
            border-block-start-color: hsl(from var(--primary) h s l / 0.6);
        }
        [data-theme='deco'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep::after {
            inset-block-start: -3px;
            inset-inline-start: calc(50% - 2.5px);
        }
    }

    [data-theme='deco'] .kp-gantt__tick:is(button) {
        border-radius: 0;
        text-decoration: none;
    }
    [data-theme='deco'] .kp-gantt__tick:is(button):hover {
        color: var(--kp-sig-deco-gold-hi, var(--primary));
        box-shadow: inset 0 -1px 0 var(--primary);
    }
    [data-theme='deco'] .kp-gantt__tick:is(button)[aria-pressed='true'] {
        background: var(--kp-sig-deco-lac, var(--card));
        color: var(--kp-sig-deco-gold-hi, var(--primary));
        box-shadow:
            inset 0 -1px 0 var(--primary),
            inset 0 -3px 0 var(--kp-sig-deco-lac, var(--card)),
            inset 0 -4px 0 var(--primary);
    }
    [data-theme='deco'] .kp-gantt__run[data-kp-state='ok'][data-kp-series] {
        box-shadow:
            inset 0 0 0 1px var(--kp-gantt-series),
            inset 0 0 0 2px var(--kp-sig-deco-lac, var(--card));
    }
    [data-theme='deco'] .kp-week__next:not(:has(+ .kp-week__next:not([data-kp-day-start]))) {
        border-block-end-color: hsl(from var(--primary) h s l / 0.4);
    }
    [data-theme='deco'] .kp-facet__swatch[data-kp-facet-pattern] {
        border-radius: 0;
        outline: 1px solid hsl(from var(--primary) h s l / 0.75);
        outline-offset: 1px;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='deco'] .kp-gantt__tick:is(button) {
            transition:
                box-shadow var(--kp-sig-deco-contact, 160ms) var(--fx-ease),
                color var(--kp-sig-deco-contact, 160ms) var(--fx-ease);
        }
    }
}

@layer kp.register {
    /* @kp-soft/themes — css/light-register.css
   The light register, 5.0.0 [S48, LIFT_PLAN]: "Plain Sight", the concept
   demo Kenny approved on 2026-09-08. Scoped to [data-theme='light'] and
   inert elsewhere; opt-in, imported after themes.css. The demo is the
   reference for every value here — see themes/light/anatomy.md for the
   idea and the research it names (loom.com, notion.so, Aardvark Book
   Club, each independently measured in the demo's own header comment).

   The theme's whole case: restraint is a decision, not an absence of
   one. Every colour below is already the token — themes/light/tokens.json
   converts to the demo's own hex values exactly (checked, X0), so this
   file changes no token and adds no colour of its own (DI9). What it adds
   is shape, easing and one mechanism: exposure. Since 2026-10-08 (Kenny,
   research/light-character, applied in themes/light/CHARACTER.md §4) light
   does one thing: a part is a glare first, blurred and too bright, and
   comes down into focus and into its own white; what leaves goes back into
   the glare; a waiting surface stands out of focus and its exposure
   breathes. Nothing slides, nothing grows, nothing is drawn. Every one-shot
   motion eases on the settle (`--kp-ease-arrive`, cubic-bezier(0.16, 1,
   0.3, 1)) and every close on its inverse (`--kp-ease-leave`); contact is
   200 ms (`--fx-duration`), an exposure 700 ms, a group 120 ms apart, a loop
   3600 ms (tokens `--kp-sig-light-*` in kp.signature below).

   The two radius vocabularies the demo measured (a small surface radius
   for cards/inputs/the dialog, a full pill for buttons/chips) are already
   how css/components.css reads `--radius` and `--kp-radius-pill` — this
   file only asks the button and the icon button to use the pill, since
   the base layer defaults a button to the surface radius. Everything
   else keeps the base layer's shape.

   Elevation, answered once, everywhere it recurs: card, popover, dialog,
   menu, toast, tooltip, confirm, the datepicker/combobox/palette panels
   and the theme menu are all pure white on a pure white page (DI6: card
   and popover are both `--card`/`--popover` = white), so the base layer's
   border-only treatment leaves them looking like a page with no surfaces
   at all. The three shadow steps below are the demo's own three (the
   card's 1px/2px wash, the dropdown's 8px/24px, the dialog's 20px/48px),
   each a relative colour of `--foreground` (DI9) at the demo's own alpha. */

    [data-theme='light'] {
        /* The configuration surface [AR43], the demo's own values as
       defaults: the lede's two marks stagger 620ms then +160ms, exactly
       as the demo's `animation-delay`s read; the dossier's three
       redactions stagger 140ms apart, exactly as the demo's script did. */
        --kp-classified-delay: 620ms;
        --kp-reveal-stagger: 160ms;
        --kp-redact-stagger: 140ms;
        /* Two eases, measured separately in the demo's own header: a
       confident settle for arrivals (notion.so, four uses in the
       fetched chunks) and a quicker curve for hover/active (loom.com's
       own micro-interaction curve). Since 2026-10-08 the second is the
       first: light has one curve, the settle, and it is also --fx-ease
       (css/themes.css). */
        --kp-ease-arrive: cubic-bezier(0.16, 1, 0.3, 1);
        /* The same curve turned round (the control points reflected through
       the middle): what a close eases on, so that an arrival, which plays
       a close backwards, settles on --kp-ease-arrive. */
        --kp-ease-leave: cubic-bezier(0.7, 0, 0.84, 0);
        --kp-ease-hover: var(--kp-ease-arrive);
        /* The demo's three shadow steps, each a relative colour of
       --foreground (DI9) at the demo's own measured alpha. */
        --kp-shadow-sm: 0 1px 2px hsl(from var(--foreground) h s l / 0.06);
        --kp-shadow-md: 0 8px 24px hsl(from var(--foreground) h s l / 0.12);
        --kp-shadow-lg: 0 20px 48px hsl(from var(--foreground) h s l / 0.22);
        /* White on white, told apart by these three shadows and the seam, and
       nothing else [G7; Kenny, 2026-10-08, question 7]: no texture. The base
       layer paints none for this theme either (its blueprint grid, T6, is gone). */
        --fx-texture: none;
        --fx-texture-opacity: 0;
        /* The reveals this theme performs [S45]: js/effects.js reads
       these and leaves a theme that declares none at rest. `clip` is
       new — see js/effects.js's `clip` branch and TIMINGS['kp-clip-reveal']
       — because none of the six existing headline routines keep the text
       whole while opening a shape around it. */
        --kp-reveal-headline: clip;
        --kp-reveal-emphasis: sweep;
        --kp-reveal-rule: draw;
    }

    /* ── Type: one face, two weights [G18; Kenny, 2026-10-08, question 18] ──
       Instrument Sans for everything: headings 600 tracked -0.01em, figures
       600 with tabular numerals, labels 500 at 0.8125rem, prose 400.
       Monospace only for identifiers and timestamps; no display face and no
       small capitals. */

    [data-theme='light'] h1,
    [data-theme='light'] h2,
    [data-theme='light'] h3,
    [data-theme='light'] h4 {
        font-weight: 600;
        letter-spacing: -0.01em;
    }

    [data-theme='light'] :is(.kp-field__label, .kp-badge, .kp-tag) {
        font-weight: 500;
    }

    [data-theme='light'] .kp-kpi__label {
        font-weight: 500;
    }

    [data-theme='light'] .kp-numeric,
    [data-theme='light'] .kp-kpi__value,
    [data-theme='light'] .kp-calendar__num {
        font-variant-numeric: tabular-nums;
    }

    /* ── The hooks [S45]: the headline, the mark, the rule, the divider ── */

    /* The headline comes into focus where it stands, once: a glare first,
       blurred and too bright, then its own white and crisp (G2, G13; Kenny,
       2026-10-08). The register's rounded clip window is retired. The text
       itself never changes — no noise, no per-word stagger, no dither —
       which is the one thing every other headline routine in the package
       does and this one deliberately does not [anatomy: "no ornament"]. */
    [data-theme='light'] [data-kp-reveal='headline'] {
        filter: none;
        opacity: 1;
    }

    [data-theme='light'][data-kp-effects] [data-kp-reveal='headline']:not(.is-deciphered) {
        filter: var(--kp-sig-light-glare, blur(5px) brightness(1.6));
        opacity: 0;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] [data-kp-reveal='headline'].is-revealing {
            animation: kp-clip-reveal var(--kp-sig-light-time, 700ms) var(--kp-ease-arrive) both;
        }
    }

    /* The rule is there from the start and comes into focus with its
       heading: it is not drawn (G2). */
    [data-theme='light'] [data-kp-reveal='rule'] {
        position: relative;
        padding-block-end: var(--kp-space-sm, 0.5rem);
        margin-block-end: var(--kp-space-sm, 0.5rem);
    }

    [data-theme='light'] [data-kp-reveal='rule']::after {
        content: '';
        position: absolute;
        inset-inline-start: 0;
        inset-block-end: 0;
        block-size: 2px;
        inline-size: 3rem;
        background: var(--primary);
    }

    [data-theme='light'][data-kp-effects] [data-kp-reveal='rule']:not(.is-in)::after {
        filter: var(--kp-sig-light-glare, blur(5px) brightness(1.6));
        opacity: 0;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] [data-kp-reveal='rule'].is-in::after {
            animation: kp-sig-light-expose var(--kp-sig-light-time, 700ms) var(--kp-ease-arrive) backwards;
        }
    }

    /* The mark: base/soft pairing as the emphasis mechanism (TH115/S47),
       a highlighter ground rather than a plate — the demo's own reasoning
       for why (a fragmented inline box's clip-path drops content on a
       wrapped line, confirmed at 320px in the demo's own verification
       pass). Since 2026-10-08 the highlight is not swept across: the phrase
       takes its ground at once and comes into focus out of the glare
       (G2). Loose marks (the lede) clear on load, staggered by the module
       itself through --kp-classified-delay and --kp-reveal-stagger above
       — no CSS stagger needed here. */
    /* Marks partition into two mutually exclusive groups by ancestry —
       a loose mark (the lede) and one inside a `[data-kp-reveal='emphasis']`
       container (the dossier) — rather than fighting over specificity: a
       CSS animation (below) always outranks a normal declaration
       regardless of how specific it is, so the two groups have to be
       selector-exclusive or the sweep's own end colour leaks into the
       dossier's redaction. */
    [data-theme='light'] mark:not([data-kp-reveal='emphasis'] mark) {
        background-image: linear-gradient(var(--accent), var(--accent));
        background-repeat: no-repeat;
        background-position: 0 0;
        background-size: 100% 100%;
        color: var(--accent-foreground);
        padding: 0 0.2em;
        border-radius: 0.25em;
        box-decoration-break: clone;
        -webkit-box-decoration-break: clone;
    }

    [data-theme='light'][data-kp-effects] mark:not(.is-cleared):not([data-kp-reveal='emphasis'] mark) {
        background-size: 0% 100%;
        color: var(--foreground);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'][data-kp-effects] mark.is-cleared:not([data-kp-reveal='emphasis'] mark) {
            animation: kp-mark-sweep var(--kp-sig-light-time, 700ms) var(--kp-ease-arrive) both;
        }
    }

    /* The dossier's marks are a different mechanism from the lede's — an
       opaque bar that clears, not a highlighter (the demo's own
       `.kp-redaction`, translated onto <mark> so the package's trigger
       wiring [data-kp-reveal-trigger] can drive it; see anatomy's closing
       section). The trigger toggles every mark's `.is-cleared` in the
       same tick (js/effects.js `wireTrigger`), so the demo's 140ms stagger
       is reproduced here as a `transition-delay` per mark instead of a
       per-mark `setTimeout` — same visible result, one clock instead of
       three. */
    [data-theme='light'] [data-kp-reveal='emphasis'] mark {
        display: inline-block;
        border-radius: 0.2em;
        padding: 0 0.1em;
        background: var(--foreground);
        color: transparent;
    }

    [data-theme='light'] [data-kp-reveal='emphasis'] mark.is-cleared {
        background: var(--accent);
        color: var(--foreground);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] [data-kp-reveal='emphasis'] mark {
            transition:
                background-color var(--fx-duration, 200ms) var(--kp-ease-hover),
                color var(--fx-duration, 200ms) var(--kp-ease-hover);
        }

        [data-theme='light'] [data-kp-reveal='emphasis'] mark.is-cleared:nth-of-type(2) {
            transition-delay: var(--kp-redact-stagger);
        }

        [data-theme='light'] [data-kp-reveal='emphasis'] mark.is-cleared:nth-of-type(3) {
            transition-delay: calc(2 * var(--kp-redact-stagger));
        }
    }

    /* The divider: a seam, not a tear — the demo's own words. A hairline
       with a small circle sitting on it; the alt divider tints the circle
       with the accent/signal pair (TH115/S47), the one place this theme
       uses the saturated companion at all. */
    [data-theme='light'] [data-kp-divider] {
        position: relative;
        display: block;
        block-size: 1px;
        background: var(--border);
        margin-block: var(--kp-space-2xl, 2rem);
    }

    [data-theme='light'] [data-kp-divider]::after {
        content: '';
        position: absolute;
        inset-inline-start: 50%;
        inset-block-start: 50%;
        transform: translate(-50%, -50%);
        inline-size: 2.75rem;
        block-size: 2.75rem;
        border-radius: var(--kp-radius-pill, 999px);
        background: var(--background);
        border: 1px solid var(--border-strong);
    }

    [data-theme='light'] [data-kp-divider='alt']::after {
        background: var(--accent);
        border-color: var(--fx-signal);
    }

    /* ── Navbar: a hairline strip, the dropdown answered [KT14] ────────── */

    [data-theme='light'] .kp-nav-wrap {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='light'] .kp-nav__brand {
        font-weight: 600;
        letter-spacing: -0.02em;
    }

    /* The bar's links carry no indigo (Kenny, 2026-09-15,
       navigation#bar-collapsed: "I don't like the blue in the navbar for
       the links"). Before, every link read in --link, which this theme
       derives from --primary, and took --primary again on hover, focus and
       the current page — one indigo for four states. Now the resting link
       is the slate muted ink, and pointing at it, focusing it or being on
       its page brings it up to the full ink; the current page keeps the
       base layer's weight and thick underline besides [DI4]. Since Kenny's
       second note ("Ook daar weg", and on navigation#app-shell "blauw moet
       uit navbar", 2026-09-15 [scope-93]) the indigo has left the call to
       action and the side navigation too: no part of a navigation in this
       theme computes to --primary or --link at rest, under the pointer or
       as the current page. */
    [data-theme='light'] .kp-nav__link {
        border-radius: var(--radius, 0.5rem);
        color: var(--muted-foreground);
    }

    [data-theme='light'] .kp-nav__link:hover,
    [data-theme='light'] .kp-nav__link:focus-visible,
    [data-theme='light'] .kp-nav__link[aria-current] {
        color: var(--foreground);
        background: none;
    }

    [data-theme='light'] .kp-nav__link--lang {
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        font-weight: 500;
    }

    /* The call to action, without the indigo [scope-93]: a pill drawn in
       the full ink — a one-and-a-half-pixel ring painted inside the box, so
       the bar's height and the link's baseline stay what they were — which
       fills with the ink under the pointer or the focus. Before, an indigo
       plate (--primary) that turned to the ink on hover. The ring is a
       shadow rather than a border: a border would add to the box. */
    [data-theme='light'] .kp-nav__link--cta {
        background: none;
        color: var(--foreground);
        box-shadow: inset 0 0 0 1.5px var(--foreground);
        font-weight: 600;
        border-radius: var(--kp-radius-pill, 999px);
        padding-inline: var(--kp-space-lg, 1rem);
    }

    [data-theme='light'] .kp-nav__link--cta:hover,
    [data-theme='light'] .kp-nav__link--cta:focus-visible {
        background: var(--foreground);
        color: var(--background);
    }

    /* The ring above replaced the package's focus shadow (_rules.css) in a
       later layer; the focus ring is composed in front of it again. */
    [data-theme='light'] .kp-nav__link--cta:focus-visible {
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            inset 0 0 0 1.5px var(--foreground);
    }

    /* The dropdown [KT14]: the demo's own panel — white, a strong hairline,
       the dropdown shadow step, a plain hover wash. */
    [data-theme='light'] .kp-nav__menu {
        border-radius: var(--radius, 0.5rem);
        box-shadow: var(--kp-shadow-md);
    }

    /* Collapsed, the dropdown is a list in the flow, not a panel [gap-12]:
       the rule above dresses the floating panel in kp.register, which
       beats the reset in kp.components, so the reset is restated here. */
    @container kp-nav (max-width: 40rem) {
        [data-theme='light'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__menu {
            min-width: 0;
            padding-inline-start: var(--kp-nav-menu-indent, 1rem);
            border: 0;
            background: transparent;
            box-shadow: none;
        }
    }

    /* A dropdown's and a mega menu's links in the full ink, not the indigo
       --link, for the same note as the bar's links; the hover wash is what
       marks the one pointed at. */
    [data-theme='light'] .kp-nav__menu a {
        color: var(--foreground);
    }

    [data-theme='light'] .kp-nav__menu a:hover,
    [data-theme='light'] .kp-nav__menu a:focus-visible {
        background: var(--muted);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] .kp-nav__link,
        [data-theme='light'] .kp-nav__menu {
            transition-timing-function: var(--kp-ease-hover);
        }
    }

    /* ── Buttons: the pill half of the radius vocabulary ───────────────── */

    [data-theme='light'] .kp-button,
    [data-theme='light'] .kp-icon-button {
        border-radius: var(--kp-radius-pill, 999px);
    }

    /* On an alert the close button sits on the alert's own plate, in the
       alert's ink, the way it does on a toast [fix-95]. */
    [data-theme='light'] .kp-alert .kp-icon-button {
        background: transparent;
        border-color: transparent;
        color: inherit;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] .kp-button {
            transition-timing-function: var(--kp-ease-hover);
        }
    }

    /* ── Fields: the small radius half, kept plain ──────────────────────── */

    [data-theme='light'] .kp-field__input {
        background: var(--background);
    }

    [data-theme='light'] .kp-fieldset {
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
    }

    [data-theme='light'] .kp-switch__input:not(:checked) {
        background: var(--background);
    }

    /* ── Card / dossier ──────────────────────────────────────────────────── */

    [data-theme='light'] .kp-card {
        box-shadow: var(--kp-shadow-sm);
    }

    /* ── Elevated panels: card and popover are both pure white (DI6), so
       elevation has to come from the border and the shadow — the anatomy
       names this as a real constraint, not an oversight. One answer for
       every panel that floats over the page. ────────────────────────── */
    [data-theme='light'] .kp-popover,
    [data-theme='light'] .kp-menu,
    [data-theme='light'] .kp-toast,
    [data-theme='light'] .kp-tooltip,
    [data-theme='light'] .kp-datepicker__panel,
    [data-theme='light'] .kp-combobox__list,
    [data-theme='light'] .kp-palette,
    [data-theme='light'] .kp-theme-menu__list {
        box-shadow: var(--kp-shadow-md);
    }

    /* One panel, one shadow [G7]: a menu inside a popover is the same panel as
       the popover, which already casts the medium shadow (the register gave
       both, so a menu cast two). */
    [data-theme='light'] .kp-popover > .kp-menu {
        box-shadow: none;
    }

    /* The wrapper round the theme picker's icon button is not a card: only its
       dropdown list is. */
    [data-theme='light'] .kp-theme-menu {
        background: none;
        border: 0;
        box-shadow: none;
    }

    /* Severity toasts [scope-60]. The plain toast above is repainted here in
       a later layer than kp.components, which swallowed every variant's
       plate; each is restated on the alert's token pair, as the severity
       badge wears it. */
    [data-theme='light'] .kp-toast--success {
        background: var(--success);
        color: var(--success-foreground);
        border-color: var(--success);
    }

    [data-theme='light'] .kp-toast--info {
        background: var(--info);
        color: var(--info-foreground);
        border-color: var(--info);
    }

    [data-theme='light'] .kp-toast--warning {
        background: var(--warning);
        color: var(--warning-foreground);
        border-color: var(--warning);
    }

    [data-theme='light'] .kp-toast--destructive,
    [data-theme='light'] .kp-toast--error {
        background: var(--destructive);
        color: var(--destructive-foreground);
        border-color: var(--destructive);
    }

    [data-theme='light']
        :is(.kp-toast--success, .kp-toast--info, .kp-toast--warning, .kp-toast--destructive, .kp-toast--error)
        :is(.kp-button--ghost, .kp-icon-button) {
        color: inherit;
    }

    /* A button hovered on a toast takes a shade of the toast's own plate
       (--kp-toast-button-hover, set in kp.components), not this theme's page hover (Kenny's second nostromo pass,
       2026-09-13). Restated here because this layer repaints the hover. */
    [data-theme='light'] .kp-toast :is(.kp-button--ghost, .kp-icon-button):hover:not(:disabled) {
        background: var(--kp-toast-button-hover);
        color: inherit;
    }

    [data-theme='light'] .kp-menu__item:hover {
        background: var(--muted);
    }

    /* ── Badges, tags, status ────────────────────────────────────────────── */

    [data-theme='light'] .kp-badge,
    [data-theme='light'] .kp-tag {
        border: 1px solid var(--border);
    }

    /* The plain alert only [gap-1, Kenny 2026-09-10]. This rule used to
       repaint the ground of EVERY alert, and `kp.register` is a later layer
       than `kp.components`, so it beat `.kp-alert--destructive`'s own plate
       while that variant's ink — `--destructive-foreground`, which is drawn
       to sit ON the plate — stayed. Measured in firefox on 2026-09-12:
       seventeen of the twenty-two themes carried a destructive alert whose
       text was unreadable, grotesk at 1.00 exactly, white on white.

       Kenny saw it in chassis-rs and said to write it down and touch
       nothing; this is the round he asked for it in. Same shape as fix-12,
       one property over: a register overriding half of a pair the base
       layer defines together. */
    [data-theme='light'] .kp-alert:not([class*='kp-alert--']) {
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        background: var(--muted);
    }

    /* The info plate's own ink read 4.51:1; a twentieth of the page's text
       in it reads 4.79 [alert-contrast-M1]. The band's items are left
       alone: they keep the page's text on a soft tint. */
    [data-theme='light'] .kp-alert--info:not(.kp-attention__item) {
        color: color-mix(in oklab, var(--info-foreground) 95%, var(--foreground));
    }

    [data-theme='light'] .kp-health__dot {
        border-radius: var(--kp-radius-pill, 999px);
    }

    /* ── Loading and empty states ────────────────────────────────────────── */

    [data-theme='light'] .kp-skeleton {
        background: var(--muted);
    }

    [data-theme='light'] .kp-spinner {
        border-color: var(--border);
        border-top-color: var(--primary);
    }

    [data-theme='light'] .kp-error {
        color: var(--destructive);
    }

    /* ── Text shapes: identifiers in the mono face ──────────────────────── */

    [data-theme='light'] .kp-id,
    [data-theme='light'] .kp-url,
    [data-theme='light'] .kp-timestamp,
    [data-theme='light'] .kp-masked,
    [data-theme='light'] .kp-copyable,
    [data-theme='light'] .kp-truncate,
    [data-theme='light'] .kp-cell-break,
    [data-theme='light'] .kp-cell-truncate {
        font-family: var(--theme-font-mono);
        font-size: 0.9em;
    }

    [data-theme='light'] .kp-copyable__button {
        border-radius: var(--kp-radius-pill, 999px);
    }

    /* The copy button's two states win over this register's own button
       rules [gap-12]: those paint in kp.register, which beats the states
       in kp.components, so copied lost its success plate and a refused
       copy looked idle. Restated token for token. */
    [data-theme='light'] .kp-copyable .kp-copyable__button[data-kp-copied] {
        border-color: var(--success);
        color: var(--success-foreground);
        background: var(--success);
    }

    [data-theme='light'] .kp-copyable .kp-copyable__button[data-kp-copy-failed] {
        border-color: var(--destructive);
        border-style: dashed;
        color: var(--destructive);
    }

    /* ── Data: tables, timelines, trees ─────────────────────────────────── */

    [data-theme='light'] .kp-table th {
        background: var(--muted);
        /* The reach above a sticky header paints this ground too [fix-32]. */
        --kp-datatable-head-ground: var(--muted);
        font-weight: 600;
    }

    [data-theme='light'] .kp-table td {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='light'] .kp-datatable {
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
    }

    [data-theme='light'] .kp-datatable__bar {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='light'] .kp-diff {
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
    }

    [data-theme='light'] .kp-diff__line,
    [data-theme='light'] .kp-diff__hunk {
        font-family: var(--theme-font-mono);
        font-size: 0.9em;
    }

    /* The added line's wash (Kenny, 2026-09-15, data#diff: "the plus colour
       isn't distinct enough from the background"). This theme's --success is
       a pale ground (88% lightness), so the shared 14% wash of it came out at
       ΔE 0.75 from the diff's ground — invisible — while the removed line,
       washed from the saturated --destructive, sat at ΔE 6.6. The added line
       now washes from the saturated green ink instead, at the strength that
       matches the removed line: ΔE 6.7, with the muted line numbers still
       above 4.5:1 on it. */
    [data-theme='light'] .kp-diff__line[data-kind='added'] {
        background: hsl(from var(--success-foreground) h s l / 0.14);
    }

    /* The step list is soft daylight cards, lifted a hair off the page. */
    [data-theme='light'] .kp-steplist {
        --kp-steplist-gap: 0.625rem;
    }

    [data-theme='light'] .kp-steplist__item {
        border-radius: calc(var(--radius) * 1.25);
        box-shadow: 0 1px 2px hsl(from var(--foreground) h s l / 0.06);
    }

    [data-theme='light'] .kp-timeline {
        border-inline-start: 2px solid var(--border);
    }

    [data-theme='light'] .kp-timeline__marker {
        background: var(--primary);
        border-radius: var(--kp-radius-pill, 999px);
    }

    [data-theme='light'] .kp-tree {
        font-family: var(--theme-font-mono);
        font-size: 0.9em;
    }

    /* A branch's children are kept drawn while they glide shut
       (js/motion.js glideGroup(), lesson 26): the state is already
       `aria-expanded="false"` while the glide plays. */
    [data-theme='light'] .kp-tree [role='treeitem'][aria-expanded='false'] > [role='group'][data-kp-group-folding],
    [data-theme='light'] .kp-tree [role='treeitem'][aria-expanded='false'] + [role='group'][data-kp-group-folding] {
        display: block;
    }

    /* The accordion [gap-12]: quiet at rest; open takes the primary ink. */
    [data-theme='light'] .kp-accordion__summary::marker {
        color: var(--muted-foreground);
    }

    [data-theme='light'] .kp-accordion__item[open] > .kp-accordion__summary {
        color: var(--primary);
    }

    [data-theme='light'] .kp-reorder {
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
    }

    /* ── Navigation and steps ────────────────────────────────────────────── */

    [data-theme='light'] .kp-tab[aria-selected='true'] {
        color: var(--primary);
        border-bottom: 2px solid var(--primary);
    }

    /* The trails' size is the package's [scope-87]; their numerals are this
       register's: tabular, so page numbers and file numbers line up. */
    [data-theme='light'] .kp-breadcrumb,
    [data-theme='light'] .kp-pagination {
        font-variant-numeric: tabular-nums;
    }

    /* The breadcrumb in the bar's scheme, not the indigo --link (Kenny,
       2026-09-15, navigation#app-shell [scope-94]): a crumb rests in the
       slate muted ink — a visited one too — and pointing at it or focusing
       it brings it up to the full ink, as the bar's links do since
       scope-92 and scope-93. The page you are on is in the full ink with
       the weight and the absent underline it already had, so it is marked
       by more than a colour [DI4]. */
    [data-theme='light'] .kp-breadcrumb a,
    [data-theme='light'] .kp-breadcrumb a:visited {
        color: var(--muted-foreground);
    }

    [data-theme='light'] .kp-breadcrumb a:hover,
    [data-theme='light'] .kp-breadcrumb a:focus-visible,
    [data-theme='light'] .kp-breadcrumb [aria-current] {
        color: var(--foreground);
    }

    [data-theme='light'] .kp-pagination [aria-current] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: var(--kp-radius-pill, 999px);
    }

    [data-theme='light'] .kp-wizard {
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
    }

    [data-theme='light'] .kp-wizard__steps {
        font-size: var(--kp-text-sm, 0.8125rem);
        font-weight: 500;
    }

    /* ── Pickers ─────────────────────────────────────────────────────────── */

    [data-theme='light'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: var(--kp-radius-pill, 999px);
    }

    [data-theme='light'] .kp-colorpicker__swatch {
        border: 1px solid var(--border-strong);
        border-radius: 0.4rem;
    }

    [data-theme='light'] .kp-shortcuts__row kbd {
        border: 1px solid var(--border-strong);
        border-radius: var(--radius, 0.5rem);
        background: var(--card);
        font-family: var(--theme-font-mono);
    }

    [data-theme='light'] .kp-combobox__status,
    [data-theme='light'] .kp-palette__status,
    [data-theme='light'] .kp-theme-menu__status {
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    /* ── The roots the rules above reach only by their parts ───────────── */

    [data-theme='light'] .kp-form {
        gap: var(--kp-space-lg, 1rem);
    }

    [data-theme='light'] .kp-field {
        gap: var(--kp-space-xs, 0.25rem);
    }

    /* Roots only their parts carry a rule above: a bare, undecorated
       declaration is still an answer (subject roots read the selector's
       last compound, and a `__`-suffixed one names an element, not the
       root — gates/selectors.mjs `subjectRoots`). */
    [data-theme='light'] .kp-nav {
        gap: var(--kp-space-xl, 1.5rem);
    }

    [data-theme='light'] .kp-table {
        border-collapse: separate;
        border-spacing: 0;
    }

    [data-theme='light'] .kp-health {
        gap: var(--kp-space-xs, 0.25rem);
    }

    [data-theme='light'] .kp-laurels {
        gap: var(--kp-space-xl, 1.5rem);
    }

    [data-theme='light'] .kp-grid,
    [data-theme='light'] .kp-split {
        gap: var(--kp-space-md, 0.75rem);
    }

    [data-theme='light'] .kp-combobox,
    [data-theme='light'] .kp-datepicker,
    [data-theme='light'] .kp-colorpicker,
    [data-theme='light'] .kp-shortcuts {
        border-radius: var(--radius, 0.5rem);
    }

    [data-theme='light'] .kp-grid__tile,
    [data-theme='light'] .kp-split__pane {
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
    }

    [data-theme='light'] .kp-split__separator {
        background: var(--border);
    }

    [data-theme='light'] .kp-toasts {
        gap: var(--kp-space-sm, 0.5rem);
    }

    [data-theme='light'] .kp-confirm {
        box-shadow: var(--kp-shadow-lg);
    }

    /* ── The demo's own pieces [S46] ─────────────────────────────────────── */

    [data-theme='light'] .kp-side-note {
        font-size: var(--kp-text-sm, 0.8125rem);
        font-weight: 500;
        color: var(--muted-foreground);
    }

    [data-theme='light'] .kp-laurels li {
        border-inline-start: 2px solid var(--fx-signal);
        padding-inline-start: var(--kp-space-sm, 0.5rem);
    }

    [data-theme='light'] .kp-laurels b {
        display: block;
        color: var(--foreground);
        font-size: var(--kp-text-md, 1rem);
        font-weight: 600;
    }

    [data-theme='light'] .kp-lede {
        max-width: 42rem;
        font-size: 1.0625rem;
    }

    [data-theme='light'] .kp-platforms {
        font-size: var(--kp-text-sm, 0.8125rem);
        font-weight: 500;
        color: var(--muted-foreground);
    }

    [data-theme='light'] .kp-spec {
        background: var(--muted);
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
    }

    [data-theme='light'] .kp-spec dt {
        font-size: var(--kp-text-sm, 0.8125rem);
        font-weight: 500;
        color: var(--muted-foreground);
    }

    /* The log wears what this register already decided for its other data
 * surface, `.kp-spec` — the same ground, the same edge, the same face
 * [gap-14]. A new component that invents a look of its own is a
 * twenty-third decision nobody made. */
    [data-theme='light'] .kp-log {
        background: var(--muted);
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
    }

    [data-theme='light'] .kp-log__level {
        font-family: var(--theme-font-mono);
        font-size: var(--kp-text-xs, 0.75rem);
        --kp-log-level-ink: var(--muted-foreground);
    }

    [data-theme='light'] .kp-spec__swatch {
        border: 1px solid var(--border-strong);
        border-radius: 0.4rem;
    }

    [data-theme='light'] .kp-spec__font {
        font-family: var(--theme-font-display);
    }

    /* ── Footer ──────────────────────────────────────────────────────────── */

    [data-theme='light'] .kp-footer {
        background: var(--muted);
    }

    [data-theme='light'] .kp-footer a:hover,
    [data-theme='light'] .kp-footer a:focus-visible {
        color: var(--primary);
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────────── */

    /* kp-mark-sweep animates a filter, not opacity — an inline phrase coming
       into focus, once; documented in gates/check-motion.mjs's
       OUT_OF_SCOPE. kp-clip-reveal carries a row in TIMINGS
       (js/effects.js). */
    @keyframes kp-clip-reveal {
        0% {
            filter: var(--kp-sig-light-glare, blur(5px) brightness(1.6));
            opacity: 0;
        }

        60% {
            opacity: 1;
        }

        100% {
            filter: none;
            opacity: 1;
        }
    }

    @keyframes kp-mark-sweep {
        0% {
            filter: var(--kp-sig-light-glare, blur(5px) brightness(1.6));
        }

        100% {
            filter: none;
        }
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — a grey row with air between the items. */
    [data-theme='light'] .kp-marquee {
        border-block: 1px solid var(--border);
        color: var(--muted-foreground);
        --kp-marquee: 55000ms;
        --kp-marquee-gap: 2.5rem;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    /* A mega menu's group headings speak in the caption's voice [scope-48]. */
    [data-theme='light'] .kp-nav__menu[data-kp-menu-label]::before,
    [data-theme='light'] .kp-nav__menu--wide .kp-nav__menu-heading {
        text-transform: none;
        letter-spacing: 0;
        border-block-end: 0;
        padding-block-end: 0;
    }

    /* ── The side navigation [feat-nav-3] ────────────────────────────
       Kenny asked for this one to stay simple, so it does: the row you
       are on is named in the full ink and carries a short rule at its
       leading edge. Nothing else changes. */
    [data-theme='light'] .kp-sidenav {
        --kp-sidenav-surface: var(--card);
    }

    [data-theme='light'] .kp-sidenav__link,
    [data-theme='light'] .kp-sidenav__category-toggle {
        border-inline-start: 2px solid transparent;
    }

    /* The current row in the full ink with its leading rule in the same
       ink, not the indigo (Kenny, 2026-09-15, navigation#app-shell: "blauw
       moet uit navbar" [scope-93]); the base layer's weight stays, so the
       row is marked by the rule and the weight, never by a colour alone
       [DI4]. */
    [data-theme='light'] .kp-sidenav__link[aria-current='page'] {
        color: var(--foreground);
        background: none;
        border-inline-start-color: var(--foreground);
    }

    /* ── Back to top, and a picture [feat-page-1, feat-media-1] ──────
       Simple, as Kenny asked: a hairline and a muted caption. */
    [data-theme='light'] .kp-to-top {
        box-shadow: 0 1px 3px hsl(from var(--foreground) h s l / 0.14);
    }

    [data-theme='light'] .kp-media {
        border: 1px solid var(--border);
    }

    [data-theme='light'] .kp-media-figure > figcaption {
        color: var(--muted-foreground);
    }

    /* The figure carries the caption's voice, so the decision sits with
       the picture rather than with the words under it. */
    [data-theme='light'] .kp-media-figure {
        color: var(--muted-foreground);
    }

    /* ── Pointing, focusing, pressing: light's own manners [G14–G17;
       Kenny, 2026-10-08, research/light-character questions 14 to 17] ─────
       The shade tightens [gap-4, approved 2026-09-12]: the only one of the
       six with no world of its own to draw on. Light is the plain light
       theme, and that is deliberate — there is no era, no material and no
       instrument to quote. So physics rather than ornament: the control
       floats above the paper and settles toward it when touched, which makes
       its shadow shorter and harder. Measured in firefox 2026-09-12: the
       blur goes from 14px to 5, the control settles 2px, label contrast
       11.74, the box unchanged.

       Since 2026-10-08 these manners are every pointed-at part's, wherever it
       stands (a header, a menu, a tile, a drawer, a tour, a toast): the
       button and the icon button settle 2px and their shadow tightens; a
       menu entry takes the muted wash; a key figure that is a link, a
       calendar day and a tile settle with the softer shadow of a card; a
       press lands the part flat (shadow gone, 2px down) and flashes it, the
       shutter (brightness 1.25 for the contact), then it stands crisp in its
       pressed ground; focus is DI2's two-channel ring and wins over the
       pointer when both apply. One order everywhere: pointer, focus, press. */
    /* Phase 7, `focus-ring`: two shadow layers at rest, the first empty.
       This theme transitions box-shadow, and a one-layer-to-two-layer
       transition interpolates by inserting a blank layer — so mid-flight
       the ring reads as a nought-spread layer, which is exactly "half a
       ring". Same shape in both states means the transition is a spread
       growing from nought to two rather than a layer arriving from
       nowhere. */
    [data-theme='light'] .kp-button {
        box-shadow:
            0 0 0 0 transparent,
            0 6px 14px hsl(from var(--foreground) h s l / 0.12);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] :is(.kp-button, .kp-icon-button) {
            transition:
                box-shadow var(--fx-duration, 200ms) var(--fx-ease, ease),
                translate var(--fx-duration, 200ms) var(--fx-ease, ease),
                background-color var(--fx-duration, 200ms) var(--fx-ease, ease),
                border-color var(--fx-duration, 200ms) var(--fx-ease, ease),
                color var(--fx-duration, 200ms) var(--fx-ease, ease);
        }
    }

    [data-theme='light'] :is(.kp-button, .kp-icon-button):hover:not(:disabled) {
        translate: 0 2px;
    }

    [data-theme='light'] .kp-button:hover:not(:disabled) {
        box-shadow:
            0 0 0 0 transparent,
            0 2px 5px hsl(from var(--foreground) h s l / 0.2);
    }

    /* Focus wins over the pointer: it sits after the pointer's rule at the
       same weight. The ring is DI2's two channels (the outline the outer, the
       shadow the inner), kept in front of the settled shadow; the outline in
       the contrast colour so the two are not one colour twice. Third face of
       `fix-12` and `gap-1`: a later layer beating a state the earlier layer
       defines. */
    [data-theme='light'] :is(.kp-button, .kp-icon-button):focus-visible:not(:disabled) {
        translate: 0 2px;
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring-contrast);
        outline-offset: var(--kp-focus-ring-inner-width, 2px);
        box-shadow: 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring);
    }

    [data-theme='light'] .kp-button:focus-visible:not(:disabled) {
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            0 2px 5px hsl(from var(--foreground) h s l / 0.2);
    }

    /* A press lands the pill flat and flashes it: translate 2px, the shadow
       gone, brightness for the contact, then crisp in the pressed ground the
       components layer paints (--secondary-active and its kin). Kept after
       focus, so a key pressed on a focused button keeps its ring. */
    [data-theme='light'] :is(.kp-button, .kp-icon-button):active:not(:disabled) {
        translate: 0 2px;
    }

    [data-theme='light'] .kp-button:active:not(:disabled) {
        box-shadow:
            0 0 0 0 transparent,
            0 0 0 0 transparent;
    }

    [data-theme='light'] .kp-button:active:focus-visible:not(:disabled) {
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            0 0 0 0 transparent;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] :is(.kp-button, .kp-icon-button):active:not(:disabled) {
            animation: kp-sig-light-flash var(--fx-duration, 200ms) linear 1;
        }
    }

    /* ── The other parts that are pointed at [G14, G15] ──────────────────
       A menu entry takes the muted wash (the rule above), its ring is DI2's
       inside the entry, and a press lands it and flashes it; a key figure
       that is a link or a toggle, a trend tile and a calendar day settle
       toward the paper with the softer shadow of a card and, pointed at, a
       stronger hairline; the corner link of a trend tile takes the pale
       cyan wash a link takes. */
    [data-theme='light'] .kp-menu__item:focus-visible {
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring-contrast);
        outline-offset: -2px;
        box-shadow: inset 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring);
    }

    [data-theme='light'] .kp-menu__item:active:not(:disabled, [aria-disabled='true']) {
        background: var(--secondary-active);
        translate: 0 2px;
    }

    [data-theme='light'] :is(a.kp-kpi, .kp-kpi--toggle, .kp-kpi--trend):hover {
        translate: 0 2px;
        border-color: var(--border-strong);
        box-shadow:
            var(--kp-sig-light-band, 0 0 0 0 transparent),
            0 1px 2px hsl(from var(--foreground) h s l / 0.08);
    }

    /* A calendar day keeps the hairline it had (a tone paints its own). */
    [data-theme='light'] .kp-calendar__day:hover {
        translate: 0 2px;
        box-shadow: 0 1px 2px hsl(from var(--foreground) h s l / 0.08);
    }

    [data-theme='light'] :is(a.kp-kpi, .kp-kpi--toggle):focus-visible,
    [data-theme='light'] .kp-kpi--trend:has(.kp-kpi__link:focus-visible),
    [data-theme='light'] .kp-calendar__day:focus-visible {
        translate: 0 2px;
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring-contrast);
        outline-offset: var(--kp-focus-ring-inner-width, 2px);
        box-shadow:
            var(--kp-sig-light-band, 0 0 0 0 transparent),
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring);
    }

    [data-theme='light'] :is(a.kp-kpi, .kp-kpi--toggle):active,
    [data-theme='light'] .kp-kpi--trend:has(.kp-kpi__link:active) {
        translate: 0 2px;
        background: var(--muted);
        box-shadow: var(--kp-sig-light-band, 0 0 0 0 transparent);
    }

    [data-theme='light'] .kp-calendar__day:active {
        translate: 0 2px;
        box-shadow: none;
    }

    [data-theme='light'] .kp-kpi__link:hover {
        background: var(--accent);
        text-decoration-color: var(--primary);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] :is(a.kp-kpi, .kp-kpi--toggle, .kp-kpi--trend, .kp-calendar__day, .kp-menu__item) {
            transition:
                box-shadow var(--fx-duration, 200ms) var(--fx-ease, ease),
                translate var(--fx-duration, 200ms) var(--fx-ease, ease),
                background-color var(--fx-duration, 200ms) var(--fx-ease, ease),
                border-color var(--fx-duration, 200ms) var(--fx-ease, ease);
        }

        [data-theme='light'] :is(a.kp-kpi, .kp-kpi--toggle):active,
        [data-theme='light'] .kp-kpi--trend:has(.kp-kpi__link:active),
        [data-theme='light'] .kp-calendar__day:active,
        [data-theme='light'] .kp-menu__item:active:not(:disabled, [aria-disabled='true']) {
            animation: kp-sig-light-flash var(--fx-duration, 200ms) linear 1;
        }
    }

    /* ── A warning is a band along the top and a pill [G8; Kenny,
       2026-10-08, question 8] ───────────────────────────────────────────
       A key figure (and a trend tile) in the warning or the destructive tone
       carries a 3px band of the tone's colour along its top edge, drawn as
       an inset shadow so it follows the corners; the card stays white (it
       was a band along the start edge and a figure on a plate); the change
       on it sits on a soft pill in the tone's ink. An alert in either tone
       is the same: a white card, the band, the label on a soft pill. A
       destructive menu entry takes the band and the soft pill on pointing.
       Never a tinted card, never a frame all round. */
    [data-theme='light'] .kp-kpi {
        --kp-sig-light-band: 0 0 0 0 transparent;
        box-shadow: var(--kp-sig-light-band), var(--kp-shadow-sm);
    }

    [data-theme='light'] .kp-kpi[data-kp-tone='warning'] {
        --kp-sig-light-tone: var(--warning-foreground);
        --kp-sig-light-band: inset 0 3px 0 0 var(--warning-foreground);
    }

    [data-theme='light'] .kp-kpi[data-kp-tone='destructive'] {
        --kp-sig-light-tone: var(--destructive);
        --kp-sig-light-band: inset 0 3px 0 0 var(--destructive);
        border-color: var(--border);
    }

    [data-theme='light'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value {
        padding-inline: 0;
        background: none;
        color: inherit;
    }

    [data-theme='light'] .kp-kpi__delta[data-kp-tone],
    [data-theme='light'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__delta {
        padding-inline: 0.6em;
        border-radius: var(--kp-radius-pill, 999px);
        background: hsl(from var(--kp-sig-light-tone, var(--foreground)) h s l / 0.14);
        color: var(--kp-sig-light-tone, var(--foreground));
    }

    [data-theme='light'] .kp-kpi__delta[data-kp-tone='good'] {
        --kp-sig-light-tone: var(--success-foreground);
    }

    [data-theme='light'] .kp-kpi__delta[data-kp-tone='bad'] {
        --kp-sig-light-tone: var(--destructive);
    }

    [data-theme='light'] :is(.kp-alert--warning, .kp-alert--destructive):not(.kp-attention__item) {
        border-color: var(--border);
        background: var(--card);
        color: var(--card-foreground);
        box-shadow:
            inset 0 3px 0 0 var(--kp-sig-light-tone),
            var(--kp-shadow-sm);
    }

    [data-theme='light'] .kp-alert--warning:not(.kp-attention__item) {
        --kp-sig-light-tone: var(--warning-foreground);
    }

    [data-theme='light'] .kp-alert--destructive:not(.kp-attention__item) {
        --kp-sig-light-tone: var(--destructive);
    }

    [data-theme='light'] :is(.kp-alert--warning, .kp-alert--destructive):not(.kp-attention__item) .kp-alert__label {
        align-self: start;
        padding-inline: 0.6em;
        border-radius: var(--kp-radius-pill, 999px);
        background: hsl(from var(--kp-sig-light-tone) h s l / 0.14);
        color: var(--kp-sig-light-tone);
    }

    [data-theme='light'] :is(.kp-alert--warning, .kp-alert--destructive):not(.kp-attention__item) .kp-alert__icon {
        color: var(--kp-sig-light-tone);
    }

    [data-theme='light'] .kp-menu__item--destructive {
        color: var(--destructive);
        box-shadow: inset 0 3px 0 0 var(--destructive);
    }

    [data-theme='light'] .kp-menu__item--destructive:is(:hover, :focus):not(:active) {
        background: hsl(from var(--destructive) h s l / 0.12);
    }

    /* ── The palette's trigger in the bar [scope-48, scope-80] ─────────── */

    /* In the voice of this register's own nav links (Kenny, 2026-09-14,
       search-voice "Per thema"): words at the bar's own size in the links'
       muted ink on the theme's radius, taking the full ink when pointed at,
       as the links do since Kenny's no-indigo note of 2026-09-15. The
       link's typeface, case, spacing, shape and pointer answer are restated
       here, because the trigger is a button beside the list rather than a
       link in it. The underline a plain link carries is not: it says "this
       is a link", and the trigger is not one. */
    [data-theme='light'] .kp-nav__search .kp-nav__search-trigger {
        padding-inline: 0;
        border: 0;
        border-radius: var(--radius, 0.5rem);
        background: none;
        color: var(--muted-foreground);
    }

    [data-theme='light'] .kp-nav__search .kp-nav__search-trigger:hover,
    [data-theme='light'] .kp-nav__search .kp-nav__search-trigger:focus-visible {
        color: var(--foreground);
    }

    /* ── The alarm [scope-94] ──────────────────────────────────────────────
       The alarm in daylight: the page stays white and the headline, the frame and the bars are its own red, with a pale red glow breathing at the edges instead of a dark plate. Every colour is one of this theme's tokens. The
       button keeps this register's shape and takes the alarm's paint, on
       selectors long enough to outrank this register's own button states;
       the dialog takes no focus ring, because in the auto mode the whole
       screen is what has focus. */
    [data-theme='light'] .kp-alarm {
        --kp-alarm-ground: hsl(from var(--background) h s l / 0.97);
        --kp-alarm-ink: var(--destructive);
        --kp-alarm-soft: var(--foreground);
        --kp-alarm-split: var(--primary);
        --kp-alarm-on-ink: var(--destructive-foreground);
        --kp-alarm-glow: hsl(from var(--destructive) h s l / 0.22);
        --kp-alarm-halo: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-scan: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-vignette: hsl(from var(--destructive) h s l / 0);
    }

    [data-theme='light'] .kp-alarm:focus-visible {
        outline: none;
    }

    [data-theme='light'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack,
    [data-theme='light'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:hover:not(:disabled),
    [data-theme='light'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:active:not(:disabled) {
        border-color: var(--kp-alarm-ink);
        background: var(--kp-alarm-ink);
        color: var(--kp-alarm-on-ink);
        text-shadow: none;
    }

    [data-theme='light'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:is(:hover, :focus-visible):not(:disabled):not(:active) {
        background: var(--kp-alarm-on-ink);
        color: var(--kp-alarm-ink);
    }

    [data-theme='light'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep,
    [data-theme='light'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep:is(:hover, :focus-visible):not(:disabled) {
        border-color: currentColor;
        background: transparent;
        color: inherit;
        text-shadow: none;
    }

    /* A submenu item's mark [Kenny, 2026-09-20]: an en dash, the quietest rule a light page can draw. */
    [data-theme='light'] .kp-sidenav__submenu .kp-sidenav__link {
        --kp-sidenav-submenu-mark: '–';
    }
}

/* ── Signature [scope-140] ─────────────────────────────────────────────── */
/* light's approved signature (Kenny, 2026-10-03, three review rounds): the
   progress bar and the ten elements (spinner, skeleton, switch, check and
   radio, toast, dialog, tooltip, wizard steps, empty state, link hover),
   ported once from research/progress-signature/themes/light.css and research/signature-elements/themes/light.css
   and maintained here from now on. In kp.signature, which css/themes.css
   orders after kp.register, so it draws over the register exactly as the
   approved demos did, whatever the weight of a register selector. */
@layer kp.signature {
    /* The link signature is for links in running text; a link in a navigation,
       a menu, a breadcrumb (a nav) or the footer keeps its own component's look
       (scope-93: no link colour in a navigation). */
    /* A shadow or outline the signature draws on a focusable control yields to
       the theme's focus ring while the control has focus (DI2). */
    [data-theme='light'] .kp-progressbar {
        --kp-progressbar-height: calc(0.75rem * var(--kp-progressbar-scale, 1));
        /* One pixel of the drawing at the bar's size (1px at the small size). */
        --kp-ps-px: calc(1px * var(--kp-progressbar-scale, 1));
        --kp-ps-bead: calc(0.75rem * var(--kp-progressbar-scale, 1));
        /* The three waiting dots: one dot, drawn once, at the bar's size. */
        --kp-ps-dot-step: calc(1rem * var(--kp-progressbar-scale, 1));
    }

    [data-theme='light'] .kp-progressbar__track {
        border-radius: 0;
        background: linear-gradient(var(--border), var(--border)) 0 50% / 100% 2px no-repeat;
    }

    [data-theme='light'] .kp-progressbar__fill {
        inset-block: calc(50% - 2 * var(--kp-ps-px));
        block-size: calc(4 * var(--kp-ps-px));
        background: var(--primary);
        clip-path: inset(0 calc((1 - var(--kp-value)) * 100%) 0 0 round var(--kp-radius-pill, 999px));
        transition: clip-path var(--kp-sig-light-time, 700ms) var(--kp-sig-light-ease);
    }

    [data-theme='light'] .kp-progressbar__head {
        inset-block: calc(50% - var(--kp-ps-bead) / 2);
        inline-size: var(--kp-ps-bead);
        block-size: var(--kp-ps-bead);
        border-radius: 50%;
        background: var(--fx-signal);
        box-shadow: inset 0 0 0 2px var(--background);
        transform: translateX(calc(var(--kp-value) * (100cqi - var(--kp-ps-bead))));
        transition: transform var(--kp-sig-light-time, 700ms) var(--kp-sig-light-ease);
    }

    [data-theme='light'] .kp-progressbar[aria-valuenow='100'] .kp-progressbar__head {
        background: var(--primary);
    }

    [data-theme='light'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
        inset: 0;
        inline-size: auto;
        block-size: auto;
        clip-path: none;
        animation: none;
        background:
            radial-gradient(
                    circle,
                    var(--primary) 0 calc(3.5 * var(--kp-ps-px)),
                    var(--background) calc(4 * var(--kp-ps-px)) calc(5.5 * var(--kp-ps-px)),
                    transparent calc(6 * var(--kp-ps-px))
                )
                calc(50% - var(--kp-ps-dot-step)) 50% / var(--kp-ps-bead) var(--kp-ps-bead) no-repeat,
            radial-gradient(
                    circle,
                    var(--primary) 0 calc(3.5 * var(--kp-ps-px)),
                    var(--background) calc(4 * var(--kp-ps-px)) calc(5.5 * var(--kp-ps-px)),
                    transparent calc(6 * var(--kp-ps-px))
                )
                50% 50% / var(--kp-ps-bead) var(--kp-ps-bead) no-repeat,
            radial-gradient(
                    circle,
                    var(--fx-signal) 0 calc(3.5 * var(--kp-ps-px)),
                    var(--background) calc(4 * var(--kp-ps-px)) calc(5.5 * var(--kp-ps-px)),
                    transparent calc(6 * var(--kp-ps-px))
                )
                calc(50% + var(--kp-ps-dot-step)) 50% / var(--kp-ps-bead) var(--kp-ps-bead) no-repeat;
    }

    /* Busy: the bead orbits the line [G11; Kenny, 2026-10-08, question 11:
       "the bead orbits the line"]. The hairline stands; one cyan bead, the
       determinate bar's own head, runs to the end of it and back, on an
       even there-and-back, one loop a leg. Standing still (reduced motion)
       it is the three beads at the middle, which read as working and never
       as a share that is not there [gap-11]. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
            background: none;
        }

        [data-theme='light'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__head {
            display: block;
            transform: translateX(0);
            transition: none;
            animation: kp-sig-light-line var(--kp-sig-light-loop) ease-in-out infinite alternate;
        }
    }

    /* ── Light's grammar, as tokens [themes/light/CHARACTER.md §1, decided by
       Kenny on research/light-character, 2026-10-08]. One token per rule:
       every rule below reads these and names no number of its own. ── */
    [data-theme='light'] {
        /* G1: one curve, the settle: most of the way at once, then a long
           settle into focus, the way a lens pulls focus. It is the theme's
           --fx-ease too (css/themes.css). A close, a leave and the part of a
           beat that goes into the glare ease on its inverse; inside
           @keyframes both are written out (a var() there is invalid). */
        --kp-sig-light-ease: var(--kp-ease-arrive, cubic-bezier(0.16, 1, 0.3, 1));
        --kp-sig-light-ease-out: var(--kp-ease-leave, cubic-bezier(0.7, 0, 0.84, 0));
        --kp-sig-light-pill: var(--kp-radius-pill, 999px);
        /* G4: contact is --fx-duration (200 ms); an exposure (an arrival, an
           opening, the leave as its reverse, a re-exposure) is one time; the
           parts of a group stand one beat apart; a loop is one period. */
        --kp-sig-light-time: 700ms;
        --kp-sig-light-step: 120ms;
        --kp-sig-light-loop: 3600ms;
        --kp-sig-light-orbit: 1200ms;
        /* G1, G5: the glare. White is brightness, never a tint. */
        --kp-sig-light-glare: blur(5px) brightness(1.6);
        /* G9: the beat a changed figure goes into. */
        --kp-sig-light-beat: blur(2px) brightness(1.4);
        /* G10: out of focus, breathing between these two. */
        --kp-sig-light-dim: blur(3px) brightness(1.3);
        --kp-sig-light-dazzle: blur(5px) brightness(1.6);
        /* G12: the spinner's bead burns out. */
        --kp-sig-light-burn: blur(4px) brightness(1.8);
        /* G17: the shutter. */
        --kp-sig-light-shutter: 1.25;
        /* js/motion.js reads its caps from the root: a close or a size glide
           of one exposure is not cut short (its defaults, 600 and 480 ms, are
           other themes'). */
        --kp-close-max: var(--kp-sig-light-time);
        --kp-size-max: var(--kp-sig-light-time);
    }

    [data-theme='light'] .kp-spinner {
        --kp-sig-dur: var(--kp-sig-light-orbit);
        --kp-sig-s: var(--kp-spinner-size, 1.25rem);
        position: relative;
        border: 1px solid var(--border);
        border-radius: 50%;
        background: none;
        animation: none;
    }

    [data-theme='light'] .kp-spinner::before,
    [data-theme='light'] .kp-spinner::after {
        content: '';
        position: absolute;
        inset: -4px;
        border-radius: 50%;
    }

    [data-theme='light'] .kp-spinner::after {
        background: radial-gradient(circle at 50% 4.5px, var(--primary) 0 3px, transparent 3.5px);
    }

    [data-theme='light'] .kp-spinner::before {
        background: radial-gradient(circle at 50% 4.5px, var(--fx-signal) 0 2px, transparent 2.5px);
        transform: rotate(-40deg);
    }

    /* The skeleton's shapes (the picture is drawn with the other waiting
       surfaces, "Loading is out of focus", below): a line is a pill, a block
       takes the plate's radius, a circle is round. */
    [data-theme='light'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        block-size: 0.75rem;
        border-radius: var(--kp-sig-light-pill);
    }

    [data-theme='light'] .kp-skeleton--block {
        border-radius: var(--radius, 0.5rem);
    }

    [data-theme='light'] .kp-skeleton--circle {
        border-radius: 50%;
    }

    [data-theme='light'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) + .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        margin-block-start: 0.75rem;
    }

    [data-theme='light'] .kp-switch {
        --kp-switch-radius: var(--kp-sig-light-pill);
        --kp-switch-thumb-radius: 50%;
    }

    [data-theme='light'] .kp-switch__input {
        border-color: var(--border-strong);
        background: var(--muted);
    }

    [data-theme='light'] .kp-switch__input::before {
        background: var(--background);
        box-shadow:
            0 0 0 1px var(--border-strong),
            0 2px 4px hsl(from var(--foreground) h s l / 0.18);
    }

    [data-theme='light'] .kp-switch__input:checked {
        border-color: var(--primary);
        background: var(--primary);
    }

    [data-theme='light'] .kp-switch__input:checked::before {
        inset-inline-start: var(--kp-switch-inset, 0.125rem);
        background: var(--primary-foreground);
        box-shadow: 0 2px 4px hsl(from var(--foreground) h s l / 0.3);
        transform: translateX(calc(var(--kp-switch-width, 2.5rem) - var(--kp-switch-height, 1.5rem)));
    }

    [data-theme='light'] .kp-field__check {
        --kp-sig-dur: var(--fx-duration, 200ms);
        appearance: none;
        display: inline-grid;
        place-content: center;
        inline-size: 1.15rem;
        block-size: 1.15rem;
        margin: 0;
        border: 1px solid var(--border-strong);
        border-radius: 0.3rem;
        background: var(--background);
    }

    [data-theme='light'] .kp-field__check[type='checkbox']:checked {
        border-color: var(--primary);
        background: var(--primary);
    }

    [data-theme='light'] .kp-field__check[type='checkbox']:checked::before {
        content: '';
        inline-size: 0.6rem;
        block-size: 0.32rem;
        border-inline-start: 2px solid var(--primary-foreground);
        border-block-end: 2px solid var(--primary-foreground);
        border-end-start-radius: 1px;
        transform: translateY(-1px) rotate(-45deg);
    }

    [data-theme='light'] .kp-field__check[type='radio'] {
        border-radius: 50%;
    }

    [data-theme='light'] .kp-field__check[type='radio']:checked {
        border: 1.5px solid var(--primary);
    }

    [data-theme='light'] .kp-field__check[type='radio']:checked::before {
        content: '';
        inline-size: 0.5rem;
        block-size: 0.5rem;
        border-radius: 50%;
        background: var(--primary);
    }

    [data-theme='light'] .kp-toast {
        --kp-sig-dur: var(--kp-sig-light-time);
        border-color: var(--border);
        box-shadow: var(--kp-shadow-md);
    }

    /* The unopened dialog is the one js/motion.js measures for the theme's
       time (a probe it adds and takes off), and it reads close = two thirds
       of that: so it runs one and a half exposures, and the dialog that is
       open runs one, which is also its close and its opening (js/motion.js
       plays the opening as the close backwards, in the close's time). */
    [data-theme='light'] .kp-dialog {
        --kp-sig-dur: calc(var(--kp-sig-light-time) * 1.5);
        border-color: var(--border);
        box-shadow: var(--kp-shadow-lg);
    }

    [data-theme='light'] .kp-dialog[open] {
        --kp-sig-dur: var(--kp-sig-light-time);
    }

    [data-theme='light'] .kp-tooltip {
        --kp-sig-dur: var(--kp-sig-light-time);
        margin-inline-start: 0.5rem;
        padding: 0.3rem 0.8rem;
        border: 0;
        border-radius: var(--kp-sig-light-pill);
        background: var(--foreground);
        color: var(--background);
        box-shadow: var(--kp-shadow-md);
        font-size: 0.8125rem;
        font-weight: 500;
    }

    /* The page's one hover card (js/hovercard.js) holds several lines and rows. A pill radius is for one line
       of words: on a card it reads as an oval (Kenny, kpadopt-tooltip-sort, 2026-10-16), so the card takes the
       popover's own corner. */
    [data-theme='light'] .kp-tooltip[data-kp-hovercard-card] {
        padding: 0.5rem 0.8rem;
        border-radius: var(--radius, 0.5rem);
    }

    [data-theme='light'] .kp-tooltip::before {
        content: '';
        position: absolute;
        inset-block-start: -3px;
        inset-inline-start: 1rem;
        inline-size: 7px;
        block-size: 7px;
        border-radius: 1px;
        background: var(--foreground);
        transform: rotate(45deg);
    }

    [data-theme='light'] .kp-wizard__steps {
        gap: 0.5rem 1.5rem;
    }

    [data-theme='light'] .kp-wizard__steps li {
        position: relative;
        gap: 0.5rem;
        padding: 0.25rem 0.75rem 0.25rem 0.25rem;
        border-radius: var(--kp-sig-light-pill);
    }

    [data-theme='light'] .kp-wizard__steps li:not(:last-child)::after {
        content: '';
        position: absolute;
        inset-block-start: 50%;
        inset-inline-start: calc(100% + 0.25rem);
        inline-size: 1rem;
        block-size: 1px;
        background: var(--border-strong);
    }

    [data-theme='light'] .kp-wizard__steps li::before {
        border-color: var(--border-strong);
        background: var(--background);
        font-weight: 600;
    }

    [data-theme='light'] .kp-wizard__steps li[data-state='done'] {
        color: var(--foreground);
    }

    [data-theme='light'] .kp-wizard__steps li[data-state='done']::before {
        border-color: var(--primary);
        color: var(--primary);
    }

    [data-theme='light'] .kp-wizard__steps li[data-state='current'] {
        background: var(--accent);
        color: var(--accent-foreground);
    }

    [data-theme='light'] .kp-wizard__steps li[data-state='current']::before {
        border-color: var(--primary);
        background: var(--primary);
        color: var(--primary-foreground);
    }

    [data-theme='light'] .kp-empty {
        position: relative;
        padding: 2.75rem 1.5rem 1.25rem;
        border: 0;
        border-radius: var(--radius);
    }

    [data-theme='light'] .kp-empty::before {
        content: '';
        position: absolute;
        inset-block-start: 1.1rem;
        inset-inline-start: calc(50% - 3.5rem);
        inline-size: 7rem;
        block-size: 11px;
        background:
            radial-gradient(circle, var(--fx-signal) 0 3px, var(--background) 3.5px 4.5px, transparent 5px) center / 11px 11px no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) center / 100% 1px no-repeat;
    }

    [data-theme='light'] .kp-empty__title {
        font-size: 1.05rem;
        font-weight: 600;
        letter-spacing: -0.01em;
    }

    [data-theme='light'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a) {
        border-radius: 0.2em;
        text-decoration-thickness: 1px;
        text-decoration-color: hsl(from var(--primary) h s l / 0.45);
        text-underline-offset: 0.22em;
        -webkit-box-decoration-break: clone;
        box-decoration-break: clone;
    }

    [data-theme='light'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a):hover {
        background: var(--accent);
        text-decoration-color: var(--primary);
    }

    [data-theme='light']
        a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a):hover:not(:focus-visible) {
        box-shadow:
            -0.15em 0 0 var(--accent),
            0.15em 0 0 var(--accent);
    }

    @media (prefers-reduced-motion: no-preference) {
        /* The indigo bead burns out where it dwells at the top and is back
           in focus by the foot [G12; Kenny, 2026-10-08, question 12]. */
        [data-theme='light'] .kp-spinner::after {
            animation:
                kp-sig-light-light-orbit var(--kp-sig-dur) var(--kp-sig-light-ease) infinite,
                kp-sig-light-burn var(--kp-sig-dur) linear infinite;
        }

        [data-theme='light'] .kp-spinner::before {
            animation: kp-sig-light-light-orbit var(--kp-sig-dur) var(--kp-sig-light-ease) -1100ms infinite;
        }

        [data-theme='light'] .kp-switch__input::before {
            transition:
                transform var(--fx-duration, 200ms) var(--kp-sig-light-ease),
                background-color var(--fx-duration, 200ms) var(--kp-sig-light-ease);
        }

        [data-theme='light'] .kp-field__check[type='checkbox']:checked::before {
            animation: kp-sig-light-light-tick var(--kp-sig-dur) var(--kp-sig-light-ease) both;
        }

        [data-theme='light'] .kp-field__check[type='radio']:checked::before {
            animation: kp-sig-light-expose var(--kp-sig-dur) var(--kp-sig-light-ease) backwards;
        }

        /* What opens comes into focus where it stands, under its anchor
           [G2, G3, G13]: no rise, no float, no window. Each arrival is an
           exposure on the settle; each close is the same played backwards
           (js/motion.js turns the entrance round, so it eases on the
           inverse). Toasts are exposed one after the other in reading order,
           a step apart. */
        [data-theme='light'] :is(.kp-toast, .kp-dialog, .kp-tooltip) {
            animation: kp-sig-light-expose var(--kp-sig-dur) var(--kp-sig-light-ease) backwards;
        }

        [data-theme='light'] .kp-toast + .kp-toast {
            animation-delay: var(--kp-sig-light-step);
        }

        /* A menu or a popover hangs from its button, a drawer stands at its
           edge, a tour card where the tour puts it: each comes into focus
           where it is. */
        [data-theme='light'] :is(.kp-menu-button > .kp-menu, .kp-popover[popover]:not(.kp-tooltip)) {
            animation: kp-sig-light-expose var(--kp-sig-light-time) var(--kp-sig-light-ease) backwards;
        }

        [data-theme='light'] :is(dialog.kp-drawer[open], .kp-tour[open]) {
            animation: kp-sig-light-expose var(--kp-sig-light-time) var(--kp-sig-light-ease) backwards;
        }
    }

    @keyframes kp-sig-light-light-orbit {
        from {
            transform: rotate(0);
        }

        to {
            transform: rotate(1turn);
        }
    }

    @keyframes kp-sig-light-light-tick {
        from {
            clip-path: inset(0 100% 0 0 round 2px);
        }

        to {
            clip-path: inset(0 0 0 0 round 2px);
        }
    }

    /* ── The exposure [G1, G2, G13; Kenny, 2026-10-08, questions 1, 2 and 13].
       A part is a glare first, blurred and too bright (brightness 1.6, blur
       5px), and comes down into focus and into its own white; what leaves goes
       back into the glare. In place: no rise, no slide, no scale. The
       arrival eases on the settle; the leave is the same pair played the
       other way on its inverse, so frame t of the arrival is frame (T - t) of
       the leave. Neither keyframe names its own easing: it is the animation's,
       so js/motion.js can turn either round. ─────────────────────────────── */
    @keyframes kp-sig-light-expose {
        from {
            opacity: 0;
            filter: var(--kp-sig-light-glare, blur(5px) brightness(1.6));
        }

        to {
            opacity: 1;
            filter: none;
        }
    }

    @keyframes kp-sig-light-leave {
        from {
            opacity: 1;
            filter: none;
        }

        to {
            opacity: 0;
            filter: var(--kp-sig-light-glare, blur(5px) brightness(1.6));
        }
    }

    /* Growing and shrinking, this theme's way [scope-142; approved by Kenny
       on research/size-motion, 2026-10-04; redrawn 2026-10-08]. js/motion.js
       marks a gliding box `[data-kp-resizing]` and what arrives in it
       `[data-kp-arriving]`: the box brightens a touch while it glides (white,
       brightness, never a tint), and what arrives in it comes into focus. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] [data-kp-resizing] {
            filter: brightness(1.04);
        }

        [data-theme='light'] [data-kp-arriving] {
            animation: kp-sig-light-expose var(--kp-sig-light-time) var(--kp-sig-light-ease) backwards;
        }
    }

    /* Leaving, this theme's way [scope-142; picked by Kenny on research/size-motion,
       2026-10-04; 2026-10-08: out of the glare in place, question 13]. js/motion.js
       marks what leaves `[data-kp-leaving]`, closes its space during the exit, and in a
       row of leaves starts the next one halfway through this one. */
    @media (prefers-reduced-motion: no-preference) {
        /* ── light: it goes back into the glare where it stands ── */
        /* Opening is closing turned around (Kenny's pick on research/open-reverse,
           2026-10-05): js/motion.js opens the dialog as its close played backwards,
           in the close's time, and lets what arrives play this leave backwards. */
        [data-theme='light'] {
            --kp-open: reverse-close;
            /* A part a script removes or hides (the busy table's layer, a file
               row, an empty state, a re-shown alert) goes back into the glare
               first, as it comes out of it (js/motion.js leavesState(), lessons
               19, 23, 24); what takes no box arrives as nothing; the space a
               leave folds shut takes the exposure's own time and starts with it. */
            --kp-leave-state: leave;
            --kp-arrive-unseen: skip;
            --kp-leave-fold-grow: 1;
            --kp-leave-fold-start: 0;
            /* ...on the leave's own (inverse) curve, so the space and the part
               go together; the arrival plays it backwards, on the settle. */
            --kp-leave-fold-ease: var(--kp-sig-light-ease-out);
        }

        [data-theme='light'] [data-kp-leaving] {
            animation: kp-sig-light-leave var(--kp-sig-light-time) var(--kp-sig-light-ease-out) forwards;
        }
    }

    /* ── The meter with a mark, this theme's way [picked by Kenny on
       research/character-meter, round 3, 2026-10-05: shape 1, while
       loading 1, how the share arrives 2, when the tone changes 2,
       the mark past the end 2]. The package's own markup and states
       (setMeter(), js/kpi.js): the track on the meter, the share on ::before,
       the sign past the end or the loading picture on ::after, the mark
       `.kp-meter__mark`. Every animation and transition under
       prefers-reduced-motion: no-preference; still frames otherwise. ── */

    /* The shared part: room past the end, loading without the pulse, the mark
       centred on its width, the package's signs cleared for the shape's own.
       Under :where() so each picked rule below wins as it did in the demo. */
    :where([data-theme='light']) :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-room: 0.625rem;
        box-sizing: border-box;
    }

    :where([data-theme='light']) .kp-meter--inline {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-sig-meter-room));
    }

    /* Each character draws its own loading picture instead of the pulse. */
    :where([data-theme='light']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: clip;
        animation: none;
    }

    /* The mark is centred on its share, whatever its width. */
    :where([data-theme='light']) .kp-meter__mark {
        --kp-sig-meter-mw: 2px;
        box-sizing: border-box;
        inline-size: var(--kp-sig-meter-mw);
        inset-inline-start: calc(clamp(0, var(--kp-mark, 0), 1) * 100% - var(--kp-sig-meter-mw) / 2);
    }

    :where([data-theme='light']) .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - 0.75rem);
    }

    /* The sign past the end, cleared of the package's ▸ for each character
       to draw its own. */
    :where([data-theme='light']) :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '';
        position: absolute;
        inset: auto;
        translate: none;
        color: inherit;
        font-size: 0.75rem;
        line-height: 1;
        text-shadow: none;
        white-space: nowrap;
        pointer-events: none;
    }

    /* A mark past the end keeps the package's sign inside the bar's end, in
       each character's own glyph and ink. */
    :where([data-theme='light']) .kp-meter__mark[data-kp-over]::after {
        content: var(--kp-sig-meter-mo-sign, '▸');
        color: var(--kp-sig-meter-mo-ink, var(--foreground));
        font-family: var(--kp-sig-meter-mo-font, inherit);
        text-shadow:
            0 0 1px var(--kp-sig-meter-mo-halo, var(--card)),
            0 0 2px var(--kp-sig-meter-mo-halo, var(--card));
    }

    /* ── shape: option 1, on light's grammar ── */

    /* ── light · the hairline track, a flat share, a plain stroke ─────────
       The share is one flat fill (no gradient, no sun on its end, G7); the
       mark is a plain stroke with a white edge (the gnomon, its shadow and the
       glint past the end are retired, G19); past the end the mark sits at the
       end and nothing else is drawn. */
    [data-theme='light'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-meter-height: 0.375rem;
        --kp-sig-meter-room: 1rem;
        --kp-sig-meter-mo-sign: '';
        border-radius: 999px;
        background: var(--muted);
        box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--border-strong) 40%, transparent);
    }

    [data-theme='light'] :is(.kp-meter, .kp-kpi__meter)::before {
        border-radius: 999px;
        background: var(--kp-meter-fill-colour);
    }

    [data-theme='light'] .kp-meter__mark {
        inset-block: -4px;
        border-radius: 1px;
        background: var(--foreground);
        box-shadow: 0 0 0 1px var(--card);
    }

    [data-theme='light'] :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after,
    [data-theme='light'] .kp-meter__mark[data-kp-over]::after {
        content: none;
    }

    [data-theme='light'] .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - var(--kp-sig-meter-mw) - 1px);
    }

    /* ── how the share arrives: exposed along its length, start to end, out
       of the glare, on the exposure and the settle (G2); a new share glides on
       the same time ── */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] :is(.kp-meter, .kp-kpi__meter):not([data-kp-loading])::before {
            animation: kp-sig-light-feed var(--kp-sig-light-time) var(--kp-sig-light-ease) backwards;
            transition:
                inline-size var(--kp-sig-light-time) var(--kp-sig-light-ease),
                background-color var(--fx-duration, 200ms) var(--kp-sig-light-ease);
        }

        /* ── when the tone changes: the meter is re-exposed (G9) ── */
        [data-theme='light'] :is(.kp-meter, .kp-kpi__meter):not([data-kp-loading], [data-kp-tone]) {
            animation: kp-sig-light-meter-expose-o var(--kp-sig-light-time) linear;
        }

        [data-theme='light'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='warning']:not([data-kp-loading]) {
            animation: kp-sig-light-meter-expose-w var(--kp-sig-light-time) linear;
        }

        [data-theme='light'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='destructive']:not([data-kp-loading]) {
            animation: kp-sig-light-meter-expose-d var(--kp-sig-light-time) linear;
        }

        [data-theme='light'] .kp-meter__mark {
            transition: inset-inline-start var(--kp-sig-light-time) var(--kp-sig-light-ease);
        }
    }

    /* ── Loading is out of focus [G10; Kenny, 2026-10-08, question 10:
       "out of focus"]. A waiting surface stands in the glare, blurred and
       bright (brightness 1.3, blur 3px), and its exposure breathes (up to
       brightness 1.6, blur 5px, 3600ms) until the reading comes into focus.
       Not a band of daylight crossing, not a dashed baseline, not a clip. It
       fills the whole element and is shaped like the result:
         - the placeholders (a skeleton's lines, blocks and circles, the
           chart's loading panel and legend stubs, the key figures' and the
           columns' lines, the trend's plot) are drawn on ::before in the
           seam's grey, so a sentence inside one (the chart's "loading") stays
           sharp;
         - the loading meter, and a loading menu entry, breathe themselves;
         - a busy card, a busy tile of a grid, a key figure and the table's
           busy panel keep their plate and their words breathe on it (a plate
           that is brighter and blurred as well is white on white); the busy
           panel's spinner keeps its own bead;
         - a busy button keeps its pill and its label breathes on it: a
           pill that is brighter and blurred as a whole is white on white, so
           the label is drawn as its own blur, in its ink;
         - a loading day of the calendar keeps its cell and its number and
           count breathe, a day later in the week a beat later.
       Under reduced motion the placeholders and the meter stand still, out of
       focus; words stay sharp. ── */
    [data-theme='light'] [aria-busy='true'] {
        --kp-busy-opacity: 1;
    }

    [data-theme='light'] .kp-skeleton {
        position: relative;
        isolation: isolate;
        background: none;
        animation: none;
    }

    [data-theme='light'] .kp-skeleton::before {
        content: '';
        position: absolute;
        inset: 0;
        z-index: -1;
        border-radius: inherit;
        background: var(--border-strong);
        filter: var(--kp-sig-light-dim);
        pointer-events: none;
    }

    [data-theme='light'] :is(.kp-skeleton--block, .kp-skeleton--circle)::before {
        background: hsl(from var(--border-strong) h s l / 0.55);
    }

    [data-theme='light'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: visible;
        background: hsl(from var(--border-strong) h s l / 0.55);
        box-shadow: none;
        filter: var(--kp-sig-light-dim);
    }

    [data-theme='light'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        content: none;
    }

    [data-theme='light'] .kp-calendar__day[data-kp-tone='loading'] {
        animation: none;
    }

    [data-theme='light'] .kp-button[aria-busy='true'] {
        --kp-sig-light-ink: var(--secondary-foreground);
        color: transparent;
        text-shadow: 0 0 3px var(--kp-sig-light-ink);
    }

    [data-theme='light'] .kp-button--primary[aria-busy='true'] {
        --kp-sig-light-ink: var(--primary-foreground);
    }

    [data-theme='light'] .kp-button--destructive[aria-busy='true'] {
        --kp-sig-light-ink: var(--destructive-foreground);
    }

    [data-theme='light'] .kp-button--ghost[aria-busy='true'] {
        --kp-sig-light-ink: var(--foreground);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] .kp-skeleton::before {
            animation: kp-sig-light-breathe var(--kp-sig-light-loop) infinite;
        }

        [data-theme='light'] .kp-skeleton:nth-child(2)::before {
            animation-delay: calc(var(--kp-sig-light-loop) / -8);
        }

        [data-theme='light'] .kp-skeleton:nth-child(3)::before {
            animation-delay: calc(var(--kp-sig-light-loop) / -4);
        }

        [data-theme='light']
            :is(.kp-meter[data-kp-loading], .kp-kpi__meter[data-kp-loading], .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading]) {
            animation: kp-sig-light-breathe var(--kp-sig-light-loop) infinite;
        }

        [data-theme='light'] .kp-button[aria-busy='true'] {
            animation: kp-sig-light-breathe-ink var(--kp-sig-light-loop) infinite;
        }

        [data-theme='light']
            :is(
                .kp-card[aria-busy='true'],
                .kp-tiles[aria-busy='true'] > .kp-card,
                .kp-kpi[aria-busy='true'],
                .kp-datatable__busy-panel,
                .kp-calendar__day[data-kp-tone='loading']
            )
            > :not(.kp-spinner, .kp-skeleton, .kp-meter, .kp-kpi__meter, .kp-calendar__day-busy) {
            animation: kp-sig-light-breathe var(--kp-sig-light-loop) infinite;
        }

        [data-theme='light'] .kp-calendar__day[data-kp-tone='loading'] > :not(.kp-calendar__day-busy) {
            animation-delay: calc(var(--kp-sig-light-col, 0) * var(--kp-sig-light-loop) / -12);
        }
    }

    /* ── A live update is re-exposed [G9; Kenny, 2026-10-08, question 9].
       js/update.js writes the new value at once and marks the element
       `[data-kp-updating='reexpose']` (a key figure's value, a state word, a
       trend's line, a column's or a tile's figure): it goes into the glare
       for a beat (brightness 1.4, blur 2px) and comes back into focus, one
       exposure (the theme's update time, themeMotion(), times 0.8). The
       figure, the word and the line never move or swell. ── */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] {
            --kp-update: reexpose;
        }

        [data-theme='light'] [data-kp-updating='reexpose'] {
            animation: kp-sig-light-reexpose calc(var(--kp-update-duration, 875ms) * 0.8) linear both;
        }
    }

    /* ── The calendar [G2, G19]: the days of a month are exposed one after the
       other in reading order, a quarter of the group step apart (a month is
       up to forty-two of them); today wears the bead, in the corner of its
       cell because the package's day carries its count under the number; the
       package's ring is retired. ── */
    [data-theme='light'] .kp-calendar__grid td:nth-child(2) {
        --kp-sig-light-col: 1;
    }

    [data-theme='light'] .kp-calendar__grid td:nth-child(3) {
        --kp-sig-light-col: 2;
    }

    [data-theme='light'] .kp-calendar__grid td:nth-child(4) {
        --kp-sig-light-col: 3;
    }

    [data-theme='light'] .kp-calendar__grid td:nth-child(5) {
        --kp-sig-light-col: 4;
    }

    [data-theme='light'] .kp-calendar__grid td:nth-child(6) {
        --kp-sig-light-col: 5;
    }

    [data-theme='light'] .kp-calendar__grid td:nth-child(7) {
        --kp-sig-light-col: 6;
    }

    [data-theme='light'] .kp-calendar__grid tbody tr:nth-child(2) {
        --kp-sig-light-row: 1;
    }

    [data-theme='light'] .kp-calendar__grid tbody tr:nth-child(3) {
        --kp-sig-light-row: 2;
    }

    [data-theme='light'] .kp-calendar__grid tbody tr:nth-child(4) {
        --kp-sig-light-row: 3;
    }

    [data-theme='light'] .kp-calendar__grid tbody tr:nth-child(5) {
        --kp-sig-light-row: 4;
    }

    [data-theme='light'] .kp-calendar__grid tbody tr:nth-child(6) {
        --kp-sig-light-row: 5;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='light'] .kp-calendar__grid:not([aria-busy='true']) td:has(> .kp-calendar__day) {
            animation: kp-sig-light-expose var(--kp-sig-light-time) var(--kp-sig-light-ease)
                calc((var(--kp-sig-light-row, 0) * 7 + var(--kp-sig-light-col, 0)) * var(--kp-sig-light-step) / 4) backwards;
        }
    }

    [data-theme='light'] .kp-calendar__day[data-kp-today] {
        position: relative;
        box-shadow: none;
    }

    [data-theme='light'] .kp-calendar__day[data-kp-today]::after {
        content: '';
        position: absolute;
        inset-block-start: 0.2rem;
        inset-inline-end: 0.2rem;
        inline-size: 0.5rem;
        block-size: 0.5rem;
        border-radius: 50%;
        background: var(--fx-signal);
        box-shadow: inset 0 0 0 0.1rem var(--background);
        pointer-events: none;
    }

    /* ── Keyframes of the grammar ── */

    /* A re-exposure: into the glare for a beat on the inverse, back into
       focus on the settle (the easings are written out: a var() is invalid
       inside @keyframes). One name per tone, so a tone that changes starts
       it again. */
    @keyframes kp-sig-light-reexpose {
        0% {
            filter: none;
            animation-timing-function: cubic-bezier(0.7, 0, 0.84, 0);
        }

        18% {
            filter: var(--kp-sig-light-beat, blur(2px) brightness(1.4));
            animation-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
        }

        100% {
            filter: none;
        }
    }

    @keyframes kp-sig-light-meter-expose-o {
        0% {
            filter: none;
            animation-timing-function: cubic-bezier(0.7, 0, 0.84, 0);
        }

        18% {
            filter: var(--kp-sig-light-beat, blur(2px) brightness(1.4));
            animation-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
        }

        100% {
            filter: none;
        }
    }

    @keyframes kp-sig-light-meter-expose-w {
        0% {
            filter: none;
            animation-timing-function: cubic-bezier(0.7, 0, 0.84, 0);
        }

        18% {
            filter: var(--kp-sig-light-beat, blur(2px) brightness(1.4));
            animation-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
        }

        100% {
            filter: none;
        }
    }

    @keyframes kp-sig-light-meter-expose-d {
        0% {
            filter: none;
            animation-timing-function: cubic-bezier(0.7, 0, 0.84, 0);
        }

        18% {
            filter: var(--kp-sig-light-beat, blur(2px) brightness(1.4));
            animation-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
        }

        100% {
            filter: none;
        }
    }

    /* Out of focus: the exposure breathes between dim and dazzling. */
    @keyframes kp-sig-light-breathe {
        0%,
        100% {
            filter: var(--kp-sig-light-dim, blur(3px) brightness(1.3));
            animation-timing-function: ease-in-out;
        }

        50% {
            filter: var(--kp-sig-light-dazzle, blur(5px) brightness(1.6));
            animation-timing-function: ease-in-out;
        }
    }

    /* The same breathing for a label on its pill: the blur of the label's
       own shadow swells from 3px to 5px and its ink goes toward the paper, as
       brightness does. */
    @keyframes kp-sig-light-breathe-ink {
        0%,
        100% {
            text-shadow: 0 0 3px var(--kp-sig-light-ink);
            animation-timing-function: ease-in-out;
        }

        50% {
            text-shadow: 0 0 5px color-mix(in oklab, var(--kp-sig-light-ink) 70%, var(--background));
            animation-timing-function: ease-in-out;
        }
    }

    /* The spinner's indigo bead burns out where it dwells at the top and is
       back in focus by the foot. */
    @keyframes kp-sig-light-burn {
        0% {
            filter: var(--kp-sig-light-burn, blur(4px) brightness(1.8));
            animation-timing-function: ease-out;
        }

        16%,
        66% {
            filter: none;
            animation-timing-function: ease-in;
        }

        100% {
            filter: var(--kp-sig-light-burn, blur(4px) brightness(1.8));
        }
    }

    /* A press flashes the pill, the shutter, for the contact. */
    @keyframes kp-sig-light-flash {
        0% {
            filter: none;
            animation-timing-function: ease-out;
        }

        35% {
            filter: brightness(var(--kp-sig-light-shutter, 1.25));
            animation-timing-function: ease-in-out;
        }

        100% {
            filter: none;
        }
    }

    /* The bead runs the hairline to its end (the bar's track is the container
       the length is measured in) and, alternating, back. */
    @keyframes kp-sig-light-line {
        from {
            transform: translateX(0);
        }

        to {
            transform: translateX(calc(100cqi - var(--kp-ps-bead, 0.75rem)));
        }
    }

    /* A line exposed along its length, start to end, out of the glare. */
    @keyframes kp-sig-light-feed {
        from {
            clip-path: inset(0 100% 0 0 round 999px);
            filter: var(--kp-sig-light-glare, blur(5px) brightness(1.6));
        }

        to {
            clip-path: inset(0 0 0 0 round 999px);
            filter: none;
        }
    }

    /* ── Every part that opens comes out of the glare and goes back into it
       [G1, G3, G13; lesson 38; all-themes pass, 2026-10-13]. The palette, the
       date picker's panel, the combobox's list, the tour's dim and ring, the
       calendar's busy layers and the bar's three openings take the exposure
       the dialog and the menus already use (700 ms on the settle); each close
       is the same played backwards on the inverse curve. ── */
    @media (prefers-reduced-motion: no-preference) {
        /* The palette is exposed as the dialog is (it had the package's bare
           fade); js/motion.js keeps the entrance and plays it backwards. The
           date picker's panel and the combobox's list hang from their field
           as a menu hangs from its button, and come into focus as it does;
           js/motion.js playClose() turns the entrance round. */
        [data-theme='light'] :is(dialog.kp-palette, .kp-combobox__list, .kp-datepicker__panel) {
            animation: kp-sig-light-expose var(--kp-sig-light-time) var(--kp-sig-light-ease) backwards;
        }

        /* The calendar button hands its focus to the day as the panel opens and takes it back
           when the panel is gone (js/datepicker.js, lesson 11). Its ring and lift settled over
           200 ms as the focus left, so the open's first 200 ms ran a ring the close never ran
           (it comes back after the close): 6.1 % at the open's first frame (round 2,
           2026-10-13). On this one button the ring and the lift come and go in the frame the
           focus moves, so they flip at the open's first frame and the close's last, mirrored. */
        [data-theme='light'] .kp-datepicker [data-kp-date-open] {
            transition-property: background-color, border-color, color;
        }

        /* The tour: the page dims round the target and the ring comes into
           view in the card's own exposure (700 ms on the settle; it was the
           package's 350 and 250 ms ease), and css/components.css takes both
           back in the same time on the inverse curve, the dim shrinking into
           the target as it grew out of it (lessons 11, 21, 22). */
        [data-theme='light'] {
            --kp-tour-dim-close: 0 0 0 0 transparent;
            --kp-tour-dim-time: var(--kp-sig-light-time);
            --kp-tour-dim-close-ease: var(--kp-sig-light-ease-out);
        }

        [data-theme='light'] [data-kp-tour-target] {
            transition:
                box-shadow var(--kp-sig-light-time) var(--kp-sig-light-ease),
                outline-color var(--kp-sig-light-time) var(--kp-sig-light-ease);
        }

        /* The ring comes in only round a live tour's target (a frozen example
           on a page is no opening). `backwards`, not `both`: a ring held by a
           finished animation cannot be taken back by the close's transition. */
        [data-theme='light']:has(dialog.kp-tour[open]) [data-kp-tour-target] {
            animation: kp-sig-light-tour-ring var(--kp-sig-light-time) var(--kp-sig-light-ease) backwards;
        }

        @keyframes kp-sig-light-tour-ring {
            from {
                outline-color: transparent;
            }
        }

        /* One loading picture: while the busy table's layer stands over the
           rows, the status line's small spinner stays out, so it holds back no
           arrival of the layer and leaves nothing behind it (lesson 23, as
           cyberpunk and deco). */
        [data-theme='light'] .kp-datatable:has(> .kp-datatable__busy-overlay) .kp-datatable__status > .kp-spinner {
            display: none;
        }

        /* The busy table's rows dim and come back in the busy layer's own
           exposure (on the settle going busy, on the inverse coming back), so
           the table under the layer is part of the same pair. */
        [data-theme='light'] .kp-datatable .kp-table tbody {
            transition: opacity var(--kp-sig-light-time) var(--kp-sig-light-ease-out);
        }

        [data-theme='light'] .kp-datatable[aria-busy='true'] .kp-table tbody {
            transition-timing-function: var(--kp-sig-light-ease);
        }

        /* The side navigation (over and push, the window-edge panel too) is
           exposed where it stands, as the dialog is [G2, G3; Kenny,
           2026-10-13 review round 2: "niet de open/close animatie van dit
           thema"]: no slide in on the contact time any more. It is a glare
           first and comes down into focus on the settle in one exposure
           (kp-sig-light-expose, 700 ms); it closes back into the glare
           (kp-sig-light-leave, the same frames the other way, on the inverse
           curve), so the close is the opening backwards. Shut, it stays in
           place and is hidden from the close's last frame. The content a push
           panel makes room in moves on the same exposure (js/sidenav.js copies
           the panel's `translate` timing to it; the panel's own translate
           never changes): most of the way at once, then settling, and back on
           the inverse curve. */
        [data-theme='light'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']) {
            translate: 0 0;
            visibility: hidden;
            animation: kp-sig-light-leave var(--kp-sig-light-time) var(--kp-sig-light-ease-out) forwards;
            transition:
                translate var(--kp-sig-light-time) var(--kp-sig-light-ease-out),
                visibility 0s linear var(--kp-sig-light-time),
                inline-size var(--kp-sidenav-duration, var(--fx-duration)) var(--kp-sidenav-ease-back, var(--kp-sig-light-ease-out));
        }

        [data-theme='light'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='true'] {
            visibility: visible;
            animation: kp-sig-light-expose var(--kp-sig-light-time) var(--kp-sig-light-ease) backwards;
            transition:
                translate var(--kp-sig-light-time) var(--kp-sig-light-ease),
                visibility 0s linear,
                inline-size var(--kp-sidenav-duration, var(--fx-duration)) var(--kp-sidenav-ease, var(--kp-sig-light-ease));
        }

        /* Its shade, where a page asks for one, comes in over the same
           exposure, as the dialog's shade does (js/sidenav.js plays it round). */
        [data-theme='light'] .kp-sidenav__backdrop {
            animation-duration: var(--kp-sig-light-time);
            animation-timing-function: var(--kp-sig-light-ease);
        }

        /* The alarm comes into focus as the dialog does [G3]: the whole plate
           a glare first, coming down into focus on the settle in one
           exposure; js/motion.js plays it backwards into the glare to close
           it. The package's rise and scale of the panel and the headline's
           shrink are not light's and are off; the glow's slow pulse stays. */
        [data-theme='light'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) {
            animation: kp-sig-light-expose var(--kp-sig-light-time) var(--kp-sig-light-ease) backwards;
        }

        [data-theme='light'] .kp-alarm:not([data-kp-alarm-motion='still']) :is(.kp-alarm__panel, .kp-alarm__title, .kp-alarm__detail) {
            animation: none;
        }

        /* The calendar's busy layers come out of the glare as anything that
           arrives and go back into it as anything that leaves: js/calendar.js
           marks a layer `[data-kp-leaving]` while its state goes
           (`--kp-calendar-busy-leave: hold`), and the rules below keep it drawn
           through the leave. */
        [data-theme='light'] :is(.kp-calendar__day-busy, .kp-calendar__busy) {
            --kp-calendar-busy-leave: hold;
            transition: none;
        }

        [data-theme='light']
            :is(.kp-calendar--busy-days, .kp-calendar--busy-whole:not(:has(> .kp-calendar__grid[aria-busy='true'])))
            .kp-calendar__day[data-kp-tone='loading']
            > .kp-calendar__day-busy:not([data-kp-leaving]),
        [data-theme='light'] .kp-calendar--busy-whole:has(> .kp-calendar__grid[aria-busy='true']) > .kp-calendar__busy:not([data-kp-leaving]) {
            animation: kp-sig-light-expose var(--kp-sig-light-time) var(--kp-sig-light-ease) backwards;
        }

        [data-theme='light'] .kp-calendar__day:has(> .kp-calendar__day-busy[data-kp-leaving]) {
            position: relative;
        }

        [data-theme='light'] .kp-calendar__day-busy[data-kp-leaving] {
            --kp-spinner-size: var(--kp-calendar-spinner, 0.75rem);
            position: absolute;
            inset-inline: 0;
            inset-block-end: 0.125rem;
            display: flex;
            justify-content: center;
            line-height: 0;
        }

        [data-theme='light'] .kp-calendar--busy-whole > .kp-calendar__busy[data-kp-leaving] {
            --kp-spinner-size: var(--kp-calendar-busy-spinner, 2.5rem);
            z-index: 1;
            display: grid;
            place-self: center;
            place-items: center;
            padding: var(--kp-space-md, 1rem);
            border-radius: var(--radius, 0.5rem);
            background: var(--card);
            box-shadow: 0 0 0 1px var(--border);
            line-height: 0;
        }

        /* The bar [Kenny via the coordinator, 2026-10-12: the navbar's opening
           and closing are in scope]. Light decides no motion for the bar, so
           it takes its menus' (G3): the hover dropdown, the mega menu and the
           phone bar's panel are a glare under the bar that comes into focus,
           and go back into the glare to close, the same frames on the inverse
           curve. Transitions, not keyframes: a close begun halfway turns round
           where it stands, and the mega menu's item is held by its transition
           (js/components.js settleClosing). Firefox does not hold `display`:
           the hover dropdown and the phone panel are held by the script for
           `--kp-nav-close-time`, the exposure. */
        [data-theme='light'] .kp-nav {
            --kp-nav-close-time: 700ms;
        }

        [data-theme='light'] .kp-nav:not([data-kp-nav-open], [data-kp-nav-closing]) .kp-nav__links > li > .kp-nav__menu,
        [data-theme='light'] .kp-nav:has(> .kp-nav__toggle) > .kp-nav__links {
            opacity: 0;
            filter: var(--kp-sig-light-glare);
            transition:
                opacity var(--kp-sig-light-time) var(--kp-sig-light-ease-out),
                filter var(--kp-sig-light-time) var(--kp-sig-light-ease-out);
        }

        [data-theme='light']
            .kp-nav:not([data-kp-nav-open], [data-kp-nav-closing])
            .kp-nav__links
            > li:is(:hover, :focus-within, [data-kp-nav-menu-open])
            > .kp-nav__menu:not(.kp-nav__menu--wide),
        [data-theme='light']
            .kp-nav:not([data-kp-nav-open], [data-kp-nav-closing])
            .kp-nav__links
            > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true']))
            > .kp-nav__menu--wide,
        [data-theme='light'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links {
            opacity: 1;
            filter: none;
            transition:
                opacity var(--kp-sig-light-time) var(--kp-sig-light-ease),
                filter var(--kp-sig-light-time) var(--kp-sig-light-ease);
        }

        @starting-style {
            [data-theme='light']
                .kp-nav:not([data-kp-nav-open], [data-kp-nav-closing])
                .kp-nav__links
                > li:is(:hover, :focus-within, [data-kp-nav-menu-open])
                > .kp-nav__menu:not(.kp-nav__menu--wide),
            [data-theme='light']
                .kp-nav:not([data-kp-nav-open], [data-kp-nav-closing])
                .kp-nav__links
                > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true']))
                > .kp-nav__menu--wide,
            [data-theme='light'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links {
                opacity: 0;
                filter: var(--kp-sig-light-glare);
            }
        }

        /* A dropdown the pointer or the focus has left is drawn through its
           close by the mark the script puts on its item. */
        [data-theme='light']
            .kp-nav:not([data-kp-nav-open], [data-kp-nav-closing])
            .kp-nav__links
            > li[data-kp-nav-closing]:not(:hover, :focus-within, [data-kp-nav-menu-open])
            > .kp-nav__menu:not(.kp-nav__menu--wide) {
            display: block;
        }

        /* Wide, the phone bar's links are the bar itself: nothing is exposed. */
        @container kp-nav (min-width: 40.0001rem) {
            [data-theme='light'] .kp-nav:has(> .kp-nav__toggle) > .kp-nav__links {
                opacity: 1;
                filter: none;
                transition: none;
            }
        }
    }

    /* A reader who asked for no motion gets no close to wait for. */
    @media (prefers-reduced-motion: reduce) {
        [data-theme='light'] .kp-nav {
            --kp-nav-close-time: 0ms;
        }
    }
}

