    /* ── The scrollbar joins the theme ────────────────────────────────── */

    [data-theme='grotesk'] {
        scrollbar-color: var(--foreground) var(--background);
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above are what they get. The
       durations are literal because check-motion.mjs computes DI5's rate
       from them; the matching --kp-* knobs are what js/effects.js reads. */
    @media (prefers-reduced-motion: no-preference) {
        /* (a) The headline's blur+brightness resolve: 600ms (five units), one-shot. */
        [data-theme='grotesk'][data-kp-effects] [data-kp-reveal='headline'].is-sharpening {
            animation: kp-sharpen-in 600ms linear forwards;
        }

        /* (c) The section rule draw-in: 360ms, delayed 600ms so it follows
           the headline settling — the demo's own reading. */
        [data-theme='grotesk'] [data-kp-reveal='rule']::after {
            transition: transform var(--kp-rule-draw) linear var(--kp-rule-delay);
        }

        /* (d) The redaction: a monotone three-step cut, staggered ~90ms. */
        /* The text switches from transparent to ink in no time, once the
           bar has finished cutting away (KT8: no mid-transition colour). */
        [data-theme='grotesk'] .kp-card[data-kp-reveal='emphasis'] mark {
            transition:
                background-size var(--kp-redact-cut) steps(3, end),
                color 0s linear var(--kp-redact-cut);
        }

        [data-theme='grotesk'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2) {
            transition-delay: var(--kp-redact-stagger), var(--kp-redact-cut);
        }

        [data-theme='grotesk'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3) {
            transition-delay: calc(2 * var(--kp-redact-stagger)), var(--kp-redact-cut);
        }

        /* (b) The nav/footer link and (e) the button mirror-invert: colour
           only, the theme's own two-speed and fx-duration/fx-ease. */
        [data-theme='grotesk'] .kp-nav__link,
        [data-theme='grotesk'] .kp-footer a {
            transition-property: color;
        }

        [data-theme='grotesk'] .kp-button {
            transition:
                background-color var(--fx-duration) var(--fx-ease),
                color var(--fx-duration) var(--fx-ease),
                border-color var(--fx-duration) var(--fx-ease);
        }

        /* (f) The confirmation dialog: Kenny's rule of 2026-09-08 (a native
           <dialog>, never a button that relabels itself), the theme's own
           fx-duration/fx-ease (120ms, linear: on time — written as
           literals here, not var(--fx-duration), because check-motion.mjs
           computes DI5's rate from the animation's own declared duration),
           opacity+transform on the panel only. */
        [data-theme='grotesk'] .kp-dialog[open] {
            animation: kp-dialog-in 120ms linear;
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* Every keyframe here has its row in TIMINGS (js/effects.js). */
    @keyframes kp-sharpen-in {
        to {
            filter: blur(0) brightness(1);
        }
    }

    /* (f) The dialog: opacity+transform on the panel only, once. */
    @keyframes kp-dialog-in {
        0% {
            opacity: 0;
            transform: translateY(6px);
        }

        100% {
            opacity: 1;
            transform: none;
        }
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — heavy rules above and below, half-bold. */
    [data-theme='grotesk'] .kp-marquee {
        border-block: 2px solid var(--foreground);
        font-weight: 600;
        letter-spacing: -0.01em;
        --kp-marquee: 30000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    /* A mega menu's group headings speak in the caption's voice [scope-48]. */
    [data-theme='grotesk'] .kp-nav__menu[data-kp-menu-label]::before,
    [data-theme='grotesk'] .kp-nav__menu--wide .kp-nav__menu-heading {
        color: var(--primary);
        font-weight: 600;
        letter-spacing: 0.02em;
        border-block-end: 2px solid var(--foreground);
    }

    /* ── The side navigation [feat-nav-3] ────────────────────────────
       Kenny said this one can be better. Its whole idea is the grid, so
       the column shows it: every row on a baseline, and the one you are
       on set in the heavy weight this theme otherwise keeps for headings
       — the type carries the state rather than a colour. */
    [data-theme='grotesk'] .kp-sidenav {
        --kp-sidenav-surface: var(--card);
        --kp-sidenav-gap: 0;
        --kp-sidenav-list-pad: 0;
        border-inline-end: 1px solid var(--border-strong);
    }

    [data-theme='grotesk'] .kp-sidenav__title {
        letter-spacing: 0.16em;
        text-transform: uppercase;
        border-block-end: 1px solid var(--border);
    }

    [data-theme='grotesk'] .kp-sidenav__link,
    [data-theme='grotesk'] .kp-sidenav__category-toggle {
        border-radius: 0;
        border-block-end: 1px solid var(--border);
        padding-inline: 0.9rem;
    }

    [data-theme='grotesk'] .kp-sidenav__link[aria-current='page'] {
        background: none;
        color: var(--foreground);
        font-weight: 800;
        letter-spacing: -0.01em;
    }

    /* ── Back to top, and a picture [feat-page-1, feat-media-1] ──────
       The grid: square corners, a caption on the baseline, and nothing
       that is not a rule. */
    [data-theme='grotesk'] .kp-to-top {
        border-radius: 0;
        border: 1px solid var(--border-strong);
    }

    [data-theme='grotesk'] .kp-media {
        border: 1px solid var(--border-strong);
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-media-figure > figcaption {
        border-block-start: 1px solid var(--border);
        padding-block-start: 0.4rem;
        letter-spacing: 0.02em;
    }

    /* The figure carries the caption's voice, so the decision sits with
       the picture rather than with the words under it. */
    [data-theme='grotesk'] .kp-media-figure {
        color: var(--foreground);
    }

    /* ── The pressed state the register had been cancelling [fix-12] ───
       `kp.register` sits after `kp.components`, and a layer beats a state:
       a register writing `.kp-button:hover { background: ... }` outranks
       the base layer's `.kp-button:active`, so pressing the button changed
       nothing. Kenny found it on Shade (dark), 2026-09-11 — "als ik gewoon
       blijf klikken op de knop zelf, dan gebeurt er precies niks".
       Grotesk's pressed states are written out with the buttons above
       (paper, never the base layer's grey; a red face deepens its red), so
       what a press paints is this register's own decision. */

    /* ── The baseline appears [scope-12, approved 2026-09-12] ──────────
       Grotesk is Swiss typography, and the instrument of Swiss typography
       is the line the letters stand on. Touching a control draws that
       line — not the control's bottom edge, the TYPE's baseline — from
       the leading edge out past the word, in the theme's one red. The
       letters end up standing ON it and the descenders cross it, which is
       what a baseline rule does.

       It says what the theme is about rather than decorating it, and it
       never covers the letters, so there is no contrast question. The
       press thickens the rule into the deeper red, downward, so its top
       edge stays exactly on the baseline.

       This replaces a first proposal that snapped `letter-spacing` from 0
       to 0.12em: about 13.8px of extra label width on an eight-character
       word, which grew the control and shifted everything beside it —
       Kenny's rejection of 2026-09-11. Nothing here changes the box. The
       rule is an absolutely positioned child, so it is out of flow even
       inside `.kp-button__label`'s inline-flex.

       `--kp-baseline-drop` is MEASURED, not guessed. Firefox, 2026-09-12,
       from the label's own font metrics: Inter 700 at 16px in a 19.20px
       line box reports ascent 16.00 and descent 4.00, so the baseline sits
       (19.20 − 20.00) / 2 + 4.00 = 3.60px above the box bottom — 0.225em.
       The first attempt measured it with a zero-width inline probe and got
       9.60px, because `.kp-button__label` is an inline-flex container and
       a probe inside it becomes a flex item, where `vertical-align` does
       nothing at all. */
    [data-theme='grotesk'] .kp-button__label,
    [data-theme='grotesk'] .kp-nav__link,
    [data-theme='grotesk'] .kp-sidenav__link {
        position: relative;
    }

    [data-theme='grotesk'] .kp-button__label::after,
    [data-theme='grotesk'] .kp-nav__link::after,
    [data-theme='grotesk'] .kp-sidenav__link::after {
        content: '';
        position: absolute;
        inset-inline: calc(-1 * var(--kp-baseline-reach, 0.5rem));
        /* The rule's TOP edge on the baseline, so the letters stand on it. */
        inset-block-end: calc(var(--kp-baseline-drop, 0.225em) - var(--kp-baseline-weight, 2px));
        block-size: var(--kp-baseline-weight, 2px);
        background: var(--kp-baseline-colour, var(--primary));
        scale: 0 1;
        transform-origin: left center;
        pointer-events: none;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] .kp-button__label::after,
        [data-theme='grotesk'] .kp-nav__link::after,
        [data-theme='grotesk'] .kp-sidenav__link::after {
            transition: scale var(--fx-duration, 220ms) var(--fx-ease, ease);
        }
    }

    [data-theme='grotesk'] .kp-nav__link:hover::after,
    [data-theme='grotesk'] .kp-nav__link:focus-visible::after,
    [data-theme='grotesk'] .kp-sidenav__link:hover::after,
    [data-theme='grotesk'] .kp-sidenav__link:focus-visible::after {
        scale: 1 1;
    }

    /* The bar's disclosure button (the mega menu's "Equipment") is one of the bar's links, so its
       ::after is the same baseline rule (review round 2, Kenny 2026-10-13: hovering it drew "a small
       slanted line"). css/components.css draws the disclosure's caret on that same ::after (a
       0.4em box, two 1.5px borders, turned 45 degrees, -135 while open); left in place, the rule
       above took the caret's width, borders and turn and drew a 6 px slanted stroke. The caret's
       own properties are cleared here, in the open state too, so the rule spans the word as it
       does under every other link; grotesk's dropdown link ("Readings") shows no caret either. */
    [data-theme='grotesk'] .kp-nav__link.kp-nav__disclosure::after,
    [data-theme='grotesk'] .kp-nav__link.kp-nav__disclosure[aria-expanded='true']::after {
        display: block;
        margin: 0;
        inline-size: auto;
        border: 0;
        rotate: none;
        translate: none;
    }

    /* The press thickens the rule [Kenny, 2026-10-07: "the rule thickens", his
       scope-12]: at once and for as long as it is held, the baseline under a
       button's words is out, 4 px, in the deeper red; a nav link's was out
       already (it is drawn by hovering) and only thickens. Nothing here is in
       the transition list, so a click shorter than 120 ms still shows — the
       reading that fixed Shade (light) and Shade (dark). */
    [data-theme='grotesk'] .kp-button:active:not(:disabled) .kp-button__label::after {
        scale: 1 1;
        transition: none;
    }

    [data-theme='grotesk'] .kp-button:active:not(:disabled) .kp-button__label,
    [data-theme='grotesk'] .kp-nav__link:active,
    [data-theme='grotesk'] .kp-sidenav__link:active {
        --kp-baseline-weight: var(--kp-baseline-weight-pressed, 4px);
        --kp-baseline-colour: var(--primary-active);
    }

    /* ── Read-only fields [gap-11] ────────────────────────────────────── */

    /* A read-only field is a value on a record, not a box to type in. This
       register sets the field's border and ground in kp.register, which
       beats the read-only look in kp.components, so read-only painted like
       an editable field. The state is answered here, on top of the rest
       look, which stays as it was. */
    [data-theme='grotesk'] .kp-field__input[readonly] {
        border-style: dashed;
        background-color: var(--muted);
    }

    /* ── The palette's trigger in the bar [scope-48, scope-80] ─────────── */

    /* In the voice of this register's own nav links (Kenny, 2026-09-14,
       search-voice "Per thema"): bold muted words that take the full ink
       when pointed at, while the baseline rule this register draws under its
       links grows out from the start. The link's typeface, case, spacing,
       shape and pointer answer are restated here, because the trigger is a
       button beside the list rather than a link in it. The underline a plain
       link carries is not: it says "this is a link", and the trigger is not
       one. */
    [data-theme='grotesk'] .kp-nav__search .kp-nav__search-trigger {
        position: relative;
        padding-inline: 0;
        font-weight: 600;
        letter-spacing: 0.01em;
        white-space: nowrap;
        border: 0;
        border-radius: 0;
        background: none;
        color: var(--muted-foreground);
    }

    [data-theme='grotesk'] .kp-nav__search .kp-nav__search-trigger:hover,
    [data-theme='grotesk'] .kp-nav__search .kp-nav__search-trigger:focus-visible {
        color: var(--foreground);
    }

    [data-theme='grotesk'] .kp-nav__search .kp-nav__search-trigger::after {
        content: '';
        position: absolute;
        inset-inline: calc(-1 * var(--kp-baseline-reach, 0.5rem));
        inset-block-end: calc(var(--kp-baseline-drop, 0.225em) - var(--kp-baseline-weight, 2px));
        block-size: var(--kp-baseline-weight, 2px);
        background: var(--kp-baseline-colour, var(--primary));
        scale: 0 1;
        transform-origin: left center;
        pointer-events: none;
    }

    [data-theme='grotesk'] .kp-nav__search .kp-nav__search-trigger:hover::after,
    [data-theme='grotesk'] .kp-nav__search .kp-nav__search-trigger:focus-visible::after {
        scale: 1 1;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] .kp-nav__search .kp-nav__search-trigger::after {
            transition: scale var(--fx-duration, 220ms) var(--fx-ease, ease);
        }
    }

    /* ── The alarm [scope-94] ──────────────────────────────────────────────
       A poster, not a screen: the whole window is its red, the headline enormous in white with tight spacing, set flush left, with no frame and no bars. Every colour is one of this theme's tokens. The
       button keeps this register's shape and takes the alarm's paint, on
       selectors long enough to outrank this register's own button states;
       the dialog takes no focus ring, because in the auto mode the whole
       screen is what has focus. */
    [data-theme='grotesk'] .kp-alarm {
        --kp-alarm-ground: var(--destructive);
        --kp-alarm-ink: var(--destructive-foreground);
        --kp-alarm-soft: var(--destructive-foreground);
        --kp-alarm-split: var(--foreground);
        --kp-alarm-on-ink: var(--destructive);
        --kp-alarm-glow: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-halo: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-scan: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-vignette: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-bar: 0rem;
        --kp-alarm-frame: 0 solid;
        /* Smaller than the poster it was: at 864x450 the headline pushed
           20px past the frame [scope-108]. */
        --kp-alarm-title-size: clamp(2rem, 10cqi, 8rem);
        --kp-alarm-title-tracking: -0.04em;
    }

    [data-theme='grotesk'] .kp-alarm:focus-visible {
        outline: none;
    }

    [data-theme='grotesk'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack,
    [data-theme='grotesk'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:hover:not(:disabled),
    [data-theme='grotesk'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:active:not(:disabled) {
        border-color: var(--kp-alarm-ink);
        background: var(--kp-alarm-ink);
        color: var(--kp-alarm-on-ink);
        text-shadow: none;
    }

    [data-theme='grotesk'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:is(:hover, :focus-visible):not(:disabled):not(:active) {
        background: var(--kp-alarm-on-ink);
        color: var(--kp-alarm-ink);
    }

    [data-theme='grotesk'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep,
    [data-theme='grotesk'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep:is(:hover, :focus-visible):not(:disabled) {
        border-color: currentColor;
        background: transparent;
        color: inherit;
        text-shadow: none;
    }

    [data-theme='grotesk'] .kp-alarm__panel {
        justify-items: start;
        text-align: start;
    }

    /* A submenu item's mark [Kenny, 2026-09-20]: an em dash: typography, not ornament. */
    [data-theme='grotesk'] .kp-sidenav__submenu .kp-sidenav__link {
        --kp-sidenav-submenu-mark: '—';
    }

    /* ── A plate is a column under its rule [G7; Kenny, 2026-10-07 on
       research/grotesk-character: surface = a column under its rule, no box].
       A card, a key figure, the busy panel and the page header are white
       paper with no frame: a 3 px ink rule along the top says where it starts
       and the words stand flush left on the column. The grid's hairlines
       stay under data and on the page (the twelve columns). What floats over
       the page (dialog, popover, menu, toast, tooltip) keeps its 3 px ink
       frame above, so it stands off what is under it. No shadow, no blur, no
       tint, nothing translucent: the plate has no paper of its own, so the
       red plate behind it (the signature layer) shows only its ink. ── */
    [data-theme='grotesk'] :is(.kp-card, .kp-kpi, .kp-datatable__busy-panel, .kp-page-header) {
        border: 0;
        border-block-start: 3px solid var(--foreground);
        border-radius: 0;
        background: transparent;
        box-shadow: none;
    }

    [data-theme='grotesk'] :is(.kp-card, .kp-kpi) {
        padding: 0.5rem 0 0.65rem;
    }

    [data-theme='grotesk'] .kp-page-header {
        padding-block: 0.6rem 0.7rem;
    }

    /* A key figure or a card that is a link or a toggle: hovered, its rule
       turns red and thickens to 7 px (the rule is 3, the red goes 4 deeper
       inside it, so the words stay where they are) and it takes a 4 % wash of
       the red [hover = a bar on the edge thickens]. A filter that is on keeps
       its pressed colours (the package's). */
    [data-theme='grotesk'] :is(a.kp-kpi, .kp-kpi--toggle, .kp-kpi--trend):hover {
        border-block-start-color: var(--primary);
        background: color-mix(in oklab, var(--primary) 4%, var(--card));
        box-shadow: inset 0 4px 0 0 var(--primary);
    }

    /* ── A warning is indexed [G13; Kenny, 2026-10-07: tone = indexed]. A key
       figure in a tone carries a 6 px bar of the tone down its start edge, like
       a thumb index, and the tone's word, set in bold before its figure, so
       colour is never the only carrier (DI4); the figure itself stays ink on
       paper (the package's plate under the figure is taken off). The words
       are knobs (--kp-sig-gr-word-warning, --kp-sig-gr-word-destructive) so
       a page in another language sets its own. ── */
    [data-theme='grotesk'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) {
        padding-inline-start: 0.9rem;
        border-inline-start: 6px solid var(--kp-sig-gr-tone);
        box-shadow: none;
    }

    [data-theme='grotesk'] .kp-kpi[data-kp-tone='warning'] {
        --kp-sig-gr-tone: var(--warning);
    }

    [data-theme='grotesk'] .kp-kpi[data-kp-tone='destructive'] {
        --kp-sig-gr-tone: var(--destructive);
    }

    [data-theme='grotesk'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value {
        padding-inline: 0;
        background: none;
        color: var(--foreground);
    }

    [data-theme='grotesk'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value::before {
        margin-inline-end: 0.4em;
        font-family: var(--theme-font-body);
        font-size: 0.78rem;
        font-weight: 700;
        letter-spacing: 0;
        vertical-align: 0.35em;
    }

    [data-theme='grotesk'] .kp-kpi[data-kp-tone='warning'] .kp-kpi__value::before {
        content: var(--kp-sig-gr-word-warning, 'Warning');
    }

    [data-theme='grotesk'] .kp-kpi[data-kp-tone='destructive'] .kp-kpi__value::before {
        content: var(--kp-sig-gr-word-destructive, 'Failed');
    }

    /* The change sits on a square plate with the timetable's arrows, ↗ and ↘
       [G13]. A change with a tone keeps the package's status pair. */
    [data-theme='grotesk'] .kp-kpi__delta {
        padding-inline: 0.3em;
        border-radius: 0;
        font-family: var(--theme-font-body);
        font-weight: 700;
    }

    [data-theme='grotesk'] .kp-kpi__delta:not([data-kp-tone]) {
        background: var(--secondary);
        color: var(--secondary-foreground);
    }

    [data-theme='grotesk'] .kp-kpi__delta[data-kp-direction='up']::before {
        content: '↗\00a0';
    }

    [data-theme='grotesk'] .kp-kpi__delta[data-kp-direction='down']::before {
        content: '↘\00a0';
    }
}

/* ── Signature [scope-140] ─────────────────────────────────────────────── */
/* grotesk's approved signature (Kenny, 2026-10-03, three review rounds): the
   progress bar and the ten elements (spinner, skeleton, switch, check and
   radio, toast, dialog, tooltip, wizard steps, empty state, link hover),
   ported once from research/progress-signature/themes/grotesk.css and research/signature-elements/themes/grotesk.css
   and maintained here from now on. In kp.signature, which css/themes.css
   orders after kp.register, so it draws over the register exactly as the
   approved demos did, whatever the weight of a register selector. */
@layer kp.signature {
    /* The link signature is for links in running text; a link in a navigation,
       a menu, a breadcrumb (a nav) or the footer keeps its own component's look
       (scope-93: no link colour in a navigation). */
    [data-theme='grotesk'] .kp-progressbar {
        --kp-progressbar-height: calc(1rem * var(--kp-progressbar-scale, 1));
        --gr-ink: var(--border-strong);
        --gr-red: var(--primary);
        --gr-base: 2px;
        --gr-col: calc(100% / 12);
    }

    [data-theme='grotesk'] .kp-progressbar__track {
        border-radius: 0;
        background:
            linear-gradient(var(--gr-ink), var(--gr-ink)) left bottom / 100% var(--gr-base) no-repeat,
            linear-gradient(color-mix(in oklab, var(--gr-ink) 28%, transparent), color-mix(in oklab, var(--gr-ink) 28%, transparent)) right top / 1px
                100% no-repeat,
            linear-gradient(90deg, color-mix(in oklab, var(--gr-ink) 28%, transparent) 0 1px, transparent 1px) 0 0 / var(--gr-col) 100% repeat-x,
            var(--card);
    }

    [data-theme='grotesk'] .kp-progressbar__fill {
        inset-block-end: var(--gr-base);
        background: var(--gr-red);
        transition: clip-path var(--fx-duration, 120ms) var(--fx-ease, cubic-bezier(0.2, 0, 0, 1));
    }

    [data-theme='grotesk'] .kp-progressbar__head {
        inline-size: 3px;
        background: var(--gr-ink);
        transform: translateX(calc(var(--kp-value) * (100cqi - 3px)));
        transition: transform var(--fx-duration, 120ms) var(--fx-ease, cubic-bezier(0.2, 0, 0, 1));
    }

    /* The busy bar is the slab [bars = the slab; Kenny, 2026-10-07 on
       research/grotesk-character: "one heavy ink bar, its red plate turning
       clockwise behind it"]: a solid ink bar the full width and, behind it,
       the same bar in red, `--kp-sig-gr-r` away, which closes in clockwise
       at an even pace, falls into register (the red goes behind the black)
       and dwells, then opens out again clockwise: 2640 ms. Only the red
       fringe shows until the plates register; nothing in it is thinner than
       3 px. A bar with a share is the red fill on the ruled track, as before.
       Standing still the plate lies a little out of register. */
    [data-theme='grotesk'] .kp-progressbar[data-kp-indeterminate] {
        --kp-sig-gr-r: calc(3px * var(--kp-progressbar-scale, 1));
    }

    [data-theme='grotesk'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__track {
        background: var(--card);
    }

    [data-theme='grotesk'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__track::before {
        content: '';
        position: absolute;
        inset: var(--kp-sig-gr-r);
        background: var(--gr-red);
        --kp-sig-gr-a: 39.8deg;
        --kp-sig-gr-q: 0.78;
        translate: calc(var(--kp-sig-gr-r) * var(--kp-sig-gr-q) * cos(var(--kp-sig-gr-a)))
            calc(var(--kp-sig-gr-r) * var(--kp-sig-gr-q) * sin(var(--kp-sig-gr-a)));
    }

    [data-theme='grotesk'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
        inset: var(--kp-sig-gr-r);
        inline-size: auto;
        clip-path: none;
        animation: none;
        background: var(--gr-ink);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__track::before {
            animation: kp-sig-grotesk-loop var(--kp-sig-gr-loop) linear infinite;
        }
    }

    /* ── The grammar [Kenny, 2026-10-07 on research/grotesk-character: all
       nineteen questions approved; themes/grotesk/CHARACTER.md "Applied"].
       The anchor is Out of register: a second, red plate under the black ink;
       where it stands says what the part is (slipped: arriving, waiting,
       changing; in register, behind the black: there, held). It runs on time:
       an even pace (`--fx-ease` is linear), a dead stop, a dwell, in whole
       units of the register's 120 ms: contact 1 unit, a set 2, a fall 8, a
       loop 22. Written as literals: js/motion.js reads its caps from the root
       and parses their milliseconds. ── */
    [data-theme='grotesk'] {
        --kp-sig-gr-unit: 120ms;
        --kp-sig-gr-set: 240ms;
        --kp-sig-gr-fall: 960ms;
        --kp-sig-gr-loop: 2640ms;
        /* The second plate: the red, and how far it slipped (a part says its own). */
        --kp-sig-gr-plate: var(--primary);
        --kp-sig-gr-r: 6px;
        --kp-sig-gr-draw: var(--kp-rule-draw, 360ms);
        --kp-sig-gr-ease: linear;
        --kp-sig-gr-cols: repeating-linear-gradient(to right, hsl(from var(--foreground) h s l / 0.06) 0 1px, transparent 1px calc(100% / 12));
        /* A close is as long as a fall, a resize is the cut's two units, and
           nothing is dimmed while it waits: the proof says busy (G7). */
        --kp-close-max: var(--kp-sig-gr-fall);
        --kp-size-max: var(--kp-sig-gr-set);
        --kp-busy-opacity: 1;
    }

    /* A part's second plate slips less on a small part and more on a window. */
    [data-theme='grotesk'] :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-kpi__link, .kp-tag, .kp-badge) {
        --kp-sig-gr-r: 4px;
    }

    [data-theme='grotesk'] :is(.kp-dialog, .kp-toast, .kp-tooltip, .kp-popover, .kp-menu) {
        --kp-sig-gr-r: 8px;
    }

    /* A red face's second plate is the ink: its own red would not show. */
    [data-theme='grotesk'] :is(.kp-button--primary, .kp-button--destructive) {
        --kp-sig-gr-plate: var(--foreground);
    }

    /* The spinner is the twin that turns [spinner = the twin turns]: a square
       ink outline (3 px at the least) and, behind it, its red twin, which
       turns clockwise at an even pace and is in register every quarter turn
       (a square looks the same every 90 degrees), where it rests for 3
       units: a quarter turn in 8 units, 2640 ms for half a turn. It never
       stops turning and never turns back. Standing still, the twin lies a
       little turned. On a red face the twin is the ink and the square the
       face's own white. */
    [data-theme='grotesk'] .kp-spinner {
        --kp-sig-gr-t: max(3px, calc(var(--kp-spinner-size, 1.25rem) * 0.15));
        position: relative;
        border: 0;
        border-radius: 0;
        background: none;
        animation: none;
    }

    [data-theme='grotesk'] .kp-spinner::before,
    [data-theme='grotesk'] .kp-spinner::after {
        content: '';
        position: absolute;
        inset: 0;
        box-sizing: border-box;
        border: var(--kp-sig-gr-t) solid var(--kp-sig-gr-c);
    }

    [data-theme='grotesk'] .kp-spinner::before {
        --kp-sig-gr-c: var(--primary);
        rotate: 22deg;
    }

    [data-theme='grotesk'] .kp-spinner::after {
        --kp-sig-gr-c: var(--foreground);
    }

    [data-theme='grotesk'] :is(.kp-button--primary, .kp-button--destructive) .kp-spinner::before {
        --kp-sig-gr-c: var(--foreground);
    }

    [data-theme='grotesk'] .kp-button--primary .kp-spinner::after {
        --kp-sig-gr-c: var(--primary-foreground);
    }

    [data-theme='grotesk'] .kp-button--destructive .kp-spinner::after {
        --kp-sig-gr-c: var(--destructive-foreground);
    }

    /* The skeleton is the proof [loading = out of register]: the place a
       reading will stand is printed in two plates, the ink on ::after and,
       under it, the red on ::before, which closes in clockwise at an even
       pace, falls into register (the red vanishes behind the black), dwells
       for 4 units and opens out again clockwise: 22 units, 2640 ms, the
       lines of one skeleton together. The first line is the heading, twice
       as thick. Standing still, the red lies a little out of register. A
       block and a circle are drawn as a frame. */
    [data-theme='grotesk'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        --kp-sig-gr-r: 0.65rem;
        position: relative;
        block-size: 0.7rem;
        border-radius: 0;
        background: none;
        animation: none;
    }

    [data-theme='grotesk'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block):first-child {
        block-size: 1.4rem;
        margin-block-end: 0.5rem;
    }

    [data-theme='grotesk'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) + .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        margin-block-start: 0.65rem;
    }

    [data-theme='grotesk'] .kp-skeleton:is(.kp-skeleton--circle, .kp-skeleton--block) {
        --kp-sig-gr-r: 6px;
        position: relative;
        background: none;
        animation: none;
    }

    [data-theme='grotesk'] .kp-skeleton::before,
    [data-theme='grotesk'] .kp-skeleton::after {
        content: '';
        position: absolute;
        inset: 0;
        box-sizing: border-box;
    }

    [data-theme='grotesk'] .kp-skeleton:is(.kp-skeleton--circle, .kp-skeleton--block)::before,
    [data-theme='grotesk'] .kp-skeleton:is(.kp-skeleton--circle, .kp-skeleton--block)::after {
        border: 3px solid var(--kp-sig-gr-c);
    }

    [data-theme='grotesk'] .kp-skeleton--circle::before,
    [data-theme='grotesk'] .kp-skeleton--circle::after {
        border-radius: 50%;
    }

    [data-theme='grotesk'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)::before {
        background: var(--kp-sig-gr-c);
    }

    [data-theme='grotesk'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)::after {
        background: var(--kp-sig-gr-c);
    }

    [data-theme='grotesk'] .kp-skeleton::before {
        --kp-sig-gr-c: var(--primary);
        --kp-sig-gr-a: 37.9deg;
        --kp-sig-gr-q: 0.57;
        translate: calc(var(--kp-sig-gr-r) * var(--kp-sig-gr-q) * cos(var(--kp-sig-gr-a)))
            calc(var(--kp-sig-gr-r) * var(--kp-sig-gr-q) * sin(var(--kp-sig-gr-a)));
    }

    [data-theme='grotesk'] .kp-skeleton::after {
        --kp-sig-gr-c: var(--foreground);
    }

    /* A meter that measures, and a day, an entry or a card that waits: the
       part's own proof, a red copy of it travelling the same loop behind it. */
    [data-theme='grotesk'] :is(.kp-calendar__day[data-kp-tone='loading'], .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading]) {
        --kp-sig-gr-a: 39.8deg;
        --kp-sig-gr-q: 0.78;
        filter: drop-shadow(
            calc(var(--kp-sig-gr-r) * var(--kp-sig-gr-q) * cos(var(--kp-sig-gr-a)))
                calc(var(--kp-sig-gr-r) * var(--kp-sig-gr-q) * sin(var(--kp-sig-gr-a))) 0
                rgb(from var(--kp-sig-gr-plate) r g b / clamp(0, calc(var(--kp-sig-gr-q) * 40), 1))
        );
        animation: none;
    }

    [data-theme='grotesk'] .kp-switch {
        --kp-switch-radius: 0;
