    [data-theme='grotesk'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a):hover {
        color: var(--foreground);
        text-decoration-thickness: 4px;
        text-underline-offset: 0.12em;
