    @media (prefers-reduced-motion: no-preference) {
        /* Waiting: the red plate's loop, 22 units: a gap of 2, one clockwise turn
           in 7 while it closes in, a dwell of 5 in register, one clockwise turn
           out in 8; and the spinner's twin, which turns clockwise throughout. */
        [data-theme='grotesk'] .kp-skeleton::before,
        [data-theme='grotesk'] :is(.kp-calendar__day[data-kp-tone='loading'], .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading]) {
            animation: kp-sig-grotesk-loop var(--kp-sig-gr-loop) linear infinite;
        }

        [data-theme='grotesk'] .kp-spinner::before {
            animation: kp-sig-grotesk-turn var(--kp-sig-gr-loop) linear infinite;
        }

        [data-theme='grotesk'] .kp-switch__input::before {
            transition: transform var(--kp-sig-gr-unit) var(--kp-sig-gr-ease);
        }

        [data-theme='grotesk'] .kp-field__check[type='checkbox']:checked::before {
            animation: kp-sig-grotesk-gr-cut var(--kp-sig-dur) var(--kp-sig-gr-ease) both;
        }

        [data-theme='grotesk'] .kp-field__check[type='radio']:checked::before {
            animation: kp-sig-grotesk-gr-disc var(--kp-sig-dur) var(--kp-sig-gr-ease) both;
        }

        [data-theme='grotesk'] .kp-toast::before {
            animation: kp-sig-grotesk-gr-rule var(--kp-sig-gr-draw) var(--kp-sig-gr-ease) both;
        }

        /* What opens and what arrives is printed in black and its red plate
           falls into register on it [direction = the plate, opening = the
           plate]: it travels the closing spiral clockwise at an even pace,
           8 units, and stops dead in register. Its close is the same fall
           played backwards (js/motion.js plays a dialog's entrance in
           reverse), so a close is an open turned around, as everywhere else. */
        [data-theme='grotesk'] :is(.kp-toast, .kp-dialog, .kp-tooltip) {
            animation: kp-sig-grotesk-fall var(--kp-sig-dur) linear backwards;
        }

        [data-theme='grotesk'] .kp-dialog__title::before {
            animation: kp-sig-grotesk-gr-rule var(--kp-sig-gr-draw) var(--kp-sig-gr-ease) var(--kp-sig-gr-unit) both;
        }

        /* Hovering draws a bar and the press thickens the rule (the register
           layer); focusing is DI2's two-channel ring and, as on every
           arrival, the plate falling into register on the focused part. It
           stays in register for as long as the focus does. */
        [data-theme='grotesk']
            :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-field__input, a.kp-kpi, .kp-kpi--toggle, .kp-kpi__link):focus-visible {
            animation: kp-sig-grotesk-fall var(--kp-sig-gr-fall) linear backwards;
        }

        /* A value that changed is re-registered [live = the plate]. js/update.js
           writes the new value at once and marks its host
           `[data-kp-updating='plate']` for the update's time (the close's and
           the size's longer, times 1.25: 1200 ms; the fall is four fifths of
           it, 960): its red plate falls back into register on it. The value
           never moves. A state word keeps its width-holding ::after; a spark
           is an svg, whose parent carries the mark. */
        [data-theme='grotesk'] {
            --kp-update: plate;
        }

        [data-theme='grotesk'] [data-kp-updating='plate'] {
            --kp-sig-gr-r: 0.14em;
            animation: kp-sig-grotesk-update-plate calc(var(--kp-update-duration, 1200ms) * 0.8) linear backwards;
        }

        [data-theme='grotesk'] .kp-state-word[data-kp-updating='plate'] {
            --kp-sig-gr-r: 0.22em;
        }

        [data-theme='grotesk'] [data-kp-updating='plate']:has(> svg) {
            --kp-sig-gr-r: 3px;
        }
    }

    /* The plate's fall [the anchor, research/grotesk-anchor ga-fall]: one turn
       round the ink in 45 degree steps, clockwise (screen y points down), the
       radius closing from 1 to 0.2 of --kp-sig-gr-r and into register in the
       seventh of eight units, then the dwell. The register frame is a
       transparent shadow, so no hair of red shows at the edge of the ink. The
       plate is the part's own drop-shadow, in the red (a red face's, the ink). */
    @keyframes kp-sig-grotesk-fall {
        0% {
            filter: drop-shadow(var(--kp-sig-gr-r) 0 0 var(--kp-sig-gr-plate));
        }

        10.94% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * 0.626) calc(var(--kp-sig-gr-r) * 0.626) 0 var(--kp-sig-gr-plate));
        }

        21.88% {
            filter: drop-shadow(0 calc(var(--kp-sig-gr-r) * 0.771) 0 var(--kp-sig-gr-plate));
        }

        32.81% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * -0.465) calc(var(--kp-sig-gr-r) * 0.465) 0 var(--kp-sig-gr-plate));
        }

        43.75% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * -0.543) 0 0 var(--kp-sig-gr-plate));
        }

        54.69% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * -0.303) calc(var(--kp-sig-gr-r) * -0.303) 0 var(--kp-sig-gr-plate));
        }

        65.63% {
            filter: drop-shadow(0 calc(var(--kp-sig-gr-r) * -0.314) 0 var(--kp-sig-gr-plate));
        }

        76.56% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * 0.141) calc(var(--kp-sig-gr-r) * -0.141) 0 var(--kp-sig-gr-plate));
        }

        87.5%,
        100% {
            filter: drop-shadow(0 0 0 transparent);
        }
    }

    /* The same fall under another name, so a meter whose tone goes from one
       warning to the other starts it again. */
    @keyframes kp-sig-grotesk-fall-again {
        0% {
            filter: drop-shadow(var(--kp-sig-gr-r) 0 0 var(--kp-sig-gr-plate));
        }

        10.94% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * 0.626) calc(var(--kp-sig-gr-r) * 0.626) 0 var(--kp-sig-gr-plate));
        }

        21.88% {
            filter: drop-shadow(0 calc(var(--kp-sig-gr-r) * 0.771) 0 var(--kp-sig-gr-plate));
        }

        32.81% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * -0.465) calc(var(--kp-sig-gr-r) * 0.465) 0 var(--kp-sig-gr-plate));
        }

        43.75% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * -0.543) 0 0 var(--kp-sig-gr-plate));
        }

        54.69% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * -0.303) calc(var(--kp-sig-gr-r) * -0.303) 0 var(--kp-sig-gr-plate));
        }

        65.63% {
            filter: drop-shadow(0 calc(var(--kp-sig-gr-r) * -0.314) 0 var(--kp-sig-gr-plate));
        }

        76.56% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * 0.141) calc(var(--kp-sig-gr-r) * -0.141) 0 var(--kp-sig-gr-plate));
        }

        87.5%,
        100% {
            filter: drop-shadow(0 0 0 transparent);
        }
    }

    /* The same fall once more, named as js/update.js wants a register's update
       keyframes named (`kp-sig-<theme>-update-*`): it waits for exactly those. */
    @keyframes kp-sig-grotesk-update-plate {
        0% {
            filter: drop-shadow(var(--kp-sig-gr-r) 0 0 var(--kp-sig-gr-plate));
        }

        10.94% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * 0.626) calc(var(--kp-sig-gr-r) * 0.626) 0 var(--kp-sig-gr-plate));
        }

        21.88% {
            filter: drop-shadow(0 calc(var(--kp-sig-gr-r) * 0.771) 0 var(--kp-sig-gr-plate));
        }

        32.81% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * -0.465) calc(var(--kp-sig-gr-r) * 0.465) 0 var(--kp-sig-gr-plate));
        }

        43.75% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * -0.543) 0 0 var(--kp-sig-gr-plate));
        }

        54.69% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * -0.303) calc(var(--kp-sig-gr-r) * -0.303) 0 var(--kp-sig-gr-plate));
        }

        65.63% {
            filter: drop-shadow(0 calc(var(--kp-sig-gr-r) * -0.314) 0 var(--kp-sig-gr-plate));
        }

        76.56% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * 0.141) calc(var(--kp-sig-gr-r) * -0.141) 0 var(--kp-sig-gr-plate));
        }

        87.5%,
        100% {
            filter: drop-shadow(0 0 0 transparent);
        }
    }

    /* The waiting loop, in polar coordinates [slip = clockwise in, clockwise
       out; Kenny, 2026-10-07: "I only like it going clockwise", so the rule of
       opposites is broken on purpose, themes/grotesk/CHARACTER.md §0b]: a gap
       of 2 units, one turn in over 7 while the plate closes in, a dwell of 5 in
       register, one more turn out over 8 as it opens out. --kp-sig-gr-a only
       ever grows, so the plate never turns back, in either text direction. */
    @keyframes kp-sig-grotesk-loop {
        0%,
        9.09% {
            --kp-sig-gr-a: 0deg;
            --kp-sig-gr-q: 1;
        }

        40.91%,
        63.64% {
            --kp-sig-gr-a: 360deg;
            --kp-sig-gr-q: 0;
        }

        100% {
            --kp-sig-gr-a: 720deg;
            --kp-sig-gr-q: 1;
        }
    }

    /* The spinner's twin: a quarter turn in 8 units, a dwell of 3 in register,
       another quarter turn, a dwell of 3: half a turn a loop, in register every
       quarter (a square repeats every 90 degrees). */
    @keyframes kp-sig-grotesk-turn {
        0% {
            rotate: 0deg;
        }

        36.36%,
        50% {
            rotate: 90deg;
        }

        86.36%,
        100% {
            rotate: 180deg;
        }
    }

    @keyframes kp-sig-grotesk-gr-cut {
        from {
            clip-path: inset(0 100% 0 0);
        }

        to {
            clip-path: inset(0);
        }
    }

    @keyframes kp-sig-grotesk-gr-disc {
        from {
            transform: scale(0);
        }
    }

    @keyframes kp-sig-grotesk-gr-rule {
        from {
            transform: scaleX(0);
        }

        to {
            transform: scaleX(1);
        }
    }

    /* Growing and shrinking, this theme's way [scope-142; approved by Kenny
       on research/size-motion, 2026-10-04]. js/motion.js marks a gliding box
       `[data-kp-resizing]` and what arrives in it `[data-kp-arriving]`. */
    @media (prefers-reduced-motion: no-preference) {
        /* ── grotesk: the cut. The box jumps in three hard cuts behind a heavy
           rule, and a new line is cut in from the left in three. ────────── */
        [data-theme='grotesk'] {
            --kp-size-ease: steps(3, jump-end);
        }

        [data-theme='grotesk'] [data-kp-resizing] {
            outline: 3px solid var(--foreground);
            outline-offset: 0;
        }

        /* What arrives in a gliding box is printed in black and its red plate falls
           into register on it, as everything that arrives does [direction = the
           plate; Kenny, 2026-10-07]; the box itself still takes its size in the
           three cuts he picked. */
        [data-theme='grotesk'] [data-kp-arriving] {
            animation: kp-sig-grotesk-fall var(--kp-sig-gr-fall) linear backwards;
        }
    }

    /* Leaving, this theme's way [scope-142; Kenny, 2026-10-07 on
       research/grotesk-character: leave = opens out clockwise, then it is gone].
       js/motion.js marks what leaves `[data-kp-leaving]`, closes its space during
       the exit, and in a row of leaves starts the next one halfway through this
       one. The part stands in black; its red plate leaves register and turns one
       full turn clockwise while it opens out to --kp-sig-gr-r (a fall's 8 units,
       960 ms), and the part is gone at the end of the turn. Arriving was the
       fall closing in clockwise, so the plate has turned the same way the whole
       time: the leave is NOT the arrival played backwards. This is the one place
       the rule that a close is its open reversed is broken on purpose, and
       js/motion.js is told so by this register not declaring
       `--kp-open: reverse-close`: what arrives plays its own fall above, not this
       leave backwards (that would turn the plate counter-clockwise). */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] [data-kp-leaving] {
            --kp-sig-gr-a: 0deg;
            --kp-sig-gr-q: 0;
            filter: drop-shadow(
                calc(var(--kp-sig-gr-r) * var(--kp-sig-gr-q) * cos(var(--kp-sig-gr-a)))
                    calc(var(--kp-sig-gr-r) * var(--kp-sig-gr-q) * sin(var(--kp-sig-gr-a))) 0
                    rgb(from var(--kp-sig-gr-plate) r g b / clamp(0, calc(var(--kp-sig-gr-q) * 40), 1))
            );
            animation: kp-sig-grotesk-leave var(--kp-sig-gr-fall) linear forwards;
        }

        @keyframes kp-sig-grotesk-leave {
            0% {
                --kp-sig-gr-a: 0deg;
                --kp-sig-gr-q: 0;
                visibility: visible;
            }

            99.9% {
                --kp-sig-gr-a: 360deg;
                --kp-sig-gr-q: 1;
                visibility: visible;
            }

            100% {
                --kp-sig-gr-a: 360deg;
                --kp-sig-gr-q: 1;
                visibility: hidden;
            }
        }
    }

    /* ── The meter with a mark, this theme's way [picked by Kenny on
       research/character-meter, rounds 3 and 4, 2026-10-05: shape 1,
       while loading 2, how the share arrives 3, when the tone
       changes 3, the mark past the end 2]. The package's own markup
       and states (setMeter(), js/kpi.js): the track on the meter, the share on
       ::before, the sign past the end or the loading picture on ::after, the
       mark `.kp-meter__mark`. Every animation and transition under
       prefers-reduced-motion: no-preference; still frames otherwise. ── */

    /* The shared part: room past the end, loading without the pulse, the mark
       centred on its width, the package's signs cleared for the shape's own.
       Under :where() so each picked rule below wins as it did in the demo. */
    :where([data-theme='grotesk']) :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-room: 0.625rem;
        box-sizing: border-box;
    }

    :where([data-theme='grotesk']) .kp-meter--inline {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-sig-meter-room));
    }

    /* Each character draws its own loading picture instead of the pulse. */
    :where([data-theme='grotesk']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: clip;
        animation: none;
    }

    :where([data-theme='grotesk']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    /* The mark is centred on its share, whatever its width. */
    :where([data-theme='grotesk']) .kp-meter__mark {
        --kp-sig-meter-mw: 2px;
        box-sizing: border-box;
        inline-size: var(--kp-sig-meter-mw);
        inset-inline-start: calc(clamp(0, var(--kp-mark, 0), 1) * 100% - var(--kp-sig-meter-mw) / 2);
    }

    :where([data-theme='grotesk']) .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - 0.75rem);
    }

    /* The sign past the end, cleared of the package's ▸ for each character
       to draw its own. */
    :where([data-theme='grotesk']) :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '';
        position: absolute;
        inset: auto;
        translate: none;
        color: inherit;
        font-size: 0.75rem;
        line-height: 1;
        text-shadow: none;
        white-space: nowrap;
        pointer-events: none;
    }

    /* A mark past the end keeps the package's sign inside the bar's end, in
       each character's own glyph and ink. */
    :where([data-theme='grotesk']) .kp-meter__mark[data-kp-over]::after {
        content: var(--kp-sig-meter-mo-sign, '▸');
        color: var(--kp-sig-meter-mo-ink, var(--foreground));
        font-family: var(--kp-sig-meter-mo-font, inherit);
        text-shadow:
            0 0 1px var(--kp-sig-meter-mo-halo, var(--card)),
            0 0 2px var(--kp-sig-meter-mo-halo, var(--card));
    }

    /* ── shape: option 1 ── */

    /* ── grotesk · 1 · the rule and its cursor (round 4) ──────────────── */

    /* A steel rule: a white strip in a black outline, a long tick every
       tenth and a short one every fiftieth hanging from its top edge, the
       share a red band along its lower half under the ticks, a black
       cursor triangle pointing up from below as the mark, a bold red +
       past the end. */
    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-meter-height: 0.625rem;
        --kp-sig-meter-room: 0.875rem;
        --kp-sig-meter-mo-ink: var(--foreground);
        border-radius: 0;
        background:
            linear-gradient(90deg, var(--foreground) 1px, transparent 1px) 0 0 / 10% 5px repeat-x,
            linear-gradient(90deg, var(--foreground) 1px, transparent 1px) 0 0 / 2% 2px repeat-x,
            var(--card);
        box-shadow: inset 0 0 0 1px var(--foreground);
    }

    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)::before {
        inset-block: 5px 1px;
        border-radius: 0;
    }

    /* The cursor: a black hairline across the rule, a black triangle under it. */
    [data-theme='grotesk'] .kp-meter__mark {
        inset-block: 0 -1px;
        border-radius: 0;
        background: var(--foreground);
        box-shadow: 0 0 0 1px var(--card);
    }

    [data-theme='grotesk'] .kp-meter__mark::before {
        content: '';
        position: absolute;
        inset-block-start: 100%;
        inset-inline-start: 50%;
        inline-size: 8px;
        block-size: 5px;
        translate: -50% 0;
        background: var(--foreground);
        clip-path: polygon(50% 0, 100% 100%, 0 100%);
    }

    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '+';
        inset-inline-start: calc(100% + 2px);
        inset-block-start: 50%;
        translate: 0 -50%;
        color: var(--primary);
        font: 900 1rem/1 var(--theme-font-display, sans-serif);
    }

    /* ── while loading: the meter's proof [loading = out of register; Kenny,
       2026-10-07]. The meter's own drawing is printed in two plates: the
       ruler (a hairline above and below it and a tick every tenth) in ink on
       ::after and, under it, the same ruler in red on ::before, which travels
       the clockwise loop (22 units) behind it. Standing still the red lies a
       little out of register. ── */

    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        --kp-sig-gr-r: 4px;
        background: var(--card);
        box-shadow: none;
        animation: none;
    }

    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::before,
    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        all: unset;
        content: '';
        display: block;
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::before {
        background:
            linear-gradient(var(--primary) 0 0) 0 0 / 100% 1.5px no-repeat,
            linear-gradient(var(--primary) 0 0) 0 100% / 100% 1.5px no-repeat,
            repeating-linear-gradient(90deg, var(--primary) 0 1.5px, transparent 1.5px 10%);
        --kp-sig-gr-a: 39.8deg;
        --kp-sig-gr-q: 0.78;
        translate: calc(var(--kp-sig-gr-r) * var(--kp-sig-gr-q) * cos(var(--kp-sig-gr-a)))
            calc(var(--kp-sig-gr-r) * var(--kp-sig-gr-q) * sin(var(--kp-sig-gr-a)));
    }

    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        background:
            linear-gradient(var(--foreground) 0 0) 0 0 / 100% 1.5px no-repeat,
            linear-gradient(var(--foreground) 0 0) 0 100% / 100% 1.5px no-repeat,
            repeating-linear-gradient(90deg, var(--foreground) 0 1.5px, transparent 1.5px 10%);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::before {
            animation: kp-sig-grotesk-loop var(--kp-sig-gr-loop) linear infinite;
        }
    }

    /* ── how the share arrives: option 3 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)::before {
            animation: kp-sig-grotesk-meter-grow-o 480ms steps(4) backwards;
            transition: inline-size 480ms steps(4);
            transform-origin: 0 50%;
        }
    }

    /* ── when the tone changes: the plate falls back into register [G13: a tone
       never jolts or swells the part; Kenny, 2026-10-07 on
       research/grotesk-character: live = the plate]. A meter that turns to
       warning or destructive is printed again: its red plate falls into
       register on it once, 960 ms; the two tones have a name each, so a change
       from one to the other starts it again. A meter that is loading draws
       its own proof. ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='warning']:not([data-kp-loading]) {
            --kp-sig-gr-r: 4px;
            animation: kp-sig-grotesk-fall var(--kp-sig-gr-fall) linear;
        }

        [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='destructive']:not([data-kp-loading]) {
            --kp-sig-gr-r: 4px;
            animation: kp-sig-grotesk-fall-again var(--kp-sig-gr-fall) linear;
        }
    }

    /* ── the mark past the end: option 2 ── */

    [data-theme='grotesk'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-mo-sign: '→';
    }

    [data-theme='grotesk'] .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% + 3px);
    }

    [data-theme='grotesk'] .kp-meter__mark[data-kp-over]::after {
        inset-inline-start: calc(100% + 2px);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] .kp-meter__mark {
            transition:
                inset-inline-start 480ms var(--kp-sig-gr-ease),
                rotate 480ms var(--kp-sig-gr-ease);
        }
    }

    @keyframes kp-sig-grotesk-meter-grow-o {
        0% {
            scale: 0 1;
        }

        100% {
            scale: 1 1;
        }
    }

    /* A menu and a popover are printed and their red plate falls into register on them, as
       on the toast (G3, the plate); they close as the fall played backwards (js/motion.js
       playClose). */
    [data-theme='grotesk'] :is(.kp-menu-button > .kp-menu, .kp-popover[popover]:not(.kp-tooltip)) {
        --kp-sig-dur: var(--kp-sig-gr-fall);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] :is(.kp-menu-button > .kp-menu, .kp-popover[popover]:not(.kp-tooltip)) {
            animation: kp-sig-grotesk-fall var(--kp-sig-dur) linear backwards;
        }
    }

    /* ── Pairs: every close is its open reversed, and the plate's fall on every part that opens
       [all-themes audit, 2026-10-13; docs/THEME_LESSONS.md 19-27, 31, 36-38]. A close that is not a
       leave (a dialog, a drawer, the palette, the alarm, a menu, a popover, the date picker, the
       combobox's list, the bar's menus, the side navigation, the tour) is the fall played backwards
       in the fall's own 960 ms: the red plate spirals back out the way it came. A part a script removes
       or hides (the busy layers, a file row, a toast, a dismissed alert) takes the decided leave above
       instead (clockwise out, CHARACTER.md §0b): that one is not the arrival reversed, on purpose. ── */
    [data-theme='grotesk'] {
        /* A part a script removes or hides leaves first, as everything else does here (lesson 19);
           what takes no box arrives as nothing (23); the space a leave folds shut takes the leave's
           own 960 ms and starts with it (24). */
        --kp-leave-state: leave;
        --kp-arrive-unseen: skip;
        --kp-leave-fold-grow: 1;
        --kp-leave-fold-start: 0;
        /* The bar's hover dropdown and its phone panel are held on screen for the close's time
           (js/components.js, lesson 36). */
        --kp-nav-close-time: 960ms;
        /* The tour's dim and ring: printed at once with the card and taken off at once at the end of
           its close, as the dialog's backdrop is (nothing fades, G1). The close holds them for the
           card's 960 ms and then drops them: `steps(1, end)`, the opening's `steps(1, start)` turned
           round. */
        --kp-tour-dim-close: 0 0 0 0 transparent;
        --kp-tour-dim-time: 960ms;
        --kp-tour-dim-close-ease: steps(1, end);
        --kp-tour-dim-close-delay: 0s;
    }

    @media (prefers-reduced-motion: reduce) {
        [data-theme='grotesk'] {
            --kp-nav-close-time: 0ms;
        }
    }

    /* A tree branch's children are kept drawn while their group glides shut (lesson 26). */
    [data-theme='grotesk'] .kp-tree [role='treeitem'][aria-expanded='false'] > [role='group'][data-kp-group-folding],
    [data-theme='grotesk'] .kp-tree [role='treeitem'][aria-expanded='false'] + [role='group'][data-kp-group-folding] {
        display: block;
    }

    /* The windows that slip most: the palette, the shortcuts sheet, the tour's card, the picker's
       panel, the combobox's list, the bar's panels. */
    [data-theme='grotesk'] :is(.kp-palette, .kp-shortcuts, .kp-tour, .kp-datepicker__panel, .kp-combobox__list, .kp-nav__menu, .kp-alarm__panel) {
        --kp-sig-gr-r: 8px;
    }

    /* On the alarm's red ground the plate is the ink: its own red would not show. */
    [data-theme='grotesk'] .kp-alarm__panel {
        --kp-sig-gr-plate: var(--foreground);
    }

    @media (prefers-reduced-motion: no-preference) {
        /* Every backdrop is printed at once and held while its window's plate falls, and the close
           holds it the same 960 ms and lets it go with the window (lesson 16: with no motion of its own
           js/motion.js fades it out on `ease-in`, which the opening never did). */
        [data-theme='grotesk'] :is(.kp-dialog, .kp-drawer, .kp-alarm, .kp-palette, .kp-shortcuts)[open]::backdrop {
            animation: kp-sig-grotesk-hold var(--kp-sig-gr-fall) linear backwards;
        }

        /* The dialog's and the drawer's title rule is drawn in the fall's own time, with its unit
           of delay and its draw written into the keyframes, so js/motion.js (which plays every kept
           entrance backwards in the close's 960 ms, without its delay) turns it round frame for frame. */
        [data-theme='grotesk'] .kp-dialog__title::before {
            animation: kp-sig-grotesk-gr-rule-set var(--kp-sig-gr-fall) linear both;
        }

        /* The palette and the shortcuts sheet open as the dialog does: their plate falls into
           register; js/motion.js closes them as that fall played backwards. */
        [data-theme='grotesk'] :is(.kp-palette, .kp-shortcuts)[open] {
            animation: kp-sig-grotesk-fall var(--kp-sig-gr-fall) linear backwards;
        }

        /* The alarm is a poster: the red ground is there at once (no fade, G1) and the panel's plate,
           the ink on the red, falls into register as on every window; the headline and the reason
           are printed with it, not after it. Its close is that fall backwards, the ground going last. */
        [data-theme='grotesk'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) {
            animation: none;
        }

        [data-theme='grotesk'] .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__panel {
            animation: kp-sig-grotesk-fall var(--kp-sig-gr-fall) linear backwards;
        }

        [data-theme='grotesk'] .kp-alarm:not([data-kp-alarm-motion='still']) :is(.kp-alarm__title, .kp-alarm__detail) {
            animation: none;
        }

        /* The date picker's panel and the combobox's list are the popover's plate: it falls into
           register on them, and js/motion.js playClose plays that backwards (the panel's opening
           mark stays on through the close, lesson 10). */
        [data-theme='grotesk']
            :is(.kp-combobox__list:popover-open, .kp-datepicker__panel:is([data-kp-date-open], [data-kp-closing], [data-kp-reversing]):popover-open) {
            animation: kp-sig-grotesk-fall var(--kp-sig-gr-fall) linear backwards;
        }

        /* The tour's card is a window like the dialog: its plate falls into register, and js/tour.js
           plays that backwards when the tour ends. A step is no arrival (lesson 30). */
        [data-theme='grotesk'] .kp-tour[open]:not([data-kp-tour-stepping]) {
            animation: kp-sig-grotesk-fall var(--kp-sig-gr-fall) linear backwards;
        }

        [data-theme='grotesk'] .kp-tour[data-kp-tour-stepping] {
            animation: none;
        }

        [data-theme='grotesk'] [data-kp-tour-target] {
            transition:
                box-shadow var(--kp-sig-gr-fall) steps(1, start),
                outline-color var(--kp-sig-gr-fall) steps(1, start);
        }

        /* A refreshing table's kept rows are dimmed at once when its busy layer arrives and come back
           at once when the layer's leave is over, not when it starts. */
        [data-theme='grotesk'] .kp-datatable .kp-table tbody {
            transition: opacity 0s linear var(--kp-sig-gr-fall);
        }

        [data-theme='grotesk'] .kp-datatable[aria-busy='true'] .kp-table tbody {
            transition: opacity 0s linear;
        }

        /* The calendar's busy layers (the whole grid's card and a day's spinner) arrive by the fall
           and leave by the decided leave (clockwise out, §0b): js/calendar.js marks a layer
           `[data-kp-leaving]` while its state goes (`--kp-calendar-busy-leave: hold`), and the rules
           below keep it drawn through that leave. */
        [data-theme='grotesk'] :is(.kp-calendar__day-busy, .kp-calendar__busy) {
            --kp-calendar-busy-leave: hold;
            transition: none;
        }

        [data-theme='grotesk']
            :is(.kp-calendar--busy-days, .kp-calendar--busy-whole:not(:has(> .kp-calendar__grid[aria-busy='true'])))
            .kp-calendar__day[data-kp-tone='loading']
            > .kp-calendar__day-busy,
        [data-theme='grotesk'] .kp-calendar--busy-whole:has(> .kp-calendar__grid[aria-busy='true']) > .kp-calendar__busy {
            animation: kp-sig-grotesk-fall var(--kp-sig-gr-fall) linear backwards;
        }

        [data-theme='grotesk'] .kp-calendar__day:has(> .kp-calendar__day-busy[data-kp-leaving]) {
            position: relative;
        }

        [data-theme='grotesk'] .kp-calendar__day-busy[data-kp-leaving] {
            --kp-spinner-size: var(--kp-calendar-spinner, 0.75rem);
            position: absolute;
            inset-inline: 0;
            inset-block-end: 0.125rem;
            display: flex;
            justify-content: center;
            line-height: 0;
        }

        [data-theme='grotesk'] .kp-calendar--busy-whole > .kp-calendar__busy[data-kp-leaving] {
            --kp-spinner-size: var(--kp-calendar-busy-spinner, 2.5rem);
            z-index: 1;
            display: grid;
            place-self: center;
            place-items: center;
            padding: var(--kp-space-md, 1rem);
            border-radius: 0;
            background: var(--card);
            box-shadow: 0 0 0 1px var(--border);
            line-height: 0;
        }

        /* The bar's dropdown and mega menu: shown, the plate falls into register on the panel; once
           the pointer, the focus or the press is gone the panel is held for the close's 960 ms
           (`[data-kp-nav-closing]` on its item, js/components.js) while the fall plays backwards under
           a second name, so it starts again. The mega menu's item is released when a transition on
           the panel ends: the hold below is that transition. No package fade: nothing fades (G1). */
        [data-theme='grotesk'] .kp-nav__menu {
            --kp-sig-gr-hold: 0;
            transition: --kp-sig-gr-hold var(--kp-sig-gr-fall) linear;
            animation: kp-sig-grotesk-fall-back var(--kp-sig-gr-fall) linear reverse forwards;
        }

        [data-theme='grotesk']
            .kp-nav__links
            > li[data-kp-nav-closing]:not(:hover, :focus-within, [data-kp-nav-menu-open])
            > .kp-nav__menu:not(.kp-nav__menu--wide) {
            display: block;
            opacity: 1;
        }

        [data-theme='grotesk']
            :is(
                .kp-nav__links > li:is(:hover, :focus-within, [data-kp-nav-menu-open]) > .kp-nav__menu:not(.kp-nav__menu--wide),
                .kp-nav__links > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true'])) > .kp-nav__menu--wide
            ) {
            --kp-sig-gr-hold: 1;
            animation: kp-sig-grotesk-fall var(--kp-sig-gr-fall) linear backwards;
        }
    }

    @container kp-nav (max-width: 40rem) {
        /* Collapsed, the lists nested in the open phone panel are its own rows: they do not fall again. */
        [data-theme='grotesk'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__links .kp-nav__menu {
            animation: none;
            transition: none;
        }

        /* The phone panel is printed and its plate falls into register; closing, the panel is held
           (`[data-kp-nav-closing]`, for `--kp-nav-close-time`) while the fall plays backwards. The
           toggle's ink plate comes with the opening's first frame and goes with the closing's last
           (`[data-kp-nav-open]` is taken off when the close is over), which is that turned round. */
        @media (prefers-reduced-motion: no-preference) {
            [data-theme='grotesk'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links {
                --kp-sig-gr-r: 8px;
                animation: kp-sig-grotesk-fall var(--kp-sig-gr-fall) linear backwards;
            }

            [data-theme='grotesk'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-closing] > .kp-nav__links {
                --kp-sig-gr-r: 8px;
                animation: kp-sig-grotesk-fall-back var(--kp-sig-gr-fall) linear reverse forwards;
            }
        }
    }

    /* The side navigation (over and push) opens as every window does: it slides out from behind its
       start edge in one contact unit (G2) and its red plate falls into register over the fall's 960 ms;
       its backdrop is printed at once and held. The close is that played backwards: the plate spirals
       out, and the slide back and the content's return come in the last unit, so frame t of the close is
       frame 960 - t of the opening. */
    [data-theme='grotesk'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']) {
        --kp-sig-gr-r: 8px;
    }

    /* Shut, the panel is not drawn: its plate, played backwards when the page loads, must not show
       past its edge, and nothing in it takes the keyboard. The close keeps it drawn for the fall.
       Before js/sidenav.js has marked it (no `data-kp-sidenav-open` yet) it is shut too, and hidden:
       otherwise the script's first `false` started the close's 960 ms hold on a visible panel, and
       a panel never opened played its close on the page for up to a second after load (round 2,
       2026-10-13: the pair meter caught it in its "before" picture, 56 % left over, in about one
       run in three of a full run). */
    [data-theme='grotesk'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']):not([data-kp-sidenav-open='true']) {
        visibility: hidden;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='grotesk'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='true'] {
            animation:
                kp-sig-grotesk-fall var(--kp-sig-gr-fall) linear backwards,
                kp-sig-grotesk-slide var(--kp-sig-gr-fall) linear backwards;
            transition: visibility 0s linear;
        }

        /* No fill: once it has played the closed panel carries no plate (it would show past its edge).
           The slide is keyframed in the fall's time (one unit of travel, then held) rather than a
           transition with a delay, so the two directions are the same frames. */
        [data-theme='grotesk'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='false'] {
            animation:
                kp-sig-grotesk-fall-back var(--kp-sig-gr-fall) linear reverse,
                kp-sig-grotesk-slide-back var(--kp-sig-gr-fall) linear reverse;
            transition: visibility 0s linear var(--kp-sig-gr-fall);
        }

        [data-theme='grotesk'] .kp-sidenav__backdrop {
            animation: kp-sig-grotesk-hold var(--kp-sig-gr-fall) linear both;
        }

        [data-theme='grotesk'] [data-kp-sidenav-shift='open'] {
            transition:
                margin-inline-start var(--kp-sig-gr-unit) linear,
                padding-inline-start var(--kp-sig-gr-unit) linear;
        }

        [data-theme='grotesk'] [data-kp-sidenav-shift='closed'] {
            transition:
                margin-inline-start var(--kp-sig-gr-unit) linear calc(var(--kp-sig-gr-fall) - var(--kp-sig-gr-unit)),
                padding-inline-start var(--kp-sig-gr-unit) linear calc(var(--kp-sig-gr-fall) - var(--kp-sig-gr-unit));
        }
    }

    /* The side navigation's slide in the fall's 8 units: one unit out from behind its start edge, held
       for the rest; the close plays a second name backwards, so it starts again. */
    @keyframes kp-sig-grotesk-slide {
        0% {
            translate: var(--kp-sidenav-away, -100%) 0;
        }

        12.5%,
        100% {
            translate: 0 0;
        }
    }

    @keyframes kp-sig-grotesk-slide-back {
        0% {
            translate: var(--kp-sidenav-away, -100%) 0;
        }

        12.5%,
        100% {
            translate: 0 0;
        }
    }

    /* A backdrop that is printed at once and held: the window's fall runs over it. */
    @keyframes kp-sig-grotesk-hold {
        from,
        to {
            opacity: 1;
        }
    }

    /* The title rule in the fall's 8 units: one unit of rest, three to draw, held from the fourth. */
    @keyframes kp-sig-grotesk-gr-rule-set {
        0%,
        12.5% {
            transform: scaleX(0);
        }

        50%,
        100% {
            transform: scaleX(1);
        }
    }

    /* The fall under a third name, played backwards for a close a CSS state change starts (the
       bar's panels): a new name, so the browser starts it again rather than turning the finished
       opening round in place (lesson 8). */
    @keyframes kp-sig-grotesk-fall-back {
        0% {
            filter: drop-shadow(var(--kp-sig-gr-r) 0 0 var(--kp-sig-gr-plate));
        }

        10.94% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * 0.626) calc(var(--kp-sig-gr-r) * 0.626) 0 var(--kp-sig-gr-plate));
        }

        21.88% {
            filter: drop-shadow(0 calc(var(--kp-sig-gr-r) * 0.771) 0 var(--kp-sig-gr-plate));
        }

        32.81% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * -0.465) calc(var(--kp-sig-gr-r) * 0.465) 0 var(--kp-sig-gr-plate));
        }

        43.75% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * -0.543) 0 0 var(--kp-sig-gr-plate));
        }

        54.69% {
            filter: drop-shadow(calc(var(--kp-sig-gr-r) * -0.303) calc(var(--kp-sig-gr-r) * -0.303) 0 var(--kp-sig-gr-plate));
        }

