        }

        87.5%,
        100% {
            filter: drop-shadow(0 0 0 transparent);
        }
    }
}

@layer kp.register {
    /* Bottom tab bar [kpadopt-nav] — grotesk: a printed column. The bar stands under a black rule; the current tab is a baseline drawn under its label at an even pace from the start, thickened by a press; red signals once, on the count (G1, G7, G8, G14). */
    [data-theme='grotesk'] .kp-tabbar {
        border-block-start: 2px solid var(--foreground);
    }

    [data-theme='grotesk'] .kp-tabbar__tab {
        border-radius: 0;
    }

    [data-theme='grotesk'] .kp-tabbar__tab::before {
        inset-block: auto 0;
        inset-inline: 0.5rem;
        block-size: 3px;
        background: var(--foreground);
        transform-origin: 0 50%;
