    [data-theme='grotesk'] .kp-tabbar__tab:dir(rtl)::before {
        transform-origin: 100% 50%;
    }

    [data-theme='grotesk'] .kp-tabbar__tab[aria-current]:not([aria-current='false']) .kp-tabbar__icon {
        color: inherit;
