                calc(var(--kp-bp-px) * 100% + 0px - var(--kp-bp-px) * 11px) calc(var(--kp-bp-py) * 100% + 8px - var(--kp-bp-py) * 15px),
                calc(var(--kp-bp-px) * 100% + 12px - var(--kp-bp-px) * 11px) calc(var(--kp-bp-py) * 100% + 8px - var(--kp-bp-py) * 15px),
                calc(var(--kp-bp-px) * 100% + 4px - var(--kp-bp-px) * 7px) calc(var(--kp-bp-py) * 100% + 4px - var(--kp-bp-py) * 15px),
                calc(var(--kp-bp-px) * 100% + 4px - var(--kp-bp-px) * 7px) calc(var(--kp-bp-py) * 100% + 12px - var(--kp-bp-py) * 15px),
