        [data-theme='blueprint'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])::after {
            inset: -8px;
        }

        [data-theme='blueprint'] .kp-alarm[open]:not([data-kp-alarm-motion='still'])::after {
            inset: calc(var(--kp-alarm-bar, 0.9rem) + 0.75rem - 8px) calc(0.75rem - 8px);
            box-shadow: none;
            animation: none;
        }

        /* Its backdrop (where a page keeps one) dims in the panel's 5 units on the feed. A literal,
           for the flash check that reads it. */
        [data-theme='blueprint'] .kp-sidenav__backdrop {
            animation-duration: 800ms;
            animation-timing-function: var(--kp-sig-bp-feed);
        }

        /* The alarm is a dialog the size of the screen: traced and inked as the dialog, its ground,
           frame, bars and words together at the ink; js/motion.js keeps this entrance and plays it
           backwards to close it. What it holds stays visible to the focus (the acknowledge button
           takes it at once) and is painted by the ink. The frame's breathing glow, which lived on
           the ::after the pen now takes, breathes on the scan layer's ::after. The package's fade,
           rise and scale are not this theme's (G2: nothing rises or scales). */
        [data-theme='blueprint'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) {
            --kp-bp-ov: hidden auto;
            animation: kp-sig-blueprint-trace var(--kp-sig-bp-panel) linear backwards;
        }

        [data-theme='blueprint'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) > :is(.kp-alarm__scan, .kp-alarm__bars, .kp-alarm__panel) {
            visibility: visible;
            opacity: var(--kp-bp-ink);
        }

        [data-theme='blueprint'] .kp-alarm:not([data-kp-alarm-motion='still']) :is(.kp-alarm__panel, .kp-alarm__title, .kp-alarm__detail) {
            animation: none;
        }

        [data-theme='blueprint'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) .kp-alarm__scan::after {
            content: '';
            inset: 0;
            block-size: auto;
            background: none;
            box-shadow: inset 0 0 7rem var(--kp-alarm-glow);
            animation: kp-alarm-pulse 1400ms ease-in-out infinite alternate;
        }
    }
}

@layer kp.register {
    /* Bottom tab bar [kpadopt-nav] — blueprint: a drafted sheet. The current tab is dimensioned: a witness line with end ticks is drawn under its label at the plotter's feed; the lettering is capitals in the mono, the sans speaks (G1, G8, G15); a count is a flagged annotation. */
    [data-theme='blueprint'] .kp-tabbar {
        border-block-start-style: solid;
    }

    [data-theme='blueprint'] .kp-tabbar__tab {
        border-radius: 0;
    }

    [data-theme='blueprint'] .kp-tabbar__label {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }

    [data-theme='blueprint'] .kp-tabbar__tab::before {
        inset-block: auto 0.125rem;
        inset-inline: 0.5rem;
        block-size: 7px;
        background:
            linear-gradient(var(--primary), var(--primary)) center / 100% 1px no-repeat,
            linear-gradient(var(--primary), var(--primary)) left / 1px 7px no-repeat,
            linear-gradient(var(--primary), var(--primary)) right / 1px 7px no-repeat;
        transform-origin: 0 50%;
    }

    [data-theme='blueprint'] .kp-tabbar__tab:dir(rtl)::before {
        transform-origin: 100% 50%;
    }

    [data-theme='blueprint'] .kp-tabbar__tab:is(:hover, :focus-visible):not([aria-current]:not([aria-current='false']))::before {
        scale: 0.4 1;
        opacity: 0.6;
    }

    [data-theme='blueprint'] .kp-tabbar__badge {
        border-radius: 0;
        font-family: var(--theme-font-mono);
        outline: 1px solid var(--primary);
        outline-offset: 1px;
    }
}
/* ── End of the signature ── */

/* ── Segmented control, list toolbar, key line [kpadopt-controls] ── */
