    @media (forced-colors: active) {
        [data-theme='dark'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a):hover {
            text-decoration-color: currentColor;
        }
    }

    /* ── Pointing, the keyboard and the press: one manner for every control
       [G14, G15, G17; Kenny, 2026-10-09, questions 14, 15 and 17]. A button
       in a header, a menu, a drawer, a tile or a tour hovers, focuses and
       presses exactly like dark's own bracketed button; a menu entry like
       the button; a link by its underline taking the film (above). The line
       rests at the start: a 2 px slice of the film with its glow stands at
       the control's start edge and the brackets close one step (the
       register's own, above). The keyboard's ring is DI2's two channels
       inside the cut, and it wins over the pointer when both apply. A press
       is a pass: on contact the line crosses the face (220 ms) and the film
       edge turns a quarter (+90 degrees) and settles; the brackets close; the
       release turns it back. Nothing moves. ── */
    [data-theme='dark'] :is(.kp-button, .kp-icon-button, .kp-menu__item) {
        background-image: var(--kp-sig-dk-line);
        background-repeat: no-repeat;
        background-position: 0 0;
        background-size: 0 100%;
    }

    [data-theme='dark'] :is(.kp-button, .kp-icon-button, .kp-menu__item):hover:not(:disabled, [aria-disabled='true']) {
        background-size: 2px 100%;
    }

    [data-theme='dark'] :is(.kp-button, .kp-icon-button, .kp-menu__item):hover:not(:disabled, [aria-disabled='true'], :focus-visible) {
        box-shadow: inset 7px 0 9px -6px hsl(from var(--chart-1) h s l / 0.4);
    }

    /* The film's edge on a link tile or a filter tile: the line at the start. */
    [data-theme='dark'] :is(a.kp-kpi, .kp-kpi--toggle)::before {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        inline-size: 2px;
        background: var(--kp-sig-dk-line);
        box-shadow: 0 0 9px hsl(from var(--chart-1) h s l / 0.4);
        opacity: 0;
        pointer-events: none;
    }

    [data-theme='dark'] :is(a.kp-kpi, .kp-kpi--toggle):hover::before {
        opacity: 1;
    }

    [data-theme='dark'] :is(a.kp-kpi, .kp-kpi--toggle):is(:focus-visible) {
        outline: none;
        box-shadow:
            inset 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            inset 0 0 0 calc(var(--kp-focus-ring-inner-width, 2px) + 2px) var(--focus-ring-contrast);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] :is(.kp-button, .kp-icon-button, .kp-menu__item) {
            transition:
                background-color var(--fx-duration) var(--fx-ease),
                border-color var(--fx-duration) var(--fx-ease),
                color var(--fx-duration) var(--fx-ease),
                box-shadow var(--fx-duration) var(--fx-ease),
                background-size var(--fx-duration) var(--fx-ease),
                --kp-sig-dk-turn var(--fx-duration) cubic-bezier(0.64, 0, 0.78, 0);
        }

        [data-theme='dark'] :is(a.kp-kpi, .kp-kpi--toggle)::before {
            transition: opacity var(--fx-duration) var(--fx-ease);
        }

        /* On contact: the edge turns a quarter on the settle, the ground and the
           line answer at once; the line crosses the face in the contact time. */
        [data-theme='dark'] :is(.kp-button, .kp-icon-button, .kp-menu__item):active:not(:disabled) {
            --kp-sig-dk-turn: 90deg;
            background-size: 2px 100%;
            transition:
                background-color 0s,
                border-color 0s,
                color 0s,
                box-shadow 0s,
                background-size 0s,
                --kp-sig-dk-turn var(--fx-duration) var(--fx-ease);
            animation: kp-sig-dark-tap var(--fx-duration) linear both;
        }
    }

    /* ── A live update is one pass over the figure [G9; Kenny, 2026-10-09,
       question 9: "One pass over the figure"]. js/update.js writes the new
       value at once and marks the element `[data-kp-updating='pass']`; the
       line crosses the changed figure once from its start (the theme's update
       time, 660 ms), the letters behind it take the film and settle back to
       ink once it has gone by; the figure never moves, flares or jolts and
       the box keeps its space. Applies to the key figure, the state word, the
       trend, the strip column and the tile alike. A state word keeps its
       width-holding ::after, so its line is drawn on ::before; a spark (an
       svg) has no letters, its line crosses the parent's box. Two numbers, how
       far the line has come (--kp-sig-dk-at) and how much ink lies over the
       film (--kp-sig-dk-ink), are @property at the top of this file. ── */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] {
            --kp-update: pass;
        }

        [data-theme='dark'] [data-kp-updating='pass'] {
            position: relative;
            --kp-sig-dk-ink-colour: var(--foreground);
        }

        [data-theme='dark'] .kp-kpi > .kp-kpi__value[data-kp-updating='pass'] {
            justify-self: start;
            inline-size: fit-content;
        }

        [data-theme='dark'] [data-kp-updating='pass']:not(:has(> svg)) {
            background:
                linear-gradient(var(--kp-sig-dk-gdir), transparent var(--kp-sig-dk-at), var(--kp-sig-dk-ink-colour) var(--kp-sig-dk-at)),
                linear-gradient(
                    hsl(from var(--kp-sig-dk-ink-colour) h s l / var(--kp-sig-dk-ink)),
                    hsl(from var(--kp-sig-dk-ink-colour) h s l / var(--kp-sig-dk-ink))
                ),
                var(--kp-iris);
            -webkit-background-clip: text;
            background-clip: text;
            color: transparent;
            animation: kp-sig-dark-figure var(--kp-update-duration, 660ms) linear both;
        }

        [data-theme='dark'] [data-kp-updating='pass']:not(.kp-state-word)::after,
        [data-theme='dark'] .kp-state-word[data-kp-updating='pass']::before {
            content: '';
            position: absolute;
            inset: -2px -4px;
            z-index: 1;
            background: var(--kp-sig-dk-line) var(--kp-sig-dk-end) 0 / 2px 100% no-repeat;
            filter: var(--kp-sig-dk-glow);
            opacity: 0;
            pointer-events: none;
            animation: kp-sig-dark-pass-live var(--kp-update-duration, 660ms) linear both;
        }
    }

    /* ── The opening is a pass [G3, G13; Kenny, 2026-10-09, question 3:
       "Swept in from its own left edge, left to right"]. A dialog, a menu, a
       popover, a combobox list, a date picker, a palette, a toast, a tooltip
       and a drawer open the same way: the line starts at the left edge of the
       element that opens (never at its button) and crosses only that
       element's own box at one pace, laying the panel behind it, the film
       edge turning; it stops dead at the end and the turn settles 220 ms
       later (880 ms in all). The close is the pass back, right to left,
       taking the panel off behind it: js/motion.js plays this entrance
       backwards (`--kp-open: reverse-close`), frame t of the close being
       frame (T - t) of the open. The panel is revealed by a mask of three
       layers (the box, and the reach of its halo on either side, which come
       with the line's first and last 4 %), so the halo and the cut follow
       what is laid instead of being cut square. The line is the panel's
       ::after; the film turn is one number on the panel (the film's own
       @property, kp-sig-dark-film). ── */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark']
            :is(.kp-dialog, .kp-menu, .kp-popover, .kp-toast, .kp-combobox__list, .kp-datepicker__panel, .kp-palette, .kp-theme-menu__list) {
            --kp-sig-dk-r: var(--kp-halo-reach, 2.5rem);
        }

        [data-theme='dark']
            :is(
                .kp-dialog,
                dialog.kp-drawer,
                .kp-menu,
                .kp-popover,
                .kp-tooltip,
                .kp-toast,
                .kp-combobox__list,
                .kp-datepicker__panel,
                .kp-palette,
                .kp-theme-menu__list
            ) {
            animation:
                kp-sig-dark-sweep var(--kp-sig-dk-time) linear backwards,
                kp-sig-dark-film var(--kp-sig-dk-time) linear backwards;
        }

        [data-theme='dark']
            :is(
                .kp-dialog,
                dialog.kp-drawer,
                .kp-menu,
                .kp-popover,
                .kp-tooltip,
                .kp-toast,
                .kp-combobox__list,
                .kp-datepicker__panel,
                .kp-palette,
                .kp-theme-menu__list,
                .kp-nav__menu
            )::after {
            content: '';
            position: absolute;
            inset: 0;
            z-index: 3;
            background: var(--kp-sig-dk-line) var(--kp-sig-dk-end) 0 / 2px 100% no-repeat;
            clip-path: none;
            filter: var(--kp-sig-dk-glow);
            opacity: 0;
            pointer-events: none;
            animation: kp-sig-dark-pass-line var(--kp-sig-dk-time) linear backwards;
        }

        /* A menu inside a popover is not swept twice: the popover is. */
        [data-theme='dark'] .kp-popover :is(.kp-menu, .kp-popover) {
            animation: none;
        }

        [data-theme='dark'] .kp-popover :is(.kp-menu, .kp-popover)::after {
            content: none;
        }

        /* The drawer comes in from its own left edge too, over its own height
           and width: it casts no halo, so there is no reach. */
        [data-theme='dark'] dialog.kp-drawer {
            --kp-sig-dk-r: 0px;
        }

        /* A dialog's backdrop is not swept; js/motion.js fades it with the
           dialog. */

        /* The nav dropdown opens by hovering or focusing its item, with no script
           in between: the same pass, and the close is the pass back. While it
           closes the item keeps the panel on screen for the whole pass back
           (`display` is a discrete transition), and the closed style plays the
           entrance reversed. */
        @container kp-nav (width > 40rem) {
            [data-theme='dark'] .kp-nav__menu {
                --kp-sig-dk-r: var(--kp-halo-reach, 2.5rem);
                opacity: 1;
                transition: display var(--kp-sig-dk-time) allow-discrete;
                animation:
                    kp-sig-dark-sweep var(--kp-sig-dk-time) linear reverse forwards,
                    kp-sig-dark-film var(--kp-sig-dk-time) linear reverse forwards;
            }

            [data-theme='dark'] .kp-nav__menu::after {
                animation: kp-sig-dark-pass-line var(--kp-sig-dk-time) linear reverse forwards;
            }

            [data-theme='dark'] .kp-nav__links > li:hover > .kp-nav__menu,
            [data-theme='dark'] .kp-nav__links > li:focus-within > .kp-nav__menu,
            [data-theme='dark'] .kp-nav__links > li[data-kp-nav-menu-open] > .kp-nav__menu {
                animation:
                    kp-sig-dark-sweep var(--kp-sig-dk-time) linear backwards,
                    kp-sig-dark-film var(--kp-sig-dk-time) linear backwards;
            }

            [data-theme='dark'] .kp-nav__links > li:hover > .kp-nav__menu::after,
            [data-theme='dark'] .kp-nav__links > li:focus-within > .kp-nav__menu::after,
            [data-theme='dark'] .kp-nav__links > li[data-kp-nav-menu-open] > .kp-nav__menu::after {
                animation: kp-sig-dark-pass-line var(--kp-sig-dk-time) linear backwards;
            }
        }

        /* The tooltip's halo is none: its reach is none. */
        [data-theme='dark'] .kp-tooltip {
            --kp-sig-dk-r: 0px;
        }
    }

    @container kp-nav (max-width: 40rem) {
        [data-theme='dark'] .kp-nav__menu::after {
            content: none;
        }
    }

    /* The mask is only ever on while the pass plays: both ends of the keyframe
       are the finished pose, so a still part carries no mask. The panel is the
       box (layer one, which the line sweeps) and the reach of its halo on the
       left (layer two, laid in the first 4 % of the pass) and on the right
       (layer three, laid in the last 4 %). Written out once, 0 to 75 % of the
       880 ms is the pass of 660 ms (G4); the rest holds while the turn
       settles. */
    @keyframes kp-sig-dark-sweep {
        0% {
            mask-image: var(--kp-sig-dk-solid), var(--kp-sig-dk-solid), var(--kp-sig-dk-solid);
            mask-repeat: no-repeat;
            mask-origin: border-box;
            mask-clip: no-clip;
            mask-composite: add;
            mask-position:
                var(--kp-sig-dk-from) 0 top calc(-1 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-from) calc(-1 * var(--kp-sig-dk-r)) top calc(-1 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-from) calc(100% + var(--kp-sig-dk-r)) top calc(-1 * var(--kp-sig-dk-r));
            mask-size:
                0px calc(100% + 2 * var(--kp-sig-dk-r)),
                0px calc(100% + 2 * var(--kp-sig-dk-r)),
                0px calc(100% + 2 * var(--kp-sig-dk-r));
        }

        3% {
            mask-size:
                4% calc(100% + 2 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-r) calc(100% + 2 * var(--kp-sig-dk-r)),
                0px calc(100% + 2 * var(--kp-sig-dk-r));
        }

        72% {
            mask-size:
                96% calc(100% + 2 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-r) calc(100% + 2 * var(--kp-sig-dk-r)),
                0px calc(100% + 2 * var(--kp-sig-dk-r));
        }

        75%,
        100% {
            mask-image: var(--kp-sig-dk-solid), var(--kp-sig-dk-solid), var(--kp-sig-dk-solid);
            mask-repeat: no-repeat;
            mask-origin: border-box;
            mask-clip: no-clip;
            mask-composite: add;
            mask-position:
                var(--kp-sig-dk-from) 0 top calc(-1 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-from) calc(-1 * var(--kp-sig-dk-r)) top calc(-1 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-from) calc(100% + var(--kp-sig-dk-r)) top calc(-1 * var(--kp-sig-dk-r));
            mask-size:
                100% calc(100% + 2 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-r) calc(100% + 2 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-r) calc(100% + 2 * var(--kp-sig-dk-r));
        }
    }

    /* The line crosses the panel's own box and goes in and out at its ends. */
    @keyframes kp-sig-dark-pass-line {
        0% {
            translate: calc(-100% * var(--kp-sig-dk-s)) 0;
            opacity: 0;
        }

        3% {
            translate: calc(-96% * var(--kp-sig-dk-s)) 0;
            opacity: 1;
        }

        69% {
            translate: calc(-8% * var(--kp-sig-dk-s)) 0;
            opacity: 1;
        }

        75%,
        100% {
            translate: 0 0;
            opacity: 0;
        }
    }

    /* The film's turn, laid with the pass: the colour runs round the edge as
       the line crosses (345 degrees at the pace of the line) and settles the
       last 15 degrees on --kp-settle in the 220 ms after the line has stopped,
       cyan at the top. */
    @keyframes kp-sig-dark-film {
        0% {
            --kp-sig-dk-turn: 0deg;
            animation-timing-function: linear;
        }

        75% {
            --kp-sig-dk-turn: 345deg;
            animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
        }

        100% {
            --kp-sig-dk-turn: 360deg;
        }
    }

    /* The figure takes the film through its letters while the line crosses it
       and settles back to ink once it has gone by. */
    @keyframes kp-sig-dark-figure {
        0% {
            --kp-sig-dk-at: 0%;
            --kp-sig-dk-ink: 0;
            animation-timing-function: linear;
        }

        75% {
            --kp-sig-dk-at: 100%;
            --kp-sig-dk-ink: 0;
            animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
        }

        100% {
            --kp-sig-dk-at: 100%;
            --kp-sig-dk-ink: 1;
        }
    }

    /* A live pass: the line goes in at the start and out at the end of the
       update's own time. */
    @keyframes kp-sig-dark-pass-live {
        0% {
            translate: calc(-100% * var(--kp-sig-dk-s)) 0;
            opacity: 0;
        }

        4% {
            translate: calc(-96% * var(--kp-sig-dk-s)) 0;
            opacity: 1;
        }

        92% {
            translate: calc(-8% * var(--kp-sig-dk-s)) 0;
            opacity: 1;
        }

        100% {
            translate: 0 0;
            opacity: 0;
        }
    }

    /* The pass of a small part or of a word: its box, from the start edge, at
       one pace, stopping dead. */
    @keyframes kp-sig-dark-lay {
        from {
            clip-path: inset(var(--kp-sig-dk-cut));
        }

        to {
            clip-path: inset(0);
        }
    }

    /* A comet crosses a waiting surface. The head (the 2 px line) and the tail
       (a third of the part, or the share the property --kp-sig-dk-cw says)
       are two background layers moved together from just before the start to
       just past the end in three quarters of the loop; the last quarter the
       slot is dark. A percentage position is a share of the box less the
       layer, so the head sits at (1 + cw) of the box less its own width and
       the tail at 1 / (1 - cw). */
    @keyframes kp-sig-dark-comet {
        0% {
            background-position:
                calc(0% - 2px) 0,
                calc(-100% * var(--kp-sig-dk-cw) / (1 - var(--kp-sig-dk-cw))) 0;
        }

        75%,
        100% {
            background-position:
                calc(100% * (1 + var(--kp-sig-dk-cw)) - 2px) 0,
                calc(100% / (1 - var(--kp-sig-dk-cw))) 0;
        }
    }

    /* The spinner's loop: one number, 0 to 1. */
    @keyframes kp-sig-dark-bars {
        from {
            --kp-sig-dk-ph: 0;
        }

        to {
            --kp-sig-dk-ph: 1;
        }
    }

    /* A press: the line crosses the face and stops at its end. */
    @keyframes kp-sig-dark-tap {
        from {
            background-position: 0 0;
        }

        to {
            background-position: 100% 0;
        }
    }

    /* Growing and shrinking, this theme's way [scope-142; Kenny, 2026-10-09:
       the darkroom is retired]. js/motion.js marks a gliding box
       `[data-kp-resizing]` and what arrives in it `[data-kp-arriving]`. The
       box keeps the line's glow while it changes; what arrives is laid by the
       pass (below), and nothing develops from a pale print. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] [data-kp-resizing] {
            filter: var(--kp-sig-dk-glow);
        }
    }

    /* Leaving, this theme's way [G13; Kenny, 2026-10-09, question 13: "The
       pass lays, the pass back takes off"]. js/motion.js marks what leaves
       `[data-kp-leaving]`, closes its space during the exit, and in a row of
       leaves starts the next one a tenth into this one. The line crosses back
       from the end and the part goes dark behind it, the film taken with it:
       the opening played backwards, in the same time. Opening is closing
       turned around (Kenny's pick on research/open-reverse, 2026-10-05): what
       arrives plays this leave backwards (js/motion.js), so it is laid from
       the start by the pass and the turn settles to cyan at the top, and
       frame t of the arrival is frame (T - t) of the leave. The line is
       drawn on the parts that can carry a pseudo-element: the alert, the key
       figure and the card (on ::before, its ::after being the plate); a row
       or any other part is taken off by the mask and the film alone. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] {
            --kp-open: reverse-close;
            /* A part a script removes or hides (the busy table's layer, a file
               row, an empty state, a re-shown alert) is taken off by the pass
               back first, as the pass lays it (js/motion.js leavesState(),
               lessons 19, 23, 24); what takes no box arrives as nothing; the
               space a leave folds shut takes the pass's own time and starts
               with it. */
            --kp-leave-state: leave;
            --kp-arrive-unseen: skip;
            --kp-leave-fold-grow: 1;
            --kp-leave-fold-start: 0;
        }

        [data-theme='dark'] :is(.kp-card, .kp-alert, .kp-kpi) {
            --kp-sig-dk-r: var(--kp-halo-reach, 2.5rem);
        }

        [data-theme='dark'] .kp-kpi {
            --kp-sig-dk-r: 0px;
        }

        /* The leave plays the pass's frames under their second names (the
           `-back` keyframes at the end of this layer), so a part whose
           entrance is the pass itself (a toast) starts its leave afresh
           instead of turning the finished entrance round in place (lesson 10;
           all-themes pass, 2026-10-13). The attribute is named twice: the
           entrance rule above names `dialog.kp-drawer` in its list, which
           outranks a single attribute, so a leaving toast kept its entrance
           and had no leave of its own to turn round into its arrival. */
        [data-theme='dark'] [data-kp-leaving][data-kp-leaving] {
            --kp-leave-stagger: 0.1;
            animation:
                kp-sig-dark-sweep-back var(--kp-sig-dk-time) linear reverse forwards,
                kp-sig-dark-film-back var(--kp-sig-dk-time) linear reverse forwards;
        }

        [data-theme='dark'] [data-kp-leaving]:is(.kp-alert, .kp-kpi, .kp-card:not([data-kp-label])) {
            position: relative;
        }

        [data-theme='dark'] [data-kp-leaving]:is(.kp-alert, .kp-kpi)::after,
        [data-theme='dark'] [data-kp-leaving].kp-card:not([data-kp-label])::before {
            content: '';
            position: absolute;
            inset: 0;
            z-index: 3;
            background: var(--kp-sig-dk-line) var(--kp-sig-dk-end) 0 / 2px 100% no-repeat;
            filter: var(--kp-sig-dk-glow);
            opacity: 0;
            pointer-events: none;
            animation: kp-sig-dark-pass-line-back var(--kp-sig-dk-time) linear reverse forwards;
        }
    }

    /* ── A key figure is a panel, and a warning is the film gone coral [G6,
       G7, G8; Kenny, 2026-10-09, questions 6, 7 and 8]. A tile that stands on
       its own is cut on the same two corners as the card, with the film along
       its edge; the plate stays near-black. A warning or a failure takes the
       tone's colour along the whole film edge (the warning ink for a warning,
       coral for a failure) and its change is set in that ink; there is no
       lamp, no tinted plate and no lit number. A destructive menu entry has
       a coral edge at its start and coral ink; a warning or failed alert is
       the same, with its label in the tone. The strip's columns keep the
       package's shared frames. ── */
    [data-theme='dark'] .kp-kpi:not(.kp-kpis[data-kp-kpis-columns] > .kp-kpi) {
        --kp-sig-dk-tone: transparent;
        position: relative;
        border-color: transparent;
        background:
            linear-gradient(var(--card), var(--card)) padding-box,
            var(--kp-iris) border-box;
        clip-path: polygon(
            0 0,
            calc(100% - var(--kp-chamfer-panel)) 0,
            100% var(--kp-chamfer-panel),
            100% 100%,
            var(--kp-chamfer-panel) 100%,
            0 calc(100% - var(--kp-chamfer-panel))
        );
    }

    [data-theme='dark'] .kp-kpi[data-kp-tone='warning'] {
        --kp-sig-dk-tone: var(--warning-foreground);
    }

    [data-theme='dark'] .kp-kpi[data-kp-tone='destructive'] {
        --kp-sig-dk-tone: var(--destructive);
    }

    [data-theme='dark'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) {
        box-shadow: none;
        --kp-sig-dk-ink-colour: var(--kp-sig-dk-tone);
    }

    [data-theme='dark'] .kp-kpi:not(.kp-kpis[data-kp-kpis-columns] > .kp-kpi):is([data-kp-tone='warning'], [data-kp-tone='destructive']) {
        border-color: transparent;
        background:
            linear-gradient(var(--card), var(--card)) padding-box,
            linear-gradient(var(--kp-sig-dk-tone), var(--kp-sig-dk-tone)) border-box;
    }

    [data-theme='dark'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value {
        padding-inline: 0;
        background: transparent;
        color: var(--kp-sig-dk-tone);
    }

    [data-theme='dark'] .kp-kpi[data-kp-tone='destructive']:where(.kp-kpis[data-kp-kpis-columns] > .kp-kpi) {
        border-color: var(--destructive);
    }

    [data-theme='dark'] .kp-kpi[data-kp-tone='warning']:where(.kp-kpis[data-kp-kpis-columns] > .kp-kpi) {
        border-color: var(--warning-foreground);
    }

    [data-theme='dark'] .kp-alert:is(.kp-alert--warning, .kp-alert--destructive) {
        background: var(--card);
        color: var(--foreground);
        border: 1px solid var(--kp-sig-dk-tone);
    }

    [data-theme='dark'] .kp-alert--warning {
        --kp-sig-dk-tone: var(--warning-foreground);
    }

    [data-theme='dark'] .kp-alert--destructive {
        --kp-sig-dk-tone: var(--destructive);
    }

    [data-theme='dark'] .kp-alert:is(.kp-alert--warning, .kp-alert--destructive) .kp-alert__label {
        color: var(--kp-sig-dk-tone);
    }

    [data-theme='dark'] .kp-menu__item--destructive {
        color: var(--destructive);
        box-shadow: inset 2px 0 0 var(--destructive);
    }

    /* ── The meter with a mark, this theme's way [picked by Kenny on
       research/character-meter, rounds 3 and 4, 2026-10-05: shape 1, while
       loading 2 (round 4), how the share arrives 3 (round 4), when the tone
       changes 3, the mark past the end 3]. The package's own markup
       and states (setMeter(), js/kpi.js): the track on the meter, the share on
       ::before, the sign past the end or the loading picture on ::after, the
       mark `.kp-meter__mark`. Every animation and transition under
       prefers-reduced-motion: no-preference; still frames otherwise.
       Redrawn on the grammar [Kenny, 2026-10-09]: loading is the comet, the
       share is laid by the pass, a tone is the film gone coral. ── */

    /* The shared part: room past the end, loading without the pulse, the mark
       centred on its width, the package's signs cleared for the shape's own.
       Under :where() so each picked rule below wins as it did in the demo. */
    :where([data-theme='dark']) :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-room: 0.625rem;
        box-sizing: border-box;
    }

    :where([data-theme='dark']) .kp-meter--inline {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-sig-meter-room));
    }

    /* Each character draws its own loading picture instead of the pulse. */
    :where([data-theme='dark']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: clip;
        animation: none;
    }

    :where([data-theme='dark']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    /* The mark is centred on its share, whatever its width. */
    :where([data-theme='dark']) .kp-meter__mark {
        --kp-sig-meter-mw: 2px;
        box-sizing: border-box;
        inline-size: var(--kp-sig-meter-mw);
        inset-inline-start: calc(clamp(0, var(--kp-mark, 0), 1) * 100% - var(--kp-sig-meter-mw) / 2);
    }

    :where([data-theme='dark']) .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - 0.75rem);
    }

    /* The sign past the end, cleared of the package's ▸ for each character
       to draw its own. */
    :where([data-theme='dark']) :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '';
        position: absolute;
        inset: auto;
        translate: none;
        color: inherit;
        font-size: 0.75rem;
        line-height: 1;
        text-shadow: none;
        white-space: nowrap;
        pointer-events: none;
    }

    /* A mark past the end keeps the package's sign inside the bar's end, in
       each character's own glyph and ink. */
    :where([data-theme='dark']) .kp-meter__mark[data-kp-over]::after {
        content: var(--kp-sig-meter-mo-sign, '▸');
        color: var(--kp-sig-meter-mo-ink, var(--foreground));
        font-family: var(--kp-sig-meter-mo-font, inherit);
        text-shadow:
            0 0 1px var(--kp-sig-meter-mo-halo, var(--card)),
            0 0 2px var(--kp-sig-meter-mo-halo, var(--card));
    }

    /* ── shape: option 1 ── */

    /* ── dark · the machined channel ──────────────────────────────── */
    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-meter-height: 0.5rem;
        --kp-sig-meter-room: 0.625rem;
        --kp-sig-meter-cut: 3px;
        --kp-sig-meter-halo: var(--kp-meter-halo, var(--card));
        border-radius: 0;
        background:
            linear-gradient(
                    135deg,
                    var(--kp-sig-meter-halo) 0 calc(50% - 0.7px),
                    var(--border-strong) calc(50% - 0.7px) calc(50% + 0.7px),
                    transparent 0
                )
                0 0 / var(--kp-sig-meter-cut) var(--kp-sig-meter-cut) no-repeat,
            linear-gradient(
                    -45deg,
                    var(--kp-sig-meter-halo) 0 calc(50% - 0.7px),
                    var(--border-strong) calc(50% - 0.7px) calc(50% + 0.7px),
                    transparent 0
                )
                100% 100% / var(--kp-sig-meter-cut) var(--kp-sig-meter-cut) no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) var(--kp-sig-meter-cut) 0 / calc(100% - var(--kp-sig-meter-cut)) 1px no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 0 100% / calc(100% - var(--kp-sig-meter-cut)) 1px no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 0 var(--kp-sig-meter-cut) / 1px calc(100% - var(--kp-sig-meter-cut)) no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 100% 0 / 1px calc(100% - var(--kp-sig-meter-cut)) no-repeat,
            var(--muted);
    }

    /* Bright machined metal, the oxide film along its top edge laid along
       the whole scale. */
    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)::before {
        inset: 1px;
        inline-size: calc(clamp(0, var(--kp-value, 0), 1) * (100% - 2px));
        border-radius: 0;
        background:
            var(--kp-sig-dk-meter-film, linear-gradient(90deg, var(--chart-1), var(--chart-2), var(--chart-3), var(--chart-4))) 0 0 /
                calc(100% / clamp(0.01, var(--kp-value, 0), 1)) 2px no-repeat,
            var(--kp-meter-fill-colour);
        clip-path: polygon(
            calc(var(--kp-sig-meter-cut) - 1px) 0,
            100% 0,
            100% calc(100% - var(--kp-sig-meter-cut) + 1px),
            calc(100% - var(--kp-sig-meter-cut) + 1px) 100%,
            0 100%,
            0 calc(var(--kp-sig-meter-cut) - 1px)
        );
    }

    /* A V milled into the edge, a dark cut through the metal. */
    [data-theme='dark'] .kp-meter__mark {
        inset-block: -1px;
        border-radius: 0;
        background: var(--background);
        box-shadow:
            1px 0 0 var(--primary),
            -1px 0 0 var(--primary);
    }

    [data-theme='dark'] .kp-meter__mark::before {
        content: '';
        position: absolute;
        inset-block-end: 100%;
        inset-inline-start: 50%;
        inline-size: 8px;
        block-size: 5px;
        translate: -50% 0;
        background: var(--primary);
        clip-path: polygon(0 0, 100% 0, 50% 100%);
    }

    /* The part runs out of the channel with a chamfered tip. */
    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        inset-inline-start: calc(100% + 2px);
        inset-block: 1px;
        inline-size: 0.4375rem;
        background:
            linear-gradient(90deg, var(--chart-4), var(--chart-1)) 0 0 / 100% 2px no-repeat,
            var(--kp-meter-fill-colour);
        clip-path: polygon(0 0, calc(100% - 3px) 0, 100% 50%, calc(100% - 3px) 100%, 0 100%);
    }

    /* ── while loading: option 2 ── */

    /* Loading is the comet, as everywhere [G10]: the 2 px line and its tail a
       third of the channel long cross it from start to end and lay nothing.
       The picture is the channel's own ::after, laid over the whole channel. */
    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        all: unset;
        content: '';
        position: absolute;
        inset: 1px;
        pointer-events: none;
        background-image: var(--kp-sig-dk-line), var(--kp-sig-dk-tail);
        background-repeat: no-repeat;
        background-size:
            2px 100%,
            calc(var(--kp-sig-dk-cw) * 100%) 100%;
        background-position:
            calc(50% * (1 + var(--kp-sig-dk-cw)) - 1px) 0,
            50% 0;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
            animation: kp-sig-dark-comet var(--kp-sig-dk-loop) linear infinite;
        }
    }

    /* ── how the share arrives: the pass ── */

    /* The share is laid by the line from the start of the channel, 660 ms at
       one pace; a new share moves to its size in the contact time on the
       theme's curve. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)::before {
            animation: kp-sig-dark-meter-lay 660ms linear backwards;
            transition: inline-size var(--fx-duration) var(--fx-ease);
        }
    }

    /* ── when the tone changes: the film goes coral ── */

    /* A warning or a failure takes the tone's colour along the whole length of
       the share's film edge; the channel does not swell [G8]. */
    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='warning'] {
        --kp-sig-dk-meter-film: linear-gradient(var(--warning-foreground), var(--warning-foreground));
    }

    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='destructive'] {
        --kp-sig-dk-meter-film: linear-gradient(var(--destructive), var(--destructive));
    }

    /* ── the mark past the end: option 3 ── */

    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-mo-sign: '▸';
    }

    [data-theme='dark'] .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - var(--kp-sig-meter-mw) - 1px);
        rotate: 24deg;
        transform-origin: 50% 100%;
    }

    [data-theme='dark'] .kp-meter__mark[data-kp-over]::after {
        inset-inline-start: calc(100% + 3px);
        rotate: -24deg;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-meter__mark {
            transition:
                inset-inline-start var(--fx-duration) var(--fx-ease),
                rotate var(--fx-duration) var(--fx-ease);
        }
    }

    @keyframes kp-sig-dark-meter-lay {
        from {
            mask-image: var(--kp-sig-dk-solid);
            mask-repeat: no-repeat;
            mask-size: 0px 100%;
        }

        to {
            mask-image: var(--kp-sig-dk-solid);
            mask-repeat: no-repeat;
            mask-size: 100% 100%;
        }
    }

    /* ── Every part that opens is laid by the pass and taken off by the pass
       back [G3, G13; lesson 38; all-themes pass, 2026-10-13]. The tour's card,
       its dim and ring, the calendar's busy layers and the bar's three
       closings take the pass the dialog and the menus already use (880 ms,
       the line at one pace); each close is the opening played backwards. The
       `-back` keyframes below are the same frames under a second name, so a
       close starts afresh instead of taking over the finished opening of the
       same name (lesson 10). ── */
    @media (prefers-reduced-motion: no-preference) {
        /* The tour's card is swept in where it stands as the dialog is (it had
           the package's 160 ms fade); js/motion.js playEntranceBackwards()
           turns it and its line round when the tour ends. A step is no
           arrival: the card plays no entrance again. */
        [data-theme='dark'] .kp-tour {
            --kp-sig-dk-r: var(--kp-halo-reach, 2.5rem);
        }

        [data-theme='dark'] .kp-tour[open]:not([data-kp-tour-stepping]) {
            animation:
                kp-sig-dark-sweep var(--kp-sig-dk-time) linear backwards,
                kp-sig-dark-film var(--kp-sig-dk-time) linear backwards;
        }

        [data-theme='dark'] .kp-tour[open]:not([data-kp-tour-stepping])::after {
            content: '';
            position: absolute;
            inset: 0;
            z-index: 3;
            background: var(--kp-sig-dk-line) var(--kp-sig-dk-end) 0 / 2px 100% no-repeat;
            filter: var(--kp-sig-dk-glow);
            opacity: 0;
            pointer-events: none;
            animation: kp-sig-dark-pass-line var(--kp-sig-dk-time) linear backwards;
        }

        /* The page dims round the target and the ring comes in over the card's
           own pass, at its one pace (it was the package's 350 and 250 ms
           ease); css/components.css takes both back in the same time, the dim
           shrinking into the target as it grew out of it (lessons 11, 21,
           22). */
        [data-theme='dark'] {
            --kp-tour-dim-close: 0 0 0 0 transparent;
            --kp-tour-dim-time: var(--kp-sig-dk-time);
            --kp-tour-dim-close-ease: linear;
        }

        [data-theme='dark'] [data-kp-tour-target] {
            transition:
                box-shadow var(--kp-sig-dk-time) linear,
                outline-color var(--kp-sig-dk-time) linear;
        }

        /* The ring comes in only round a live tour's target (a frozen example
           on a page is no opening). */
        [data-theme='dark']:has(dialog.kp-tour[open]) [data-kp-tour-target] {
            animation: kp-sig-dark-tour-ring var(--kp-sig-dk-time) linear backwards;
        }

        @keyframes kp-sig-dark-tour-ring {
            from {
                outline-color: transparent;
            }
        }

        /* The calendar's busy layers are laid by the pass as anything that
           arrives and taken off by the pass back as anything that leaves:
           js/calendar.js marks a layer `[data-kp-leaving]` while its state goes
           (`--kp-calendar-busy-leave: hold`), and the rules below keep it drawn
           through the leave. */
        [data-theme='dark'] :is(.kp-calendar__day-busy, .kp-calendar__busy) {
            --kp-calendar-busy-leave: hold;
            transition: none;
        }

        [data-theme='dark']
            :is(.kp-calendar--busy-days, .kp-calendar--busy-whole:not(:has(> .kp-calendar__grid[aria-busy='true'])))
            .kp-calendar__day[data-kp-tone='loading']
            > .kp-calendar__day-busy:not([data-kp-leaving]),
        [data-theme='dark'] .kp-calendar--busy-whole:has(> .kp-calendar__grid[aria-busy='true']) > .kp-calendar__busy:not([data-kp-leaving]) {
            animation:
                kp-sig-dark-sweep var(--kp-sig-dk-time) linear backwards,
                kp-sig-dark-film var(--kp-sig-dk-time) linear backwards;
        }

        [data-theme='dark'] .kp-calendar__day:has(> .kp-calendar__day-busy[data-kp-leaving]) {
            position: relative;
        }

        [data-theme='dark'] .kp-calendar__day-busy[data-kp-leaving] {
            --kp-spinner-size: var(--kp-calendar-spinner, 0.75rem);
            position: absolute;
            inset-inline: 0;
            inset-block-end: 0.125rem;
            display: flex;
            justify-content: center;
            line-height: 0;
        }

        [data-theme='dark'] .kp-calendar--busy-whole > .kp-calendar__busy[data-kp-leaving] {
            --kp-spinner-size: var(--kp-calendar-busy-spinner, 2.5rem);
            z-index: 1;
            display: grid;
            place-self: center;
            place-items: center;
            padding: var(--kp-space-md, 1rem);
            border-radius: var(--radius, 0.5rem);
            background: var(--card);
            box-shadow: 0 0 0 1px var(--border);
            line-height: 0;
        }

        /* The busy table's rows dim and come back over the busy layer's own
           pass, at its one pace, so the table under the layer is part of the
           same pair (they changed at once). Two dims stand while a table is
           busy: its rows' (`--kp-datatable-busy-opacity`) and the whole
           table's (css/layout.css, `--kp-busy-opacity` on `[aria-busy]`); the
           whole table's was the one left in one frame, measured at the open's
           first frame (round 2, 2026-10-13: the wrapper at 0.7 at 1 ms). */
        [data-theme='dark'] .kp-datatable,
        [data-theme='dark'] .kp-datatable .kp-table tbody {
            transition: opacity var(--kp-sig-dk-time) linear;
        }

        /* The bar [Kenny via the coordinator, 2026-10-12: the navbar's opening
           and closing are in scope]. The dropdown and the mega menu were
           already swept in from the bar (G3) but closed at once in Firefox;
           the phone bar's panel opened with no pass of its own. Each now takes
           the pass back to close. Firefox does not hold `display`: the hover
           dropdown and the phone panel are held by the script for
           `--kp-nav-close-time`, the pass; the mega menu by a transition on
           --kp-sig-dk-hold (js/components.js settleClosing). */
        [data-theme='dark'] .kp-nav {
            --kp-nav-close-time: 880ms;
        }

        @container kp-nav (width > 40rem) {
            [data-theme='dark']
                .kp-nav__links
                > li[data-kp-nav-closing]:not(:hover, :focus-within, [data-kp-nav-menu-open])
                > .kp-nav__menu:not(.kp-nav__menu--wide) {
                display: block;
                opacity: 1;
                animation:
                    kp-sig-dark-sweep-back var(--kp-sig-dk-time) linear reverse forwards,
                    kp-sig-dark-film-back var(--kp-sig-dk-time) linear reverse forwards;
            }

            [data-theme='dark']
                .kp-nav__links
                > li[data-kp-nav-closing]:not(:hover, :focus-within, [data-kp-nav-menu-open])
                > .kp-nav__menu:not(.kp-nav__menu--wide)::after {
                animation: kp-sig-dark-pass-line-back var(--kp-sig-dk-time) linear reverse forwards;
            }

            [data-theme='dark'] .kp-nav__menu--wide {
                --kp-sig-dk-hold: 0;
                transition:
                    display var(--kp-sig-dk-time) allow-discrete,
                    --kp-sig-dk-hold var(--kp-sig-dk-time) linear;
            }

            [data-theme='dark']
                .kp-nav__links
                > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true']))
                > .kp-nav__menu--wide {
                --kp-sig-dk-hold: 1;
            }

            [data-theme='dark']
                .kp-nav__links
                > li[data-kp-nav-closing]:not([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true']))
                > .kp-nav__menu--wide {
                animation:
                    kp-sig-dark-sweep-back var(--kp-sig-dk-time) linear reverse forwards,
                    kp-sig-dark-film-back var(--kp-sig-dk-time) linear reverse forwards;
            }

            [data-theme='dark']
                .kp-nav__links
                > li[data-kp-nav-closing]:not([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true']))
                > .kp-nav__menu--wide::after {
                animation: kp-sig-dark-pass-line-back var(--kp-sig-dk-time) linear reverse forwards;
            }
        }

        /* The phone bar's panel is swept in under the bar from its start edge,
           its line crossing it, and taken off by the pass back. */
        @container kp-nav (max-width: 40rem) {
            [data-theme='dark'] .kp-nav:has(> .kp-nav__toggle) > .kp-nav__links {
                --kp-sig-dk-r: 0px;
                position: relative;
            }

            [data-theme='dark'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links {
                animation:
                    kp-sig-dark-sweep var(--kp-sig-dk-time) linear backwards,
                    kp-sig-dark-film var(--kp-sig-dk-time) linear backwards;
            }

            [data-theme='dark'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links::after {
                content: '';
                position: absolute;
                inset: 0;
                z-index: 3;
                background: var(--kp-sig-dk-line) var(--kp-sig-dk-end) 0 / 2px 100% no-repeat;
                filter: var(--kp-sig-dk-glow);
                opacity: 0;
                pointer-events: none;
                animation: kp-sig-dark-pass-line var(--kp-sig-dk-time) linear backwards;
            }

            [data-theme='dark'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-closing] > .kp-nav__links {
                animation:
                    kp-sig-dark-sweep-back var(--kp-sig-dk-time) linear reverse forwards,
                    kp-sig-dark-film-back var(--kp-sig-dk-time) linear reverse forwards;
            }

            [data-theme='dark'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-closing] > .kp-nav__links::after {
                content: '';
                position: absolute;
                inset: 0;
                z-index: 3;
                background: var(--kp-sig-dk-line) var(--kp-sig-dk-end) 0 / 2px 100% no-repeat;
                filter: var(--kp-sig-dk-glow);
                opacity: 0;
                pointer-events: none;
                animation: kp-sig-dark-pass-line-back var(--kp-sig-dk-time) linear reverse forwards;
            }

            /* The panel is swept as one: its nested list is not swept again. */
            [data-theme='dark'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) .kp-nav__links .kp-nav__menu {
                animation: none;
            }

            [data-theme='dark'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) .kp-nav__links .kp-nav__menu::after {
                content: none;
            }
        }
    }

    /* A reader who asked for no motion gets no close to wait for. */
    @media (prefers-reduced-motion: reduce) {
        [data-theme='dark'] .kp-nav {
            --kp-nav-close-time: 0ms;
        }
    }

    @keyframes kp-sig-dark-sweep-back {
        0% {
            mask-image: var(--kp-sig-dk-solid), var(--kp-sig-dk-solid), var(--kp-sig-dk-solid);
            mask-repeat: no-repeat;
            mask-origin: border-box;
            mask-clip: no-clip;
            mask-composite: add;
            mask-position:
                var(--kp-sig-dk-from) 0 top calc(-1 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-from) calc(-1 * var(--kp-sig-dk-r)) top calc(-1 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-from) calc(100% + var(--kp-sig-dk-r)) top calc(-1 * var(--kp-sig-dk-r));
            mask-size:
                0px calc(100% + 2 * var(--kp-sig-dk-r)),
                0px calc(100% + 2 * var(--kp-sig-dk-r)),
                0px calc(100% + 2 * var(--kp-sig-dk-r));
        }

        3% {
            mask-size:
                4% calc(100% + 2 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-r) calc(100% + 2 * var(--kp-sig-dk-r)),
                0px calc(100% + 2 * var(--kp-sig-dk-r));
        }

        72% {
            mask-size:
                96% calc(100% + 2 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-r) calc(100% + 2 * var(--kp-sig-dk-r)),
                0px calc(100% + 2 * var(--kp-sig-dk-r));
        }

        75%,
        100% {
            mask-image: var(--kp-sig-dk-solid), var(--kp-sig-dk-solid), var(--kp-sig-dk-solid);
            mask-repeat: no-repeat;
            mask-origin: border-box;
            mask-clip: no-clip;
            mask-composite: add;
            mask-position:
                var(--kp-sig-dk-from) 0 top calc(-1 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-from) calc(-1 * var(--kp-sig-dk-r)) top calc(-1 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-from) calc(100% + var(--kp-sig-dk-r)) top calc(-1 * var(--kp-sig-dk-r));
            mask-size:
                100% calc(100% + 2 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-r) calc(100% + 2 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-r) calc(100% + 2 * var(--kp-sig-dk-r));
        }
    }

    @keyframes kp-sig-dark-film-back {
        0% {
            --kp-sig-dk-turn: 0deg;
            animation-timing-function: linear;
        }

        75% {
            --kp-sig-dk-turn: 345deg;
            animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
        }

        100% {
            --kp-sig-dk-turn: 360deg;
        }
    }

    @keyframes kp-sig-dark-pass-line-back {
        0% {
            translate: calc(-100% * var(--kp-sig-dk-s)) 0;
            opacity: 0;
        }

        3% {
            translate: calc(-96% * var(--kp-sig-dk-s)) 0;
            opacity: 1;
        }

        69% {
            translate: calc(-8% * var(--kp-sig-dk-s)) 0;
            opacity: 1;
        }

        75%,
        100% {
            translate: 0 0;
            opacity: 0;
        }
    }

    /* ── The alarm is a dialog: it is swept in where it stands (G3), review round 2 ──
       Kenny, 2026-10-13: "Dat gaat niet open/close met de animatie van Dark". The alarm ran the
       package's entrance (the plate faded in, the panel rose and scaled, the headline shrank into
       place, the reason faded after it), which js/motion.js only turned around. Now the alarm's
       own box, the whole screen, is laid by the dialog's pass: the line crosses it from its start
       edge at one pace and the plate, its frame, its glow, the panel and the words are laid behind
       it; the close is the pass back (js/motion.js plays this entrance backwards in the dialog's
       close time, `--kp-open: reverse-close`). The plate casts no halo, so the reach is none. The
       line is the vignette layer's ::after, the plate's own ::after being its breathing glow. The
       film's turn is left out: the alarm draws no film edge. The held-open frame in the
       catalogue (`[data-kp-alarm-inline]`, never `[open]`) stays still. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) {
            --kp-sig-dk-r: 0px;
            animation: kp-sig-dark-sweep var(--kp-sig-dk-time) linear backwards;
        }

        [data-theme='dark'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) :is(.kp-alarm__panel, .kp-alarm__title, .kp-alarm__detail) {
            animation: none;
        }

        [data-theme='dark'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) .kp-alarm__scan::after {
            content: '';
            inset: 0;
            z-index: 3;
            block-size: auto;
            background: var(--kp-sig-dk-line) var(--kp-sig-dk-end) 0 / 2px 100% no-repeat;
            filter: var(--kp-sig-dk-glow);
            opacity: 0;
            pointer-events: none;
            animation: kp-sig-dark-pass-line var(--kp-sig-dk-time) linear backwards;
        }
    }

    /* ── The side navigation is swept in as the dialog is (G3, G13), review round 3 ──
       Kenny, 2026-10-13 22:12: "Niet de open/close animatie van dit thema". The panel that comes
       over the page or pushes it (and the window-edge panel of research/sidenav-edge) slid in on
       the package's 220 ms translate. It no longer slides: it stands where it opens, and the line
       crosses it from its start edge at one pace (660 ms, linear), laying the panel behind it, as
       the dialog's pass does; the close is the pass back, right to left, taking it off, frame for
       frame the opening backwards (880 ms both ways, `--kp-sig-dk-time`; the close plays the
       `-back` copies of the frames reversed, so it starts as an animation of its own). It casts no
       halo, so the reach is none; it draws no film edge, so there is no film turn (as the alarm).
       Shut, it stays in place and is hidden from the close's last frame. The content a push panel
       moves (and the edge tab) travels with the line: in the 660 ms of the pass and back in the
       last 660 ms of the close, at the line's one pace. js/sidenav.js copies the panel's
       `translate` timing to it; the panel's own translate never changes, so that timing is only
       the clock, written over the whole 880 ms with a held stretch (`linear()`, 660 / 880 = 75 %)
       so the move and the pass stay one pair. A backdrop, where a page asks for one, comes and
       goes over the same 880 ms at one pace. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']) {
            --kp-sig-dk-r: 0px;
            translate: 0 0;
            visibility: hidden;
            animation: kp-sig-dark-sweep-back 880ms linear reverse forwards;
            transition:
                translate 880ms linear(0, 0 25%, 1),
                visibility 0s linear 880ms,
                inline-size var(--kp-sidenav-duration, var(--fx-duration)) var(--kp-sidenav-ease-back, var(--fx-ease));
        }

        [data-theme='dark'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='true'] {
            visibility: visible;
            animation: kp-sig-dark-sweep 880ms linear backwards;
            transition:
                translate 880ms linear(0, 1 75%, 1),
                visibility 0s linear,
                inline-size var(--kp-sidenav-duration, var(--fx-duration)) var(--kp-sidenav-ease, var(--fx-ease));
        }

        [data-theme='dark'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])::after {
            content: '';
            position: absolute;
            inset: 0;
            z-index: 3;
            background: var(--kp-sig-dk-line) var(--kp-sig-dk-end) 0 / 2px 100% no-repeat;
            filter: var(--kp-sig-dk-glow);
            opacity: 0;
            pointer-events: none;
            animation: kp-sig-dark-pass-line-back 880ms linear reverse forwards;
        }

        [data-theme='dark'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='true']::after {
            animation: kp-sig-dark-pass-line 880ms linear backwards;
        }

        [data-theme='dark'] .kp-sidenav__backdrop {
            animation: kp-sidenav-backdrop 880ms linear both;
        }
    }
}

@layer kp.register {
    /* Bottom tab bar [kpadopt-nav] — dark: near-black with a film on the edge. The current tab is a film line laid along the top edge by one pass from the start, a chamfered wash under it (G6, G7, G13); a count is chamfered, never rounded. */
    [data-theme='dark'] .kp-tabbar {
        box-shadow: 0 -1px 0 hsl(from var(--fx-signal) h s l / 0.22);
    }

    [data-theme='dark'] .kp-tabbar__tab {
