        [data-theme='formal'] .kp-popover[popover]:not(.kp-tooltip):has(> .kp-menu > :nth-child(5)) {
            --kp-fm-n: 5;
        }

        [data-theme='formal'] .kp-popover[popover]:not(.kp-tooltip):has(> .kp-menu > :nth-child(6)) {
