            --kp-fm-f: clamp(0, var(--kp-fm-t) * var(--kp-fm-total) / var(--kp-sig-fm-len), 1);
            --kp-fm-lf: clamp(0, (var(--kp-fm-t) * var(--kp-fm-total) - var(--kp-sig-fm-len)) / var(--kp-sig-fm-lift), 1);
            --kp-fm-open: calc(100% - var(--kp-fm-f) * (100% + var(--kp-sig-fm-reach)));
