        }

        [data-theme='formal'] :is(.kp-menu-button > .kp-menu, .kp-popover[popover]:not(.kp-tooltip) > .kp-menu) > * {
            --kp-fm-f: clamp(0, (var(--kp-fm-t) * var(--kp-fm-total) - var(--kp-fm-k, 0) * var(--kp-sig-fm-st)) / var(--kp-sig-fm-len), 1);
            --kp-fm-lf: clamp(
                0,
                (var(--kp-fm-t) * var(--kp-fm-total) - var(--kp-fm-k, 0) * var(--kp-sig-fm-st) - var(--kp-sig-fm-len)) / var(--kp-sig-fm-lift),
