    /* ── Keyframes ───────────────────────────────────────────────────────
       Timing functions are written out or left to the animation's shorthand
       (linear: a rule at an even pace, a dead stop, G1); a close plays an
       animation backwards, and linear is its own inverse. ── */

    /* A tick, and a radio's dot, are ruled start to end. */
    @keyframes kp-sig-formal-pen {
        from {
            clip-path: inset(0 100% 0 0);
        }

        to {
            clip-path: inset(0);
        }
    }

    /* A rule on a waiting surface: ruled (17 %), held (to 62 %), lifted from
       the start (to 79 %), gone until the loop comes round. */
    @keyframes kp-sig-formal-ledger {
        0% {
            clip-path: inset(0 100% 0 0);
        }

        17% {
            clip-path: inset(0);
        }

        62% {
            clip-path: inset(0);
        }

        79%,
        100% {
            clip-path: inset(0 0 0 100%);
        }
    }

    @keyframes kp-sig-formal-loading {
        from {
            --kp-fm-l: 0;
        }

        to {
            --kp-fm-l: 1;
        }
    }

    @keyframes kp-sig-formal-update-closed {
        from {
            --kp-fm-u: 0;
        }

        to {
            --kp-fm-u: 1;
        }
    }

    /* The busy bar: the band ruled across (48 %), the second rule closing
       it (52 %), both lifted from the start (to 100 %). */
    @keyframes kp-sig-formal-bar-band {
        0% {
            clip-path: inset(0 100% 0 0);
        }

        48%,
        52% {
            clip-path: inset(0);
        }

        100% {
            clip-path: inset(0 0 0 100%);
        }
    }

    @keyframes kp-sig-formal-bar-second {
        0%,
        48% {
            clip-path: inset(0 100% 0 0);
        }

        52% {
            clip-path: inset(0);
        }

        100% {
            clip-path: inset(0 0 0 100%);
        }
    }

    @keyframes kp-sig-formal-bar-head {
        0% {
            transform: translateX(0);
            opacity: 1;
        }

        48% {
            transform: translateX(100cqi);
            opacity: 1;
        }

        48.1%,
        100% {
            transform: translateX(100cqi);
            opacity: 0;
        }
    }

    /* The spinner: the arc ruled round the outer ring (to 50 %), the inner
       arc closing it (58 %), both lifted from the start (60 % to 100 %). */
    @keyframes kp-sig-formal-arc-outer {
        0% {
            --kp-fm-a0: 0deg;
            --kp-fm-a1: 0deg;
        }

        50%,
        60% {
            --kp-fm-a0: 0deg;
            --kp-fm-a1: 360deg;
        }

        100% {
            --kp-fm-a0: 360deg;
            --kp-fm-a1: 360deg;
        }
    }

    @keyframes kp-sig-formal-arc-inner {
        0%,
        50% {
            --kp-fm-a0: 0deg;
            --kp-fm-a1: 0deg;
        }

        58%,
        60% {
            --kp-fm-a0: 0deg;
            --kp-fm-a1: 360deg;
        }

        100% {
            --kp-fm-a0: 360deg;
            --kp-fm-a1: 360deg;
        }
    }

    /* ── The meter with a mark, this theme's way [picked by Kenny on
       research/character-meter, round 3, 2026-10-05: shape 1, while
       loading 2, how the share arrives 1, when the tone changes 1,
       the mark past the end 2]. The package's own markup and states
       (setMeter(), js/kpi.js): the track on the meter, the share on ::before,
       the sign past the end or the loading picture on ::after, the mark
       `.kp-meter__mark`. Every animation and transition under
       prefers-reduced-motion: no-preference; still frames otherwise. ── */

    /* The shared part: room past the end, loading without the pulse, the mark
       centred on its width, the package's signs cleared for the shape's own.
       Under :where() so each picked rule below wins as it did in the demo. */
    :where([data-theme='formal']) :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-room: 0.625rem;
        box-sizing: border-box;
    }

    :where([data-theme='formal']) .kp-meter--inline {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-sig-meter-room));
    }

    /* Each character draws its own loading picture instead of the pulse. */
    :where([data-theme='formal']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: clip;
        animation: none;
    }

    :where([data-theme='formal']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    /* The mark is centred on its share, whatever its width. */
    :where([data-theme='formal']) .kp-meter__mark {
        --kp-sig-meter-mw: 2px;
        box-sizing: border-box;
        inline-size: var(--kp-sig-meter-mw);
        inset-inline-start: calc(clamp(0, var(--kp-mark, 0), 1) * 100% - var(--kp-sig-meter-mw) / 2);
    }

    :where([data-theme='formal']) .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - 0.75rem);
    }

    /* The sign past the end, cleared of the package's ▸ for each character
       to draw its own. */
    :where([data-theme='formal']) :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '';
        position: absolute;
        inset: auto;
        translate: none;
        color: inherit;
        font-size: 0.75rem;
        line-height: 1;
        text-shadow: none;
        white-space: nowrap;
        pointer-events: none;
    }

    /* A mark past the end keeps the package's sign inside the bar's end, in
       each character's own glyph and ink. */
    :where([data-theme='formal']) .kp-meter__mark[data-kp-over]::after {
        content: var(--kp-sig-meter-mo-sign, '▸');
        color: var(--kp-sig-meter-mo-ink, var(--foreground));
        font-family: var(--kp-sig-meter-mo-font, inherit);
        text-shadow:
            0 0 1px var(--kp-sig-meter-mo-halo, var(--card)),
            0 0 2px var(--kp-sig-meter-mo-halo, var(--card));
    }

    /* ── shape: option 1 ── */

    /* ── formal · the bound volume and its ribbon ─────────────────── */
    [data-theme='formal'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-meter-height: 0.625rem;
        --kp-sig-meter-room: 0.75rem;
        --kp-sig-meter-mo-ink: var(--primary);
        border-radius: 1px;
        background:
            repeating-linear-gradient(180deg, color-mix(in oklab, var(--border-strong) 45%, transparent) 0 1px, transparent 1px 2px), var(--card);
        box-shadow: inset 0 0 0 1px var(--border-strong);
    }

    /* Navy buckram: the cloth's weave, the headband's light top edge. */
    [data-theme='formal'] :is(.kp-meter, .kp-kpi__meter)::before {
        border-radius: 1px 2px 2px 1px;
        background:
            repeating-linear-gradient(45deg, hsl(from var(--primary-foreground) h s l / 0.1) 0 1px, transparent 1px 3px),
            repeating-linear-gradient(-45deg, hsl(from var(--primary-foreground) h s l / 0.1) 0 1px, transparent 1px 3px), var(--kp-meter-fill-colour);
        box-shadow:
            inset 0 1px 0 hsl(from var(--primary-foreground) h s l / 0.3),
            inset -1px 0 0 hsl(from var(--foreground) h s l / 0.4);
    }

    /* One more volume leans past the end of the shelf. */
    [data-theme='formal'] :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        inset-inline-start: calc(100% + 3px);
        inset-block: 0;
        inline-size: 0.3125rem;
        border-radius: 1px;
        background: var(--kp-meter-fill-colour);
        box-shadow: inset 0 1px 0 hsl(from var(--primary-foreground) h s l / 0.3);
        transform: skewX(-16deg);
        transform-origin: bottom;
    }

    /* The ribbon: a paper edge round a gold ribbon, cut in a swallowtail,
       hanging out below the book. */
    [data-theme='formal'] .kp-meter__mark {
        --kp-sig-meter-mw: 8px;
        inset-block: -2px -8px;
        border-radius: 0;
        background: var(--card);
        clip-path: polygon(0 0, 100% 0, 100% 100%, 50% calc(100% - 4px), 0 100%);
    }

    [data-theme='formal'] .kp-meter__mark::before {
        content: '';
        position: absolute;
        inset: 0 1px 1px;
        background: var(--fx-signal);
        clip-path: polygon(0 0, 100% 0, 100% 100%, 50% calc(100% - 3px), 0 100%);
    }

    [data-theme='formal'] .kp-meter__mark[data-kp-over] {
        background: transparent;
        clip-path: none;
    }

    /* ── while loading: a rule is ruled along it [G10; Kenny, 2026-10-08,
       question 10: loading is ruling the lines, the sliding bar is retired].
       The meter's groove is one line high: one navy rule is ruled across it,
       held, lifted from the start and ruled again, 2400 ms, even pace;
       standing still it is ruled. ── */

    [data-theme='formal'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        animation: none;
    }

    [data-theme='formal'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        all: unset;
        content: '';
        position: absolute;
        inset-inline: 0;
        inset-block: calc(50% - 1px) auto;
        block-size: 2px;
        pointer-events: none;
        background: var(--primary);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='formal'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
            animation: kp-sig-formal-ledger var(--kp-sig-fm-loop) linear infinite;
        }
    }

    /* ── how the share arrives: option 1 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='formal'] :is(.kp-meter, .kp-kpi__meter)::before {
            animation: kp-sig-formal-meter-wipe-o var(--kp-sig-fm-time) linear backwards;
            transition: inline-size var(--kp-sig-fm-time) var(--fx-ease);
        }
    }

    /* ── when the tone changes: option 1 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='formal'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='warning']::before {
            animation-name: kp-sig-formal-meter-wipe-w;
        }

        [data-theme='formal'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='destructive']::before {
            animation-name: kp-sig-formal-meter-wipe-d;
        }
    }

    /* ── the mark past the end: option 2 ── */

    [data-theme='formal'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-mo-sign: '›';
    }

    [data-theme='formal'] .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% + 3px);
    }

    [data-theme='formal'] .kp-meter__mark[data-kp-over]::after {
        inset-inline-start: calc(100% + 2px);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='formal'] .kp-meter__mark {
            transition:
                inset-inline-start var(--fx-duration) var(--fx-ease),
                rotate var(--fx-duration) var(--fx-ease);
        }
    }

    @keyframes kp-sig-formal-meter-wipe-d {
        0% {
            clip-path: inset(0 100% 0 0);
        }

        100% {
            clip-path: inset(0);
        }
    }

    @keyframes kp-sig-formal-meter-wipe-o {
        0% {
            clip-path: inset(0 100% 0 0);
        }

        100% {
            clip-path: inset(0);
        }
    }

    @keyframes kp-sig-formal-meter-wipe-w {
        0% {
            clip-path: inset(0 100% 0 0);
        }

        100% {
            clip-path: inset(0);
        }
    }

    /* ── A warning is a red-ink entry [G5, G8; Kenny, 2026-10-08, questions 5
       and 8: navy rules, red ink marks, gold never acts; the red-ink entry].
       A warning or failed key figure, trend tile, strip column, destructive
       menu entry and alert is ruled off along its start edge in 3 px red
       ink; its figure is in red ink on the paper, never on a tinted plate;
       the change sits on a square plate inside a hairline, its ground
       paper. Never a stamp, never a frame all round. The warning-ink nudges
       the register held for the old amber plates went with the plates. ── */
    [data-theme='formal'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) {
        --kp-kpi-meter-fill: var(--destructive);
        border-color: var(--border);
        background: var(--card);
        box-shadow: inset 3px 0 0 var(--destructive);
    }

    [data-theme='formal'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value {
        padding-inline: 0;
        background: none;
        color: var(--destructive);
    }

    [data-theme='formal'] .kp-kpi__delta {
        border-radius: 0;
    }

    [data-theme='formal'] .kp-kpi__delta[data-kp-tone='bad'] {
        border: 1px solid var(--destructive);
        background: var(--card);
        color: var(--destructive);
    }

    [data-theme='formal'] .kp-menu__item--destructive {
        border-radius: 0;
        box-shadow: inset 3px 0 0 var(--destructive);
        color: var(--destructive);
    }

    /* The red edge bar and the two-channel focus ring share the box-shadow
       property, and the bar's rule outranks the plain `:focus-visible` one, so
       the keyboard saw only the paper-coloured outer half of the ring (an
       almost invisible mark on this entry). Like the mirror button above, the
       combined rule keeps both: the bar, then the inner ring, as every other
       entry of the menu shows it [G14, G16; the dashboard's destructive menu
       item, suite triage 10.0.0]. */
    [data-theme='formal'] .kp-menu__item--destructive:focus-visible {
        box-shadow:
            inset 3px 0 0 var(--destructive),
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring);
    }

    [data-theme='formal'] .kp-alert:is(.kp-alert--warning, .kp-alert--destructive) {
        border-color: var(--border);
        background: var(--card);
        box-shadow: inset 3px 0 0 var(--destructive);
        color: var(--foreground);
    }

    [data-theme='formal'] .kp-alert:is(.kp-alert--warning, .kp-alert--destructive) .kp-alert__icon {
        color: var(--destructive);
    }

    /* A day of the month: paper with a rule, not a tinted plate. A kept night
       is ruled along its start edge in navy, a night to look at in red ink, a
       failed one in two red rules; today stands in the double rule. */
    [data-theme='formal']
        :is(.kp-calendar__day, .kp-calendar__swatch, .kp-matrix__cell, .kp-heat__swatch--plate):is(
            [data-kp-tone='ok'],
            [data-kp-tone='warn'],
            [data-kp-tone='bad']
        ) {
        --kp-fm-edge: inset 3px 0 0 var(--primary);
        border-color: var(--border);
        background: var(--card);
        box-shadow: var(--kp-fm-edge);
        color: var(--foreground);
    }

    [data-theme='formal'] :is(.kp-calendar__day, .kp-calendar__swatch, .kp-matrix__cell, .kp-heat__swatch--plate)[data-kp-tone='warn'] {
        --kp-fm-edge: inset 3px 0 0 var(--destructive);
        color: var(--destructive);
    }

    [data-theme='formal'] :is(.kp-calendar__day, .kp-calendar__swatch, .kp-matrix__cell, .kp-heat__swatch--plate)[data-kp-tone='bad'] {
        --kp-fm-edge: inset 3px 0 0 var(--destructive), inset 6px 0 0 var(--card), inset 8px 0 0 var(--destructive);
        color: var(--destructive);
    }

    [data-theme='formal'] .kp-calendar__day[data-kp-today] {
        border-color: var(--primary);
        box-shadow:
            var(--kp-fm-edge, 0 0 transparent),
            inset 0 0 0 2px var(--card),
            inset 0 0 0 3px var(--primary);
    }

    /* ── The voice [G18; Kenny, 2026-10-08, question 18]: figures in the
       display face with tabular numerals, labels in small capitals. ── */
    [data-theme='formal'] :is(.kp-kpi__value, .kp-state-word, .kp-calendar__num, .kp-calendar__count, .kp-chart__num) {
        font-family: var(--theme-font-display);
        font-variant-numeric: tabular-nums;
        font-weight: 560;
    }

    [data-theme='formal'] :is(.kp-kpi__label, .kp-calendar__title, .kp-calendar__grid th, .kp-chart__tick) {
        font-variant-caps: all-small-caps;
        letter-spacing: 0.06em;
        text-transform: none;
    }

    [data-theme='formal'] .kp-kpi__label {
        font-size: 0.9375rem;
    }

    [data-theme='formal'] .kp-page-header__title {
        font-family: var(--theme-font-display);
        font-variation-settings: 'opsz' 60;
        font-weight: 600;
    }

    /* ── What matters carries the double rule [G7; Kenny, 2026-10-08,
       question 7]: the page header is a letterhead, a strip column is a
       certificate, a drawer is a sheet like a dialog. A plain card, a tile,
       a menu is paper with a hairline and no frame. ── */
    [data-theme='formal'] .kp-page-header {
        padding-block-end: var(--kp-space-md, 0.75rem);
        border-block-end: 3px double var(--border-strong);
    }

    [data-theme='formal'] .kp-kpis[data-kp-kpis-columns] > .kp-kpi {
        border: 1px solid var(--border-strong);
        box-shadow:
            inset 0 0 0 3px var(--card),
            inset 0 0 0 4px var(--border-strong);
    }

    [data-theme='formal'] .kp-kpis[data-kp-kpis-columns] > .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) {
        box-shadow:
            inset 3px 0 0 var(--destructive),
            inset 0 0 0 3px var(--card),
            inset 0 0 0 4px var(--border-strong);
    }

    [data-theme='formal'] :is(dialog.kp-drawer, .kp-tour) {
        box-shadow:
            inset 0 0 0 3px var(--popover),
            inset 0 0 0 4px var(--border-strong),
            0 18px 40px -24px hsl(from var(--foreground) h s l / 0.5);
    }

    /* The seal stays before the state word and on the busy table, where
       Kenny placed it (motifs, question 19: "those plus the seal where
       picked"): a wax seal in two rings of navy, set, not pressed. */
    [data-theme='formal'] .kp-state-word {
        padding-inline-start: 1.5em;
        background-image: radial-gradient(
            circle closest-side,
            var(--primary) 0 56%,
            var(--card) 56% 60%,
            var(--primary) 60% 80%,
            var(--card) 80% 84%,
            var(--primary) 84% 100%,
            transparent 100%
        );
        background-repeat: no-repeat;
        background-size: 1.15em 1.15em;
        background-position: 0 50%;
    }

    [data-theme='formal'] .kp-datatable__busy-words::before {
        content: '';
        display: inline-block;
        inline-size: 1.15em;
        block-size: 1.15em;
        margin-inline-end: 0.5em;
        border-radius: 50%;
        vertical-align: -0.2em;
        background: radial-gradient(
            circle closest-side,
            var(--primary) 0 56%,
            var(--card) 56% 60%,
            var(--primary) 60% 80%,
            var(--card) 80% 84%,
            var(--primary) 84% 100%,
            transparent 100%
        );
    }

    /* A key figure's link ("Open"): the rule under its words, doubled on a
       press (G15, G17). */
    [data-theme='formal'] .kp-kpi__link {
        border-radius: 0;
        text-decoration: underline 2px transparent;
        text-decoration-skip-ink: none;
        text-underline-offset: 0.3em;
    }

    [data-theme='formal'] .kp-kpi__link:hover {
        text-decoration-line: underline;
        text-decoration-style: solid;
        text-decoration-color: var(--primary);
    }

    [data-theme='formal'] .kp-kpi__link:active {
        text-decoration-style: double;
        text-decoration-thickness: 1px;
    }

    [data-theme='formal'] .kp-chart__tip {
        border-radius: 0;
    }

    /* ── Every part that opens is ruled open and ruled off [G3, G13; lesson 38;
       all-themes pass, 2026-10-13]. The tour's dim and ring, the calendar's
       busy layers and the bar's three openings (the hover dropdown, the mega
       menu, the phone bar's panel) take the ruling the dialog and the menus
       already use; each close is its opening played backwards. ── */
    @media (prefers-reduced-motion: no-preference) {
        /* The tour: the page dims round the target and the ring is drawn in
           over the card's own 740 ms, at the ruling's even pace (it was the
           package's 350 and 250 ms ease); css/components.css takes both back
           in the same time on the same (linear) curve, the dim shrinking
           into the target as it grew out of it (lessons 11, 21, 22). */
        [data-theme='formal'] {
            --kp-tour-dim-close: 0 0 0 0 transparent;
            --kp-tour-dim-time: 740ms;
            --kp-tour-dim-close-ease: linear;
        }

        [data-theme='formal'] [data-kp-tour-target] {
            transition:
                box-shadow 740ms linear,
                outline-color 740ms linear;
        }

        /* The ring is drawn in only round a live tour's target (a frozen
           example on a page is no opening). */
        [data-theme='formal'] body:has(> dialog.kp-tour[open]) [data-kp-tour-target],
        [data-theme='formal']:has(dialog.kp-tour[open]) [data-kp-tour-target] {
            animation: kp-sig-formal-tour-ring 740ms linear backwards;
        }

        /* The card's lines are turned round with it: js/motion.js
           playEntranceBackwards() reverses the card and its pseudo-elements
           (css/components.css), and its title, text and foot are ruled lines
           of their own, so they take the same reversal here, bottom first. */
        [data-theme='formal'] .kp-tour[data-kp-reversing='reset'] > *,
        [data-theme='formal'] .kp-tour[data-kp-reversing='reset'] > *::after {
            animation-name: none !important;
        }

        [data-theme='formal'] .kp-tour[data-kp-reversing='play'] > *,
        [data-theme='formal'] .kp-tour[data-kp-reversing='play'] > *::after {
            animation-direction: reverse !important;
            animation-fill-mode: both !important;
        }

        /* A reversed animation waits its delay first, so each line's wait is
           turned round with it: the 740 ms span minus the line's end (the line
           ends at its wait + 400 ms, its pen at its wait + 560 ms, the pen on
           the card's top edge at 560 ms), the line that came in last goes first. */
        [data-theme='formal'] .kp-tour[data-kp-reversing='play']::before {
            animation-delay: 180ms !important;
        }

        [data-theme='formal'] .kp-tour[data-kp-reversing='play'] > :nth-child(1) {
            animation-delay: 340ms !important;
        }

        [data-theme='formal'] .kp-tour[data-kp-reversing='play'] > :nth-child(1)::after {
            animation-delay: 180ms !important;
        }

        [data-theme='formal'] .kp-tour[data-kp-reversing='play'] > :nth-child(2) {
            animation-delay: 280ms !important;
        }

        [data-theme='formal'] .kp-tour[data-kp-reversing='play'] > :nth-child(2)::after {
            animation-delay: 120ms !important;
        }

        [data-theme='formal'] .kp-tour[data-kp-reversing='play'] > :nth-child(3) {
            animation-delay: 220ms !important;
        }

        [data-theme='formal'] .kp-tour[data-kp-reversing='play'] > :nth-child(3)::after {
            animation-delay: 60ms !important;
        }

        [data-theme='formal'] .kp-tour[data-kp-reversing='play'] > :nth-child(n + 4) {
            animation-delay: 160ms !important;
        }

        [data-theme='formal'] .kp-tour[data-kp-reversing='play'] > :nth-child(n + 4)::after {
            animation-delay: 0ms !important;
        }

        /* The busy table's rows (and the table, layout.css) dim and come back
           in the busy layer's own 560 ms, at the even pace, so the table
           under the layer is part of the same pair (they changed at once). */
        [data-theme='formal'] .kp-datatable {
            transition:
                outline-color calc(var(--kp-resize-dur, 300ms) / 2) ease-out,
                outline-offset calc(var(--kp-resize-dur, 300ms) / 2) ease-out,
                filter calc(var(--kp-resize-dur, 300ms) / 2) ease-out,
                opacity 560ms linear;
        }

        [data-theme='formal'] .kp-datatable .kp-table tbody {
            transition: opacity 560ms linear;
        }

        /* The side navigation (over and push, the window-edge panel too) is
           ruled in where it stands, as the dialog is [G3; Kenny, 2026-10-13
           review round 2: "niet de open/close animatie van dit thema"]: it no
           longer slides in on the contact time. Its frame rule along the top
           edge, then its lines (the header, the list, the foot), each clipped
           open start to end with the 2 px navy pen under it, 60 ms apart, in
           the dialog's 740 ms (400 + 160 + three lines 60 ms apart, the same
           waits as kp-sig-formal-ruled-line / -ruled-pen). One registered number,
           --kp-fm-t (0 to 1), draws every clip and pen, as in the menus; the
           opening runs it up (kp-sig-formal-ruling) and the close runs it down
           (kp-sig-formal-ruling-back) at the even pace, so the close is the
           ruling taken off, frame for frame the opening backwards. Shut, the
           panel stays in place and is hidden from the close's last frame.
           The content a push panel makes room in moves with the frame rule's
           pen, in the first 400 ms of the 740 at the even pace, and back in
           the last 400 ms of the close (js/sidenav.js copies the panel's
           `translate` timing to it; the panel's own translate never changes).
           The move is written over the whole 740 ms with a held stretch
           (`linear()`, 400 / 740 = 54.054 %) rather than as 400 ms with a
           delay, so the content's move is as long as the panel's ruling and
           the two stay one pair. */
        [data-theme='formal'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']) {
            --kp-fm-t: 0;
            --kp-fm-k: 0;
            translate: 0 0;
            visibility: hidden;
            animation: kp-sig-formal-ruling-back 740ms linear;
            transition:
                translate 740ms linear(0, 0 45.946%, 1),
                visibility 0s linear 740ms,
                inline-size var(--kp-sidenav-duration, var(--fx-duration)) var(--kp-sidenav-ease-back, linear);
        }

        [data-theme='formal'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='true'] {
            --kp-fm-t: 1;
            visibility: visible;
            animation: kp-sig-formal-ruling 740ms linear;
            transition:
                translate 740ms linear(0, 1 54.054%, 1),
                visibility 0s linear,
                inline-size var(--kp-sidenav-duration, var(--fx-duration)) var(--kp-sidenav-ease, linear);
        }

        [data-theme='formal'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']) > :nth-child(1) {
            --kp-fm-k: 0;
        }

        [data-theme='formal'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']) > :nth-child(2) {
            --kp-fm-k: 1;
        }

        [data-theme='formal'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']) > :nth-child(3) {
            --kp-fm-k: 2;
        }

        [data-theme='formal'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']) > :nth-child(n + 4) {
            --kp-fm-k: 3;
        }

        [data-theme='formal'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']),
        [data-theme='formal'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']) > * {
            --kp-fm-f: clamp(0, (var(--kp-fm-t) * 740 - var(--kp-fm-k, 0) * var(--kp-sig-fm-st)) / var(--kp-sig-fm-len), 1);
            --kp-fm-lf: clamp(0, (var(--kp-fm-t) * 740 - var(--kp-fm-k, 0) * var(--kp-sig-fm-st) - var(--kp-sig-fm-len)) / var(--kp-sig-fm-lift), 1);
            --kp-fm-open: calc(100% - var(--kp-fm-f) * (100% + var(--kp-sig-fm-reach)));
            clip-path: inset(
                calc(-1 * var(--kp-sig-fm-reach)) calc(var(--kp-fm-open) * var(--kp-fm-ltr) - var(--kp-sig-fm-reach) * (1 - var(--kp-fm-ltr)))
                    calc(-1 * var(--kp-sig-fm-reach)) calc(var(--kp-fm-open) * (1 - var(--kp-fm-ltr)) - var(--kp-sig-fm-reach) * var(--kp-fm-ltr))
            );
            background-image: linear-gradient(
